function PrepareATeam(v)
	--试图并行执行，避免偶发报错影响全局
	Timers:CreateTimer(0.01, function()
		if IsUnitExist(v) == true and v.is_banned == true then
			KillSelfTeam(v:GetTeam(), true)
		elseif IsUnitExist(v) == true then
			AddPickAndRemoveAbility(v)
			if v ~= nil then
				local level = v:GetLevel()
				AddAbilityAndSetLevel(v, 'summon_hero', level)
			end
			v.is_battle_completed = nil
			local mana = CalMoneyThisRound(v)
			Timers:CreateTimer(1, function()
				--给蓝
				AddCourierMana(v, mana)
				AddTotalMoneyStat(v:GetPlayerID(), mana)
			end)
			Timers:CreateTimer(0.5, function()
				--自动抽卡一次
				if v:HasModifier('modifier_item_second_chance') then
					Draw5ChessAndShow(v:GetTeam(), false, -1)
					v.second_draw_activate = true
				else
					Draw5ChessAndShow(v:GetTeam(), false)
				end
			end)
			--给一点经验
			if _G.battle_round ~= 1 then
				AddCourierExp({
					caster = v,
					xpadd = 1,
					cost = 0,
					disable_quick_lvl_up = true,
				})
			end

			-- _G.damage_stat[v:GetTeam()] = {}
			--大头菜概率长大
			if v.hand_entities ~= nil and v:HasModifier('modifier_item_bench_contract') and v.relic_ttl <= 10 then
				--11/21/31/41...回合不+1，为了缓冲开圣物的时间，开魔法种子圣物的时候就把第一回合的+1加进去了
				local prob_base = 2*_G.battle_round^1.2
				-- local placeholder_count = 0
				-- for k0, x0 in pairs(v.hand_entities) do
				-- 	if x0:GetUnitName() == 'placeholder' then 
				-- 		placeholder_count = placeholder_count + 1
				-- 	end
				-- end
				-- local prob = prob_base + (8-placeholder_count)*5
				local prob = prob_base
				for k, x in pairs(v.hand_entities) do
					if x:GetUnitName() == 'placeholder' and RandomInt(1, 100) <= prob then
						local scale = x.buy_price or 1
						if prob > 100 and RandomInt(1, 100) <= prob - 100 then
							scale = scale + 2
						else 
							scale = scale + 1
						end
						x.buy_price = scale
						AddModelScalePlus(x, 1.2 + scale / 10.0)
						AddTotalMoneyStat(v:GetPlayerID(), 1)
						x:SetBaseMaxHealth(scale)
						x:SetMaxHealth(scale)
						x:SetHealth(scale)
						-- CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
						-- 	unit_index = x:entindex(),
						-- 	text = '+1',
						-- })
					end
				end
			end

			--蛋概率长大
			if v.hand_entities ~= nil and (v.relic_ttl or 0) <= 10 then --and v:HasModifier('modifier_item_egg')
				--11/21/31/41...回合不+1，为了缓冲开圣物的时间
				for k, x in pairs(v.hand_entities) do
					if x:GetUnitName() == 'egg' and x.egg_chess ~= nil and FindChessCountInChessPool(x.egg_chess) > 0 then
						local egg_cost = GetChessCostByName(x.egg_chess) or 3
						local prob_table = {
							[1] = 85,
							[2] = 75,
							[3] = 65,
							[4] = 55,
							[5] = 45,
						}

						if RandomInt(1, 100) <= (prob_table[egg_cost] or 50) then
							x.egg_chess_count = x.egg_chess_count + 1

							if x.egg_chess_count > 9 then
								x.egg_chess_count = 9
							end
							local scale = x.egg_chess_count
							AddModelScalePlus(x, 1.4 + scale * 0.2)
							x:SetBaseMaxHealth(9)
							x:SetMaxHealth(9)
							x:SetHealth(scale)
							CustomNetTables:SetTableValue("unit_table", 'egg_' .. x:entindex(), {
								chess = x.egg_chess,
								count = x.egg_chess_count,
							})

							RemoveChessFromChessPool(x.egg_chess)
						end
					end
				end
			end

			--魔术箱变出来
			if v.hand_entities ~= nil then
				for k, target in pairs(v.hand_entities) do
					if target:GetUnitName() == 'magic_box' then
						MagicboxOut(target, v)
					end
				end
			end
			
			--更新圣物剩余回合
			if v.relic_ttl ~= nil then
				v.relic_ttl = v.relic_ttl - 1
				UpdateRelicTTL(v, v.relic_ttl)
				if v.relic_ttl <= 0 then
					--移除圣物
					RemoveRelic(v:GetTeam())
				end
			end

			Timers:CreateTimer(0.5, function()
				--熊猫人钓鱼
				Fish(v)

				--亡灵转化
				Ghost(v)
			end)
			--人类经验
			local human_count, is_lucky = GetHumanCount(v:GetTeam())
			if human_count >= 3 then
				--（3）人类
				--幸运挂坠
				-- local per = 50
				-- if is_lucky == true then
				-- 	per = 50*1.25
				-- end
				-- if RandomInt(1,100) < per then
				-- AddItemPlus(v,'item_zhishizhishu')
				local exp = 2
				AddCourierExp({
					caster = v,
					xpadd = exp,
					disable_quick_lvl_up = true,
					cost = 0,
					ignore_level_restrict = true,
				})
				AMHC:CreateNumberEffect(v, exp, 3, AMHC.MSG_MISS, { 255, 255, 128 }, 0)
				EmitSoundOn("is_human.magic", v)
				-- end
			end
			if v.hooray_loot_table ~= nil and table.maxn(v.hooray_loot_table) > 0 then
				for _, loot in pairs(v.hooray_loot_table) do
					if loot == 'item_zhishizhishu' then
						local exp_6_human = v:GetLevel() - 2
						if exp_6_human < 0 then
							exp_6_human = 0
						end
						AddCourierExp({
							caster = v,
							xpadd = exp_6_human,
							disable_quick_lvl_up = true,
							cost = 0,
							ignore_level_restrict = true,
						})
					else
						AddItemPlus(v, loot)
					end
				end
			end
			v.hooray_loot_table = {}
		end
	end)
end

--游戏循环1.1——清理战斗场地并重新摆上自己的随从
function ClearARound(teamid)
	for _, v in pairs(GetValidChessOnBoard(teamid)) do
		if v ~= nil and v:IsNull() == false then
			-- AddAbilityAndSetLevel(v,'no_selectable')
			--移除modifier
			RemoveAllModifiers(v)
			Timers:CreateTimer(0.1, function()
				if v ~= nil and v:IsNull() == false and v.team_id ~= 4 and v.ori_team ~= 4 then
					v.is_clearing = true
					v.no_death_rattle = true
					FillEmptySlot(v)

					SaveItem(teamid, v:entindex(), function()
						DestroyUnit(v)
					end)
				else
					DestroyUnit(v)
				end
			end)
		end
	end
	_G.to_be_destory_list[teamid] = {}
	_G.unit[teamid] = {}

	--清除镜像信使
	local hero = TeamId2Hero(teamid)
	Timers:CreateTimer(1, function()
		if hero.mirror_chesser ~= nil then
			DestroyUnit(hero.mirror_chesser.pet2)
			hero.mirror_chesser.pet2 = nil

			DestroyUnit(hero.mirror_chesser)
			hero.mirror_chesser = nil
		end

		if hero.mirror_chesser_host ~= nil then
			DestroyUnit(hero.mirror_chesser_host)
			hero.mirror_chesser_host = nil
		end
	end)
end

function RestoreARound(teamid)
	if _G.is_game_ended == true then
		return
	end

	_G.restore_check = true
	ClearARound(teamid)

	Timers:CreateTimer(0.8, function()
		_G.restore_check = false
		for _, v in pairs(_G.mychess[teamid]) do
			local base_chess = GetChessBaseName(v.chess)
			local cost = GetChessCostByName(base_chess)
			local star = GetChessNameStar(v.chess) or 1
			if FindValueInTable(_G.chess_list_by_synergy['is_druid'],base_chess) == true and star == 3 then
				cost = cost - 1
			end
			local prob_table = {
				[1] = 90,
				[2] = 80,
				[3] = 70,
				[4] = 60,
				[5] = 50,
			}
			if cost and cost > 0 and RandomInt(1,100) < (prob_table[cost] or 40) and FindValueInTable(v.item,'item_feijiangxiaomao') == true and IsUndead(base_chess) == false and TeamId2Hero(teamid).ran_undead == nil and v.chess ~= 'chess_eh11' and string.find(v.chess,'chess_io') == nil then
			-- if v.is_ghost == true then
				local ran_undead = _G.chess_list_by_mana_black[cost]
				[RandomInt(1, table.maxn(_G.chess_list_by_mana_black[cost]))]
				local suffix = nil
				if star == 2 then
					suffix = '1'
				end
				if star == 3 then
					suffix = '11'
				end
				if ran_undead then
					EmitSoundOn("undead.resurrect", TeamId2Hero(teamid))
					if suffix then
						ran_undead = ran_undead .. suffix
					end
					TeamId2Hero(teamid).ran_undead = ran_undead
					if v.buy_price then
						TeamId2Hero(teamid).buy_price_undead = v.buy_price
					end
					--删除虚拟数组里已经被转化为亡灵的棋子
					_G.mychess[teamid][v.y .. '_' .. v.x] = nil
					for iii,vvv in pairs(v.item) do
						AddItemPlus(TeamId2Hero(teamid),vvv)
					end
					CheckChess(teamid)
				end
			else
				RestoreOneChess(v, teamid)
			end
		end
		if _G.is_tester_mode == true then
			for _, v in pairs(_G.yourchess[teamid]) do
				v.x = 9 - v.x
				v.y = 9 - v.y
				RestoreOneChess(v, teamid)
			end
		end
		Timers:CreateTimer(3.1, function()
			StatClassCount(teamid)
		end)
	end)
	CheckZombieChess()
end

--二维码弹窗保护：商城二维码弹窗打开期间，先不下发 show_draw_card，
--因为客户端收到它就会 open_panel_draw_card()，把商城页面顶掉；
--等玩家点了弹窗里的“刷新我的账户信息”（客户端会发 refresh_shop_v5）或者超过保护时间，再补发
QR_HOLD_SECONDS = 180
_G.qr_hold = _G.qr_hold or {}

--弹窗打开：登记/续期保护窗口，并启动 1 秒一次的检查定时器
function SetQrPopupHold(player_id)
	local st = _G.qr_hold[player_id] or {}
	st.expire_at = GameRules:GetGameTime() + QR_HOLD_SECONDS
	_G.qr_hold[player_id] = st
	if _G.qr_hold_timer_started ~= true then
		_G.qr_hold_timer_started = true
		Timers:CreateTimer(1, function()
			local now = GameRules:GetGameTime()
			for pid, one in pairs(_G.qr_hold) do
				if one.expire_at == nil or now >= one.expire_at then
					FlushQrHold(pid)
				end
			end
			return 1
		end)
	end
end

--缩短保护窗口（只会变短）：玩家已经关掉弹窗时用
function ShortenQrHold(player_id, seconds)
	local st = _G.qr_hold[player_id]
	if st == nil then
		return
	end
	local t = GameRules:GetGameTime() + (seconds or 4)
	if st.expire_at == nil or st.expire_at > t then
		st.expire_at = t
	end
end

function IsQrPopupHolding(player_id)
	local st = _G.qr_hold[player_id]
	if st == nil or st.expire_at == nil then
		return false
	end
	return GameRules:GetGameTime() < st.expire_at
end

--二维码弹窗被关掉了（客户端点×或者关掉商城）：立刻把保护窗口缩短，别让招募面板一直不刷新
function DAC:OnQrPopupClosed(keys)
	ShortenQrHold(keys.PlayerID, 2)
end

--把之前压住的 show_draw_card 补发出去
function FlushQrHold(player_id)
	local st = _G.qr_hold[player_id]
	if st == nil then
		return
	end
	_G.qr_hold[player_id] = nil
	if st.pending ~= nil and st.pending_team ~= nil then
		CustomGameEventManager:Send_ServerToTeam(st.pending_team, "show_draw_card", st.pending)
		print('[QR] flush held show_draw_card, player_id=' .. tostring(player_id))
	end
end

--统一从这里下发 show_draw_card：二维码弹窗开着时，系统自动抽卡先压住
function SendShowDrawCard(team_id, payload)
	local hero = TeamId2Hero(team_id)
	local player_id = hero and hero:GetPlayerID()
	if player_id ~= nil and payload ~= nil and IsQrPopupHolding(player_id) then
		--auto_unlock：只是解锁招募面板，客户端收到会直接 return，不会弹面板
		--unlock：玩家自己点的刷新/买卡补位，说明他正在用招募面板，不能压
		if payload.auto_unlock ~= true and payload.unlock ~= true then
			local st = _G.qr_hold[player_id]
			st.pending = payload
			st.pending_team = team_id
			print('[QR] hold show_draw_card, player_id=' .. tostring(player_id))
			return
		end
		--玩家主动操作：取消保护（压住的那份作废，直接发最新的）
		local st = _G.qr_hold[player_id]
		st.pending = nil
		st.pending_team = nil
		st.expire_at = 0
	end
	CustomGameEventManager:Send_ServerToTeam(team_id, "show_draw_card", payload)
end

--游戏循环1.2——抽卡用到的方法
function Draw5ChessAndShow(team_id, unlock, draw_type)
	--unlock==false表示是系统自动抽牌
	--draw_type；
	--1：表示抽5橙卡，
	-- -1：表示第二次机会带reroll的抽卡，
	--4：表示奇观轮（正常抽，但每个都随机一个它没有的种族/职业）
	--5：表示普通核心（现在用-1表示了）
	--6：抽冷门棋子
	local h = TeamId2Hero(team_id)
	if h.chesslock == true then
		SendShowDrawCard(h:GetTeam(), {
			key = GetClientKey(h:GetTeam()),
			chesses = h.curr_chess_table,
			curr_money = h:GetMana(),
			auto_unlock = true,
		})
		h.chesslock = false
		return
	end
	--D+：洗回的-->ban_chess_list
	--D++：ban_chess_list-->ban_chess_list2
	h.ban_chess_list2 = {}
	if h.ban_chess_list ~= nil then
		for _, chess in pairs(h.ban_chess_list) do
			if chess ~= nil then
				table.insert(h.ban_chess_list2, chess)
			end
		end
	end

	--把上次剩的洗回棋库
	h.ban_chess_list = {}
	if draw_type == nil and h:HasModifier('modifier_item_remainder_seeker') then 
		draw_type = 6
	end
	h.last_draw_type = h.draw_type
	h.draw_type = draw_type
	if h.curr_chess_table ~= nil then
		for _, chess in pairs(h.curr_chess_table) do
			if chess ~= nil and (h.last_draw_type == nil or h.last_draw_type == -1 or h.last_draw_type == 6) then
				table.insert(h.ban_chess_list, chess.chess)
				AddAChessToChessPool(chess.chess)
			end
		end
	end
	--把上上次的删掉
	h.curr_chess_table = {}
	--抽！

	local curr_chess_table = RandomNDrawChessNew(team_id, 5, unlock, draw_type)
	h.curr_chess_table = curr_chess_table

	--发给前端已有一星的棋子，亮灯用
	local level_one_chess = FindLevelOneChess(h)
	--服务器校验是否亮灯返还钱
	if h:HasModifier('modifier_item_free_draw') then
		local refund = true
		if level_one_chess then
			local level_one_chess_table = string.split(level_one_chess, ',')
			for _,chess in pairs(curr_chess_table) do 
				if FindValueInTable(level_one_chess_table,chess.chess) == true then
					refund = false
					h.unlucky_draw = nil
				end
			end
		end
		if refund == true then --招募没亮灯
			if h.unlucky_draw == nil then 
				h.unlucky_draw = 1
			else
				h.unlucky_draw = h.unlucky_draw + 1		
			end
			if RandomFloat(0,1) < 5/h.unlucky_draw then
				AddCourierMana(h,1)  --返还1金币
			else
				AddCourierMana(h,2)  --返还2金币
			end		
		end
	end
	h.level_one_chess = level_one_chess

	local lock = false
	if draw_type == 4 then
		lock = true
		h.chesslock = true
	end
	if draw_type == 1 then
		lock = true
		h.chesslock = true
	end

	-- UpdateMyMoney(team_id)
	SendShowDrawCard(team_id, {
		key = GetClientKey(team_id),
		chesses = curr_chess_table,
		level_one_chess = level_one_chess,
		-- curr_money = h:GetMana(),
		-- curr_rm_token = GetRMToken(h),
		draw_type = draw_type,
		unlock = unlock,
		lock = lock,
		reroll_status = h.draw_type,
	})
end

function GetRelicHistorySring(hero)
	local relic_history_table = GetStat(hero:GetPlayerID(), 'relic_history') or {}
	local relic_history = ''
	for _,v in pairs(relic_history_table) do
		if v and v.relic then
			relic_history = relic_history..v.relic..','
		end
	end
	return relic_history
end

--结算一名玩家，兼容1P和2P的模式
function PostOneToServer(hero, steamid, rank, mode)
	
	SetStat(hero:GetPlayerID(), 'rank', rank)
	local quest = _G.quest_status[hero:GetTeam()]
	local chess_lineup = GetStat(hero:GetPlayerID(), 'chess_lineup') or 0
	local total_money = GetStat(hero:GetPlayerID(), 'total_money') or 0
	local win_round = GetStat(hero:GetPlayerID(), 'win_round') or 0
	local lose_round = GetStat(hero:GetPlayerID(), 'lose_round') or 0
	local synergy = JoinTableString(GetStat(hero:GetPlayerID(), 'chess_synergies')) or ''
	local relic_history = GetRelicHistorySring(hero) or ''

	local send_steamid_list = _G.steamidlist
	if table.maxn(_G.thunder_user) > 0 then
		for _, kk in pairs(_G.thunder_user) do
			local xx = string.find(_G.steamidlist, kk)
			if xx then
				local xx1 = string.sub(_G.steamidlist, 0, xx - 1)
				local xx2 = string.sub(_G.steamidlist, xx + string.len(kk) + 1, string.len(_G.steamidlist))
				send_steamid_list = xx1 .. xx2
			end
		end
		if string.sub(send_steamid_list, string.len(send_steamid_list)) == ',' then
			send_steamid_list = string.sub(send_steamid_list, 1, string.len(send_steamid_list) - 1)
		end
	end
	local url = "http://autochess.ppbizon.com/game/post/one/@" ..
	send_steamid_list ..
	"@" ..
	steamid ..
	"@" ..
	rank ..
	"?hehe=" ..
	RandomInt(1, 10000) ..
	"&duration=" ..
	math.floor(GameRules:GetGameTime() - _G.START_TIME) ..
	GetSendKey() ..
	'&map=' ..
	(GetCurrMapInfo().map_name_real or GetCurrMapInfo().map_name) ..
	'&chess_lineup=' ..
	chess_lineup ..
	'&synergy=' ..
	synergy ..
	'&population=' .. hero:GetLevel() ..
	'&total_money=' .. total_money .. '&win_round=' .. win_round .. '&lose_round=' .. lose_round .. '&relic_history=' .. relic_history

	if hero.onduty_hero_long ~= nil then
		url = url .. '&onduty_courier=' .. hero.onduty_hero_long
	end

	local onduty_chessboard = GetChessboardInfo(hero:GetPlayerID())
	if onduty_chessboard ~= nil and onduty_chessboard.id ~= nil then
		url = url .. '&onduty_chessboard=' .. onduty_chessboard.id
	end

	if mode == 'p1' then
		url = url .. '&settings=' .. json.encode(_G.user_setting[steamid])
	else
		url = url ..
		'&mode=p2&teammate=' ..
		TeamId2Hero(GetP2Ally(hero:GetTeam())).steam_id .. '&settings=' .. json.encode(_G.user_setting[steamid])
	end
	if quest == true then
		url = url .. '&finish_quest=1'
	end
	if rank == 1 then 
		-- local timer_check = ''
		-- for r1,t1 in pairs(_G.timer_count) do 
		-- 	timer_check = timer_check.. r1..'|'..t1..'_'
		-- end
		local precache_check = ''
		for r2,t2 in pairs(_G.precache_count) do 
			precache_check = precache_check.. r2..'|'..t2..'_'
		end
		-- url = url .. '&timer_check='..timer_check
		-- url = url .. '&precache_check='..precache_check
	end
	--添加阵容价值和mvp棋子信息
	local max_lineup_value = GetStat(hero:GetPlayerID(), 'max_lineup_value') or 0
	local max_lineup_value_lineup = GetStat(hero:GetPlayerID(), 'max_lineup_value_lineup') or ''
	local mvp_chess_damage = GetStat(hero:GetPlayerID(), 'mvp_chess_damage') or 0
	local mvp_chess_name = GetStat(hero:GetPlayerID(), 'mvp_chess_name') or ''
	local mvp_chess_items = GetStat(hero:GetPlayerID(), 'mvp_chess_items') or ''
	local pandaman_getlist = GetStat(hero:GetPlayerID(), 'pandaman_getlist') or ''
	url = url .. '&max_lineup_value=' .. max_lineup_value .. '&max_lineup_value_lineup=' .. max_lineup_value_lineup .. '&mvp_chess_damage=' .. mvp_chess_damage .. '&mvp_chess_name=' .. mvp_chess_name .. '&mvp_chess_items=' .. mvp_chess_items..'&pandaman_getlist='..JoinTableString(pandaman_getlist)

	local tt = _G.stat_info[steamid]
	local total_team = _G.playing_player_count
	if _G.p2_mode == true then
		total_team = math.floor(_G.playing_player_count / 2)
	end
	--构建要发送的数据，一部分直接可以从_G.stat_info（tt）获得
	_G.send_info[steamid] = {
		account_id = steamid,
		rank = rank,
		total = total_team,
		level = tt['mmr_level'],
		candy = 0,
		biscuit = 0,
		chess = tt['chess_lineup'],
		win_round = tt['win_round'],
		lose_round = tt['lose_round'],
		kills = tt['kills'],
		deaths = tt['deaths'],
		gold = tt['gold'],
		duration = tt['duration'],
		total_money = tt['total_money'],
		ban_synergy = tt['ban_synergy'],
		relic_history = tt['relic_history'] or {},
		chess_item = GetChessItemTable(hero),
		talent_tree = tt['talent_tree'] or {},
	}

	SendHTTP(url .. "&from=SyncHP", function(t)
		if t ~= nil and t.err == 0 then
			local v = t.mmr_info
			if t.aws_key then
				_G.aws_key = t.aws_key
			end
			if _G.stat_info[v.userid] ~= nil then
				--另一部分要从http返回值v获得
				_G.send_info[v.userid]['account_id'] = v.userid
				_G.send_info[v.userid]['rank'] = v.rank
				_G.send_info[v.userid]['total'] = v.total
				_G.send_info[v.userid]['level'] = v.level
				_G.send_info[v.userid]['candy'] = v.candy or 0
				_G.send_info[v.userid]['candy_award'] = v.candy or 0
				_G.send_info[v.userid]['biscuit'] = v.biscuit or 0
				_G.send_info[v.userid]['chess'] = t.lineup_info.chess
				_G.send_info[v.userid]['buff'] = t.lineup_info.buff

				_G.stat_info[v.userid]['candy_award'] = v.candy or 0
				_G.stat_info[v.userid]['candy'] = v.candy or 0
				_G.stat_info[v.userid]['biscuit'] = v.biscuit or 0
				_G.stat_info[v.userid]['level_delta'] = v.level_delta or 0
				_G.stat_info[v.userid]['delta'] = v.mmr_delta or 0
				_G.stat_info[v.userid]['mmr_level'] = v.level
				_G.stat_info[v.userid]['queen_rank'] = v.queen_rank

				CustomGameEventManager:Send_ServerToAllClients("msg", {
					data = _G.send_info[v.userid]
				})

				_G.send_time = {
					end_time = t.end_time,
					year = t.year,
					month = t.month,
					date = t.date,
					hour = t.hour,
					minute = t.minute,
					second = t.second,
				}
				local totalrank = 1
				if mode == 'p1' then
					totalrank = _G.playing_player_count
				else
					totalrank = GetP2TeamCount()
				end
				CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "show_gameover", {
					key = GetClientKey(hero:GetTeam()),
					hehe = RandomInt(1, 100000),
					rank = v.rank,
					total_rank = v.total,
					level = v.level,
					candy = v.candy,
					biscuit = v.biscuit,
					mmr_delta = v.mmr_delta,
					level_delta = v.level_delta,
					queen_rank = v.queen_rank,
					mode = mode,
					exp_info = t.exp_info,
					lineup_info = t.lineup_info,
					quest_id = _G.egg_quest,
					quest_status = v.quest_status,
				})
				if mode == 'p1' and rank == 1 then
					local dur = GameRules:GetGameTime() - _G.START_TIME + 3

					SetStat(_G.steamid2playerid[hero.steam_id], 'duration', dur)
					SetStat(_G.steamid2playerid[hero.steam_id], 'round', _G.battle_round)
					--保存最终阵容
					local lineup = ''
					for _, v in pairs(_G.mychess[hero:GetTeam()]) do
						if v ~= nil and v.chess ~= nil then
							lineup = lineup .. v.chess .. ','
						end
					end
					SetStat(_G.steamid2playerid[hero.steam_id], 'chess_lineup', lineup)
					Timers:CreateTimer(0.2, function()
						local ready_2_post = false
						local ready_1_post = false
						for y, z in pairs(_G.send_info) do
							if z.rank == 1 then
								ready_1_post = true
							end
							if z.rank == 2 then
								ready_2_post = true
							end
						end
						--展示结束面板，结束游戏！
						Timers:CreateTimer(8, function()
							GameRules:SetGameWinner(hero:GetTeam())
							_G.setwin = 1
						end)
						Timers:CreateTimer(5, function()
							PostGame()
						end)
						if _G.aws_key == '' then
							prt('Game Finished...')
						end
						if ready_2_post == true and ready_1_post == true and _G.aws_key ~= '' then
							prt('Send Amazon Data')
							local t = _G.send_time
							local amzdate = string.format(
								'%s%s%sT%s%s%sZ',
								t.year, t.month, t.date, t.hour, t.minute, t.second
							)
							local datestamp = string.format(
								'%s%s%s',
								t.year, t.month, t.date
							)
							SendAmazonData(CollectAmazonData(dur), amzdate, datestamp)
						end
					end)
					EmitGlobalSound("DOTAMusic_Diretide_Finale")

					--提交阵容
					if table.maxn(_G.upload_lineup) > 0 then
						local str = ''
						for i, v in pairs(_G.upload_lineup) do
							str = str .. json.encode(v) .. '|'
						end
						str = string.sub(str, 1, -2)
						local url_up = "http://autochess.ppbizon.com/lineup/v2/add?lineups=" ..
						str .. "&bans=" .. _G.bans .. "&hehe=" .. RandomInt(1, 10000) .. GetSendKey()
						if _G.stat_info[steamid].mmr_level then
							url_up = url_up .. '&mmr_level=' .. _G.stat_info[steamid].mmr_level
						end
						local req_up = CreateHTTPRequestScriptVM("GET", url_up)
						req_up:SetHTTPRequestAbsoluteTimeoutMS(20000)
						req_up:Send(function(result)
							-- local t_up = json.decode(result["Body"])
							-- if t_up.err == 0 then
							-- 	prt('SAVE CLOUD LINEUP OK!')
							-- end
						end)
					end
				elseif mode == 'p2' and rank == 1 then
					local dur = GameRules:GetGameTime() - _G.START_TIME + 3
					SetStat(hero:GetPlayerID(), 'duration', dur)
					SetStat(hero:GetPlayerID(), 'round', _G.battle_round)
					--保存最终阵容
					local lineup = ''
					for _, v in pairs(_G.mychess[hero:GetTeam()]) do
						if v ~= nil and v.chess ~= nil then
							lineup = lineup .. v.chess .. ','
						end
					end
					SetStat(hero:GetPlayerID(), 'chess_lineup', lineup)
					--胜利队伍第一个人提交
					if _G.p2_win_settle == false then
						_G.p2_win_settle = true
						--胜利队伍第二个人提交
					else
						prt('2P END GAME')
						EmitGlobalSound("DOTAMusic_Diretide_Finale")
						local dur = GameRules:GetGameTime() - _G.START_TIME + 3
						SetStat(hero:GetPlayerID(), 'duration', dur)
						SetStat(hero:GetPlayerID(), 'round', _G.battle_round)

						Timers:CreateTimer(4, function()
							prt('Send Amazon Data')
							local t = _G.send_time
							local amzdate = string.format(
								'%s%s%sT%s%s%sZ',
								t.year, t.month, t.date, t.hour, t.minute, t.second
							)
							local datestamp = string.format(
								'%s%s%s',
								t.year, t.month, t.date
							)
							SendAmazonData(CollectAmazonData(dur, '2p'), amzdate, datestamp)
						end)
						--提交阵容
						if table.maxn(_G.upload_lineup) > 0 then
							local str = ''
							for i, v in pairs(_G.upload_lineup) do
								str = str .. json.encode(v) .. '|'
							end
							str = string.sub(str, 1, -2)
							local url_up = "http://autochess.ppbizon.com/lineup/add?lineups=" ..
							str .. "&hehe=" .. RandomInt(1, 10000) .. GetSendKey()
							if _G.stat_info[steamid].mmr_level then
								url_up = url_up .. '&mmr_level=' .. _G.stat_info[steamid].mmr_level
							end
							local req_up = CreateHTTPRequestScriptVM("GET", url_up)
							req_up:SetHTTPRequestAbsoluteTimeoutMS(20000)
							req_up:Send(function(result)
								local t_up = json.decode(result["Body"])
								if t_up.err == 0 then
									prt('SAVE CLOUD LINEUP OK!')
								end
							end)
						end
						-- 展示结束面板，结束游戏！
						Timers:CreateTimer(8, function()
							GameRules:SetGameWinner(hero:GetTeam())
							_G.setwin = 1
						end)
						Timers:CreateTimer(5, function()
							PostGame()
						end)
					end
				end
			end
		else
			prt('GAME POST FAILED...')
			--单独结算失败了，不应该结束游戏
			-- PostGame()
			-- Timers:CreateTimer(3,function()
			-- 	GameRules:SetGameWinner(hero:GetTeam())
			-- 	_G.setwin = 1
			-- end)


			local dur = GameRules:GetGameTime() - _G.START_TIME + 3
			SetStat(_G.steamid2playerid[hero.steam_id], 'duration', dur)
			SetStat(_G.steamid2playerid[hero.steam_id], 'round', _G.battle_round)
			--保存最终阵容
			local lineup = ''
			for _, v in pairs(_G.mychess[hero:GetTeam()]) do
				if v ~= nil and v.chess ~= nil then
					lineup = lineup .. v.chess .. ','
				end
			end
			SetStat(_G.steamid2playerid[hero.steam_id], 'chess_lineup', lineup)

			if rank == 1 then
				Timers:CreateTimer(8, function()
					GameRules:SetGameWinner(hero:GetTeam())
					_G.setwin = 1
				end)
				-- 展示结束面板，结束游戏！
				Timers:CreateTimer(5, function()
					PostGame()
				end)
			end
		end
	end, function(t)
		prt('GAME POST FAILED...')
		--单独结算失败了，不应该结束游戏
		-- PostGame()
		-- Timers:CreateTimer(3,function()
		-- 	GameRules:SetGameWinner(hero:GetTeam())
		-- 	_G.setwin = 1
		-- end)
		local dur = GameRules:GetGameTime() - _G.START_TIME + 3
		SetStat(_G.steamid2playerid[hero.steam_id], 'duration', dur)
		SetStat(_G.steamid2playerid[hero.steam_id], 'round', _G.battle_round)
		--保存最终阵容
		local lineup = ''
		for _, v in pairs(_G.mychess[hero:GetTeam()]) do
			if v ~= nil and v.chess ~= nil then
				lineup = lineup .. v.chess .. ','
			end
		end
		SetStat(_G.steamid2playerid[hero.steam_id], 'chess_lineup', lineup)

		if rank == 1 then
			Timers:CreateTimer(8, function()
				GameRules:SetGameWinner(hero:GetTeam())
				_G.setwin = 1
			end)
			-- 展示结束面板，结束游戏！
			Timers:CreateTimer(5, function()
				PostGame()
			end)
		end
	end)

	if rank == 1 then
		CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
			player_id = hero:GetPlayerID(),
			win_streak = hero.win_streak or 0,
			vip = hero.is_vip,
			onduty_hero = hero.onduty_hero,
			text = "notice_player_win",
			time_stamp = math.floor(GameRules:GetGameTime()),
			type = 'player_event',
			emoji = 12,
		})

		if RandomInt(1, 100) <= 50 then
			SayCheerBubble(hero:GetTeam(), nil, 'chicken', 1)
		end
		if RandomInt(1, 100) <= 50 then
			SayCheerBubble(hero:GetTeam(), nil, 'chicken', 4)
		end
		if RandomInt(1, 100) <= 50 then
			SayCheerBubble(hero:GetTeam(), nil, 'chicken', 7)
		end
	end

	print('[HEYBOX] player_state steam='..steamid..' state=eliminated round='.._G.battle_round..' rank='..rank)
	_G.player_state_table[hero:GetTeam()] = 'eliminated'
end

function SyncHP(hero)
	SetStat(hero:GetPlayerID(), 'hp', hero:GetHealth())
	if hero:GetHealth() < 100 and _G.battle_round <= 10 and _G.egg_quest == 'q010' then
		SetQuest(hero.team_id, false)
	end
	UpdatePlayerCurrRank()
	local table_for_ui = {}
	local table_for_nt = {}
	for tui, tuv in pairs(_G.stat_info) do
		table_for_ui[tui] = CopyTableAndRemoveProps(tuv,
			{ 'chess_lineup', 'chess_hand', 'chess_synergies', 'buff', 'show_buff' })
		table_for_nt[tui] = CopyTableAndWithProps(tuv, { 'curr_rank' })
	end
	CustomGameEventManager:Send_ServerToAllClients("user_panel_ranking", {
		table = table_for_ui,
	})
	CustomNetTables:SetTableValue("dac_table", "user_panel_ranking", { table = table_for_nt, hehe = RandomInt(1, 1000) })
	--同步ui血量
	CustomGameEventManager:Send_ServerToAllClients("sync_hp", {
		player_id = hero:GetPlayerID(),
		hp = hero:GetHealth(),
		hp_max = hero:GetMaxHealth(),
		mp = hero:GetMana(),
		level = hero:GetLevel(),
		win_streak = hero.win_streak,
		unit_index = hero:entindex(),
		courier_id = hero.onduty_hero,
		sync_hp_bar = true,
	})

	local courier_info = CustomNetTables:GetTableValue("player_id_table", "courier_" .. hero:GetPlayerID()) or {}
	courier_info['level'] = hero:GetLevel()
	courier_info['win_streak'] = hero.win_streak
	CustomNetTables:SetTableValue("player_id_table", 'courier_' .. hero:GetPlayerID(), courier_info)

	if _G.START_TIME == nil then
		return
	end
	SetStat(hero:GetPlayerID(), 'duration', GameRules:GetGameTime() - _G.START_TIME)
	SetStat(hero:GetPlayerID(), 'round', _G.battle_round)
	Timers:CreateTimer(0.3, function()
		if hero:IsAlive() == false or hero:GetHealth() <= 0 then
			SetPlayerDead(hero)
		end
	end)
end

function SetPlayerDead(hero)
	if _G.death[hero:GetTeam()] == true then
		return
	end
	_G.death[hero:GetTeam()] = true
	SetRankingState(hero)
	Timers:CreateTimer(0.5, function()
		DealFuneralAffairs(hero)
	end)

	CustomNetTables:SetTableValue("game_info", "death_team", _G.death)

	RemoveAllCheerCourier(hero:GetTeam())
end

function UnlockDestroyedPieces(hero)
	if hero.destroyed_pieces ~= nil then
		UnlockUnitPieceFromChessPool(hero.destroyed_pieces)
		for _, c in pairs(hero.destroyed_pieces) do
			--发个通知c
			CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
				player_id = hero:GetPlayerID(),
				win_streak = hero.win_streak or 0,
				vip = hero.is_vip,
				onduty_hero = hero.onduty_hero,
				text = "notice_chess_unlocked",
				time_stamp = math.floor(GameRules:GetGameTime()),
				chess = c,
				type = 'chess_event',
			})
		end
	end
end

--处理玩家后事
function DealFuneralAffairs(hero)
	--释放垄断
	UnlockDestroyedPieces(hero)

	if hero:IsAlive() == true then
		hero:ForceKill(false)
	end
	EmitSoundOn("diretide.sad", hero)
	Timers:CreateTimer(0.5, function()
		--保存最终阵容
		local lineup = ''
		local lineup_count = 0
		--统计这个死亡的玩家都有哪些装备
		local consumable_items = {}
		--把阵容洗回牌库
		for _, v in pairs(_G.mychess[hero:GetTeam()]) do
			if v ~= nil and v.chess ~= nil then
				-- if v.extra_synergy == nil or table.maxn(v.extra_synergy) == 0 then
				AddAChessToChessPool(v.chess)
				-- end
				if lineup_count < hero:GetLevel() then
					lineup = lineup .. v.chess .. ','
					lineup_count = lineup_count + 1
				end
			end
		end
		--把手牌洗回牌库
		if hero.hand_entities ~= nil then
			for i = 1, 8 do
				local unitname = ''
				if hero.hand_entities[i] ~= nil and hero.hand_entities[i]:IsNull() == false then
					local unit = hero.hand_entities[i]
					unitname = unit:GetUnitName()
					if unitname == 'egg' and unit.egg_chess ~= nil then
						local count = unit.egg_chess_count or 1
						local egg_chess = unit.egg_chess
						--把count个egg_chess洗回
						-- if unit.extra_synergy == nil or table.maxn(unit.extra_synergy) == 0 then
						for i = 1, count do
							AddAChessToChessPool(egg_chess)
						end
						-- end
					else
						-- if unit.extra_synergy == nil or table.maxn(unit.extra_synergy) == 0 then
						AddAChessToChessPool(unitname)
						-- end
						for slot = 0, 9 do
							if hero.hand_entities[i]:GetItemInSlot(slot) ~= nil then
								local name = hero.hand_entities[i]:GetItemInSlot(slot):GetAbilityName()
								if hero.hand_entities[i]:GetItemInSlot(slot):IsPermanent() == false then
									local charges = hero.hand_entities[i]:GetItemInSlot(slot):GetCurrentCharges() or 1
									for i = 1, charges do
										table.insert(consumable_items, name)
									end
								end
							end
						end
					end
				end
			end
		end
		SetStat(hero:GetPlayerID(), 'chess_lineup', lineup)
		--清理商店残留棋子
		if hero.curr_chess_table ~= nil then
			for _, chess in pairs(hero.curr_chess_table) do
				if chess ~= nil and chess.chess ~= nil and chess.money == 'gold' then
					AddAChessToChessPool(chess.chess)
				end
			end
		end

		for slot = 0, 9 do
			if hero:GetItemInSlot(slot) ~= nil then
				local name = hero:GetItemInSlot(slot):GetAbilityName()
				if hero:GetItemInSlot(slot):IsPermanent() == false then
					local charges = hero:GetItemInSlot(slot):GetCurrentCharges() or 1
					for i = 1, charges do
						table.insert(consumable_items, name)
					end
				end
				hero:RemoveItem(hero:GetItemInSlot(slot))
			end
		end
		Timers:CreateTimer(0.5, function()
			ClearTeamGround(hero:GetTeam())
			ClearHand(hero:GetTeam())
		end)
		--遗产
		local gg_item_count = 0
		local alive_player_count = 0
		local gg_item_table = {}
		for ai, av in pairs(_G.counterpart) do
			if _G.counterpart[ai] ~= -1 and hero:GetTeam() ~= ai then
				alive_player_count = alive_player_count + 1
			end
		end
		for _, gi in pairs(hero.item_got or {}) do
			if RandomInt(1, 100) < (alive_player_count * 5) and gi ~= 'item_shengjian' then
				local count = _G.ITEM_2_LEVEL[gi]
				if count then
					if count >= 4 then
						for ii = 1, count do
							local item_level_1 = _G.ITEM_FOOD_LIST[RandomInt(1, table.maxn(_G.ITEM_FOOD_LIST))]
							RandomDropOneGGItem(item_level_1, hero)
						end
					else
						RandomDropOneGGItem(gi, hero)
					end
				end
				gg_item_count = gg_item_count + 1
			end
		end

		for _, cv in pairs(consumable_items) do
			if RandomInt(1, 100) < (alive_player_count * 8) then
				RandomDropOneGGItem(cv, hero)
				gg_item_count = gg_item_count + 1
			end
		end
		--棺材本
		local guancai_money = math.floor(hero:GetMana() * (alive_player_count * 10) / 100)
		local lucky_team_table = {
			[6] = 0,
			[7] = 0,
			[8] = 0,
			[9] = 0,
			[10] = 0,
			[11] = 0,
			[12] = 0,
			[13] = 0,
		}
		local try_count = 0
		local money_left = guancai_money
		while try_count < 10000 and money_left > 0 do
			local random_team = RandomInt(6, 13)
			local h = TeamId2Hero(random_team)
			if h ~= nil and h:IsAlive() == true and random_team ~= hero:GetTeam() then
				lucky_team_table[random_team] = lucky_team_table[random_team] + 1
				money_left = money_left - 1
			end
			try_count = try_count + 1
		end
		for t, count in pairs(lucky_team_table) do
			if count > 0 then
				local position_to = CenterVector(t) + Vector(RandomInt(-400, 400), RandomInt(-400, 400), 0)
				DropMoneyBag(Vector(0, 0, 128), position_to, 300, (count or 1))
			end
		end
		ShowCombat({
			t = 'player_dead',
			player = hero:GetPlayerID(),
			num = gg_item_count,
			gold = guancai_money,
		})

		--给击杀者一个大红包
		local last_damaged_by_team = hero.last_damaged_by_team
		local win_round = math.floor(GetStat(hero:GetPlayerID(), 'win_round') / 2.0 + 0.5)

		if last_damaged_by_team ~= nil and last_damaged_by_team ~= hero:GetTeam() and win_round ~= nil and win_round > 0 then
			local position_to = CenterVector(last_damaged_by_team) + Vector(RandomInt(-400, 400), RandomInt(-400, 400), 0)
			DropMoneyBag(Vector(0, 0, 128), position_to, 100, (win_round or 1))
			AddTotalMoneyStat(hero:GetPlayerID(), (win_round or 1))

			ShowCombat({
				t = 'terminate',
				player = hero:GetPlayerID(),
				player2 = TeamId2Hero(last_damaged_by_team):GetPlayerID(),
				num = win_round,
			})
		end
	end)
end

--根据玩家存活情况结算刚刚战败的玩家hero
function SetRankingState(hero)
	_G.counterpart[hero:GetTeam()] = -1
	if GetAlivePlayerCount() == 1 and _G.playing_player_count == 1 then
		--1P单人模式，直接结束游戏
		_G.is_game_ended = true
		prt('GAME OVER')
		EmitGlobalSound("dac.season.gameover")
		PostGame()
		Timers:CreateTimer(3, function()
			GameRules:SetGameWinner(DOTA_TEAM_NEUTRALS)
		end)
		return
	end
	if _G.p2_mode == true and FindValueInTable(_G.p2_death_table, hero.p2team) == false then
		table.insert(_G.p2_death_table, hero.p2team)
	end

	local alive_player_count = GetAlivePlayerCount()

	if _G.p2_mode == true and alive_player_count >= 2 then
		--2P模式，剩余队伍>=1，正常结算
		local team_rank = nil
		for xx, yy in pairs(_G.p2_death_table) do
			if hero.p2team == yy then
				team_rank = GetP2TeamCount() + 1 - xx
			end
		end
		if team_rank ~= nil then
			if FindValueInTable(_G.send_status, hero.steam_id) == true then
				RemoveTableItem(_G.send_status, hero.steam_id)
				PostOneToServer(hero, hero.steam_id, team_rank, 'p2')
				local teammate = TeamId2Hero(GetP2Ally(hero:GetTeam()))
				if teammate ~= nil and FindValueInTable(_G.send_status, teammate.steam_id) == true then
					RemoveTableItem(_G.send_status, teammate.steam_id)
					PostOneToServer(teammate, teammate.steam_id, team_rank, 'p2')
				end
			end
		end
	end
	if _G.p2_mode == true and alive_player_count <= 2 then
		--2P模式，剩余队伍<=1，结算胜者（2个玩家），游戏结束
		if _G.p2_win_sent == true then
			return
		end
		_G.p2_win_sent = true
		_G.is_game_ended = true
		prt('GAME OVER')
		if alive_player_count > 0 then
			if _G.send_status[2] ~= nil then
				local steamid_2 = _G.send_status[2]
				RemoveTableItem(_G.send_status, steamid_2)
				local h_2 = PlayerId2Hero(_G.steamid2playerid[steamid_2])
				if _G.egg_quest == 'q002' and GetCurrMapInfo().map_name == 'ranked_2x4' then
					SetQuest(h_2.team_id, true)
				end
				PostOneToServer(h_2, steamid_2, 1, 'p2')
			end
			if _G.send_status[1] ~= nil then
				local steamid_1 = _G.send_status[1]
				RemoveTableItem(_G.send_status, steamid_1)
				local h_1 = PlayerId2Hero(_G.steamid2playerid[steamid_1])
				if _G.egg_quest == 'q002' and GetCurrMapInfo().map_name == 'ranked_2x4' then
					SetQuest(h_1.team_id, true)
				end
				PostOneToServer(h_1, steamid_1, 1, 'p2')
			end
		end
	end

	if alive_player_count >= 2 and _G.p2_mode ~= true and _G.playing_player_count > 1 then
		--1P多人模式，当前名次>=2，正常结算
		if FindValueInTable(_G.send_status, hero.steam_id) == true then
			RemoveTableItem(_G.send_status, hero.steam_id)
			PostOneToServer(hero, hero.steam_id, alive_player_count, 'p1')
		end
	end
	if alive_player_count <= 2 and _G.p2_mode ~= true and _G.playing_player_count > 1 then
		_G.is_game_ended = true
		--1P第一名
		if GetAlivePlayerCount() == 1 then
			local last_steamid = _G.send_status[1]
			local last_hero = PlayerId2Hero(_G.steamid2playerid[last_steamid])
			--TODO
			RemoveTableItem(_G.send_status, last_steamid)
			if _G.egg_quest == 'q001' and GetCurrMapInfo().map_name == 'ranked_1x8' then
				SetQuest(last_hero.team_id, true)
			end

			PostOneToServer(last_hero, last_steamid, 1, 'p1')
			
			Timers:CreateTimer(0.5,function()
				for iii,vvv in pairs(_G.send_info) do 
					print('[HEYBOX] result steam='..iii..' rank='..vvv.rank)
				end
			end)
			
			play_particle('particles/themed_fx/cny_fireworks_rockets_bsnd.vpcf', PATTACH_ABSORIGIN_FOLLOW, last_hero, 10)

			print('[HEYBOX] match_end winner='..last_steamid)
		end
		--为防止发送失败了，30秒后自动结束游戏
		Timers:CreateTimer(30, function()
			if _G.setwin == nil then
				GameRules:SetGameWinner(last_hero:GetTeam())
			end
		end)
	end
	--hero是刚刚战败的玩家
	if GetAlivePlayerCount() == 2 and _G.playing_player_count > 2 and _G.p2_mode ~= true and _G.battle_round <= 44 then
		--1P模式：决赛提醒
		_G.pilao_round = _G.battle_round + 6 --野怪关不算
		prt('#text_grand_final_start')
		-- EmitGlobalSound("diretide_eventstart_Stinger")
		EmitGlobalSound("dac.season.grandfinal")

		--给决赛双方添加一些观众
		-- for _,steam_id in pairs(_G.send_status) do
		-- 	local player_id = _G.steamid2playerid[steam_id]
		-- 	local team_id = _G.playerid2team[player_id]
		-- 	SummonCheerCourier(team_id,3)
		-- end
		-- if RandomInt(1,100) < 25 then
		-- 	SayCheerBubble(hero:GetTeam(), nil, 'grand_final', 3)
		-- end
		-- if RandomInt(1,100) < 25 then
		-- 	SayCheerBubble(hero:GetTeam(), nil, 'grand_final', 6)
		-- end
	end
end

function PostGame()
	CustomNetTables:SetTableValue("dac_table", "end_board", { data = _G.stat_info, hehe = RandomInt(1, 100000) })
end

function PostPlayerInfo()
	StatAllPlayerLineup()
	UpdateStatUI()
end

function LoadPVEEnemy(wave, team)
	local hero = TeamId2Hero(team)
	if hero:HasModifier('modifier_item_more_creep') then
		hero.is_more_creep = true
	else
		hero.is_more_creep = nil
	end
	if _G.battle_boss[wave] ~= nil and hero then
		for index, vi in pairs(_G.battle_boss[wave]) do
			if wave < 100 and index > 10 then
				if hero.is_more_creep then
					LoadOnePVEEnemy(vi, team)
				end
			else
				LoadOnePVEEnemy(vi, team)
			end
		end
	end
	Timers:CreateTimer(4.5, function()
		AddComboAbility(team)
	end)
end

function LoadOnePVEEnemy(vi, team)
	local animation_info = GetAnimation('n101')
	Timers:CreateTimer(RandomFloat(0, 0.9), function()
		--播放起始动画
		local ppp = ShowTPEffectAtPosition(XY2Vector(vi.x, vi.y, team), animation_info.tp_effect)

		Timers:CreateTimer(RandomFloat(0.1, 2.1), function()
			if ppp ~= nil then
				ParticleManager:DestroyParticle(ppp, true)
				ParticleManager:ReleaseParticleIndex(ppp)
			end
			_G.unit[team][vi.y .. '_' .. vi.x] = 1
			
			local x = CreateUnitByName(vi.enemy, XY2Vector(vi.x, vi.y, team), true, nil, nil, DOTA_TEAM_NEUTRALS)
			x:SetForwardVector(Vector(0, -1, 0))
			x.y_x = vi.y .. '_' .. vi.x
			x.y = vi.y
			x.x = vi.x
			x.team_id = 4
			x.at_team_id = team
			AddAbilityAndSetLevel(x, 'root_self')
			AddAbilityAndSetLevel(x, 'jiaoxie_wudi')
			table.insert(_G.to_be_destory_list[team], x)

			local hero = TeamId2Hero(team)
			if hero.is_more_creep then
				-- ModMaxHP({
				-- 	caster = x,
				-- 	per = -20,
				-- 	is_heal = false,
				-- })
				AddAbilityAndSetLevel(x, 'more_creep')
			end

			--复制物品
			if vi.item ~= nil then
				for _, it in pairs(vi.item) do
					x:AddItemByName(it)
				end
			end

			--播放后续动画
			if animation_info.tp_sound ~= nil then
				EmitSoundOn(animation_info.tp_sound, x)
			end
			if animation_info.animation_modifier ~= nil then
				BlinkChessX({ caster = x, blink_type = animation_info.animation_modifier })
			end
		end)
	end)
end

--pve野怪敌人死亡，掉落战利品/金钱
function DropItem(unit)
	if (unit:GetTeam() == 4 or unit.ori_team == 4) and string.find(unit:GetUnitName(), 'pve') ~= nil and unit.is_summoned ~= true and unit.no_drop ~= true then
		--pve敌人击杀者得钱
		local hero = TeamId2Hero(unit.at_team_id or unit.team_id or unit.ori_team)
		local drop_money = GetHitDamage(unit)
		if hero ~= nil then
			AddCourierMana(hero, drop_money, false)
			AddTotalMoneyStat(hero:GetPlayerID(), drop_money)
			AMHC:CreateNumberEffect(unit, drop_money, 3, AMHC.MSG_MISS, { 255, 255, 0 }, 0)
			AMHC:CreateParticle("particles/generic_gameplay/rune_bounty_owner.vpcf", PATTACH_OVERHEAD_FOLLOW, false, unit,
				5)

			--掉装备
			local unit_level = GetLevel(unit)

			if unit_level <= 2 or unit.is_summoned == true then
				return
			end

			local ran = RandomInt(1, 100)
			local item_count = 0
			local curr_per = 0

			if _G.drop_item_gailv[unit_level] ~= nil then
				for per, lv in pairs(_G.drop_item_gailv[unit_level]) do
					if ran >= per and curr_per <= per then
						curr_per = per
						item_count = lv
					end
				end
			end
			if item_count == 0 then
				if hero.undrop_item_count == nil then
					hero.undrop_item_count = 0
				end
				hero.undrop_item_count = hero.undrop_item_count + 1
			end
			if hero.undrop_item_count and hero.undrop_item_count >= 5 then
				--第五个>2的野怪不掉就必掉一个1级
				item_count = 1
			end
			if item_count > 5 then
				item_count = 5
			end
			if item_count > 0 then
				--掉
				-- for ii=1,item_count do
				-- local i = _G.ITEM_FOOD_LIST[RandomInt(1,table.maxn(_G.ITEM_FOOD_LIST))]
				local i = _G.ITEM_LIST_BY_LEVEL[item_count][RandomInt(1, table.maxn(_G.ITEM_LIST_BY_LEVEL[item_count]))]

				if hero:HasModifier('modifier_item_double_lootbox') == true then
					--绿皮船长的宝藏
					i = 'item_lootbox_lv' .. item_count
				end

				local newItem = CreateItem(i, hero, hero)
				local drop = CreateItemOnPositionForLaunch(unit:GetAbsOrigin(), newItem)
				local dropRadius = RandomFloat(50, 200)
				newItem:SimulateLaunchLoot(unit:GetAbsOrigin() +
				Vector(RandomFloat(-100, 100), RandomFloat(-100, 100), 0))

				hero.undrop_item_count = 0
				if string.find(i, 'item_relicbox') == nil and string.find(i, 'item_lootbox') == nil then
					AddItemGot(hero, i)
				end
				-- end
			end

			if unit:GetUnitName() == 'pve_roshan' then
				local newItem = CreateItem('item_buxiuzhishouhu', hero, hero)
				local drop = CreateItemOnPositionForLaunch(unit:GetAbsOrigin(), newItem)
				local dropRadius = RandomFloat(50, 200)
				newItem:SimulateLaunchLoot(unit:GetAbsOrigin() +
				Vector(RandomFloat(-100, 100), RandomFloat(-100, 100), 0))
			end
		end
	end
end

function DropItemAppointed(hero, unit, item, no_effect)
	-- hero:AddItemByName(item)
	local newItem = CreateItem(item, hero, hero)
	local drop = CreateItemOnPositionForLaunch(unit:GetAbsOrigin(), newItem)
	local dropRadius = RandomFloat(10, 100)
	if unit == nil or unit:IsNull() == true or unit:GetAbsOrigin() == nil then
		unit = hero
	end
	-- newItem:SimulateLaunchLoot(false,200,0.75,unit:GetAbsOrigin() + Vector(RandomFloat( -100, 100 ),RandomFloat( -100, 100 ),0))
	newItem:SimulateLaunchLoot(unit:GetAbsOrigin() + Vector(RandomFloat(-100, 100), RandomFloat(-100, 100), 0), no_effect)
end

