			-- 	local max_hp = u:GetMaxHealth()
			-- 	if 1.0*hp/max_hp > 0.3 then
			-- 		u.is_monk_escaped = nil
			-- 		u.is_monk_escaping = nil
			-- 	end
			-- end
			--判断牧师被近身状态的变化
			-- local enemy_team_id = 4
			-- if u:GetTeam() == 4 then
			-- 	enemy_team_id = u.at_team_id
			-- end
			-- if u.is_priest_escaping == true and IsLonely4Team(u,enemy_team_id) == true then
			-- 	u.is_priest_escaping = nil 	
			-- end

			--【优先级4：攻击】决定是否要攻击
			if IsChessCanAttack(u) == true and u:HasModifier('modifier_is_centaur_buff') == false then
				if IsChannelingWalk(u) == false then
					local attack_result = FindAClosestEnemyAndAttack(u)
					if attack_result ~= nil and attack_result > 0 then
						return attack_result + ai_delay
					end
				end
			end

			--【优先级5：移动】不攻击就走动
			if u.stop_moving ~= true and IsChessCanMove(u) == true then
				local find_ok = nil
				local try_count = 0
				local blink_type = 'run'

				--寻路
				if (u:HasModifier('modifier_queenofpain_sonic_wave_chaos_debuff') or u:HasModifier('modifier_lion_voodoo') or u:HasModifier('modifier_is_satyr_debuff')) then
					--混乱，随机走动
					find_ok = FindRandomEmptyGridAtUnit(u, false)
					blink_type = 'run'
				elseif IsChannelingWalk(u) == true and u:HasModifier('modifier_is_centaur_buff') == false then
					if u:HasModifier('modifier_is_centaur_buff_plus') and u:HasAbility('is_centaur_buff') then
						--4半人马
						u:FindAbilityByName('is_centaur_buff'):ApplyDataDrivenModifier(u, u, 'modifier_is_centaur_buff',
							{})
						return 0.2
					end
					--剑圣、老鹿等，在释放技能的时候，走向最近的临近敌人的空格子
					find_ok = FindNearestChannelingWalkPosition(u)
				elseif u.has_assassin_blink == true then
					--背刺跳跃
					if not IsChessCanMove(u, true) then
						return 0.2
					end
					RemoveAbilityAndModifier(u, 'jiaoxie_wudi')
					RemoveAbilityAndModifier(u, 'jiaoxie')
					if u:HasModifier('modifier_is_centaur_buff') then
						local aaa = GetChessAbility(u)
						local rrr = u:FindAbilityByName(aaa):GetSpecialValueFor('radius') or 200
						find_ok = FindNextCentaurPosition(u, rrr)
						blink_type = 'run'
						u.has_assassin_blink = nil
						InitAssassinJump(u)
						return 0.2
					else
						find_ok = FindAssassinJumpPosition(u)
						-- blink_type = 'jump'
						if find_ok then
							local x = Vector2X(find_ok, u.at_team_id or u.team_id)
							local y = Vector2Y(find_ok, u.at_team_id or u.team_id)
							local xx = u.x
							local yy = u.y
							_G.unit[u.at_team_id or u.team_id][y .. '_' .. x] = 1
							u:SetAbsOrigin(find_ok)
							u.y_x = y .. '_' .. x
							u.y = y
							u.x = x
							_G.unit[u.at_team_id or u.team_id][yy .. '_' .. xx] = nil

							play_particle("particles/units/heroes/hero_queenofpain/queen_blink_start.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)
							EmitSoundOn("DOTA_Item.BlinkDagger.Activate", u)
							u.is_moved = true
							u.has_assassin_blink = nil
							InitAssassinJump(u)
							return 0.2
						end
					end
				elseif u:HasModifier('modifier_is_centaur_buff') then
					--半人马冲锋
					local aaa = GetChessAbility(u)
					local rrr = u:FindAbilityByName(aaa):GetSpecialValueFor('radius') or 200
					find_ok = FindNextCentaurPosition(u, rrr)
					u.check_end_pos = find_ok
				elseif u:HasModifier('modifier_is_centaur_buff_plus') then
					--4半人马
					if not u:HasAbility('is_centaur_buff') then
						u:AddAbility('is_centaur_buff')
					end
					u:FindAbilityByName('is_centaur_buff'):ApplyDataDrivenModifier(u, u, 'modifier_is_centaur_buff', {})
					return 0.2
				else
					--正常行走：走向最近的能攻击到敌人的格子
					find_ok = FindNextSkipPosition(u)
				end

				-- if find_ok ~= nil then
				-- 	if HasShoes(u) then
				-- 		blink_type = 'jump'
				-- 	elseif blink_type == 'run' then
				-- 		local pos1 = XY2Vector(u.x,u.y,u.at_team_id or u.team_id)
				-- 		if (find_ok - pos1):Length2D() > 128*3 then
				-- 			find_ok = (find_ok - pos1):Normalized() * 128 * 3 + pos1
				-- 		end
				-- 	end
				-- end

				if find_ok ~= nil then
					if HasShoes(u) and u:HasModifier("modifier_is_centaur_buff") == false then
						blink_type = 'jump'
					end
					--走！
					local x = Vector2X(find_ok, u.at_team_id or u.team_id)
					local y = Vector2Y(find_ok, u.at_team_id or u.team_id)
					local xx = u.x
					local yy = u.y
					_G.unit[u.at_team_id or u.team_id][y .. '_' .. x] = 1
					u:SetForwardVector((find_ok - u:GetAbsOrigin()):Normalized())
					u.is_moving = true
					BlinkChessX({
						p = find_ok,
						caster = u,
						blink_type = blink_type,
						set_forward = true,
					})
					u.y_x = y .. '_' .. x
					u.y = y
					u.x = x
					_G.unit[u.at_team_id or u.team_id][yy .. '_' .. xx] = nil

					if u:HasModifier("modifier_is_centaur_buff") then
						if u:HasModifier('modifier_bloodseeker_thirst') == false then
							u:AddNewModifier(u, nil, "modifier_bloodseeker_thirst", nil)
						end
						u.centaur_rushing = true
						local speed = u:GetIdealSpeed()
						local duration = (find_ok - u:GetAbsOrigin()):Length2D() / speed
						Timers:CreateTimer(duration + 0.5, function()
							u.centaur_rushing = false
							u:RemoveModifierByName("modifier_is_centaur_buff")
							u:RemoveModifierByName("modifier_bloodseeker_thirst")
						end)
					end
					u.is_moved = true

					return 0.5
				else
					if u:HasModifier("modifier_is_centaur_buff") then
						u.centaur_rushing = false
						u:RemoveModifierByName("modifier_is_centaur_buff")
						u:RemoveModifierByName("modifier_bloodseeker_thirst")
					end
				end
			end
			if u:HasModifier("modifier_is_centaur_buff") then
				u.centaur_rushing = false
				u:RemoveModifierByName("modifier_is_centaur_buff")
				u:RemoveModifierByName("modifier_bloodseeker_thirst")
			end

			--无事可做，挂机
			return RandomFloat(0.3, 0.5) + ai_delay
		end)
	end
end

function StartGame()
	for i = 6, 13 do
		CustomGameEventManager:Send_ServerToTeam(i, "receive_client_key", {
			key = GetClientKey(i),
			hehe = RandomInt(1, 100000),
		})
	end

	Timers:CreateTimer(function()
		for i = 6, 13 do
			local h1 = TeamId2Hero(i)
			if h1 ~= nil and h1:IsNull() == false then
				if IsUnitExist(h1) == true then
					AddFOWViewer(i, Entities:FindByName(nil, "center" .. (i - 6)):GetOrigin(), 1000, 3, true)
				end
				local open_fog = _G.user_setting[h1.steam_id]['is_fog_show']
				open_fog = 1
				if open_fog and tonumber(open_fog) ~= 1 then
					for j = 0, 11 do
						local hero = TeamId2Hero(j + 6)
						if hero ~= nil and IsUnitExist(hero) == true then
							AddFOWViewer(i, Entities:FindByName(nil, "center" .. j):GetOrigin(), 1000, 3, false)
						end
					end
				end
			end
		end
		return 2
	end)
	--5秒后开始游戏
	Timers:CreateTimer(5, function()
		if _G.playing_player_count == 1 then
			prt('#tips_1_player')
		else
			prt('GAME START!')
		end

		--初始化棋子库
		InitChessPool(_G.playing_player_count)

		EnableBanChess()

		_G.START_TIME = GameRules:GetGameTime()
		StartAPrepareRound()
	end)
	ShowLuaPing()
end

function GameOver()
	_G.is_game_ended = true
	if _G.ended == false then
		CustomNetTables:SetTableValue("dac_table", "curtain_tips", { text = "#gameover", hehe = RandomInt(1, 1000) })
		CustomNetTables:SetTableValue("dac_table", "game_over", { text = "#gameover", hehe = RandomInt(1, 1000) })

		local win_team = 2
		if _G.good_castle.hp > 0 then
			win_team = 2
		end
		if _G.bad_castle.hp > 0 then
			win_team = 3
		end

		for i, v in pairs(_G.hero) do
			if v.team == win_team then
				v:AddAbility('gameover_win')
				v:FindAbilityByName('gameover_win'):SetLevel(1)
			else
				v:AddAbility('gameover_lose')
				v:FindAbilityByName('gameover_lose'):SetLevel(1)
			end
		end

		_G.ended = true
		-- EmitGlobalSound("Loot_Drop_Stinger_Arcana")

		GameRules:SendCustomMessage('gameover', 0, 0)

		Timers:CreateTimer(2, function()
			CalScore()
		end)
	end
end

--【底层方法】
function IsValueInTable(value, table)
	for k, v in pairs(table) do
		if v == value then
			return true
		end
	end
	return false
end

function FindValueInTable(tbl, value)
	if tbl == nil then
		tbl = {}
	end
	local found = false
	for i, v in pairs(tbl) do
		if v == value then
			found = true
		end
	end
	return found
end

function CopyTableAndWithProps(origin_table, props_table)
	local new_table = {}
	if origin_table ~= nil then
		for k, v in pairs(origin_table) do
			if FindValueInTable(props_table, k) == true then
				new_table[k] = v
			end
		end
		return new_table
	else
		return {}
	end
end

function CopyTableAndRemoveProps(origin_table, props_table)
	local new_table = {}
	if origin_table ~= nil then
		for k, v in pairs(origin_table) do
			if FindValueInTable(props_table, k) == false then
				new_table[k] = v
			end
		end
		return new_table
	else
		return {}
	end
end

function CopyTable(origin_table)
	local new_table = {}
	if origin_table ~= nil then
		for k, v in pairs(origin_table) do
			table.insert(new_table, v)
		end
		return new_table
	else
		return {}
	end
end

function AddTable(origin_table, add_table)
	if origin_table == nil then
		origin_table = {}
	end
	if add_table == nil then
		add_table = {}
	end
	for k, v in pairs(add_table) do
		table.insert(origin_table, v)
	end
	return origin_table
end

function CombineTable(origin_table, add_table, is_quchong)
	if origin_table == nil then
		origin_table = {}
	end
	if add_table == nil then
		add_table = {}
	end
	local result = {}
	for k, v in pairs(origin_table) do
		if is_quchong ~= true or FindValueInTable(result, v) == false then
			table.insert(result, v)
		end
	end
	for k, v in pairs(add_table) do
		if is_quchong ~= true or FindValueInTable(result, v) == false then
			table.insert(result, v)
		end
	end
	return result
end

function DiffTable(big_table, small_table)
	local temp_table = {}
	for k, v in pairs(big_table) do
		table.insert(temp_table, v)
	end
	for k1, v1 in pairs(small_table) do
		RemoveOneValueInTable(temp_table, v1)
	end
	if table.maxn(temp_table) > 0 then
		return temp_table
	else
		return {}
	end
end

function RemoveOneKeyInTable(tbl, key)
	local new_table = {}
	for i, v in pairs(tbl) do
		if i ~= key then
			new_table[i] = v
		end
	end
	tbl = nil
	return new_table
end

function RemoveOneValueInTable(tbl, value)
	if tbl == nil or type(tbl) ~= 'table' then
		return
	end
	local max = table.maxn(tbl)
	for i = max, 1, -1 do
		if value == tbl[i] then
			table.remove(tbl, i)
			return true
		end
	end
	return false
end

function RemoveFirstKeyInTable(tbl)
	local new_table = {}
	local is_first = true
	for i, v in pairs(tbl) do
		if is_first == true then
			is_first = false
		else
			new_table[i] = v
		end
	end
	tbl = nil
	return new_table
end

