			-- end
			-- lastdx = dx
			-- lastdy = dy
			-- lastx = node.x
			-- lasty = node.y
			-- lastd = d
		end
	else
		--没找到路
		return nil
	end

	-- 	--找到路了
	-- 	for _,node in pairs(pppp) do
	-- 		if node.x ~= startx or node.y ~= starty then

	-- 			-- if node.x > startx + 1 then
