	-- 				table.insert(ban_table[syn], chs)
	-- 			end
	-- 		end
	-- 	end
	-- end

	for syn, chs_list in pairs(ban_table) do
		_G.ban_chess_list[syn] = {
			chess_list = CopyTable(chs_list),
