function IsUnitExist(u, ignore_dead)
	if u == nil or u:IsNull() == true or type(u) ~= 'table' or (u:GetClassname() ~= 'npc_dota_creature' and u:GetClassname() ~= 'npc_dota_hero_wisp') then
		-- print(type(u)..': '..u:GetClassname())
		return false
	end
	if (ignore_dead or u:IsAlive() == true) and u.is_removing ~= true then
		--and u:GetClassname()=='npc_dota_creature'
		return true
	else
		return false
	end
end

function ApplyDamageDelay(keys)
	local caster = keys.caster
	local damage = keys.damage or 1
	local damage_type = keys.damage_type or DAMAGE_TYPE_MAGICAL
	local delay = keys.delay or 0
	local victim = keys.victim
	local ability = keys.ability
	local p = keys.p

	Timers:CreateTimer(delay, function()
		if victim ~= nil and victim:IsNull() == false and victim:IsAlive() == true then
			ApplyDamage({
				victim = victim,
				attacker = caster,
				damage_type = damage_type,
				damage = damage,
				ability = ability,
			})
			if p ~= nil then
				play_particle(p, PATTACH_ABSORIGIN_FOLLOW, victim, 3)
			end
		end
	end)
end

function IsHexxed(u)
	if IsUnitExist(u) == false then
		return false
	end
	if u:FindModifierByName('modifier_hexxed') ~= nil then
		return true
	end
	if u:FindModifierByName('modifier_shadow_shaman_voodoo') ~= nil then
		return true
	end
	if u:FindModifierByName('modifier_lion_voodoo') ~= nil then
		return true
	end
	return false
end

function SetNotAfk(h)
	if IsUnitExist(h) and h.check_afk then
		h.check_afk = nil

		_G.connect_state[h:GetPlayerID()] = true
	end
end

