function IsAttackLowPriority(unit)
	if unit:FindModifierByName('modifier_dazzle_bozang') ~= nil and unit:GetHealth() < 10 then
		return true
	elseif unit:FindModifierByName('modifier_siren_song_debuff') ~= nil then
		return true
	elseif unit:FindModifierByName('modifier_winter_wyvern_cold_embrace') ~= nil then
		return true
	elseif unit:FindModifierByName('modifier_muerta_pierce_the_veil_buff') ~= nil then
		return true
	elseif unit:FindModifierByName('modifier_invisible_to_enemy') ~= nil then
		return true
	elseif unit:IsInvulnerable() == true then
		return true
	elseif unit:HasAbility('is_wizard') == true then
		return true
	else
		return false
	end
end

--显示caster头顶的miss，默认是红色
function ShowMiss(keys)
	local u = keys.caster
	local color = keys.color or Vector(255, 32, 32)
	if u == nil then
		return
	end
	if u.miss_particle ~= nil then
		ParticleManager:DestroyParticle(u.miss_particle, true)
		u.miss_particle = nil
		u.miss_particle_id = nil
	end
	local pos = PATTACH_ABSORIGIN_FOLLOW
	local pp = ParticleManager:CreateParticle('effect/miss/1.vpcf', pos, u)

	ParticleManager:SetParticleControl(pp, 0, u:GetOrigin())
	ParticleManager:SetParticleControl(pp, 3, color)
	ParticleManager:SetParticleControl(pp, 4, Vector(5, 0, 0))

	local id = RandomFloat(1, 10000)
	u.miss_particle = pp
	u.miss_particle_id = id

	Timers:CreateTimer(5, function()
		if u.miss_particle ~= nil and u.miss_particle_id == id then
			ParticleManager:DestroyParticle(u.miss_particle, true)
			ParticleManager:ReleaseParticleIndex(u.miss_particle)
			u.miss_particle = nil
			u.miss_particle_id = nil
		end
	end)

	--9精灵：闪避幻象
	local target = u:GetAttackTarget()
	--target是被攻击者（闪避者）
	-- if IsUnitExist(target) == true and target:GetHealth() > 0 and (target.elf_illusion == nil or IsUnitExist(target.elf_illusion) == false ) then
	if IsUnitExist(target) == true and target:GetHealth() > 0 then
		if target:FindModifierByName('modifier_is_elf_buff_plus_plus') ~= nil and target:FindAbilityByName('is_elf_buff_plus_plus') ~= nil and target:FindAbilityByName('is_elf_buff_plus_plus'):IsCooldownReady() == true then
			-- target.elf_illusion = target
			play_particle("particles/units/heroes/hero_mirana/mirana_moonlight_ray.vpcf", PATTACH_ABSORIGIN_FOLLOW,
				target, 2)
			-- EmitSoundOn("Hero_Dark_Seer.Ion_Shield_end", target)
			target:FindAbilityByName('is_elf_buff_plus_plus'):StartCooldown(5)

			Timers:CreateTimer(0.1, function()
				if IsUnitExist(target) == true and target:GetHealth() > 0 then
					-- local items = GetAllItemsAndCDInUnits({ [1] = u })

					if target:HasAbility('dac_guai_base') == true then
						--隐形
						target:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(target, target,
							'modifier_base_invisible', { duration = 1.0 })
					end
					SummonMinion(target, u:GetUnitName(), 1, nil, function(w)
						local hp_set = u:GetHealth()
						if hp_set < 1 then hp_set = 1 end
						w:SetHealth(hp_set)
						w:AddNewModifier(w, nil, "modifier_illusion", { duration = 7 })
						w.is_mirror = true
						w:SetMaxMana(0)
						target.elf_illusion = w
						-- if items ~= nil then
						-- 	GiveItems2Unit(items, w)
						-- end
						FillEmptySlot(w)
						-- ExtendBeastBuff(w,target,false,false)

						if GetChessAbility(w) ~= nil then
							local a, a_level = GetChessAbility(w)

							if w:FindAbilityByName(a) == nil then
								AddAbilityAndSetLevel(w, a, a_level)
							else
								w:FindAbilityByName(a):SetLevel(a_level)
							end
						end
					end)
				end
			end)
		end
	end
end

function AllocateABattleRoundV3()
	local finished = false
	local trytime = 0

	_G.last_3rd_round = _G.last_2nd_round
	_G.last_2nd_round = _G.last_round
	_G.last_round = _G.current_round

	while trytime < 10000 and finished == false do
		trytime = trytime + 1
		_G.current_round = {}

		local alive_player_count = 0
		--统计玩家死活
		for u, v in pairs(_G.counterpart) do
			if TeamId2Hero(u) ~= nil and TeamId2Hero(u):IsNull() == false and TeamId2Hero(u):IsAlive() == true then
				--活玩家
				_G.counterpart[u] = u
				alive_player_count = alive_player_count + 1
			else
				--死玩家
				_G.counterpart[u] = -1
			end
		end

		local rann = 0
		if alive_player_count <= 1 then
			rann = 0
		elseif alive_player_count == 2 then
			rann = 1
		else
			rann = RandomInt(1, alive_player_count - 1)
		end
		--给活玩家分配一个随机对手
		for rotate_count = 1, rann do
			for i, j in pairs(_G.counterpart) do
				if j ~= -1 then
					local aliveteam = j

					local try_count = 0
					while (aliveteam == j or _G.counterpart[aliveteam] == nil or _G.counterpart[aliveteam] == -1) and try_count < 10000 do
						aliveteam = aliveteam + 1
						if aliveteam > 13 then
							aliveteam = 6
						end
						try_count = try_count + 1
					end
					_G.counterpart[i] = aliveteam
				end
			end
		end

		for ii, jj in pairs(_G.counterpart) do
			if jj ~= -1 then
				table.insert(_G.current_round, ii * 100 + jj)
			end
		end

		finished = true
		for i, v in pairs(_G.current_round) do
			if alive_player_count >= 7 then
				if IsValueInTable(v, _G.last_round) == true or IsValueInTable(v, _G.last_2nd_round) == true or IsValueInTable(v, _G.last_3rd_round) == true then
					finished = false
				end
			elseif alive_player_count >= 5 then
				if IsValueInTable(v, _G.last_round) == true or IsValueInTable(v, _G.last_2nd_round) == true then
					finished = false
				end
			elseif alive_player_count >= 3 then
				if IsValueInTable(v, _G.last_round) == true then
					finished = false
				end
			elseif alive_player_count >= 1 then
				finished = true
			else
				return
			end
		end
	end
end

function RemoveMovingModifier(unit)
	if HasMovingModifier(unit) == true then
		unit:RemoveModifierByName("modifier_jump")
		unit:RemoveModifierByName("modifier_run")
		unit:RemoveModifierByName("modifier_elfrun")
		unit:RemoveModifierByName("modifier_tuitui")
		unit:RemoveModifierByName("modifier_gungun")
		unit:RemoveModifierByName("modifier_toss")
		unit:RemoveModifierByName("modifier_hook")
		unit:RemoveModifierByName("modifier_breaksoil")
	end
end

function HasMovingModifier(unit)
	if unit:HasModifier("modifier_jump") or unit:HasModifier("modifier_run") or unit:HasModifier("modifier_tuitui") or unit:HasModifier("modifier_elfrun") or unit:HasModifier("modifier_gungun") or unit:HasModifier("modifier_toss") or unit:HasModifier("modifier_hook") or unit:HasModifier("modifier_breaksoil") or unit:HasModifier("modifier_primal_beast_pulverize_lua_debuff") then
		return true
	else
		return false
	end
end

function ChangeUnitPosition(unit, new_position, is_immediately)
	local team_id = unit.at_team_id or unit.team_id
	local old_position = unit:GetAbsOrigin()
	local old_y = unit.y
	local old_x = unit.x
	local old_y_x = unit.y_x
	local new_y = Vector2Y(new_position, team_id)
	local new_x = Vector2X(new_position, team_id)
	local new_y_x = new_y .. '_' .. new_x

	_G.unit[team_id][old_y_x] = nil
	_G.unit[team_id][new_y_x] = 1
	unit.y_x = new_y_x
	unit.y = new_y
	unit.x = new_x

	if is_immediately == true then
		-- Timers:CreateTimer(delay or 0, function()
		RemoveMovingModifier(unit)
		unit:SetOrigin(XY2Vector(new_x, new_y, team_id))
		-- end)
	end
end

function SwapUnitsPosition(caster, target_table, position_table)
	local chessboard_id = caster.at_team_id or caster.team_id

	for index, target in pairs(target_table) do
		_G.unit[chessboard_id][target.y_x] = nil
	end

	for index, target in pairs(target_table) do
		if index == 1 then
			RemoveRoot(caster)
			--播放特效
			local caster_pfx = ParticleManager:CreateParticle(
			"particles/units/heroes/hero_vengeful/vengeful_nether_swap.vpcf", PATTACH_ABSORIGIN, caster)
			ParticleManager:SetParticleControlEnt(caster_pfx, 0, caster, PATTACH_POINT_FOLLOW, "attach_hitloc",
				caster:GetAbsOrigin(), true)
			ParticleManager:SetParticleControlEnt(caster_pfx, 1, target, PATTACH_POINT_FOLLOW, "attach_hitloc",
				target:GetAbsOrigin(), true)
			local pos0 = target:GetAbsOrigin()
			local x0 = Vector2X(pos0, chessboard_id)
			local y0 = Vector2Y(pos0, chessboard_id)

			caster.y_x = y0 .. '_' .. x0
			caster.y = y0
			caster.x = x0
			caster:SetAbsOrigin(pos0)

			_G.unit[chessboard_id][y0 .. '_' .. x0] = 1

			target.is_moved = true

			RemoveMovingModifier(caster)
			--VS指向性技能单独触发天怒技能
			TriggerSMArcaneBolt({
				caster = caster,
				target = target,
			})
			Timers:CreateTimer(5,function()
				if caster_pfx ~= nil then
	                ParticleManager:DestroyParticle(caster_pfx, true)
	                ParticleManager:ReleaseParticleIndex(caster_pfx)
	            end
			end)
		end
		if position_table[index] then
			target:Stop()
			target:AddNewModifier(target, nil, "modifier_stunned", { duration = 0.1 })
			RemoveRoot(target)
			local target_pfx = ParticleManager:CreateParticle(
			"particles/units/heroes/hero_vengeful/vengeful_nether_swap_target.vpcf", PATTACH_ABSORIGIN, target)
			ParticleManager:SetParticleControlEnt(target_pfx, 0, target, PATTACH_POINT_FOLLOW, "attach_hitloc",
				target:GetAbsOrigin(), true)
			ParticleManager:SetParticleControlEnt(target_pfx, 1, caster, PATTACH_POINT_FOLLOW, "attach_hitloc",
				caster:GetAbsOrigin(), true)
			local pos = position_table[index]

			local x = Vector2X(pos, chessboard_id)
			local y = Vector2Y(pos, chessboard_id)
			target.y_x = y .. '_' .. x
			target.y = y
			target.x = x

			_G.unit[chessboard_id][y .. '_' .. x] = 1
			

			target:SetAbsOrigin(position_table[index])
			RemoveMovingModifier(target)
			Timers:CreateTimer(5,function()
				if target_pfx ~= nil then
	                ParticleManager:DestroyParticle(target_pfx, true)
	                ParticleManager:ReleaseParticleIndex(target_pfx)
	            end
			end)
		end
	end
end

function GetChessAbilityCD(u)
	local cd = 9999
	if IsUnitExist(u) == false then
		return cd
	end
	local ability_name = GetChessAbility(u)
	if ability_name ~= nil and u:FindAbilityByName(ability_name) ~= nil then
		cd = math.floor(u:FindAbilityByName(ability_name):GetCooldownTimeRemaining())
	end
	return cd
end

function ReduceChessAbilityCD(u, sec)
	if IsUnitExist(u) == false then
		return
	end
	if sec == nil then
		return
	end
	local ability_name = _G.chess_ability_list[u:GetUnitName()]
	local ability = u:FindAbilityByName(ability_name)
	if GetUnitBaseName(u) == 'chess_rubick' and u.steal_ability ~= nil then
		ability = u:FindAbilityByName(u.steal_ability)
	end
	local cd = ability:GetCooldownTimeRemaining()
	local cd_new = cd - sec
	if cd_new < 0 then
		cd_new = 0
	end
	if cd_new <= 0 then
		ability:EndCooldown()
	else
		ability:EndCooldown()
		ability:StartCooldown(cd_new)
	end
end

function UpdatePlayerWorldPanel(battle_table)
	if battle_table == nil then
		battle_table = {
			[6] = {},
			[7] = {},
			[8] = {},
			[9] = {},
			[10] = {},
			[11] = {},
			[12] = {},
			[13] = {},
		}
		for i = 6, 13 do
			if TeamId2Hero(i) ~= nil and TeamId2Hero(i).steam_id ~= nil then
				battle_table[i] = {
					steam_id = TeamId2Hero(i).steam_id
				}
			end
		end
	end
	if _G.battle_boss[_G.battle_round] ~= nil then
		battle_table['pve_round'] = _G.battle_round
	end
	for i = 6, 13 do
		CustomGameEventManager:Send_ServerToTeam(i, "update_player_worldpanel", battle_table)
	end
	CustomGameEventManager:Send_ServerToTeam(1, "update_player_worldpanel", battle_table)
end

