function FindEmptyGridAtUnit(u, front_flag, self_only)
	local team_id = u.at_team_id or u.team_id
	if front_flag == nil and self_only == nil then
		front_flag = true
	end

	--优先选取面前的空格子
	local forward_v = u:GetAbsOrigin() + u:GetForwardVector():Normalized() * 128
	local forward_x = Vector2X(forward_v, team_id)
	local forward_y = Vector2Y(forward_v, team_id)
	if IsIn8x8(forward_x, forward_y) == true and IsEmptyGrid(team_id, forward_x, forward_y) == true and front_flag == true then
		return XY2Vector(forward_x, forward_y, team_id)
	end

	--遍历身边的格子
	local random1 = RandomInt(0, 1)
	local random2 = 1

	if random1 == 0 then
		random1 = -1
	end
	if u.team_id == 4 then
		random2 = -1
	end

	for y = 1 * random2, -1 * random2, -1 * random2 do
		for x = -1 * random1, 1 * random1, random1 do
			if IsEmptyGrid(team_id, u.x + x, u.y + y) == true then
				if self_only then
					if u:GetTeam() ~= 4 then
						if IsInDefendArea(u.x + x, u.y + y) == true then
							return XY2Vector(u.x + x, u.y + y, team_id)
						end
					else
						if IsInAttackArea(u.x + x, u.y + y) == true then
							return XY2Vector(u.x + x, u.y + y, team_id)
						end
					end
				else
					if IsIn8x8(u.x + x, u.y + y) == true then
						return XY2Vector(u.x + x, u.y + y, team_id)
					end
				end
			end
		end
	end

	for xx = -2, 2 do
		for yy = -2, 2 do
			if IsEmptyGrid(team_id, u.x + xx, u.y + yy) == true then
				if self_only then
					if u:GetTeam() ~= 4 then
						if IsInDefendArea(u.x + xx, u.y + yy) == true then
							return XY2Vector(u.x + xx, u.y + yy, team_id)
						end
					else
						if IsInAttackArea(u.x + xx, u.y + yy) == true then
							return XY2Vector(u.x + xx, u.y + yy, team_id)
						end
					end
				else
					if IsIn8x8(u.x + xx, u.y + yy) == true then
						return XY2Vector(u.x + xx, u.y + yy, team_id)
					end
				end
			end
		end
	end

	return nil
end

function FindEmptyGridAtPosition(team_id, p)
	if p == nil then
		return nil
	end

	local xx = Vector2X(p, team_id)
	local yy = Vector2X(p, team_id)

	--遍历身边的格子
	local random1 = RandomInt(0, 1)

	if random1 == 0 then
		random1 = -1
	end

	for y = 1, -1, -1 do
		for x = -1 * random1, 1 * random1, random1 do
			if IsIn8x8(xx + x, yy + y) == true and IsEmptyGrid(team_id, xx + x, yy + y) == true then
				return XY2Vector(xx + x, yy + y, team_id)
			end
		end
	end

	for x = -2, 2 do
		for y = -2, 2 do
			if IsIn8x8(xx + x, yy + y) == true and IsEmptyGrid(team_id, xx + x, yy + y) == true then
				return XY2Vector(xx + x, yy + y, team_id)
			end
		end
	end

	return nil
end

function FindRandomEmptyGridAtUnit(u)
	local team_id = u.at_team_id or u.team_id
	local try_count = 0
	local p = nil

	while try_count < 20 and p == nil do
		local x = RandomInt(-1, 1)
		local y = RandomInt(-1, 1)
		if IsIn8x8(u.x + x, u.y + y) == true and IsEmptyGrid(team_id, u.x + x, u.y + y) == true then
			p = XY2Vector(u.x + x, u.y + y, team_id)
		end
		try_count = try_count + 1
	end

	return p
end

function FindFarthestEmptyGridAtUnit(u, caster)
	local team_id = u.at_team_id or u.team_id
	local max_distance = 0
	local p = nil
	local xx = u.x or Vector2X(u:GetAbsPosition(), team_id)
	local yy = u.y or Vector2Y(u:GetAbsPosition(), team_id)
	for x = -1, 1 do
		for y = -1, 1 do
			if IsIn8x8(xx + x, yy + y) == true and IsEmptyGrid(team_id, xx + x, yy + y) == true then
				local dis = (XY2Vector(xx + x, yy + y, team_id) - caster:GetAbsOrigin()):Length2D()
				if dis > max_distance then
					max_distance = dis
					p = XY2Vector(xx + x, yy + y, team_id)
				end
			end
		end
	end
	return p
end

--通用方法之寻找一个倒霉蛋
function FindUnluckyDog(u, exclude_unit_table, exclude_modifier, is_melee, in_range)
	local unluckydog = nil
	local try_count = 0
	while unluckydog == nil and try_count < 10 do
		local uu = GetValidChessOnBoard(u.at_team_id or u.team_id)
		[RandomInt(1, table.maxn(GetValidChessOnBoard(u.at_team_id or u.team_id)))]
		if uu ~= nil and uu:IsNull() == false and uu:IsAlive() == true and uu.team_id ~= u.team_id and not uu:HasAbility('is_ward') and uu.is_moving ~= true and HasMovingModifier(uu) == false then
			if exclude_modifier == nil or uu:HasModifier(exclude_modifier) == false then
				if is_melee == nil or uu:Script_GetAttackRange() < 250 then
					unluckydog = uu
				end
			end
			if exclude_unit_table ~= nil then
				for _, e_unit in pairs(exclude_unit_table) do
					if uu:entindex() == e_unit:entindex() then
						unluckydog = nil
					end
				end
			end
			if in_range ~= nil then
				if (uu:GetAbsOrigin() - u:GetAbsOrigin()):Length2D() > (in_range or 0) + u:GetHullRadius() + uu:GetHullRadius() then
					unluckydog = nil
				end
			end
		end
		try_count = try_count + 1
	end
	return unluckydog
end

function FindAllyClosest(u, including_hand, exclude_table)
	local unluckydog = nil
	local length2d = 99999
	local team = u.at_team_id or u.team_id
	local x = u.x or Vector2X(u:GetAbsOrigin(), team)
	local y = u.y or Vector2Y(u:GetAbsOrigin(), team)
	local my_pos = XY2Vector(x, y, team)
	--窃取羁绊时不排除隐身的
	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		local pos = unit:GetAbsOrigin()
		if (my_pos - pos):Length2D() < length2d and unit.team_id == u.team_id and unit:entindex() ~= u:entindex() and IsUnitExist(unit) then
			if exclude_table == nil or (exclude_table ~= nil and FindValueInTable(exclude_table, unit:entindex()) == false) then
				unluckydog = unit
				length2d = (my_pos - pos):Length2D()
			end
		end
	end
	local hh = TeamId2Hero(u:GetTeam())
	if including_hand and hh ~= nil and hh.hand_entities ~= nil then
		for _, unith in pairs(hh.hand_entities) do
			local posh = unith:GetAbsOrigin()
			if string.find(unith:GetUnitName(), 'chess_') and (my_pos - posh):Length2D() < length2d and unith:entindex() ~= u:entindex() and IsUnitExist(unith) then
				if exclude_table == nil or (exclude_table ~= nil and FindValueInTable(exclude_table, unith:entindex()) == false) then
					unluckydog = unith
					length2d = (my_pos - posh):Length2D()
				end
			end
		end
	end
	return unluckydog
end

function FindAllyRandom(u)
	local unluckydog = nil
	local team = u.at_team_id or u.team_id
	local my_pos = XY2Vector(u.x, u.y, team)
	local try_count = 0

	while unluckydog == nil and try_count < 10000 do
		local random = RandomInt(1, table.maxn(GetValidChessOnBoard(team)))
		local unit = GetValidChessOnBoard(team)[random]
		if unit ~= nil and unit.y_x and unit:IsNull() == false and unit:IsAlive() == true and unit.team_id == u.team_id and unit:IsInvisible() == false and unit:entindex() ~= u:entindex() then
			if unluckydog == nil then
				unluckydog = unit
			end
		end
		try_count = try_count + 1
	end

	return unluckydog
end

function FindWarlock6Luckydog(u)
	local luckydog = nil
	local least_hp = 9999
	local team = u.at_team_id or u.team_id

	if _G.to_be_destory_list[team] then
		for _, unit in pairs(GetValidChessOnBoard(team)) do
			if IsUnitExist(unit) == true and unit:HasModifier('modifier_is_warlock_buff_plus_plus') == true and unit:HasAbility('is_ward') == false and string.find(unit:GetUnitName(), 'chess_') ~= nil then
				if unit.warlock_buff_count == nil or unit.warlock_buff_count < 5 then
					local hp = unit:GetHealth()
					if hp < least_hp then
						least_hp = hp
						luckydog = unit
					end
				end
			end
		end
	end
	return luckydog
end

function FindHighLevelUnluckyDog(u, is_force_high_level, is_ignore_nomana, exclude_debuff, is_in_attack_range,
								 ignore_magic_immune)
	local unluckydog = nil
	local max_level = 0
	local team = u.at_team_id or u.team_id
	local my_pos = XY2Vector(u.x, u.y, team)
	if ignore_magic_immune == nil then
		ignore_magic_immune = true
	end

	--第二个参数true==是否强制最高等级，否则有30%概率随机
	--第三个参数true==是否排除被动技能的棋子（被动哥视为1级）
	if RandomInt(1, 100) < 30 and is_force_high_level ~= true then
		--30%概率随机找敌人
		return FindUnluckyDogRandom(u)
	end

	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		local lv = GetLevel(unit)
		if unit:GetMaxMana() <= 0 and is_ignore_nomana == true then
			lv = 1
		end
		if not ignore_magic_immune and unit:IsMagicImmune() == true then
			lv = -1
		end
		lv = lv + RandomFloat(0.0, 0.5)
		local a = unit.steal_ability or _G.chess_ability_list[unit:GetUnitName()]

		if lv > max_level and unit.team_id ~= u.team_id and unit:HasAbility('is_ward') == false then
			if exclude_debuff == nil or unit:HasModifier(exclude_debuff) == false then
				if not is_in_attack_range or (is_in_attack_range and IsUnitInAttackRange(u, unit)) then
					unluckydog = unit
					max_level = lv
				end
			end
		end
	end
	return unluckydog
end

--寻找攻击范围内最高攻击力的敌人
function FindHighADUnluckyDog(u, exclude_debuff, is_in_attack_range, ignore_magic_immune)
	local unluckydog = nil
	local max_ad = 0
	local team = u.at_team_id or u.team_id
	local my_pos = XY2Vector(u.x, u.y, team)
	if ignore_magic_immune == nil then
		ignore_magic_immune = true
	end

	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		local ad = unit:GetAverageTrueAttackDamage(u)
		if not ignore_magic_immune and unit:IsMagicImmune() == true then
			ad = -1
		end
		ad = ad + RandomFloat(0.0, 0.5)

		if ad > max_ad and unit.team_id ~= u.team_id and unit:HasAbility('is_ward') == false then
			if exclude_debuff == nil or unit:HasModifier(exclude_debuff) == false then
				if not is_in_attack_range or (is_in_attack_range and IsUnitInAttackRange(u, unit)) then
					unluckydog = unit
					max_ad = ad
				end
			end
		end
	end
	return unluckydog
end

function FindSheepStickUnluckyDog(u)
	local unluckydog = nil
	local max_level = 0
	local team = u.at_team_id or u.team_id
	local my_pos = XY2Vector(u.x, u.y, team)

	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
