		try_count = try_count + 1
	end

	return unluckydog
end

--选择vs换的目标（如指定level则忽视u的星级，适用于魔晶）
function FindUnluckyDogEnemySameStar(u, level)
	local unluckydog = nil
	local chessboard_id = u.at_team_id or u.team_id
	local star = level or GetChessStar(u)
	local max_star_level = 0
	local min_hp = 99999

	--遍历当前棋盘，找出同星的和低星的敌方棋子列表
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if string.find(unit:GetUnitName(),'chess') ~= nil and unit.team_id ~= u.team_id and unit:IsInvisible() == false and IsUnitExist(unit) and unit.is_moving ~= true and HasMovingModifier(unit) == false then
			--排除了各种移动状态的棋子
			local u_star = GetChessStar(unit)
			if u_star <= star then
				if u_star > max_star_level or (u_star == max_star_level and unit:GetHealth() < min_hp) then
					max_star_level = u_star
					min_hp = unit:GetHealth()
					unluckydog = unit
				end
			end
		end
	end
	return unluckydog
end

function FindUnluckyDogEnemySameLevel(u, exclude_flag)
	local unluckydog = nil
	local chessboard_id = u.at_team_id or u.team_id
	local level = GetLevel(u)
	local top_chess = nil
	local top_chess_level = 0
	local same_level_chess_table = {}
	local low_level_chess_table = {}

	--遍历当前棋盘，找出同等级的和低等级的敌方棋子列表
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if unit.team_id ~= u.team_id and IsUnitExist(unit) and unit:HasModifier('modifier_mind_control_debuff') == false and unit:IsInvisible() == false and GetLevel(unit) <= level and unit:HasAbility('tidehunter_kraken_shell') == false and unit:HasModifier('modifier_item_zhusidoupeng') == false then
			if GetLevel(unit) > top_chess_level or (GetLevel(unit) == top_chess_level and RandomInt(1, 100) > 50) and (exclude_flag and unit:HasAbility(exclude_flag) == false) then
				top_chess = unit
				top_chess_level = GetLevel(unit)
			end
		end
	end
	return top_chess
end

--寻找等级不高于自己的召唤物来控制（支配头盔用）
function FindUnluckyDogMinionSameLevel(u, level_max)
	local unluckydog = nil
	local chessboard_id = u.at_team_id or u.team_id
	local level = level_max or 2
	local top_chess = nil
	local top_chess_level = 0
	local same_level_chess_table = {}
	local low_level_chess_table = {}

	--遍历当前棋盘，找出同等级的和低等级的敌方召唤物列表
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if unit.team_id ~= u.team_id and IsUnitExist(unit) == true and unit:HasModifier('modifier_mind_control_debuff') == false and GetLevel(unit) <= level and ((unit:HasModifier("modifier_kill") == true and string.find(unit:GetUnitName(), 'chess_') == nil) or string.find(unit:GetUnitName(), 'pve_') ~= nil) and unit:HasAbility('is_ward') ~= true and unit:HasAbility('tidehunter_kraken_shell') == false and unit:HasModifier('modifier_item_zhusidoupeng') == false then
			if GetLevel(unit) > top_chess_level or (GetLevel(unit) == top_chess_level and RandomInt(1, 100) > 50) then
				top_chess = unit
				top_chess_level = GetLevel(unit)
			end
		end
	end
	return top_chess
end

