function FindBestSunderFriend(u)
	local unluckydog = u
	local hp_per_best = 0
	local hp_best = 0
	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		if unit.team_id == u.team_id and unit:entindex() ~= u:entindex() and unit:HasAbility('is_ward') == false then
