		local pos = XY2Vector(x, y, team_id)
		if IsEmptyGrid(team_id, x, y) then
			for p, vp in pairs(GetValidChessOnBoard(team_id)) do
				if vp:GetTeam() ~= warlock:GetTeam() and (vp:GetAbsOrigin() - pos):Length2D() <= 205 then
					return pos
