function FindLevelOneChess(hero)
	local level_one_chess = ''
	if hero ~= nil and _G.mychess[hero.team_id] ~= nil then
		for _, v in pairs(_G.mychess[hero.team_id]) do
			if v.chess ~= nil then
				local l1chess1 = GetChessBaseName(v.chess)
				level_one_chess = level_one_chess .. l1chess1 .. ','
			end
		end
		if hero.hand_entities ~= nil then
			for k, v in pairs(hero.hand_entities) do
				if IsUnitExist(v) then
					local l1chess2 = GetChessBaseName(v:GetUnitName())
					level_one_chess = level_one_chess .. l1chess2 .. ','
				end
			end
		end
	end
	return level_one_chess
end

--找到某玩家的所有三星棋子，去重
function FindStar3Chess(team_id)
	local star3_chess_list = {}
	local hero = TeamId2Hero(team_id)

	if hero ~= nil then
		for _, v in pairs(_G.mychess[hero.team_id]) do
			if GetChessNameStar(v.chess) == 3 then
				if FindValueInTable(star3_chess_list, v.chess) ~= true then
					table.insert(star3_chess_list, v.chess)
				end
			end
		end
		if hero.hand_entities ~= nil then
			for k, v in pairs(hero.hand_entities) do
				if IsUnitExist(v) and GetChessStar(v) == 3 then
					if FindValueInTable(star3_chess_list, v:GetUnitName()) ~= true then
						table.insert(star3_chess_list, v:GetUnitName())
					end
				end
			end
		end
	end
	return star3_chess_list
end

function Get11ChessBaseNameTable(team_id)
	local table_11chess = {}
	for _, chess in pairs(_G.mychess[team_id]) do
		if chess ~= nil and chess.chess ~= nil and string.find(chess.chess, '11') then
			table.insert(table_11chess, string.sub(chess.chess, 1, -3))
		end
	end
	return table_11chess
end

function GetMinionManaCost(u)
	local mana = 0
	if u:FindAbilityByName('mana_cost1') ~= nil then
		mana = 1
	end
	if u:FindAbilityByName('mana_cost2') ~= nil then
		mana = 2
	end
	if u:FindAbilityByName('mana_cost3') ~= nil then
		mana = 3
	end
	if u:FindAbilityByName('mana_cost4') ~= nil then
		mana = 4
	end
	if u:FindAbilityByName('mana_cost5') ~= nil then
		mana = 5
	end
	return mana
end

--获取棋子是几星的
function GetChessStar(chess)
	if IsUnitExist(chess) == false then
		return 1
	end
	local find_name = chess:GetUnitName()
	if _G.chess_transform_list[find_name] then
		--处理变身后棋子的不规则命名
		find_name = _G.chess_transform_list[find_name]
	end
	if string.find(find_name, 'chess_') == nil then
		return 1
	end
	if string.find(find_name, '_ssr') ~= nil then
		return 3
	end

	if string.find(find_name, '11') ~= nil then
		return 3
	end
	if string.find(find_name, '1') ~= nil then
		return 2
	end
	return 1
end

function GetChessNameStar(chess_name)
	--找不到的一律按1星处理
	if chess_name == nil then
		return 1
	end
	if _G.chess_transform_list[chess_name] then
		--处理变身后棋子的不规则命名
		chess_name = _G.chess_transform_list[chess_name]
	end
	if string.find(chess_name, '11') ~= nil then
		return 3
	end
	if string.find(chess_name, '1') ~= nil then
		return 2
	end
	return 1
end

function IsChessInHand(chess)
	if chess.hand_index ~= nil then
		return true
	else
		return false
	end
end

function Find2SameChessInHandOrOnBoard(caster, chess, ignore_combining)
	local count = 0
	local chess1 = nil
	local chess2 = nil
	local chess3 = nil
	if caster ~= nil and caster.hand_entities ~= nil then
		if GetTime().phase == GAME_PHASE_PREPARE and GetTime().left > 5 then
			-- 准备回合结束后，不再寻找场上棋子做为合成材料，避免一些未知的BUG。
			for _, v in pairs(_G.to_be_destory_list[caster.team_id]) do
				local kobold_or_druid = false
				if v ~= nil and v:IsNull() == false and v:GetClassname() == 'npc_dota_creature' then
					if v:FindAbilityByName('is_druid') ~= nil or v:FindAbilityByName('is_kobold') ~= nil then
						kobold_or_druid = true
					end
					if IsUnitExist(v) == true and v:GetUnitName() == chess and (kobold_or_druid == false or (kobold_or_druid == true and GetChessStar(v) >= 2)) and v.is_in_battle ~= true and v.is_moving ~= true and v.team_id == caster.team_id and v.combining ~= true then
						count = count + 1
						if count == 1 then
							chess1 = v
						end
						if count == 2 then
							chess2 = v
						end
						if count == 3 then
							chess3 = v
						end
					end
				end
			end
		end
		for _, v in pairs(caster.hand_entities) do
			if IsUnitExist(v) == true and v:GetUnitName() == chess and v:FindAbilityByName('is_druid') == nil and v:FindAbilityByName('is_kobold') == nil and GetUnitBaseName(v) ~= 'chess_io' and v.is_moving ~= true and v.combining ~= true then
				count = count + 1
				if count == 1 then
					chess1 = v
				end
				if count == 2 then
					chess2 = v
				end
				if count == 3 then
					chess3 = v
				end
			end
		end
		--combining属性要挂在实体上，虚拟棋子要转成实体再查询此属性
		-- if ignore_combining ~= true then
		-- 	if chess1 ~= nil then
		-- 		chess1.combining = true
		-- 	end
		-- 	if chess2 ~= nil then
		-- 		chess2.combining = true
		-- 	end
		-- 	if chess3 ~= nil then
		-- 		chess3.combining = true
		-- 	end
		-- end
		return count, chess1, chess2, chess3
	else
		return 0, nil, nil, nil
	end
end

--获得棋子名字的基础部分（去掉1和11）
function GetUnitBaseName(u)
	local unit_name = u:GetUnitName()
	if _G.chess_transform_list[unit_name] then
		--处理变身后棋子的不规则命名
		unit_name = _G.chess_transform_list[unit_name]
	end
	if string.find(unit_name, 'chess_') ~= nil then
		if string.find(unit_name, '11') ~= nil then
			unit_name = string.sub(unit_name, 1, -3)
		end
		if string.find(unit_name, '1') ~= nil then
			unit_name = string.sub(unit_name, 1, -2)
		end
	end
	return unit_name
end

--【羁绊】
function GetYourChessCount(team_id)
	local count = 0
	for _, v in pairs(_G.yourchess[team_id]) do
		if v and v.chess then
			count = count + 1
		end
	end
	return count
end

function SumFriendDemonOnChessboard(u)
	local dsum = 0
	local all_units = GetValidChessOnBoard(u.at_team_id or u.team_id or u:GetTeam())
	for _, unit in pairs(all_units) do
		if IsUnitExist(unit) == true and unit:GetTeam() == u:GetTeam() and unit:HasAbility('is_demon') == true then
			dsum = dsum + GetLevel(unit)
		end
	end
	return dsum
end

function GetHumanCount(team_id)
	local human_table = {}
	local extra_human_table = {}
	local is_lucky = false
	for w, vw in pairs(_G.mychess[team_id]) do
		local find_name = vw.chess
		if string.find(find_name, '11') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if string.find(find_name, '1') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if (FindValueInTable(_G.chess_list_by_synergy['is_human'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_human'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_human'], find_name) == true) and FindValueInTable(human_table, find_name) ~= true then
			table.insert(human_table, find_name)
			if vw['lastitem'] ~= nil and FindValueInTable(vw['lastitem'], 'item_xingyunguazhui') == true then
				is_lucky = true
			end
		end
		if FindValueInTable(vw.extra_synergy, 'is_human') == true then
			table.insert(extra_human_table, vw.chess)
			if vw['lastitem'] ~= nil and FindValueInTable(vw['lastitem'], 'item_xingyunguazhui') == true then
				is_lucky = true
			end
		end
	end
	local human_count = (table.maxn(human_table) + table.maxn(extra_human_table)) or 0
	local wizard_count = GetWizardCount(team_id)
	if wizard_count >= 2 and human_count >= 3 then
		human_count = human_count + 1
	end
	if TeamId2Hero(team_id).the_only_combo_self ~= nil and TeamId2Hero(team_id).the_only_combo_self == 'is_human' and wizard_count >= 3 then
		human_count = 6
	end
	return human_count, is_lucky
end

function CheckVChessHasSynergy(vchess, synergy_name)
	local find_name = vchess.chess
	if find_name then
		if string.find(find_name, '11') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if string.find(find_name, '1') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if (FindValueInTable(_G.chess_list_by_synergy[synergy_name], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman[synergy_name], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable[synergy_name], find_name) == true)
		then
			return true
		end
		if find_name == 'chess_rm' and FindValueInTable(_G.chess_rm_class, synergy_name) == true then
			return true
		end
	end
	if FindValueInTable(vchess.extra_synergy, synergy_name) == true then
		return true
	end
	return false
end

function GetDruidCount(team_id)
	--德鲁伊种族技能,统计有多少不同的德鲁伊
	local druid_table = {}
	for w, vw in pairs(_G.mychess[team_id]) do
		local is_druid = CheckVChessHasSynergy(vw, 'is_druid')
		if is_druid then
			local find_name = vw.chess or ''
			if string.find(find_name, '11') ~= nil then
				find_name = string.sub(find_name, 1, -2)
			end
			if string.find(find_name, '1') ~= nil then
				find_name = string.sub(find_name, 1, -2)
			end
			if FindValueInTable(druid_table, find_name) ~= true then
				table.insert(druid_table, find_name)
			end
		end
	end
	return table.maxn(druid_table) or 0
end

function GetPandamanCount(team_id)
	--获取当前熊猫人数量，最多为5
	local pandaman_set = _G.pandaman_list
	local pandaman_table = {}
	local xingyun_count = 0
	for w, vw in pairs(_G.mychess[team_id]) do
		local find_name = vw.chess
		if string.find(find_name, '11') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if string.find(find_name, '1') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if FindValueInTable(pandaman_table, find_name) ~= true then 
			if FindValueInTable(pandaman_set, find_name) == true or FindValueInTable(vw.extra_synergy, 'is_pandaman') == true or (find_name == 'chess_rm' and FindValueInTable(_G.chess_rm_class,'is_pandaman') == true) then 
				table.insert(pandaman_table, find_name)
			end
		end
		if vw.lastitem ~= nil and type(vw.lastitem) == 'table' then
			if FindValueInTable(vw.lastitem, 'item_xingyunguazhui') == true then 
				xingyun_count = xingyun_count + 1
			end
		end
	end
	local wizard_count = GetWizardCount(team_id)
	local panda_count = table.maxn(pandaman_table) or 0

	if wizard_count >= 2 and panda_count >= 3 then
		panda_count = panda_count + 1
	end
	if panda_count > 4 then
		panda_count = 4
	end
	if TeamId2Hero(team_id).the_only_combo_self ~= nil and TeamId2Hero(team_id).the_only_combo_self == 'is_pandaman' and wizard_count >= 3 then
		panda_count = 4
	end
	return panda_count, xingyun_count
end

function GetWizardCount(team_id)
	if _G.game_status ~= 2 or team_id == nil or _G.mychess == nil or _G.mychess[team_id] == nil then
		return 0
	end
	local wizard_table = {}
	for w, vw in pairs(_G.mychess[team_id]) do
		local find_name = vw.chess or ''
		if string.find(find_name, '11') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if string.find(find_name, '1') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if (FindValueInTable(_G.chess_list_by_synergy['is_wizard'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_wizard'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_wizard'], find_name) == true) and FindValueInTable(wizard_table, find_name) ~= true or (find_name == 'chess_rm' and FindValueInTable(_G.chess_rm_class,'is_pandaman') == true) or FindValueInTable(vw.extra_synergy, 'is_wizard') == true then
			table.insert(wizard_table, find_name)
		end
	end
	return table.maxn(wizard_table) or 0
