function GetPriestCount(team_id)
	local priest_table = {}
	for w, vw in pairs(_G.mychess[team_id]) do
		local find_name = vw.chess or ''
		if string.find(find_name, '11') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if string.find(find_name, '1') ~= nil then
			find_name = string.sub(find_name, 1, -2)
		end
		if (FindValueInTable(_G.chess_list_by_synergy['is_priest'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_priest'], find_name) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_priest'], find_name) == true) and FindValueInTable(priest_table, find_name) ~= true or (find_name == 'chess_rm' and FindValueInTable(_G.chess_rm_class,'is_priest') == true) or FindValueInTable(vw.extra_synergy, 'is_priest') == true then
			table.insert(priest_table, find_name)
		end
	end
