--钓鱼
function Fish(hero)
	local team_id = hero:GetTeam()
	local pandaman_count, xingyun_count = GetPandamanCount(team_id)
	if pandaman_count <= 0 then
		return
	end
	--幸运挂坠
	local lucky_value = (pandaman_count + xingyun_count * 0.25) / pandaman_count
	local fish_dice_table = {
		[1] = 10 * lucky_value,
		[2] = 15 * lucky_value,
	}

	-- local fish_pandaman_dice = 75

	--非气值
	local a_value = GetFishAfricaValue(hero)

	--整理base table，统计场上已有棋子
	local other_chess_base_table = {} --场上已有的非熊猫人棋子都在这里
	local pandaman_chess_base_table = {} --场上已有的熊猫人棋子都在这里
	local all_chess_base_table = {}   --所有已有的棋子都在这里
	for _, chess in pairs(_G.mychess[team_id]) do
		local base_name = GetChessBaseName(chess.chess)

		if FindValueInTable(_G.pandaman_list, base_name) == true or FindValueInTable(chess.extra_synergy, 'is_pandaman') == true then
			table.insert(pandaman_chess_base_table, base_name)
		else
			table.insert(other_chess_base_table, base_name)
		end
		table.insert(all_chess_base_table, base_name)
	end
	--1熊猫人:钓同种族
	if pandaman_count >= 1 then
		if RandomInt(1, 100) <= fish_dice_table[1] * a_value then
			-- if RandomInt(1,100) <= fish_pandaman_dice and hero.synergy_banned ~= 'is_pandaman' then
			-- 	RandomAFish(team_id,pandaman_set)
			-- else
			-- 	RandomAFish(team_id,other_chess_base_table)
			-- end
			RandomAFish(team_id, all_chess_base_table, all_chess_base_table)
		else
			AddFishAfricaValue(hero)
		end
	end
	--2熊猫人:钓隐居熊猫人
	-- if pandaman_count >= 2 then
	-- 	if RandomInt(1,100) <= fish_dice_table[2]*a_value and hero.synergy_banned ~= 'is_pandaman' then
	-- 		Timers:CreateTimer(0.3,function()
	-- 			RandomAFish(team_id,_G.pandaman_recluse_set,all_chess_base_table)
	-- 		end)
	-- 	end
	-- end
	--3熊猫人:每个熊猫人都钓自己
	if pandaman_count >= 2 then
		for _, pm in pairs(pandaman_chess_base_table) do
			if RandomInt(1, 100) <= fish_dice_table[2] * a_value and hero.synergy_banned ~= 'is_pandaman' then
				Timers:CreateTimer(RandomFloat(0.6, 1.5), function()
					RandomAFish(team_id, pm)
				end)
			end
		end
	end
end

--有鱼上钩了，选一条鱼
function RandomAFish(team_id, fisher, all_chess_base_table)
	--fisher传进来table是钓种族（包括熊猫人种族），字符串名字就是钓自己
	local hero = TeamId2Hero(team_id)
	local ran_chess = nil
	if fisher == nil then
		return
	end

	local destroy_info = CustomNetTables:GetTableValue("chess_pool_table", "destroy_info")
	local table_11chess = Get11ChessBaseNameTable(team_id)

	if type(fisher) == 'table' and table.maxn(fisher) > 0 then
		--从fisher table中随机一个棋子,钓它的同族,并排除all_chess_base_table中已拥有的
		local random_race_table = {}
		for _, f in pairs(fisher) do
			--遍历所有fisher，把它的同种族的所有可能存放进random_race_table（去重）
			local ran_race, ran_race2 = GetChessRace(f)
			if ran_race2 ~= nil and RandomInt(1, 100) < 50 then
				--双种族棋子,50%概率用种族2
				ran_race = ran_race2
			end

			local ran_pool = CombineTable(_G.chess_list_by_synergy[ran_race],
				_G.chess_list_by_synergy_black_and_pandaman[ran_race], true)

			for _, ff in pairs(ran_pool) do
				if FindValueInTable(random_race_table, ff) == false then
					local ran_race_check, ran_race2_check = GetChessRace(ff)
					local check = true
					-- if hero.synergy_banned ~= nil and (ran_race_check == hero.synergy_banned or ran_race2_check == hero.synergy_banned) then
					-- 	--排除ban的种族
					-- 	check = false
					-- end
					-- local ran_class_check, ran_class2_check, ran_class3_check = GetChessClass(ff)
					-- if hero.synergy_banned ~= nil and (ran_class_check == hero.synergy_banned or ran_class2_check == hero.synergy_banned or ran_class3_check == hero.synergy_banned) then
					-- 	--排除ban的职业
					-- 	check = false
					-- end
					if FindValueInTable(table_11chess, ff) == true then
						--排除已经三星的棋子
						check = false
					end
					if FindValueInTable(destroy_info, ff) == true then
						--排除被垄断的棋子
						check = false
					end
					if all_chess_base_table and FindValueInTable(all_chess_base_table, ff) == true then
						--排除场上已有的棋子
						check = false
					end
					if check == true then
						table.insert(random_race_table, ff)
					end
				end
			end
		end

		local trytime = 0
		while trytime < 100 and ran_chess == nil do
			trytime = trytime + 1
			ran_chess = random_race_table[RandomInt(1, table.maxn(random_race_table))]
		end
	elseif type(fisher) == 'string' then
		--指定钓fisher
		ran_chess = fisher
	end

	if ran_chess ~= nil then
		table.insert(_G.stat_info[hero.steam_id]['pandaman_getlist'],ran_chess..'_'.._G.battle_round)

		if table.maxn(_G.stat_info[hero.steam_id]['pandaman_getlist']) >= 10 then
			if _G.egg_quest == 'q054' then
				SetQuest(hero.team_id, true)
			end
		end

		InitFishAfricaValue(hero)
		PlayRandomFishDiague(team_id, ran_chess)
		local cost = GetChessCostByName(ran_chess)
		if cost ~= nil and cost > 0 then
			--从棋库中移除
			RemoveOneValueInTable(_G.chess_pool[cost], ran_chess)
			if _G.chess_remainder_table[ran_chess] ~= nil then
				_G.chess_remainder_table[ran_chess] = _G.chess_remainder_table[ran_chess] - 1
			end
		end
		Timers:CreateTimer(2, function()
			--创建鱼棋子，播动画
			local cc = CreateChessInHand(hero, ran_chess)
			cc.buy_price = math.ceil(cc:GetLevel() / 2)
			BlinkChessX({ caster = cc, blink_type = "fall" })
			--发弹幕：钓鱼
			SendServerToAllTeam("bullet", {
				player_id = hero:GetPlayerID(),
				vip = hero.is_vip,
				win_streak = hero.win_streak or 0,
				target = ran_chess,
				pre_ability = 'is_pandaman',
			})
		end)
		-- else
	end

	return ran_chess
end

--钓鱼防非概率
function GetFishAfricaValue(hero)
	if hero.fish_africa_value == nil then
		hero.fish_africa_value = -4
	end
	return math.pow(1.1, hero.fish_africa_value)
end

function InitFishAfricaValue(hero)
	hero.fish_africa_value = -4
end

function AddFishAfricaValue(hero)
	if hero.fish_africa_value == nil then
		hero.fish_africa_value = -4
	end
	hero.fish_africa_value = hero.fish_africa_value + 1
end

--自然的恩赐：精灵守卫的概率
function GetIOAfricaValue(hero)
	if hero.io_africa_value == nil then
		hero.io_africa_value = 9
	end
	return hero.io_africa_value
end

function AddIOAfricaValue(hero)
	if hero.io_africa_value == nil then
		hero.io_africa_value = 1
	end
	hero.io_africa_value = hero.io_africa_value - 2
	if hero.io_africa_value < 1 then
		hero.io_africa_value = 1
	end
end

function PlayRandomFishDiague(team_id, fish_chess)
	local u = FindRandomChessSpeak(team_id, fish_chess)
	if IsUnitExist(u) == true then
		PlayChessDialogue(u, 'fish')
	end
end

function RandomEvolveResult(seed)
	-- if seed:HasModifier('modifier_item_zhusidoupeng') == true then
	-- 	return nil
	-- end
	if seed:HasModifier('modifier_is_shaman_buff_plus') == false and seed:HasModifier('modifier_is_shaman_buff_plus') == false then
		return
	end
	if table.maxn(_G.chess_list_by_level) == 0 then
		InitChessListByLevel()
	end
	local level = GetEvolveLevel(seed) or GetLevel(seed)
	if level == 0 then
		return
	end
	local chesstable = _G.chess_list_by_level[level]
	local chessname = chesstable[RandomInt(1, table.maxn(chesstable))]
	AddAbilityAndSetLevel(seed, 'evolve')

	-- if chess_name ~= nil then
	-- 	PlayParticleOnUnitUntilDeath({
	-- 		caster = seed,
	-- 		p = "effect/evolve.vpcf",
	-- 	})
	-- end
	return chessname
end

function RandomStarEvolveChess(seed, delta)
	-- if seed:HasModifier('modifier_item_zhusidoupeng') == true then
	-- 	return nil
	-- end
	local star = GetChessNameStar(seed:GetUnitName())
	local cost = _G.chess_2_mana[GetUnitBaseName(seed)]
	local c = cost
	if c == nil or c < 1 then
		c = 1
	end
	if c > 5 then
		c = 5
	end

	local t = _G.chess_list_by_mana[c]
	local uname = t[RandomInt(1, table.maxn(t))]
	local name_suffix = ''
	if star == 2 then
		name_suffix = '1'
	elseif star == 3 then
		name_suffix = '11'
	end
	return uname .. name_suffix
end

--召唤物继承野兽buff
function ExtendBeastBuff(unit, owner, shenshi_buff, bian_buff)
	if IsUnitExist(owner) == false then
		return
	end
	--继承野兽buff
	if owner:FindAbilityByName('is_beast_buff') ~= nil then
		AddAbilityAndSetLevel(unit, 'is_beast_buff')
	end
	if owner:FindAbilityByName('is_beast_buff_plus') ~= nil then
		AddAbilityAndSetLevel(unit, 'is_beast_buff_plus')
	end
	if owner:FindAbilityByName('is_beast_buff_plus_plus') ~= nil then
		AddAbilityAndSetLevel(unit, 'is_beast_buff_plus_plus')
	end
	--继承蛛丝斗篷
	if owner:HasModifier('modifier_item_zhusidoupeng') == true then
		for slot = 0, 5 do
			if owner:GetItemInSlot(slot) ~= nil then
				local ability = owner:GetItemInSlot(slot)
				local name = ability:GetAbilityName()
				if name == 'item_zhusidoupeng' then
					ability:ApplyDataDrivenModifier(unit, unit, 'modifier_item_zhusidoupeng', {})
					break
				end
			end
		end
	end
	--继承永恒之盘的永恒buff
	if owner:HasModifier('modifier_yonghengzhipan_yongheng_buff') == true then
		for slot = 0, 5 do
			if owner:GetItemInSlot(slot) ~= nil then
				local ability = owner:GetItemInSlot(slot)
				local name = ability:GetAbilityName()
				if name == 'item_yonghengzhipan' then
					ability:ApplyDataDrivenModifier(unit, unit, 'modifier_yonghengzhipan_yongheng_buff', {})
					break
				end
			end
		end
	end
	-- if shenshi_buff and (owner:FindModifierByName('modifier_item_zhaohuanshenshi') ~= nil) then
	-- 	for slot=0,5 do
	-- 		if owner:GetItemInSlot(slot)~= nil then
	-- 			local ability = owner:GetItemInSlot(slot)
	-- 			local name = ability:GetAbilityName()
	-- 			if name == 'item_zhaohuanshenshi' then
	-- 				ability:ApplyDataDrivenModifier(unit,unit,'modifier_'..name..'_buff',{})
	-- 				break
	-- 			end
	-- 		end
	-- 	end
	-- end
	if bian_buff then
		ExtendBianBuff(unit, owner)
	end
end

function ExtendBianBuff(unit, owner)
	if IsUnitExist(owner) == false then return end
	if owner:FindModifierByName('modifier_item_linglichangbian') ~= nil and string.find(unit:GetUnitName(),'chess_') == nil then
		for slot = 0, 5 do
			if owner:GetItemInSlot(slot) ~= nil then
				local ability = owner:GetItemInSlot(slot)
				local name = ability:GetAbilityName()
				if name == 'item_linglichangbian' then
					ability:ApplyDataDrivenModifier(unit, unit, 'modifier_item_linglichangbian_buff', {})
					break
				end
			end
		end
		play_particle("particles/items4_fx/bull_whip_self.vpcf", PATTACH_ABSORIGIN_FOLLOW, unit, 3)
		EmitSoundOn("Item.Bullwhip.Enemy", unit)
		-- ChangeModelScale({
		-- 	caster = unit,
		-- 	x = 1.1,
		-- })
	end
end

function ConcealToggle(team, conceal)
	if team ~= nil and conceal == 1 and _G.game_status == 1 then
		HidePrepare(team)
	end
	if team ~= nil and conceal == -1 then
		ShowPrepare(team)
	end
end

function Conceal(keys)
	local caster = keys.caster
	if IsUnitExist(caster) == false then return end
	if keys.no_hero and caster:IsHero() == true then return end
	if GetTime().phase == GAME_PHASE_BATTLE then
		return
	end

	if caster.hand_index == nil then
		ConcealOneChess(caster)
	end
end

function Reveal(keys)
	local caster = keys.caster
	if IsUnitExist(caster) == false then return end
	RevealOneChess(caster)
end

function ConcealOneChess(chess)
	AddAbilityAndSetLevel(chess, 'invisible_to_enemy')
end

function RevealOneChess(chess)
	RemoveAbilityAndModifier(chess, 'invisible_to_enemy')
end

function HideBench(team)
	if TeamId2Hero(team).hand_entities ~= nil then
		for _, ent in pairs(TeamId2Hero(team).hand_entities) do
			AddAbilityAndSetLevel(ent, 'invisible_to_enemy')
		end
	end
end

function ShowBench(team)
	if TeamId2Hero(team).hand_entities ~= nil then
		for _, ent in pairs(TeamId2Hero(team).hand_entities) do
			RemoveAbilityAndModifier(ent, 'invisible_to_enemy')
		end
	end
end

function HidePrepare(team)
	if GetValidChessOnBoard(team) ~= nil then
		for _, ent in pairs(GetValidChessOnBoard(team)) do
			AddAbilityAndSetLevel(ent, 'invisible_to_enemy')
		end
	end
end

function ShowPrepare(team)
	if GetValidChessOnBoard(team) ~= nil then
		for _, ent in pairs(GetValidChessOnBoard(team)) do
			if IsUnitExist(ent) == true and ent:HasAbility('smoke_screen_trigger') == false then
				RemoveAbilityAndModifier(ent, 'invisible_to_enemy')
			end
		end
	end
end

