function KnockBack(keys)
	local caster = keys.caster
	local target = keys.target
	if IsUnitExist(caster) == false or IsUnitExist(target) == false then
		return false
	end
	local vec = (target:GetAbsOrigin() - caster:GetAbsOrigin()):Normalized()
	local deltax = math.floor(vec.x + 0.5)
	local deltay = math.floor(vec.y + 0.5)
	local team_id = target.at_team_id or target.team_id
	local blocks = keys.blocks or 1
	local y = target.y
	local x = target.x
	local old_y = y
	local old_x = x

	if HasMovingModifier(target) == true or target:HasMovementCapability() == false or x == nil or y == nil then
		--不推
		return false
	end

	local is_jitui = false
	while blocks > 0 do
		if IsIn8x8(x + deltax, y + deltay) == true and IsEmptyGrid(team_id, x + deltax, y + deltay) == true then
			x = x + deltax
			y = y + deltay
			blocks = blocks - 1
			is_jitui = true
		else
			blocks = 0
		end
	end

	if is_jitui == false then
		--推不动
		return false
	end

	local target_pos = XY2Vector(x, y, team_id)
	local stun_duration = ((target_pos - target:GetAbsOrigin()):Length2D() / 1000)
	target:AddNewModifier(target, nil, "modifier_stunned", { duration = stun_duration + 0.1 })

	_G.unit[team_id][y .. '_' .. x] = 1
	_G.unit[team_id][old_y .. '_' .. old_x] = nil
	target.is_moving = true
	BlinkChessX({ p = target_pos, caster = target, blink_type = 'tuitui' })

	target.y_x = y .. '_' .. x
	target.y = y
	target.x = x
	return true
end

--亡语
function DeathRattle(u, attacker)
	if u.no_death_rattle then
		return
	end
	if u.alreadywon == true then
		return
	end

	if u.killer ~= nil then
		attacker = u.killer
	end

	--血精石的使用和充能
	--使用
	if u:HasModifier('modifier_item_xuejingshi') and not u.is_huanxiang then
		local xuejingshi_count = LosePermanentStackCount(u, 'xuejingshi') or 1

		EmitSoundOn('DOTA_Item.Bloodstone.Cast', u)
	end
	--充能
	local xuejingshi_adds = FindUnitsInRadiusOnTeamGround({
		team = u:GetTeam(),
		at_team = u.at_team_id or u.team_id,
		role = 2,
		position = u:GetAbsOrigin(),
		radius = 9999,
	})
	for _, x in pairs(xuejingshi_adds) do
		if x:HasModifier("modifier_item_xuejingshi") then
			if RandomInt(1, 100) < 15 then
				AddPermanentStackCount(x, 'xuejingshi')
			end
		end
	end

	--6术士灵魂榨取亡语：最近的术士吸取（优先级最高，不影响其他）
	-- local Warlock6_enemy = FindWarlock6Luckydog(u)
	-- if IsUnitExist(Warlock6_enemy) == true and u:HasModifier('modifier_illusion') == false and u.last_damage_ability ~= 'is_monk_buff' then
	-- 	if Warlock6_enemy:FindModifierByName("modifier_is_warlock_buff_plus_plus_buff") == nil then
	-- 		Warlock6_enemy:FindAbilityByName("is_warlock_buff_plus_plus"):ApplyDataDrivenModifier(Warlock6_enemy,
	-- 			Warlock6_enemy, 'modifier_is_warlock_buff_plus_plus_buff', {})
	-- 		Warlock6_enemy.warlock_buff_count = 1
	-- 	else
	-- 		Warlock6_enemy.warlock_buff_count = Warlock6_enemy.warlock_buff_count + 1
	-- 		Warlock6_enemy:FindModifierByName('modifier_is_warlock_buff_plus_plus_buff'):SetStackCount(Warlock6_enemy
	-- 		.warlock_buff_count)
	-- 	end

	-- 	local hh = u:GetMaxHealth() * 0.30
	-- 	local mm = u:GetMana() * 0.30
	-- 	play_particle("particles/units/heroes/hero_dark_seer/dark_seer_surge.vpcf", PATTACH_ABSORIGIN_FOLLOW,
	-- 		Warlock6_enemy, 3)
	-- 	ModMaxHP({
	-- 		caster = Warlock6_enemy,
	-- 		const = hh,
	-- 		is_heal = true,
	-- 	})
	-- 	AddChessMana(Warlock6_enemy, mm, true)
	-- 	EmitSoundOn('warlock.brainsap', Warlock6_enemy)
	-- 	Warlock6_enemy:SetRenderColor(255 - (Warlock6_enemy:GetMaxHealth() / 100), 255,
	-- 		255 - (Warlock6_enemy:GetMaxHealth() / 100))
	-- end

	--亚基虫族亡语：生虫（如成功则return，不触发后面的）
	if u:HasModifier('modifier_is_aqir_buff') == true and (IsUnitExist(attacker) == false or attacker:entindex() ~= u:entindex()) then
		AqirDeathRattle(u)
	end

	-- --尸王：尸爆
	-- if u:HasModifier("modifier_ud_dead_bomb") == true then
	-- 	local ability = u:FindModifierByName("modifier_ud_dead_bomb"):GetAbility()
	-- 	if ability ~= nil then
	-- 		local radius = GetAbilityKV(ability, "radius") or 300
	-- 		local damage_per = GetAbilityKV(ability, "damage_per") or 20

	-- 	end
	-- end

	if u:HasModifier('modifier_item_buxiuzhishouhu') == true and HasKillModifier(u) == false then
		--不朽之守护：复活
		local item_table_now = GetAllItemsAndCDInUnits({ [1] = u })
		for i, v in pairs(item_table_now) do
			if v.item == 'item_buxiuzhishouhu' then
				item_table_now[i] = nil
			end
		end
		local x = SummonOneChess({
			teamid = u:GetTeam(),
			position = XY2Vector(u.x, u.y, u.at_team_id or u.team_id), --u:GetAbsOrigin(),
			chessname = u.old_chess_name or u:GetUnitName(),
			at_teamid = u.at_team_id or u.team_id,
			items = u.old_chess_items or item_table_now,
			force_forward = forward_vector,
			ai_delay = 2.4,
		})
		if IsUnitExist(x) == true then
			ExtendReincarnationFlags(u, x)
			x.buxiuzhishouhu = true

			local particleName = "content/effect/aegis.vpcf"
			x.ReincarnateParticle = ParticleManager:CreateParticle(particleName, PATTACH_ABSORIGIN_FOLLOW, x)
			-- ParticleManager:SetParticleControl(x.ReincarnateParticle, 0, x:GetAbsOrigin())
			-- ParticleManager:SetParticleControl(x.ReincarnateParticle, 1, Vector(300,0,0))
			x:EmitSound("Hero_SkeletonKing.Reincarnate")
			x:EmitSound("Aegis.Timer")

			AddAbilityAndSetLevel(x, 'jiaoxie_wudi')
			x:StartGesture(ACT_DOTA_CAST_ABILITY_4)
			-- End Particle after reincarnating
			Timers:CreateTimer(3, function()
				ParticleManager:DestroyParticle(x.ReincarnateParticle, false)
				ParticleManager:ReleaseParticleIndex(x.ReincarnateParticle)
				x:EmitSound("Hero_SkeletonKing.Reincarnate.Stinger")
				RemoveAbilityAndModifier(x, 'jiaoxie_wudi')
			end)
			return
		end
	--骷髅王：复活
	--'modifier_skeleton_king_reincarnation_scepter_active'
	elseif u:HasModifier('modifier_skeletonking_reincarnation') and HasKillModifier(u) == false and u.is_youhun ~= true and u.is_ghost ~= true and u:HasAbility('is_ward') == false then --and string.find(u:GetUnitName(),'chess_') ~= nil
		local modifier = u:FindModifierByName('modifier_skeletonking_reincarnation') 
		local ability = modifier:GetAbility()
		if ability ~= nil then
			local snk_level = ability.snk_level or 5
			-- local snk = modifier:GetCaster()
			-- if IsUnitExist(snk, true) == true then
				-- local snk_level = GetLevel(snk)
				local u_level = GetLevel(u)
				if u_level <= snk_level then
					local reduration = GetAbilityKV(ability, "duration") or 15
					local item_table_now = GetAllItemsAndCDInUnits({ [1] = u })
					local x = SummonOneChess({
						teamid = u:GetTeam(),
						position = XY2Vector(u.x, u.y, u.at_team_id or u.team_id), --u:GetAbsOrigin(),
						chessname = u:GetUnitName(),
						at_teamid = u.at_team_id or u.team_id,
						items = item_table_now,
						force_forward = forward_vector,
						ai_delay = 2.4,
					})
					if IsUnitExist(x) == true then
						ExtendReincarnationFlags(u, x)
						local particleName = "particles/units/heroes/hero_skeletonking/wraith_king_reincarnate.vpcf"
						x.ReincarnateParticle = ParticleManager:CreateParticle(particleName, PATTACH_ABSORIGIN_FOLLOW, x)
						ParticleManager:SetParticleControl(x.ReincarnateParticle, 0, x:GetAbsOrigin())
						ParticleManager:SetParticleControl(x.ReincarnateParticle, 1, Vector(300, 0, 0))
						AddAbilityAndSetLevel(x, 'jiaoxie_wudi')
						-- End Particle after reincarnating
						Timers:CreateTimer(3, function()
							ParticleManager:DestroyParticle(x.ReincarnateParticle, false)
							ParticleManager:ReleaseParticleIndex(x.ReincarnateParticle)
							RemoveAbilityAndModifier(x, 'jiaoxie_wudi')
						end)
						x:AddNewModifier(x,nil,"modifier_kill",{duration = reduration})
						AddAbilityAndSetLevel(x, 'is_ghost', 1)
						x.is_ghost = true
					end
				end
			-- end
		end
	end

	--在蛛网中死亡：诞生小蜘蛛
	if IsUnitExist(attacker) and u:HasModifier('modifier_broodmother_silken_bola') == true then
		if u:FindModifierByName('modifier_broodmother_silken_bola') == nil or u:FindModifierByName('modifier_broodmother_silken_bola'):GetAbility() == nil then
			return
		end
		local level = u:FindModifierByName('modifier_broodmother_silken_bola'):GetAbility():GetLevel() or 1
		local spider_name = 'br_spider' .. level
		play_particle('particles/units/heroes/hero_broodmother/broodmother_spiderlings_spawn.vpcf',
			PATTACH_ABSORIGIN_FOLLOW, u, 5)
		EmitSoundOn('Hero_LifeStealer.Infest', u)
		if attacker:entindex() ~= u:entindex() then
			local caster = u.web_br or attacker
			SummonMinion(attacker, spider_name, 1, nil, function(w)
				if w ~= nil then
					w:SetMana(0)
					FillEmptySlot(w)
					ExtendBeastBuff(w, caster, true, true)
					ExtendBianBuff(w, caster)
					AddAbilityAndSetLevel(w, 'jiaoxie_wudi')
				end
			end, u:GetAbsOrigin(), true, nil, true)
		end
	end
end

function ExtendReincarnationFlags(x_dead, x_born)
	CopyChessProperties(x_born, x_dead)
	x_born.vchess_index = x_dead.vchess_index
	x_born.initial_index = x_dead:entindex()
	x_born.reincarnated = true
end

function AqirDeathRattle(u)
	Timers:CreateTimer(0.1, function()
		local AQIR_CHESS_LIST = {
			[1] = {},
			[2] = {},
			[3] = {},
			[4] = {},
			[5] = {},
			[6] = {},
			[7] = {},
			[8] = {},
			[9] = {},
		}
		if _G.chess_list_by_synergy['is_aqir'] ~= nil then
			for _, chess_name in pairs(_G.chess_list_by_synergy['is_aqir']) do
				local mana = _G.chess_2_mana[chess_name] or 1
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name)
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '1')
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '11')
			end
		end
		if _G.chess_list_by_synergy_black_and_pandaman['is_aqir'] ~= nil then
			for _, chess_name in pairs(_G.chess_list_by_synergy_black_and_pandaman['is_aqir']) do
				local mana = _G.chess_2_mana[chess_name] or 1
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name)
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '1')
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '11')
			end
		end
		local wangchongtui_list = FindAllWangchongtuiChessByTeam((u.at_team_id or u.team_id), u.team_id)
		if wangchongtui_list ~= nil then
			for _, chess_name in pairs(wangchongtui_list) do
				local mana = _G.chess_2_mana[chess_name] or 1
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name)
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '1')
				mana = mana + 2
				if mana > 9 then mana = 9 end
				table.insert(AQIR_CHESS_LIST[mana], chess_name .. '11')
			end
		end

		if table.maxn(AQIR_CHESS_LIST[1]) == 0 then
			AQIR_CHESS_LIST[1] = { 'chess_sk', 'chess_veno' }
		end
		if table.maxn(AQIR_CHESS_LIST[2]) == 0 then
			AQIR_CHESS_LIST[2] = { 'chess_sk', 'chess_veno' }
		end
		if table.maxn(AQIR_CHESS_LIST[9]) == 0 then
			AQIR_CHESS_LIST[9] = { 'chess_na11', 'chess_br11', }
		end

		local max_level, max_level_chess
		if u:HasAbility('is_aqir') == true then
			--4虫
			max_level, max_level_chess = GetSameNameFriendChessMaxLevel(u)
		else
			--2虫，需要有感染debuff
			max_level, max_level_chess = GetSameNameFriendChessMaxLevel(u, 'modifier_is_aqir_buff')
		end

		-- local dead_level = u:GetLevel()
		if max_level > 0 then
			if u:HasAbility('is_aqir') == true then
				--4虫
				-- if RandomInt(1,100) > 90 then
				-- 	max_level = max_level + 2
				-- elseif RandomInt(1,100) > 70 then
				-- 	max_level = max_level + 1
				-- end
				max_level = max_level + 1

				local plus_per = 0.00
				plus_per = plus_per * GetLuckyValue(u)

				if RandomFloat(0, 1) < plus_per then
					max_level = max_level + 1
				end
			else
				--2虫
				-- if RandomInt(1,100) > 75 then
				-- 	max_level = max_level + 1
				-- end
				max_level = max_level
			end
			if max_level > 9 then
				max_level = 9
			end

			local random_pool = AQIR_CHESS_LIST[max_level]
			local random_aqir = random_pool[RandomInt(1, table.maxn(random_pool))]
			local aqir_level = GetChessNameStar(random_aqir)

			if aqir_level == 1 then
				play_particle('particles/units/heroes/hero_life_stealer/life_stealer_infest_emerge_clean_low.vpcf',
					PATTACH_ABSORIGIN_FOLLOW, u, 5)
			elseif aqir_level == 2 then
				play_particle('particles/units/heroes/hero_life_stealer/life_stealer_infest_emerge_clean_low.vpcf',
					PATTACH_ABSORIGIN_FOLLOW, u, 5)
			elseif aqir_level >= 3 then
				play_particle('particles/units/heroes/hero_life_stealer/life_stealer_infest_emerge_bloody.vpcf',
					PATTACH_ABSORIGIN_FOLLOW, u, 5)
			end
			EmitSoundOn('Hero_LifeStealer.Infest', u)

			SummonOneChessAsync({
				teamid = u:GetTeam(),
				at_teamid = u.at_team_id or u.team_id,
				chessname = random_aqir,
				position = u:GetAbsOrigin(),
				cb = function(w)
					if IsUnitExist(w) == true then
						w:SetMana(0)
						FillEmptySlot(w)
						AddChessAbility(w, aqir_level)
						AddAbilityAndSetLevel(w, 'jiaoxie_wudi')
						if max_level_chess ~= nil then
							LinkEffect(w, max_level_chess)
						end
						AddModifierKill(w, RandomInt(10, 20))

						ExtendBianBuff(w, u)
					end
				end
			})
		else
			play_particle('particles/units/heroes/hero_life_stealer/life_stealer_infest_cast.vpcf',
				PATTACH_ABSORIGIN_FOLLOW, u, 5)
			EmitSoundOn('Hero_LifeStealer.Infest', u)
		end
		RemoveAllModifiers(u)
	end)
end

function FindAllWangchongtuiChessByTeam(chessboard_id, team_id)
	local chess_list = {}
	for _, v in pairs(GetValidChessOnBoard(chessboard_id)) do
		if IsUnitExist(v) == true and v.team_id == team_id and v:HasModifier('modifier_item_wangchongtui') then
			table.insert(chess_list, GetChessBaseName(v:GetUnitName()))
		end
	end
	return chess_list
end

function GainNraqiEffect(keys)
	--无面者：获得变黑buff
	play_particle('particles/units/heroes/hero_void_spirit/astral_step/void_spirit_astral_step_dmg_burst.vpcf',
		PATTACH_ABSORIGIN_FOLLOW, keys.target, 5)
	EmitSoundOn("Hero_Bane.BrainSap", keys.target)
	-- AddAbilityAndSetLevel(keys.target,'faceless_void_time_lock')

	--驱散一下debuff
	for _, m in pairs(keys.target:FindAllModifiers()) do
		if m:IsDebuff() and IsModifierInNraqiWhiteList(m:GetName()) ~= true then
			keys.target:RemoveModifierByName(m:GetName())
		end
	end
end

function IsModifierInNraqiWhiteList(modifier)
	local nraqi_debuff_whitelist = {
		"modifier_is_undead_buff",
		"modifier_is_undead_buff_plus",
		"modifier_is_undead_buff_plus_plus",
		"modifier_is_mage_buff",
		"modifier_is_mage_buff_plus",
		"modifier_is_mage_buff_plus_plus",
		"modifier_kill",
		"modifier_illusion",
		"modifier_marci_unleash_flurry_cooldown",
		"modifier_primal_beast_pulverize_lua_debuff",
		"modifier_primal_beast_pulverize_lua",
		"modifier_void_spirit_astral_step_debuff",
		"modifier_morph_str_buff",
		"modifier_sil_silence_all",
	}
	return FindValueInTable(nraqi_debuff_whitelist, modifier)
end

function IsVoodooModifier(modifier)
	local voodoo_debuff_whitelist = {
		"modifier_hexxed",
		"modifier_shadow_shaman_voodoo",
		"modifier_lion_voodoo",
	}
	return FindValueInTable(voodoo_debuff_whitelist, modifier)
end

--【棋子技能】
function CopyArcWarden(team)
	local aw_table = {}
	for i, v in pairs(GetValidChessOnBoard(team)) do
		if string.find(v:GetUnitName(), 'chess_aw') ~= nil then
			table.insert(aw_table, v)
		end
	end
	for ii, vv in pairs(aw_table) do
		--复制本尊
		local aposition = FindEmptyGridAtUnit(vv, nil, true)
		local team_id = vv:GetTeam()
		local at_team_id = vv.at_team_id or vv.team_id
		local items = GetAllItemsAndCDInUnits({ [1] = vv })
		local chess_star = GetChessStar(vv) or 1
		local x = SummonOneChess({
			teamid = vv:GetTeam(),
			position = aposition,
			chessname = vv:GetUnitName(),
			at_teamid = at_team_id,
			items = items,
			force_forward = forward_vector,
			ai_delay = 2,
			kill_duration = 10 * chess_star,
		})
		BlinkChessX({ caster = x, blink_type = "fall" })
		if vv.extra_synergy ~= nil and table.maxn(vv.extra_synergy) > 0 then
			for _, ss in pairs(vv.extra_synergy) do
				AddSynergy({
					caster = x,
					synergy = ss
				})
			end
			x:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(x, x, 'modifier_shining', {})
		end
		if vv.mojing_ability ~= nil then
			local a_level = vv.mojing_ability_level or 1 --GetChessStar(vv)
			if vv:HasModifier('modifier_item_ahalimushenzhang') then
				a_level = a_level + 1
			end
			if a_level > 3 then
				a_level = 3
			end
			AddAbilityAndSetLevel(x, x.mojing_ability, a_level)
		end
		Timers:CreateTimer(0.5, function()
			local xuejingshi_aw = GetPermanentStackCount(vv, 'xuejingshi')
			SyncPermanentStackCount({ caster = x, stack_name = 'xuejingshi', stack = xuejingshi_aw })
			local changdun_aw = GetPermanentStackCount(vv, 'changdun')
			SyncPermanentStackCount({ caster = x, stack_name = 'changdun', stack = changdun_aw })
		end)

		x.is_copied_aw = true
		vv.is_copied_aw = true
		vv.is_self_aw = true
	end
end

function RefreshKaelOrbandAbility(kael, find_combo)
	if kael:HasModifier('modifier_om_multi_cast') == true and kael.is_multi_cast_enable == true then
		--多重施法，不切
		return
	end
	if kael:HasAbility("invoke") == false then
		--没invoke技能，不切
		return
	end
	if kael:FindAbilityByName("invoke"):IsCooldownReady() == false then
		--invoke技能没冷却好，不切
		return
	end

	local a_list = {
		is_warrior = 'forge_spirit',
		is_assassin = 'invoker_deafening_blast_datadriven',
		is_mage = 'invoker_emp',
		is_hunter = 'invoker_deafening_blast_datadriven',
		is_elf = 'chaos_meteor_datadriven',
		is_warlock = 'alacrity',
		is_troll = 'kael_ice_wall',
		is_beast = 'chaos_meteor_datadriven',
		is_human = 'invoker_sun_strike',
		is_undead = 'chaos_meteor_datadriven',
		is_orc = 'forge_spirit',
		is_goblin = 'kael_ice_wall',
		is_mech = 'invoker_sun_strike',
		is_knight = 'invoker_sun_strike',
		is_dragon = 'kael_ice_wall',
		is_shaman = 'kael_ice_wall',
		is_druid = 'chaos_meteor_datadriven',
		is_wizard = 'alacrity',
		is_naga = 'alacrity',
		is_element = 'forge_spirit',
		is_god = 'invoker_emp',
		is_pandaman = 'invoker_emp',
		is_aqir = 'chaos_meteor_datadriven',
		is_priest = 'invoker_sun_strike',
		is_dwarf = 'invoker_deafening_blast_datadriven',
		is_demonhunter = 'invoker_deafening_blast_datadriven',
		is_ogre = 'kael_ice_wall',
		is_demon = 'invoker_sun_strike',
		is_monk = 'kael_ice_wall',
		is_tauren = 'alacrity',
		is_kobold = 'chaos_meteor_datadriven',
		is_nraqi = 'invoker_sun_strike',
		is_satyr = 'invoker_sun_strike',
		is_draenei = 'kael_ice_wall',
	}
	local aa_list = {
		[1] = 'is_warrior',
		[2] = 'is_assassin',
		[3] = 'is_mage',
		[4] = 'is_hunter',
		[5] = 'is_elf',
		[6] = 'is_warlock',
		[7] = 'is_troll',
		[8] = 'is_beast',
		[9] = 'is_human',
		[10] = 'is_undead',
		[11] = 'is_orc',
		[12] = 'is_goblin',
		[13] = 'is_mech',
		[14] = 'is_knight',
		[15] = 'is_dragon',
		[16] = 'is_shaman',
		[17] = 'is_druid',
		[18] = 'is_wizard',
		[19] = 'is_naga',
		[20] = 'is_element',
		[21] = 'is_god',
		[22] = 'is_pandaman',
		[23] = 'is_aqir',
		[24] = 'is_priest',
		[25] = 'is_dwarf',
		[26] = 'is_demonhunter',
		[27] = 'is_ogre',
		[28] = 'is_demon',
		[29] = 'is_monk',
		[30] = 'is_tauren',
		[31] = 'is_kobold',
		[32] = 'is_nraqi',
		[33] = 'is_satyr',
		[34] = 'is_draenei',
	}
	local kael_ability = a_list[aa_list[RandomInt(1, table.maxn(aa_list))]]
	local try_count = 0
	if find_combo ~= nil and a_list[find_combo] ~= nil then
		kael_ability = a_list[find_combo]
	end
	while kael.kael_ability_last ~= nil and kael.kael_ability_last == kael_ability and try_count < 100 do
		try_count = try_count + 1
		kael_ability = a_list[aa_list[RandomInt(1, table.maxn(aa_list))]]
	end

	local orb_table = {
		forge_spirit = { 'exort', 'exort', 'quas' },
		kael_ice_wall = { 'exort', 'quas', 'quas' },
		invoker_sun_strike = { 'exort', 'exort', 'exort' },
		chaos_meteor_datadriven = { 'exort', 'exort', 'wex' },
		alacrity = { 'exort', 'wex', 'wex' },
		invoker_emp = { 'wex', 'wex', 'wex' },
		-- invoker_cold_snap = {'quas','quas','quas'},
		-- invoker_tornado_datadriven = {'quas','wex','wex'},
		invoker_deafening_blast_datadriven = { 'quas', 'wex', 'exort' },
	}

	if kael_ability then
		for i = 1, 3 do
			if kael['orb_' .. i] then
				ParticleManager:DestroyParticle(kael['orb_' .. i], true)
			end
		end

		if orb_table[kael_ability] ~= nil then
			for index, orb in pairs(orb_table[kael_ability]) do
				local p_name = 'particles/units/heroes/hero_invoker_kid/invoker_kid_' .. orb .. '_orb.vpcf'
				kael['orb_' .. index] = ParticleManager:CreateParticle(p_name, PATTACH_OVERHEAD_FOLLOW, kael)
				ParticleManager:SetParticleControlEnt(kael['orb_' .. index], 1, kael, PATTACH_POINT_FOLLOW,
					"attach_orb" .. index, kael:GetAbsOrigin(), false)
			end
		end

		kael.kael_ability = kael_ability

		-- kael:RemoveAbility('invoke')
		kael:RemoveAbility('forge_spirit')
		kael:RemoveAbility('kael_ice_wall')
		kael:RemoveAbility('invoker_sun_strike')
		kael:RemoveAbility('chaos_meteor_datadriven')
		kael:RemoveAbility('alacrity')
		kael:RemoveAbility('invoker_emp')
		kael:RemoveAbility('invoker_deafening_blast_datadriven')

		local _, a_level = GetChessAbility(kael)

		AddAbilityAndSetLevel(kael, kael_ability, a_level)

		EmitSoundOn('Hero_Invoker.Invoke', kael)
		play_particle('particles/units/heroes/hero_invoker/invoker_invoke.vpcf', PATTACH_ABSORIGIN_FOLLOW, kael, 3)

		local cd = kael:FindAbilityByName("invoke"):GetCooldown(a_level - 1) or 1

		kael:FindAbilityByName("invoke"):StartCooldown(cd * GetCooldownPerByGod(kael))

		kael.kael_ability_refresh = nil
	end
	return kael_ability
end

--TK：热导飞弹
function RandomMissileStart(keys)
	local caster = keys.caster
	local ability_level = keys.ability:GetLevel()

	--三连发
	RandomMissileOne({ caster = keys.caster, ability = keys.ability })
	Timers:CreateTimer(0.3, function()
		RandomMissileOne({ caster = keys.caster, ability = keys.ability })
		Timers:CreateTimer(0.3, function()
			RandomMissileOne({ caster = keys.caster, ability = keys.ability })
			if ability_level >= 3 then
				Timers:CreateTimer(0.3, function()
					RandomMissileOne({ caster = keys.caster, ability = keys.ability })
				end)
			end
		end)
	end)
end

function RandomMissileOne(keys)
	--对一个随机的unluckydog发射导弹
	local unlucky_dog = FindUnluckyDog(keys.caster)
	if unlucky_dog ~= nil then
		-- if (unlucky_dog:GetAbsOrigin() - keys.caster:GetAbsOrigin()):Length2D() < 1500 then
