	end)
end

function TransformAMohuaChess(u, is_tb_ally, demon_buff)
	local has_demon_buff = false
	if demon_buff ~= nil and u:HasAbility('is_demonhunter') == true then
		has_demon_buff = true
	end

	if not (k_m ~= nil and k_d == 0) then
		local star = GetChessStar(u)
		local max_star = u.is_mohua_max_star or 1
		if star > max_star then
			star = max_star
		end
		local new_chess_name = 'chess_tb_mohua' .. star
		local old_chess_items = GetAllItemsAndCDInUnits({ [1] = u })
		local is_satyr_buff_cd = 0

		TransformAChess(u, new_chess_name, 0, function(x)
			if IsUnitExist(x) then
				play_particle("particles/units/heroes/hero_terrorblade/terrorblade_metamorphosis_transform.vpcf",
					PATTACH_ABSORIGIN_FOLLOW, x, 3)
				EmitSoundOn("Hero_Terrorblade.Metamorphosis", x)
				if has_demon_buff then
					local aa = AddAbilityAndSetLevel(x, demon_buff)
					aa:ApplyDataDrivenModifier(x, x, 'modifier_' .. demon_buff, {})
				end
				PlayParticleOnUnitUntilDeath({
					caster = x,
					p = "particles/units/heroes/hero_terrorblade/terrorblade_metamorphosis.vpcf",
				})
				if is_tb_ally then
					x.is_tb_ally = is_tb_ally
					x.old_chess_items = old_chess_items
					if x:HasModifier('modifier_yonghengzhipan_yongheng_buff') == false then
						x:AddNewModifier(x,nil,"modifier_kill",{duration = 60})
					end
				end
			end
		end)
	end
end

function TbMohuaNew(keys)
	local ability = keys.ability
	local caster = keys.caster
	local level = ability:GetLevel() or 1
	local p = caster:GetAbsOrigin()
	EmitSoundOn('Hero_Terrorblade.Sunder.Cast', caster)
	local team_id = caster:GetTeam()
	local at_team_id = caster.at_team_id or caster.team_id
	local exclude_entindex = caster:entindex()

	local demon_buff = nil
	if caster:HasModifier('modifier_is_demon_buff') then
		demon_buff = 'is_demon_buff'
	end
	if caster:HasModifier('modifier_is_demonhunter_buff_plus') then
		demon_buff = 'is_demonhunter_buff_plus'
	end
	local items = GetAllItemsAndCDInUnits({ [1] = caster }, nil, true)
	caster.mohua_items = items
	caster.is_mohua_max_star = GetChessStar(caster) or 1
	TransformAMohuaChess(caster, false)

	local tb_star = GetChessStar(caster) or 1

	if level > 1 then
		local luckydog1 = FindMohuaFriend(team_id, at_team_id, p, exclude_entindex)
		if luckydog1 ~= nil then
			local pp = ParticleManager:CreateParticle("particles/units/heroes/hero_terrorblade/terrorblade_sunder.vpcf",
				PATTACH_ABSORIGIN_FOLLOW, caster)
			ParticleManager:SetParticleControl(pp, 0, caster:GetAbsOrigin())
			ParticleManager:SetParticleControl(pp, 1, luckydog1:GetAbsOrigin())
			Timers:CreateTimer(2, function()
				if pp ~= nil then
					ParticleManager:DestroyParticle(pp, true)
					ParticleManager:ReleaseParticleIndex(pp)
				end
			end)
			luckydog1.is_mohua_max_star = tb_star
			luckydog1.demon_buff = demon_buff
			luckydog1.mohua_items = items
		end
	end

	if level > 2 then
		Timers:CreateTimer(0.4, function()
			local luckydog2 = FindMohuaFriend(team_id, at_team_id, p, exclude_entindex)
			if luckydog2 ~= nil then
				local pp = ParticleManager:CreateParticle(
				"particles/units/heroes/hero_terrorblade/terrorblade_sunder.vpcf", PATTACH_ABSORIGIN_FOLLOW, caster)
				ParticleManager:SetParticleControl(pp, 0, caster:GetAbsOrigin())
				ParticleManager:SetParticleControl(pp, 1, luckydog2:GetAbsOrigin())
				Timers:CreateTimer(2, function()
					if pp ~= nil then
						ParticleManager:DestroyParticle(pp, true)
						ParticleManager:ReleaseParticleIndex(pp)
					end
				end)
				luckydog2.is_mohua_max_star = tb_star
				luckydog2.demon_buff = demon_buff
				luckydog2.mohua_items = items
			end
		end)
	end
end

function FindMohuaFriend(team_id, chessboard_id, p, exclude_entindex)
	local luckydog = nil
	local distance_min = 9999
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if unit:GetTeam() == team_id and unit:HasAbility('is_ward') == false and string.find(unit:GetUnitName(), 'mohua') == nil and unit.is_mohua_max_star == nil and (exclude_entindex == nil or unit:entindex() ~= exclude_entindex) then
			local distance = (unit:GetAbsOrigin() - p):Length2D()
			if distance < distance_min then
				distance_min = distance
				luckydog = unit
			end
		end
	end
	return luckydog
end

