function MultiCast(u)
	if u:HasModifier('modifier_om_multi_cast') == true and u.is_multi_cast_enable == true and HasAbilityBuff(u) == false then
		local a = nil
		if string.find(u:GetUnitName(), 'chess_rubick') and u.steal_ability ~= nil then
			a = u.steal_ability
		elseif string.find(u:GetUnitName(), 'chess_kael') and (u.kael_ability ~= nil or u.kael_ability_last ~= nil) then
			a = u.kael_ability or u.kael_ability_last
		else
			a = _G.chess_ability_list[u:GetUnitName()] or _G.summon_ability_list[u:GetUnitName()]
		end
		if u.ice_or_fire == 'fire' then
			a = 'jakiro_macropyre'
		end
		if u.ice_or_fire == 'ice' then
			a = 'jakiro_ice_path'
		end
		if a ~= nil and u:FindAbilityByName(a) ~= nil and u:FindAbilityByName(a):IsCooldownReady() == false then
			PlayMultiCastParticle({
				p = 'effect/multicast/1.vpcf',
				caster = u,
			})

			u:FindAbilityByName(a):EndCooldown()
			EmitSoundOn("om.multi_cast2", u)
			u:RemoveModifierByName('modifier_om_multi_cast')
			u:SetMana(GetManaCostX(u, a))
			
			u.is_multi_cast_enable = false

			--多重施法内置cd
			u:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(u, u, 'modifier_multi_cast_cd', { duration = 5 })
		else
			return
		end
		return 0.1
	else
		return
	end
end

--棋子施法（false为施法失败，true为施法成功）
function OnChessCastStart(u, dog)
	--触发啄木鸟图腾
	local ward_nether_result = WardNether({
		caster = u,
	})
	if ward_nether_result == true then
		--如果施法被啄木鸟图腾沉默了，就不进行后面的逻辑
		return false
	end
	local a_name = GetChessAbility(u)
	local a = u:FindAbilityByName(a_name)
	TriggerSMArcaneBolt({
		caster = u,
		target = dog
	})
	if a ~= nil then
		if a:GetAbilityName() == 'poof' or a:GetAbilityName() == 'dawnbreaker_fire_wreath' then
			dog = nil
		end
	end

	--新多重施法
	if u:HasModifier('modifier_om_multi_cast_aura_buff') == true and u:HasModifier('modifier_multi_cast_cd') == false then
		local om_modifier = u:FindModifierByName('modifier_om_multi_cast_aura_buff')
		if om_modifier ~= nil then
			local om_ability = om_modifier:GetAbility()
			if om_ability ~= nil then
				local per = GetAbilityKV(om_ability, "multi_per") or 30
				if RandomInt(1,100) < per then
					om_ability:ApplyDataDrivenModifier(u, u, 'modifier_om_multi_cast', {})
					-- om_ability:ApplyDataDrivenModifier(u, u, 'modifier_om_multi_attack_speed_buff', {})
				end
			end
		end
	end

	--林肯的逻辑判断
	if dog == nil or BlockByLinken(dog) == false then
		--可以成功施法
		if u:HasModifier('modifier_om_multi_cast') == true then
			u.is_multi_cast_enable = true
		else
			if string.find(u:GetUnitName(), 'chess_kael') ~= nil then
				u.kael_ability_refresh = true
				u.kael_ability_last = u.kael_ability
				u.kael_ability = nil
			end
		end
		if u:HasModifier('modifier_is_shaman_buff_plus') == true or u:HasModifier('modifier_is_shaman_buff_plus_plus') == true then
			--萨满施法进化
			u.evolve_result = RandomEvolveResult(u)
		end
		--成功施法。新六神减cd
		if u:HasModifier('modifier_is_god_buff_plus_plus') == true and u:GetMaxMana() > 0 then
			SixGodReduceCooldown(u)
		end

		return true
	else
		--被林肯挡了
		u:SetMana(0)
		a:StartCooldown(a:GetCooldown(a:GetLevel()))
		play_particle('particles/econ/items/drow/drow_arcana/drow_arcana_msg_deny_v2_symbol_question.vpcf',
			PATTACH_OVERHEAD_FOLLOW, u, 3)

		u:StartGesture(ACT_DOTA_CAST_ABILITY_1)

		ExecuteOrderFromTable({
			UnitIndex = u:entindex(),
			OrderType = DOTA_UNIT_ORDER_MOVE_TO_POSITION,
			Position = dog:GetAbsOrigin(),
			Queue = 0,
		})

		return false
	end
end

function PlayMultiCastParticle(keys)
	local p = keys.p
	local u = keys.caster
	local multi = keys.multi or 2
	if u == nil then
		return
	end
	local pos = keys.pos or PATTACH_OVERHEAD_FOLLOW
	local pp = ParticleManager:CreateParticle(p, pos, u)

	Timers:CreateTimer(0.1, function()
		if u == nil or u:IsNull() == true or u:IsAlive() == false then
			if pp ~= nil then
				ParticleManager:DestroyParticle(pp, true)
				ParticleManager:ReleaseParticleIndex(pp)
			end
			return
		end
		if pp == nil then
			return
		end
		return 0.1
	end)

	return pp
end

function AdjustHuskarBuff(keys)
	local caster = keys.caster
	local ability = keys.ability
	local ability_level = ability:GetLevel()

	if IsUnitExist(caster) == false then
		return
	end

	local hp_per = 1.0 * caster:GetHealth() / caster:GetMaxHealth()
	local hp_lose_per = (1 - hp_per) * 100
	local hp_lose_level = math.floor(hp_lose_per / 10)

	AddAbilityAndSetLevel(caster, 'huskar_buff' .. ability_level, hp_lose_level)
end

