	u.is_sadan_damaged = nil
	local ability = FindItemAbilityByName(u, 'item_sadan')
	if ability and ability:IsCooldownReady() == true then
		InvisibleUnitCast({
			caster = u,
			ability = 'give_sadan_buff',
			level = 1,
			unluckydog = u,
			ignore_nether_ward = true,
		})
		return 0.5
	end
end

