--净魂之刃
function TriggerJinghunzhiren(u, lengjing)
	local ability = FindItemAbilityByName(u, 'item_jinghunzhiren')
	if ability and (ability:IsCooldownReady() == true or lengjing) then
		local dog = u:GetAttackTarget()
		if u:IsNull() ~= true and dog ~= nil and dog:IsNull() ~= true then
			--有羊的目标！
			if dog:IsMagicImmune() == true then
				return
			end
			if BlockByLinken(dog) == false then
				--驱散一下种族/职业buff
				EmitSoundOn('DOTA_Item.DiffusalBlade.Activate', dog)
				play_particle("particles/items_fx/diffusal_slow.vpcf", PATTACH_ABSORIGIN_FOLLOW, dog, 6)
				for _, m in pairs(dog:FindAllModifiers()) do
					if m:IsDebuff() == false and IsModifierCanPurify(m:GetName()) == true then
						local a = m:GetAbility()
						if a and a:GetAbilityName() then
							if _G.combo_ability_list[a:GetAbilityName()] ~= nil then
								dog:RemoveModifierByName(m:GetName())
							end
						end
					end
				end
			end
			return 0.5
		else
			return
		end
	end
end

--被动版净魂之刃，已废弃
function JinghunAttack(keys)
	local caster = keys.caster
	local attack_target_curr = caster.attack_target_curr
	if IsUnitExist(caster) == false then
		return
	end
	local ability = keys.ability

	local curr_target = caster:GetAttackTarget()
	if curr_target == nil or curr_target:entindex() == nil then
		return
	end
	local curr_attack_target_index = curr_target:entindex() or 0
	local last_attack_target_index = caster.last_attack_target_index or 0

	if curr_attack_target_index ~= last_attack_target_index then
		caster.last_attack_target_index = curr_attack_target_index
		--净化！净魂之刃
		local dog = curr_target
		if caster:IsNull() ~= true and dog ~= nil and dog:IsNull() ~= true then
			if dog:IsMagicImmune() == true then
				return
			end
			if BlockByLinken(dog) == false then
				--驱散一下种族/职业buff
				EmitSoundOn('DOTA_Item.DiffusalBlade.Activate', dog)
				play_particle("particles/items_fx/diffusal_slow.vpcf", PATTACH_ABSORIGIN_FOLLOW, dog, 6)
				for _, m in pairs(dog:FindAllModifiers()) do
					if m:IsDebuff() == false and IsModifierCanPurify(m:GetName()) == true then
						local a = m:GetAbility()
						if a and a:GetAbilityName() then
							if _G.combo_ability_list[a:GetAbilityName()] ~= nil then
								dog:RemoveModifierByName(m:GetName())
							end
						end
					end
				end
			end
		else
			return
		end
	end
end

function IsModifierCanPurify(m_name)
	local black_list = {
		"modifier_ad_1000",
		"modifier_ad_100",
		"modifier_ad_10",
		"modifier_ad_1",
	}
	if m_name == nil then
		return false
	end
	if FindValueInTable(black_list, m_name) == false then
		return true
	else
		return false
	end
end

