	local ability = FindItemAbilityByName(u, 'item_fulingsuo')
	if ability and ability:IsCooldownReady() == true then
		local dog = FindHighLevelUnluckyDog(u, true, false, 'modifier_item_fulingsuo_debuff')
		if IsUnitExist(dog) == true then
			local dogs = FindAllUnitsAroundUnluckyDogByRadius(dog, 300) or {}
			for _, d in pairs(dogs) do
				if d:IsMagicImmune() ~= true then
					ability:ApplyDataDrivenModifier(d, d, 'modifier_item_fulingsuo_debuff', { duration = 4, })
					ApplyDamage({
						victim = d,
						attacker = u,
						damage = 100,
						damage_type = DAMAGE_TYPE_MAGICAL,
						ability = ability,
					})
					PlayLightningParticle(u, d, 1)
				end
			end
			EmitSoundOn("Hero_Zuus.ArcLightning.Cast", u)
			return 0.5
		else
			return
		end
	end
end

function PlayLightningParticle(u, d, duration)
	local lightningBolt = ParticleManager:CreateParticle("particles/units/heroes/hero_zuus/zuus_arc_lightning.vpcf",
		PATTACH_WORLDORIGIN, u)
	ParticleManager:SetParticleControl(lightningBolt, 0,
		Vector(u:GetAbsOrigin().x, u:GetAbsOrigin().y, u:GetAbsOrigin().z + u:GetBoundingMaxs().z))
	ParticleManager:SetParticleControl(lightningBolt, 1,
		Vector(d:GetAbsOrigin().x, d:GetAbsOrigin().y, d:GetAbsOrigin().z + d:GetBoundingMaxs().z))
	Timers:CreateTimer(duration, function()
		if lightningBolt ~= nil then
			ParticleManager:DestroyParticle(lightningBolt, true)
			ParticleManager:ReleaseParticleIndex(lightningBolt)
		end
	end)
end

function TriggerActiveItem(u, item_name, cb, lengjing)
	--用之前
	if u:FindModifierByName("modifier_" .. item_name) == nil then
		return
	end
	--使用过程
	local ai_interval = cb(u)
	--使用失败
	if ai_interval == nil then return end
	--法术棱镜
	if lengjing == true and u:HasModifier('modifier_item_fashulengjing') == true then
		Timers:CreateTimer(0.3, function()
			cb(u, true)
		end)
	end
	--使用成功
	local item_ability = FindItemAbilityByName(u, item_name)
	if item_ability then
		TriggerStartCooldown(u, item_ability, item_ability:GetCooldown(1))
	end
	if (u:HasModifier('modifier_is_shaman_buff_plus') or u:HasModifier('modifier_is_shaman_buff_plus_plus')) and item_name ~= 'item_jurenzhijie' then
		u.evolve_result = RandomEvolveResult(u)
	end
	return ai_interval
end

function FindFullManaEnemy(u)
	local all_chess = GetValidChessOnBoard(u.at_team_id or u.team_id)
	for i, v in pairs(all_chess) do
		if IsUnitExist(v) and u:GetTeam() ~= v:GetTeam() and v:GetMana() >= 90 then
			return true
		end
	end
	return false
end

function TriggerBKB(u)
	if u:FindModifierByName("modifier_bkb_buff") ~= nil then
		return
	end
	local spell_danger = FindFullManaEnemy(u)
	if u.is_bkb_damaged == nil and spell_danger == false then
		return
	end
	u.is_bkb_damaged = nil
	local ability = FindItemAbilityByName(u, 'item_bkb')
	if ability and ability:IsCooldownReady() == true then
		EmitSoundOn('DOTA_Item.BlackKingBar.Activate', u)
		u:Purge(false, true, false, false, false) --净化
		ability:ApplyDataDrivenModifier(u, u, 'modifier_bkb_buff', { duration = 4 })
		return 0.5
	end
end

