function TriggerDongchayandou(u)
	if u:FindModifierByName("modifier_pipe_buff") ~= nil then
		return
	end
	if u.is_pipe_damaged == nil then
		return
	end
	u.is_pipe_damaged = nil
	local ability = FindItemAbilityByName(u, 'item_dongchayandou')
	if ability and ability:IsCooldownReady() == true then
		play_particle("particles/items2_fx/pipe_of_insight_launch.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 6)
		EmitSoundOn("DOTA_Item.Pipe.Activate", u)
		ability:ApplyDataDrivenModifier(u, u, 'modifier_item_dongchayandou_buff', { duration = 10, })

		local units = FindUnitsInRadiusOnTeamGround({
			team = u:GetTeam(),
			at_team = u.at_team_id or u.team_id,
			role = 1,
			position = u:GetAbsOrigin(),
			radius = 500,
		})
		if units ~= nil then
			for _, unluckydog in pairs(units) do
				if IsUnitExist(unluckydog) == true and unluckydog:entindex() ~= u:entindex() then
					ability:ApplyDataDrivenModifier(u, unluckydog, 'modifier_item_dongchayandou_buff', { duration = 10 })
				end
			end
		end
		return 0.5
	end
end

