function TriggerAoshuxie(u)
	local ability = FindItemAbilityByName(u, 'item_aoshuxie')
	if ability and ability:IsCooldownReady() == true then
		local max_distance = GetAbilityKV(ability, 'max_distance') or 9999
		play_particle("particles/items_fx/arcane_boots.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 5)
		EmitSoundOn('DOTA_Item.ArcaneBoots.Activate', u)
		for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
			if unit.team_id == u.team_id and unit:GetMaxMana() ~= 0 then
				if (unit:GetAbsOrigin() - u:GetAbsOrigin()):Length2D() <= max_distance then
					play_particle('particles/items_fx/arcane_boots_recipient.vpcf', PATTACH_OVERHEAD_FOLLOW, unit, 3)
					AddChessManaInstant(unit, 40)
				end
			end
		end
		return 0.5
	end
end

function TriggerXiangweixie(u)
	if not IsChessCanMove(u, true) then
		return
	end
	if u:Script_GetAttackRange() > 205 then
		--远程不主动使用
		return
	end
	local ability = FindItemAbilityByName(u, 'item_xiangweixie')
	if ability and ability:IsCooldownReady() == true then
		local find_ok = FindNextPhaseBootsPosition(u)
		if find_ok ~= nil then
			local chessboard_id = u.at_team_id or u.team_id
			u:Stop()
			local yy = u.y
			local xx = u.x
			local y = Vector2Y(find_ok, chessboard_id)
			local x = Vector2X(find_ok, chessboard_id)
			_G.unit[chessboard_id][y .. '_' .. x] = 1
			u.is_moving = true
			BlinkChessX({
				p = find_ok,
				caster = u,
				blink_type = 'jump',
				sound = "DOTA_Item.PhaseBoots.Activate",
			})
			u.y_x = y .. '_' .. x
			u.y = y
			u.x = x
			_G.unit[chessboard_id][yy .. '_' .. xx] = nil
			return 0.5
		end
	end
end

function TriggerMeiken(u)
	local ability = FindItemAbilityByName(u, 'item_meiken')
	if ability and ability:IsCooldownReady() == true then
		local max_distance = GetAbilityKV(ability, 'max_distance') or 9999
		if u:GetHealth() < u:GetMaxHealth() / 2 or GetMeikenHealAmount(u, max_distance) >= 500 then
			EmitSoundOn("item.meiken", u)
			for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
				if unit.team_id == u.team_id and (unit:GetAbsOrigin() - u:GetAbsOrigin()):Length2D() <= max_distance then
					play_particle('particles/items2_fx/mekanism.vpcf', PATTACH_ABSORIGIN_FOLLOW, unit, 3)
					unit:Heal(500, unit)
				end
			end
			return 0.5
		end
	end
end

function TriggerWeishijingjia(u)
	local ability = FindItemAbilityByName(u, 'item_weishijingjia')
	if ability and ability:IsCooldownReady() == true then
		local max_distance = GetAbilityKV(ability, 'max_distance') or 9999
		if u:GetHealth() < u:GetMaxHealth() / 2 or GetMeikenHealAmount(u, max_distance) >= 500 then
			EmitSoundOn("item.weishijingjia", u)
			local units = FindUnitsInRadiusOnTeamGround({
				team = u:GetTeam(),
				at_team = u.at_team_id or u.team_id,
				role = 1,
				position = u:GetAbsOrigin(),
				radius = 500,
			})
			for _, unit in pairs(units) do
				if unit.team_id == u.team_id and (unit:GetAbsOrigin() - u:GetAbsOrigin()):Length2D() <= max_distance and unit:HasAbility('is_ward') == false then
					play_particle('particles/items3_fx/warmage_recipient.vpcf', PATTACH_ABSORIGIN_FOLLOW, unit, 3)
					-- ModMaxHP({
					-- 	caster = unit,
					-- 	const = 500,
					-- 	is_heal = true,
					-- })
					ability:ApplyDataDrivenModifier(u, unit, 'modifier_item_weishijingjia_buff', {})

					-- unit:Heal(500,unit)
					AddChessManaInstant(unit, 30)
					unit:Purge(false, true, false, false, false)

					--驱散一下debuff
					local black_list = {
						'modifier_mind_control_debuff',
						'modifier_sil_silence_all',
					}
					for _, m in pairs(unit:FindAllModifiers()) do
						if m:IsDebuff() and IsModifierInNraqiWhiteList(m:GetName()) ~= true then
							if FindValueInTable(black_list, m:GetName()) == false then
								unit:RemoveModifierByName(m:GetName())
							end
						end
					end
				end
			end
			return 0.5
		end
	end
end

function GetMeikenHealAmount(u, max_distance)
	local heal_amount = 0
	if not max_distance then
		max_distance = 9999
	end
	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		if IsUnitExist(unit) and unit.team_id == u.team_id and (unit:GetAbsOrigin() - u:GetAbsOrigin()):Length2D() <= max_distance then
			local amount = unit:GetMaxHealth() - unit:GetHealth()
			if amount > 500 then
				amount = 500
			end
			heal_amount = heal_amount + amount
		end
	end
	return heal_amount
end

function TriggerYuanlifazhang(u)
	--新版：如果自身血量过低，就考虑推
	if not IsChessCanMove(u, true) then
		return
	end
	-- if u.tuitui_attacked ~= true then
	-- 	return
	-- end
	local hp = u:GetHealth() or 0
	local hp_per = 1.0 * u:GetHealth() / (u:GetMaxHealth() or 1)

	local enemy_team_id = 4
	if u:GetTeam() == 4 then
		enemy_team_id = u.at_team_id
	end

	if (u:Script_GetAttackRange() > 205 and IsLonely4Team(u, enemy_team_id) == false) or (hp < 300 or hp_per < 0.5) then
		--尝试推！
		local ability = FindItemAbilityByName(u, 'item_yuanlifazhang')
		if ability and ability:IsCooldownReady() == true then
			local chessboard_id = u.at_team_id or u.team_id
			local find_ok = FindEscapePosition(u)
			if find_ok ~= nil then
				u:Stop()
				local yy = u.y
				local xx = u.x
				local y = Vector2Y(find_ok, chessboard_id)
				local x = Vector2X(find_ok, chessboard_id)
				_G.unit[chessboard_id][y .. '_' .. x] = 1
				u.is_moving = true
				BlinkChessX({ p = find_ok, caster = u, blink_type = 'tuitui' })
				EmitSoundOn("DOTA_Item.ForceStaff.Activate", u)
				u.y_x = y .. '_' .. x
				u.y = y
				u.x = x
				_G.unit[chessboard_id][yy .. '_' .. xx] = nil

				u.tuitui_attacked = nil
				AddChessManaInstant(u, 20)
				return 0.5
			else
				return
			end
		end
	else
		return
	end
end

