function JuFengAttack(keys)
	local caster = keys.caster
	local target = caster:GetAttackTarget()
	local modifier = caster:FindModifierByName('modifier_item_jufengchangji_buff')
	if modifier == nil then
		return
	end

	local stack = modifier:GetStackCount()
	if stack <= 1 or caster.taunt_target == nil or IsUnitExist(caster.taunt_target) == false then
		caster:RemoveModifierByName('modifier_item_jufengchangji_buff')
		caster.taunt_target = nil
	end
	if caster.taunt_target ~= nil and IsUnitExist(caster.taunt_target) == true and target:entindex() ~= caster.taunt_target:entindex() then
		caster:RemoveModifierByName('modifier_item_jufengchangji_buff')
		caster.taunt_target = nil
	end
	modifier:SetStackCount(stack - 1)
end

function FindItemAbilityByName(u, item_name)
	for slot = 0, 5 do
		if u:GetItemInSlot(slot) ~= nil then
			local ability = u:GetItemInSlot(slot)
			local name = ability:GetAbilityName()
			if name == item_name then
				return ability
			end
		end
	end
end

function TriggerTiaodao(u)
	if not IsChessCanMove(u, true) then
		return
	end
	RemoveAbilityAndModifier(u, 'jiaoxie_wudi')
	RemoveAbilityAndModifier(u, 'jiaoxie')
	local ability = FindItemAbilityByName(u, 'item_tiaodao')
	if ability and ability:IsCooldownReady() == true then
		local find_ok = nil
		if u:HasModifier('modifier_is_centaur_buff') then
			find_ok = FindNextCentaurPosition(u, 200)
			Timers:CreateTimer(0.5, function()
				u.centaur_rushing = false
				u:RemoveModifierByName("modifier_is_centaur_buff")
				u:RemoveModifierByName("modifier_bloodseeker_thirst")
			end)
		else
			find_ok = FindFarthestCanAttackEnemyEmptyGrid(u, GetAbilityKV(ability, 'max_blink_distance') or 600)
		end
		if find_ok ~= nil then
			local x = Vector2X(find_ok, u.at_team_id or u.team_id)
			local y = Vector2Y(find_ok, u.at_team_id or u.team_id)
			local xx = u.x
			local yy = u.y
			_G.unit[u.at_team_id or u.team_id][y .. '_' .. x] = 1
			u:SetAbsOrigin(find_ok)
			u.y_x = y .. '_' .. x
			u.y = y
			u.x = x
			_G.unit[u.at_team_id or u.team_id][yy .. '_' .. xx] = nil

			-- AMHC:CreateNumberEffect(u,20,2,AMHC.MSG_MISS,{128,128,255},0)
			-- u:GiveMana(20)

			play_particle("particles/items_fx/blink_dagger_end.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)
			EmitSoundOn("DOTA_Item.BlinkDagger.Activate", u)

			u.is_moved = true

			if u.has_assassin_blink == true then
				u.has_assassin_blink = nil
				InitAssassinJump(u)
			end
		else
			return
		end
		return 0.5
	end
end

function TriggerDatiaodao(u)
	if not IsChessCanMove(u, true) then
		return
	end
	--智力跳刀，技能冷却时跳
	local chess_ability_name = GetChessAbility(u)
	local chess_ability = u:FindAbilityByName(chess_ability_name)
	local mojing_ability_name = u.mojing_ability
	local mojing_ability = nil
	if mojing_ability_name then
		mojing_ability = u:FindAbilityByName(mojing_ability_name)
	end
	if chess_ability and chess_ability:IsCooldownReady() and (mojing_ability == nil or mojing_ability:IsCooldownReady()) then
		return
	end

	RemoveAbilityAndModifier(u, 'jiaoxie_wudi')
	RemoveAbilityAndModifier(u, 'jiaoxie')

	local ability = FindItemAbilityByName(u, 'item_zhilidatiaodao')
	if ability and ability:IsCooldownReady() == true then
		local find_ok = nil
		if u:HasModifier('modifier_is_centaur_buff') then
			find_ok = FindNextCentaurPosition(u, 200)
			Timers:CreateTimer(0.5, function()
				u.centaur_rushing = false
				u:RemoveModifierByName("modifier_is_centaur_buff")
				u:RemoveModifierByName("modifier_bloodseeker_thirst")
			end)
		else
			find_ok = FindFarthestCanAttackEnemyEmptyGrid(u, GetAbilityKV(ability, 'max_blink_distance') or 800)
		end
		if find_ok ~= nil then
			local x = Vector2X(find_ok, u.at_team_id or u.team_id)
			local y = Vector2Y(find_ok, u.at_team_id or u.team_id)
			local xx = u.x
			local yy = u.y
			_G.unit[u.at_team_id or u.team_id][y .. '_' .. x] = 1
			u:SetAbsOrigin(find_ok)
			u.y_x = y .. '_' .. x
			u.y = y
			u.x = x
			_G.unit[u.at_team_id or u.team_id][yy .. '_' .. xx] = nil

			AMHC:CreateNumberEffect(u, 30, 2, AMHC.MSG_MISS, { 128, 128, 255 }, 0)
			u:GiveMana(30)

			play_particle("particles/items_fx/blink_dagger_end.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)
			EmitSoundOn("DOTA_Item.BlinkDagger.Activate", u)

			if u.has_assassin_blink == true then
				u.has_assassin_blink = nil
				InitAssassinJump(u)
			end

			-- if name == 'item_liliangdatiaodao' then
			-- 	TriggerStartCooldown(u,ability,8)
			-- 	local modifier_show = u:FindModifierByName('modifier_item_liliangdatiaodao_buff_show')
			-- 	local stack = 0
			-- 	if modifier_show == nil then
			-- 		ability:ApplyDataDrivenModifier(u, u, 'modifier_item_liliangdatiaodao_buff_show', {})
			-- 	else
			-- 		stack = modifier_show:GetStackCount()
			-- 	end
			-- 	stack = stack + 1
			-- 	u:FindModifierByName('modifier_item_liliangdatiaodao_buff_show'):SetStackCount(stack)
			-- 	ability:ApplyDataDrivenModifier(u, u, 'modifier_item_liliangdatiaodao_buff', {})
			-- end
			-- if name == 'item_minjiedatiaodao' then
			-- 	TriggerStartCooldown(u,ability,8)
			-- 	local modifier_show = u:FindModifierByName('modifier_item_minjiedatiaodao_buff_show')
			-- 	local stack = 0
			-- 	if modifier_show == nil then
			-- 		ability:ApplyDataDrivenModifier(u, u, 'modifier_item_minjiedatiaodao_buff_show', {})
			-- 	else
			-- 		stack = modifier_show:GetStackCount()
			-- 	end
			-- 	stack = stack + 1
			-- 	u:FindModifierByName('modifier_item_minjiedatiaodao_buff_show'):SetStackCount(stack)
			-- 	ability:ApplyDataDrivenModifier(u, u, 'modifier_item_minjiedatiaodao_buff', {})
			-- end
			if name == 'item_zhilidatiaodao' then
				local modifier_show = u:FindModifierByName('modifier_item_zhilidatiaodao_buff_show')
				local stack = 0
				if modifier_show == nil then
					ability:ApplyDataDrivenModifier(u, u, 'modifier_item_zhilidatiaodao_buff_show', {})
				else
					stack = modifier_show:GetStackCount()
				end
				stack = stack + 1
				u:FindModifierByName('modifier_item_zhilidatiaodao_buff_show'):SetStackCount(stack)
				ability:ApplyDataDrivenModifier(u, u, 'modifier_item_zhilidatiaodao_buff', {})

				if chess_ability and chess_ability:GetCooldownTimeRemaining() > 0 then
					local cd = chess_ability:GetCooldownTimeRemaining()
					local cd_new = cd - 5
					if cd_new < 0 then
						cd_new = 0
					end
					if cd_new <= 0 then
						chess_ability:EndCooldown()
					else
						chess_ability:EndCooldown()
						chess_ability:StartCooldown(cd_new)
					end
				end
				if mojing_ability and mojing_ability:GetCooldownTimeRemaining() > 0 then
					local cd = mojing_ability:GetCooldownTimeRemaining()
					local cd_new = cd - 5
					if cd_new < 0 then
						cd_new = 0
					end
					if cd_new <= 0 then
						mojing_ability:EndCooldown()
					else
						mojing_ability:EndCooldown()
						mojing_ability:StartCooldown(cd_new)
					end
				end
			else
				return
			end
			return 0.5
		end
	end
end

function TriggerHongzhang(u, lengjing)
	local ability = FindItemAbilityByName(u, 'item_hongzhang')
	if ability and (ability:IsCooldownReady() == true or lengjing) then
		EmitSoundOn("DOTA_Item.Dagon.Activate", u)
		local victim = FindUnluckyDog(u)
		if victim == nil then
			return
		end
		local info = {
			Target = victim,
			Source = u,
			Ability = nil,
			EffectName = "particles/econ/events/ti5/dagon_ti5.vpcf",
			bDodgeable = false,
			iMoveSpeed = 3000,
			bProvidesVision = false,
			iVisionRadius = 0,
			iVisionTeamNumber = u:GetTeamNumber(),
			iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_ATTACK_1
		}
		projectile = ProjectileManager:CreateTrackingProjectile(info)
		if victim:IsMagicImmune() == false then
			if BlockByLinken(victim) == false then
				ApplyDamage({
					victim = victim,
					attacker = u,
					damage_type = DAMAGE_TYPE_MAGICAL,
					damage = 700,
					ability = ability,
				})
			end
		end
		return 0.5
	end
end

function TriggerJurenzhijie(u)
