	if ability and ability:IsCooldownReady() == true then
		ability:ApplyDataDrivenModifier(u, u, 'modifier_item_jurenzhijie_buff', {})
		return 0.5
	end
end

function TriggerXueji(u, lengjing)
	local ability = FindItemAbilityByName(u, 'item_xueji')
	if ability and (ability:IsCooldownReady() == true or lengjing) then
		local dog = FindHighLevelUnluckyDog(u, true, false, 'modifier_item_xueji_debuff', true, false)
		if IsUnitExist(dog) then
			if BlockByLinken(dog) == false then
				ability:ApplyDataDrivenModifier(u, dog, 'modifier_item_xueji_debuff', { duration = 6 })
				EmitSoundOn('DOTA_Item.Bloodthorn.Activate', dog)
			end
			return 0.5
		end
	end
end

function CheckXuejiDebuff(keys)
