function TriggerHuanyingfu(u)
	local ability = FindItemAbilityByName(u, 'item_huanyingfu')
	if ability and ability:IsCooldownReady() == true then
		EmitSoundOn("DOTA_Item.Manta.Activate", u)
		play_particle("particles/generic_gameplay/illusion_killed.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)
		local items = GetAllItemsAndCDInUnits({ [1] = u }, nil, true)
		SummonMinion(u, u:GetUnitName(), 2, "particles/generic_gameplay/illusion_killed.vpcf", function(w)
			if IsUnitExist(w) == false then
				return
			end
			local hp_set = u:GetHealth()
			local hp_max_set = u:GetMaxHealth()
			if hp_set < 1 then
				hp_set = 1
			end
			w:SetBaseMaxHealth(hp_max_set)
			w:SetMaxHealth(hp_max_set)
			w:SetHealth(hp_set)
			w:AddNewModifier(w, nil, "modifier_illusion", { duration = 7 })
			if items ~= nil then
				GiveItems2Unit(items, w)
			end
			w.is_mirror = true
			w:SetMaxMana(0)
			FillEmptySlot(w)
			ExtendBeastBuff(w, u, false, false)
			if GetChessAbility(w) ~= nil then
				local a, a_level = GetChessAbility(w)

				if w:FindAbilityByName(a) == nil then
					AddAbilityAndSetLevel(w, a, a_level)
				else
					w:FindAbilityByName(a):SetLevel(a_level)
				end
			end
		end)
		return 0.5
	end
end

function DropShengJian(team)
	for _, obj in pairs(_G.mychess[team]) do
		local items = obj['item']

		for item_index, item in pairs(items) do
			if item == 'item_shengjian' then
				local lucky_team = RandomDropOneGGItem('item_shengjian', TeamId2Hero(team))
				--圣剑掉落消息通知
				if lucky_team ~= nil then
					table.remove(items, item_index)
					ShowCombat({
						t = 'drop_shengjian',
						player = TeamId2Hero(team):GetPlayerID(),
						player2 = TeamId2Hero(lucky_team):GetPlayerID(),
					})
				end
			end
		end
	end
end

function GetCurrRelicNameByTeam(team)
	local hero = TeamId2Hero(team)
	if IsUnitExist(hero) == false then
		return
	end
	for slot = 0, 9 do
		local item = hero:GetItemInSlot(slot)
		if item ~= nil then
			local item_name = item:GetAbilityName()
			if FindValueInTable(_G.DROP_RELIC_LIST, item_name) == true or item_name == 'item_stolen_vault' then
				return item_name
			end
		end
	end
end
function GetCurrRelicByTeam(team)
	local hero = TeamId2Hero(team)
	if IsUnitExist(hero) == false then
		return
	end
	for slot = 0, 9 do
		local item = hero:GetItemInSlot(slot)
		if item ~= nil then
			local item_name = item:GetAbilityName()
			if FindValueInTable(_G.DROP_RELIC_LIST, item_name) == true then
				return item
			end
		end
	end
end

--收集多个棋子的装备，第二个参数是可选的进化等级
function GetAllItemsAndCDInUnits(units, item_evolve_level, ignore_temp_items, ignore_aegis)
	--收集棋子的物品
	local items_table = {}
	for _, vv in pairs(units) do
		if IsUnitExist(vv, true) == true then
			--记录装备情况
			for slot = 0, 9 do
				if vv:GetItemInSlot(slot) ~= nil then
					local item = vv:GetItemInSlot(slot)
					local name = item:GetAbilityName()
					local charges = item:GetCurrentCharges()
					local cd = item:GetCooldownTimeRemaining()
					local item_name = vv:GetItemInSlot(slot):GetAbilityName()
					if item_name ~= 'item_null' then
						if item_evolve_level ~= nil and item:IsPermanent() == true and item_name ~= 'item_shengjian' then
							if item_name == 'item_moping_kong' then
								item_name = 'item_moping'
							end
							local o_level = _G.ITEM_2_LEVEL[item_name]
							if o_level then
								local r_level = o_level + item_evolve_level
								if r_level > 5 then r_level = 5 end
								local try_time = 0
								local r_item = nil
								while try_time < 10 and (r_item == nil or r_item == 'item_shengjian') do
									try_time = try_time + 1
									r_item = _G.ITEM_LIST_BY_LEVEL[r_level]
									[RandomInt(1, table.maxn(_G.ITEM_LIST_BY_LEVEL[r_level]))]
								end
								if r_item ~= nil then
									item_name = r_item
									cd = nil
								end
							end
						end
						if not ignore_temp_items or item:IsPermanent() == true then
							local insertable = true
							for i, v in pairs(items_table) do
								if v.item == item_name and (item_name == 'item_xuejingshi' or item_name == 'item_changdun') then
									insertable = false
									break
								end
							end
							if insertable then
								table.insert(items_table, {
									item = item_name,
									charges = charges,
									cd = cd,
								})
							end
						end
					end
				end
			end
		end
	end
	return items_table
end

--把装备给棋子
function GiveItems2Unit(items, unit)
	if IsUnitExist(unit) == false then
		return
	end
	for _, v in pairs(items) do
		local item_name = v.item or v
		local charges = v.charges or 1
		local cd = v.cd or 0
		unit:AddItemByName(item_name)

		for slot = 0, 8 do
			if unit:GetItemInSlot(slot) ~= nil then
				local i = unit:GetItemInSlot(slot)
				local n = i:GetAbilityName()
				if item_name == n then
					if cd > 0 then
						i:StartCooldown(cd)
					end
					if charges > 1 then
						i:SetCurrentCharges(charges)
					end
				end
			end
		end
	end
end

function DropMoneyBag(from_position, to_position, radius, money, height)
	local newItem = CreateItem("item_money", nil, nil)
	newItem:SetPurchaseTime(0)
	newItem:SetCurrentCharges(1)

	local drop = CreateItemOnPositionSync(from_position, newItem)
	newItem:GetContainer():SetModelScale(1.4 + (money or 1) / 15)
	-- if i == 'item_money' then
	newItem.money = money or 1
	drop.money = money or 1
	-- end
	local gg_item_dis = (to_position - from_position):Length2D()
	local gg_item_t = gg_item_dis / 800
	if gg_item_t < 1 then gg_item_t = 1 end

	newItem:SimulateLaunchLoot(to_position)
	-- newItem:SimulateLaunchLoot(false,height or 600 , gg_item_t,to_position)
	-- newItem:LaunchLoot( false, height or 600, gg_item_t, to_position ,nil)
end

function DropOneItemToTeam(item, team, gg_hero)
	local newItem = CreateItem(item, gg_hero, gg_hero)
	CreateItemOnPositionForLaunch(Vector(0, 0, 128), newItem)
	local gg_item_v = CenterVector(team) + Vector(RandomInt(-512, 512), RandomInt(-512, 512), 0)
	local gg_item_dis = (gg_item_v - Vector(0, 0, 128)):Length2D()
	local gg_item_t = gg_item_dis / 800
	newItem:SimulateLaunchLoot(gg_item_v)
	-- newItem:SimulateLaunchLoot(false,height or 600 , gg_item_t,to_position)
	-- newItem:LaunchLootInitialHeight(false, 0, 400, gg_item_t, gg_item_v)
	AddItemGot(TeamId2Hero(team), item)
end

function RandomDropOneGGItem(gg_item_one, gg_item_hero, is_auto_pick)
	if not is_auto_pick then
		is_auto_pick = false
	end
	local lucky_team = nil
	local try_count = 0
	while lucky_team == nil and try_count < 100 do
		local random_team = RandomInt(6, 13)
		local hero = TeamId2Hero(random_team)
		local my_team = gg_item_hero:GetTeam()
		if hero ~= nil and hero:IsAlive() == true and random_team ~= my_team then
			lucky_team = random_team
		end
		try_count = try_count + 1
	end
	if lucky_team ~= nil then
		if TeamId2Hero(lucky_team):HasModifier('modifier_item_double_lootbox') and _G.ITEM_2_LEVEL[gg_item_one] then
			gg_item_one = 'item_lootbox_lv' .. _G.ITEM_2_LEVEL[gg_item_one]
		end
		local newItem = CreateItem(gg_item_one, gg_item_hero, gg_item_hero)
		CreateItemOnPositionForLaunch(Vector(0, 0, 128), newItem)
		local gg_item_v = CenterVector(lucky_team) + Vector(RandomInt(-512, 512), RandomInt(-512, 512), 0)
		local gg_item_dis = (gg_item_v - Vector(0, 0, 128)):Length2D()
		local gg_item_t = gg_item_dis / 800
		newItem:SimulateLaunchLoot(gg_item_v)
		AddItemGot(TeamId2Hero(lucky_team), gg_item_one)
		-- newItem:SimulateLaunchLoot(is_auto_pick,400,gg_item_t,gg_item_v)
		-- newItem:LaunchLootInitialHeight( is_auto_pick, 0, 400, gg_item_t, gg_item_v)
	end
	return lucky_team
end

