function RandomARelic(hero)
	local ran_table = {}
	for _, l in pairs(_G.DROP_RELIC_LIST) do
		if FindValueInTable(hero.relic_exclude, l) == false and FindValueInTable(hero.loot_table, l) == false then
			table.insert(ran_table, l)
		end
	end
	return ran_table[RandomInt(1, table.maxn(ran_table))]
end

