function RandomASimpleLoot(hero, max_level)
	local ran_table = {}
	-- for i=1,max_level do
	for _, l in pairs(_G.ITEM_LIST_BY_LEVEL[max_level]) do
		if FindValueInTable(hero.discard_item_table, l) == false and FindValueInTable(hero.loot_table, l) == false then
			table.insert(ran_table, l)
		end
	end
	-- end
	return ran_table[RandomInt(1, table.maxn(ran_table))]
end

