function HasEmptySlot4Relic(hero)
	if IsUnitExist(hero) == false then
		return false
	end
	local has_empty_slot = false
	--普通物品
	for slot = 0,5 do
		if hero:GetItemInSlot(slot) == nil then
			has_empty_slot = true
		end
	end
	return has_empty_slot
end

--添加物品或圣物
function AddItemPlus(hero, item_name, delay)
	if delay == nil then
		delay = 0
	end

	Timers:CreateTimer(delay, function()
		local has_empty_slot = false
		--普通物品
		for slot = 0, 8 do
			if hero:GetItemInSlot(slot) == nil or (hero:GetItemInSlot(slot):GetAbilityName() == item_name and hero:GetItemInSlot(slot):IsStackable()) then
				has_empty_slot = true
			end
		end
		--中立物品必替换（圣物）
		if FindValueInTable(_G.DROP_RELIC_LIST, item_name) then
			has_empty_slot = true
		end

		if has_empty_slot == true then
			hero:AddItemByName(item_name)
		else
			DropItemAppointed(hero, hero, item_name)
		end
	end)
end

function FillEmptySlot(x)
	--用空物品塞满剩下的格子，避免物品放进来丢失
	if not IsUnitExist(x) then
		return
	end
	local slot_count = 9
	for slot = 0, 8 do
		if x:GetItemInSlot(slot) ~= nil then
			slot_count = slot_count - 1
		end
	end
	if slot_count > 0 then
		for i = 1, slot_count do
			x:AddItemByName('item_null')
		end
	end
end

function ItemXiWa(keys)
	play_particle("particles/econ/events/ti7/shivas_guard_active_ti7.vpcf", PATTACH_ABSORIGIN_FOLLOW, keys.caster, 6)
	EmitSoundOn("DOTA_Item.ShivasGuard.Activate", keys.caster)
	local caster = keys.caster
	local ability = FindItemAbilityByName(caster, 'item_xiwa')
	local units = FindUnitsInRadiusByTeam({
		team = keys.caster.team_id,
		chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam(),
		role = 2,
		radius = 500,
		position = keys.caster:GetAbsOrigin()
	})

	for _, unluckydog in pairs(units) do
		local delay = 1.0 * (unluckydog:GetAbsOrigin() - keys.caster:GetAbsOrigin()):Length2D() / 350
		ItemXiWaOne(delay, keys.caster, unluckydog,ability)
	end
end

function ItemXiWaOne(delay, caster, unluckydog, ability)
	Timers:CreateTimer(delay, function()
		ApplyDamage({
			victim = unluckydog,
			attacker = caster,
			damage_type = DAMAGE_TYPE_MAGICAL,
			damage = 100,
			ability = ability,
		})
		InvisibleUnitCast({
			caster = caster,
			ability = 'shiva_give_debuff',
			level = 1,
			unluckydog = unluckydog,
			ignore_nether_ward = true,
		})
	end)
end

--兼容不能吃树的bug，把吃树换成即食的item_chishu_new
function MakeTangoEatable(player_id, slot)
	local hero = PlayerId2Hero(player_id)
	local item = hero:GetItemInSlot(slot)
	if item:GetAbilityName() == 'item_chishu' then
		local count = item:GetCurrentCharges()
		hero:RemoveItem(item)
		for i = 1, count do
			hero:AddItemByName('item_chishu_new')
		end
	end
end

function HuiyaoTang(keys)
	local caster = keys.caster
	local at_team_id = caster.at_team_id or caster.team_id
	local team_id = caster.team_id
	local radius = keys.radius or 400
	local damage = keys.damage or 30
	local p = caster:GetAbsOrigin()
	local ability = keys.ability

	if caster:IsHero() == true then
		return
	end

	for _, unit in pairs(GetValidChessOnBoard(at_team_id)) do
		if unit.team_id ~= team_id and (unit:GetAbsOrigin() - p):Length2D() < radius and unit:IsInvulnerable() == false then
			ApplyDamage({
				victim = unit,
				attacker = caster,
				damage_type = DAMAGE_TYPE_PURE,
				damage = damage,
				ability = keys.ability,
			})
			ability:ApplyDataDrivenModifier(unit, unit, 'modifier_item_huiyao_debuff', { duration = 3, })
			ShowHuiyaoEffect({
				caster = caster,
				target = unit,
			})
		end
	end
end
function NecHeartstopper(keys)
	local caster = keys.caster
	local at_team_id = caster.at_team_id or caster.team_id
	local team_id = caster.team_id
	local radius = keys.radius or 350
	local damage_per = keys.damage_per or 1
	local p = caster:GetAbsOrigin()
	local ability = keys.ability

	if caster:IsHero() == true then
		return
	end

	for _, unit in pairs(GetValidChessOnBoard(at_team_id)) do
		if unit.team_id ~= team_id and (unit:GetAbsOrigin() - p):Length2D() < radius and unit:IsInvulnerable() == false then
			ApplyDamage({
				victim = unit,
				attacker = caster,
				damage_type = DAMAGE_TYPE_MAGICAL,
				damage = 3*damage_per*unit:GetMaxHealth()/100,
				ability = keys.ability,
			})
		end
	end
end
function ShowHuiyaoEffect(keys)
	local unit = keys.target
	local huiyao_unit = keys.caster
	local e = ParticleManager:CreateParticle('effect/huiyao/2.vpcf', PATTACH_ABSORIGIN_FOLLOW, unit)

	ParticleManager:SetParticleControl(e, 0, unit:GetOrigin())
	ParticleManager:SetParticleControl(e, 1, huiyao_unit:GetOrigin())
	Timers:CreateTimer(1.9, function()
		if e ~= nil then
			ParticleManager:DestroyParticle(e, true)
			ParticleManager:ReleaseParticleIndex(e)
		end
	end)
end

function RemindItem(caster, modifier_name)
	if _G.game_status ~= 2 then
		if caster:IsHero() == false then
			InitChessMana(caster)
		end
	end
	Timers:CreateTimer(0.1, function()
		if IsUnitExist(caster) == false or caster.is_fuhuo == true or caster.no_save_item == true or caster.is_youhun == true or caster.team_id == 4 or HasKillModifier(caster) == true or caster.is_summoned == true then
			--这些情况不做特殊处理
			return
		end
		local modifier = caster:FindModifierByName(modifier_name)
		if modifier == nil then
			return
		end
		local item = modifier:GetAbility()
		if item == nil then
			return
		end
		local item_name = item:GetAbilityName()
		if caster:IsHero() == true and modifier_name == 'modifier_' .. item_name then
			if FindValueInTable(_G.DROP_RELIC_LIST, item_name) == true then
				--获取圣物的提醒
				SendServerToAllTeam("bullet", {
					player_id = caster:GetPlayerID(),
					win_streak = caster.win_streak or 0,
					vip = caster.is_vip,
					target = nil,
					item = item_name,
					item_level = 6,
				})
			end
			--获取代币
			if item_name == 'item_common_token' or item_name == 'item_rm_token' or item_name == 'item_gold_token' then
				UpdateMyMoney(caster:GetTeam())
			end
		end
		if modifier_name ~= ('modifier_' .. item_name) or string.find(item_name, 'item_') == nil then
			return
		end
		if FindChessRemindedItem(caster, item_name) == false then
			AddChessRemindedItem(caster, item_name)
			local item_level = _G.ITEM_2_LEVEL[item_name]
			if item_level ~= nil and item_level > 0 then
				--说谢谢
				if RandomInt(1, 50) < (item_level * 10) then
					PlayChessDialogue(caster, 'thanks')
				end
				--发弹幕：获得物品
				local hero = TeamId2Hero(caster.team_id)
				if item_level >= 4 and hero ~= nil then
					if caster:IsHero() ~= true then
						SendServerToAllTeam("bullet", {
							player_id = hero:GetPlayerID(),
							win_streak = hero.win_streak or 0,
							vip = hero.is_vip,
							target = caster:GetUnitName(),
							item = item_name,
							item_level = item_level,
						})
					end

					if item_level == 5 and _G.egg_quest == 'q022' then
						SetQuest(hero.team_id, true)
					end
					if item_level == 4 and _G.egg_quest == 'q032' then
						SetQuest(hero.team_id, true)
					end
				end
			end
		end
	end)
end

--棋子装备提醒
function InitChessRemindedItem(chess, items)
	if items == nil then
		items = {}
	end
	chess.reminded_item = items
end

function AddChessRemindedItem(chess, item)
	if chess.reminded_item == nil then
		chess.reminded_item = {}
	end
	table.insert(chess.reminded_item, item)
end

function FindChessRemindedItem(chess, item)
	if chess.reminded_item == nil then
		return false
	end
	return FindValueInTable(chess.reminded_item, item)
end

function AddPermanentStackCount(u, stack_name)
	if u:GetTeam() == 4 or u.is_tb_ally == true or u.transforming == true then
		--不加减点数的情况
		return
	end
	local v_chess = Unit2VChess(u)
	if v_chess == nil then
		return
	end
	local stack_count = v_chess[stack_name .. '_count']
	if stack_count == nil then
		if stack_name == 'xuejingshi' then
			stack_count = 1
		else
			stack_count = 0
		end
	end
	if stack_name == 'grow' then
		PlayParticleOnUnitUntilDeath({
			caster = u,
			p = "particles/generic_gameplay/dust_impact_large.vpcf",
		})
	end
	if stack_name == 'press' then
		PlayParticleOnUnitUntilDeath({
			caster = u,
			p = "particles/econ/items/legion/legion_fallen/legion_fallen_press.vpcf",
			-- p = "particles/units/heroes/hero_legion_commander/legion_commander_press.vpcf",
		})
	end
	if stack_name == 'changdun' then
		play_particle("effect/priest/shield_end_b.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)
		EmitSoundOn('changdun.stack', u)
	end
	v_chess[stack_name .. '_count'] = stack_count + 1
	u[stack_name .. '_count'] = stack_count + 1
	SyncPermanentStackCount({ caster = u, stack_name = stack_name })
end

function LosePermanentStackCount(u, stack_name)
	if u:GetTeam() == 4 then
		--客场不加减点数
		return 1
	end

	local v_chess = Unit2VChess(u)
	if v_chess == nil then
		return 1
	end
	local stack_count = v_chess[stack_name .. '_count']
	if stack_count == nil then
		if stack_name == 'xuejingshi' then
			stack_count = 1
		else
			stack_count = 0
		end
	end
	v_chess[stack_name .. '_count'] = math.ceil(stack_count / 2)
	return math.ceil(stack_count / 2)
end

function GetPermanentStackCount(u, stack_name)
	local stack_count = u[stack_name .. '_count']
	if stack_count == nil then
		if stack_name == 'xuejingshi' and IsUnitExist(u) == true and u:HasModifier('modifier_item_xuejingshi') then
			stack_count = 1
		else
			stack_count = 0
		end
	end
	return stack_count
end

function CopyChessProperties(new_chess, curr_chess)
	if new_chess == nil then
		new_chess = {
			grow_count = 0,
			press_count = 0,
			xuejingshi_count = 0,
			changdun_count = 0,
			mojing_ability = nil,
			mojing_ability_level = nil,
			extra_synergy = {},
			bh_gold = nil,
			buy_price = 0,
			wisp_altar_power_count = nil,
		}
	end
	if curr_chess == nil then
		return new_chess
	end
	if curr_chess.grow_count then
		new_chess.grow_count = curr_chess.grow_count
	end
	if curr_chess.press_count then
		new_chess.press_count = curr_chess.press_count
	end
	if curr_chess.xuejingshi_count then
		new_chess.xuejingshi_count = curr_chess.xuejingshi_count
	end
	if curr_chess.changdun_count then
		new_chess.changdun_count = curr_chess.changdun_count
	end
	if curr_chess.extra_synergy and table.maxn(curr_chess.extra_synergy) > 0 then
		new_chess.extra_synergy = CopyTable(curr_chess.extra_synergy)
	end
	if curr_chess.mojing_ability then
		new_chess.mojing_ability = curr_chess.mojing_ability
	end
	if curr_chess.mojing_ability_level then
		new_chess.mojing_ability_level = curr_chess.mojing_ability_level
	end
	if curr_chess.bh_gold then
		new_chess.bh_gold = curr_chess.bh_gold
	end
	if curr_chess.buy_price then
		new_chess.buy_price = curr_chess.buy_price
	end
	if curr_chess.wisp_altar_power_count then
		new_chess.wisp_altar_power_count = curr_chess.wisp_altar_power_count
	end
	return new_chess
end

function SyncAllPermanentStackCount(u)
	SyncPermanentStackCount({ caster = u, stack_name = 'grow' })
	SyncPermanentStackCount({ caster = u, stack_name = 'press' })
	SyncPermanentStackCount({ caster = u, stack_name = 'xuejingshi' })
	SyncPermanentStackCount({ caster = u, stack_name = 'changdun' })
	SyncPermanentStackCount({ caster = u, stack_name = 'wisp_altar_power' })
	if u.extra_synergy ~= nil and table.maxn(u.extra_synergy) > 0 then
		for _, ss in pairs(u.extra_synergy) do
			AddSynergy({
				caster = u,
				synergy = ss
			})
		end
		u:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(u, u, 'modifier_shining', {})
	end
	if u.mojing_ability then
		AddMojingAbility({
			caster = u,
		})
	end
end

function SyncPermanentStackCount(keys)
	local u = keys.caster
	local stack_name = keys.stack_name
	local ability = nil
	local modifier_name = nil
	local count = keys.stack or GetPermanentStackCount(u, stack_name)
	if IsUnitExist(u) == false or u:IsHero() then return end
	if stack_name == 'grow' then
		ability = u:FindAbilityByName('tiny_grow_new')
		if ability then
			ModMaxHP({
				caster = u,
				const = count*100,
				is_heal = true,
			})
			AddModelScalePlus(u, u:GetModelScale()*(1+count*0.02))
			if u:FindModifierByName("modifier_"..ability:GetAbilityName() .. "_count") == nil then
				ability:ApplyDataDrivenModifier(u, u, "modifier_"..ability:GetAbilityName() .. "_count", {})
			end
			u:FindModifierByName("modifier_"..ability:GetAbilityName() .. "_count"):SetStackCount(count)
		end
	elseif stack_name == 'press' then
		ability = u:FindAbilityByName('lc_qianggong')
		if ability then
			modifier_name = 'modifier_'..ability:GetAbilityName()
			for i = 1, count do
				ability:ApplyDataDrivenModifier(u, u, modifier_name, {})
			end
			if u:FindModifierByName(modifier_name .. "_count") == nil then
				ability:ApplyDataDrivenModifier(u, u, modifier_name .. "_count", {})
			end
			u:FindModifierByName(modifier_name .. "_count"):SetStackCount(count)
		end
	elseif stack_name == 'wisp_altar_power' and count > 0 then
		AddAbilityAndSetLevel(u,stack_name)
		modifier_name = 'modifier_'..stack_name
		if u:FindAbilityByName(stack_name) then
			u:FindModifierByName(modifier_name .. "_count"):SetStackCount(count)
		end
	else
		ability = FindItemInInventory(u, 'item_' .. stack_name)
		if stack_name == 'changdun' then
			modifier_name = 'modifier_item_changdun_armor'
			if u:HasModifier('modifier_item_changdun_show') and count > 0 then
				u:FindModifierByName('modifier_item_changdun_show'):SetStackCount(count)
			end
		end
		if modifier_name then
			for _, m in pairs(u:FindAllModifiers()) do
				if modifier_name == m:GetName() then
					u:RemoveModifierByName(modifier_name)
				end
			end
		end
		if ability then
			ability:SetCurrentCharges(count)
			if modifier_name then
				for i = 1, count do
					ability:ApplyDataDrivenModifier(u, u, modifier_name, {})
				end
			end
		end
	end
	if count > 0 then
		u[stack_name .. '_count'] = count
	end

	if keys.modmaxhp ~= nil then
        ModMaxHP({
            caster = u,
            const = keys.modmaxhp,
        })
    end
end

--【装饰】
function MakeGreevil(unit, is_flying)
	if unit.part1 ~= nil and unit.part1:IsNull() == false then
		unit.part1:Kill()
	end
	if unit.part2 ~= nil and unit.part2:IsNull() == false then
		unit.part2:Kill()
	end
	if unit.part3 ~= nil and unit.part3:IsNull() == false then
		unit.part3:Kill()
	end
	if unit.part4 ~= nil and unit.part4:IsNull() == false then
		unit.part4:Kill()
	end
	if unit.part5 ~= nil and unit.part5:IsNull() == false then
		unit.part5:Kill()
	end
	if unit.part6 ~= nil and unit.part6:IsNull() == false then
		unit.part6:Kill()
	end
	if unit.part7 ~= nil and unit.part7:IsNull() == false then
		unit.part7:Kill()
	end
	if unit.part8 ~= nil and unit.part8:IsNull() == false then
		unit.part8:Kill()
	end

	if unit == nil or (unit.courier_name == nil and unit.onduty_hero == nil) then
		return
	end
	local greevil_info = _G.greevil_list[unit.courier_name or unit.onduty_hero]
	if greevil_info == nil then
		return
	end


	local skin = greevil_info.skin or 0
	unit:SetSkin(skin)
	--眼睛
	local part1 = greevil_info.part1
	if part1 ~= nil then
		unit.part1 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part1 })
		unit.part1:FollowEntity(unit, true)
		unit.part1:SetSkin(skin)
	end
	--耳朵
	local part2 = greevil_info.part2
	if part2 ~= nil then
		unit.part2 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part2 })
		unit.part2:FollowEntity(unit, true)
		unit.part2:SetSkin(skin)

		if part2 == "models/items/courier/catakeet/catakeet_tail_sly.vmdl" and skin == 9 then
			--特例
			unit.part2:SetSkin(8)
		end
	end
	--角
	local part3 = greevil_info.part3
	if part1 ~= nil then
		unit.part3 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part3 })
		unit.part3:FollowEntity(unit, true)
		unit.part3:SetSkin(skin)
	end
	--鼻子
	local part4 = greevil_info.part4
	if part4 ~= nil then
		unit.part4 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part4 })
		unit.part4:FollowEntity(unit, true)
		unit.part4:SetSkin(skin)
	end
	--尾巴
	local part5 = greevil_info.part5
	if part5 ~= nil then
		unit.part5 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part5 })
		unit.part5:FollowEntity(unit, true)
		unit.part5:SetSkin(skin)
	end
	--牙齿
	local part6 = greevil_info.part6
	if part6 ~= nil then
		unit.part6 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part6 })
		unit.part6:FollowEntity(unit, true)
		unit.part6:SetSkin(skin)
	end
	--翅膀
	if is_flying == true then
		local part7 = greevil_info.part7
		if part7 ~= nil then
			unit.part7 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part7 })
			unit.part7:FollowEntity(unit, true)
			unit.part7:SetSkin(skin)
		end
	end
	if is_flying == true then
		local part8 = greevil_info.part8
		if part8 ~= nil then
			unit.part8 = SpawnEntityFromTableSynchronous('prop_dynamic', { model = part8 })
			unit.part8:FollowEntity(unit, true)
			unit.part8:SetSkin(skin)
		end
	end
end

