	end
	if (tokens[1] == '-revx') and _G.myself == true then
		ReverseLineupX(hero)
		return
	end
	if (tokens[1] == '-left') and _G.myself == true then
		LeftLineup(hero)
		return
	end
	if (tokens[1] == '-right') and _G.myself == true then
		RightLineup(hero)
		return
	end
	if (tokens[1] == '-top') and _G.myself == true then
		TopLineup(hero)
		return
	end
	if (tokens[1] == '-bottom') and _G.myself == true then
		BottomLineup(hero)
		return
	end
	if (tokens[1] == '-sparse') and _G.myself == true then
		SparseLineup(hero)
		return
	end

	--发弹幕
	if _G.p2_mode == true and keys.teamonly == 1 then
		--2P模式
		local ally_team = GetP2Ally(hero:GetTeam())
		if ally_team then
			local team_from = hero:GetTeam()
			local player_from = hero:GetPlayerID()
			local team_to = ally_team
			local player_to = TeamId2Hero(team_to):GetPlayerID()
