		-- 		context = keys.text,
		-- 		context_type = "chat",
		-- 		token = ""
		-- 	}
		-- 	SendHTTPPost("https://gtf.ai.xingzheai.cn/v2.0/game_chat_ban/detect_text",
		-- 		check_text_json,
		-- 		{serverKey=GetDedicatedServerKeyV2('xingzheai')},
		-- 		(function(object)
		-- 			if object and type(object) == 'table' then
		-- 				if object.data.suggestion == "block" then
		-- 					prt(object.data_id..'发表了黄色言论')
		-- 					prt(_G.steamid2name[object.data_id]..'发表了黄色言论')
		-- 				elseif object.data.suggestion == "review" then
		-- 					prt(object.data_id..'可能发表了黄色言论')
		-- 					prt(_G.steamid2name[object.data_id]..'可能发表了黄色言论')
		-- 				end
		-- 	        end
		-- 		end)
