function DAC:OnRefreshChess(keys)
	local player_team = _G.playerid2team[keys.PlayerID]
	local hero = _G.teamid2hero[player_team]

	if player_team ~= keys.team or IsUnitExist(hero) == false then
		return
	end

	local a = hero:FindAbilityByName("summon_hero")
	if a == nil or a:IsActivated() == false or a:IsCooldownReady() == false then
		return
	end

	a:StartCooldown(0.6)

	local cost_mana = 2
	if hero.second_draw_activate == true then
		--二次机会
		Draw5ChessAndShow(keys.team, true, -1)
		hero.second_draw_activate = nil
	elseif hero:GetMana() < 2 then
		--金币不够
		CustomGameEventManager:Send_ServerToTeam(keys.team, "mima", {
			key = GetClientKey(keys.team),
			text = "text_mima_no_mana"
		})
		return
	else
		EmitSoundOn('frostivus_ui_select', hero)
		hero.chesslock = false
		CostMana(hero, 2)
		Draw5ChessAndShow(keys.team, true)
	end
end

function DAC:OnExpBook(keys)
	local player_team = _G.playerid2team[keys.PlayerID]
	local hero = _G.teamid2hero[player_team]

	if player_team ~= keys.team or hero == nil or hero:IsNull() == true then
		return
	end

	local cost_mana = 4
	if hero:GetMana() < 4 then
		CustomGameEventManager:Send_ServerToTeam(keys.team, "mima", {
			key = GetClientKey(keys.team),
			text = "text_mima_no_mana"
		})
		return
	else
		CostMana(hero, 4)
		AddCourierExp({
			caster = hero,
			xpadd = 4,
			disable_quick_lvl_up = true,
			cost = 4,
		})
	end
end

--刷新某个玩家的账号信息（通行证到期时间 vip_expire 等）
--客户端商城二维码弹窗里的“刷新我的账户信息”按钮，实际只发了 refresh_shop_v5（刷商城货架），
--并不会重新拉账号数据；这里在收到该请求时顺带重新请求一次账号接口，把新的 vip_info 写回去
function RefreshPlayerVipInfo(player_id, notify_done)
	local steam_id = _G.playerid2steamid[player_id]
	if steam_id == nil or steam_id == '' then
		return
	end

	--防抖：1.5 秒内只请求一次，避免商城连续刷新时打过多请求
	--（客户端刷新按钮自己也有 2 秒冷却，这里不会把正常点击挡掉）
	_G.vip_refresh_time = _G.vip_refresh_time or {}
	local now = GameRules:GetGameTime()
	if _G.vip_refresh_time[player_id] ~= nil and now - _G.vip_refresh_time[player_id] < 1.5 then
		return
	end
	_G.vip_refresh_time[player_id] = now

	local url = "http://autochess.ppbizon.com/courier/get/@" .. steam_id ..
		"?hehe=" .. RandomInt(1, 9999) ..
		"&language=" .. GetReportedLanguage(player_id) .. GetSendKey()
	local req = CreateHTTPRequestScriptVM('GET', url)
	if req == nil then
		return
	end
	req:SetHTTPRequestAbsoluteTimeoutMS(10000)
	req:Send(function(res)
		if res == nil or res.StatusCode ~= 200 or res.Body == nil then
			return
		end
		local t = json.decode(res.Body)
		if t == nil or t.err ~= 0 or t.user_info == nil then
			return
		end
		ApplyPlayerVipInfo(steam_id, t.user_info)
		if notify_done == true then
			NotifyQrRefreshDone(player_id)
		end
	end)
end

--给点了“刷新我的账户信息”的玩家弹一个居中的小提示（客户端 msg_box 事件 -> show_msg）
function NotifyQrRefreshDone(player_id)
	_G.qr_msg_time = _G.qr_msg_time or {}
	local now = GameRules:GetGameTime()
	if _G.qr_msg_time[player_id] ~= nil and now - _G.qr_msg_time[player_id] < 3 then
		return
	end
	_G.qr_msg_time[player_id] = now
	local player = PlayerResource:GetPlayer(player_id)
	if player == nil then
		return
	end
	CustomGameEventManager:Send_ServerToPlayer(player, "msg_box", {
		text = '刷新完成！',
		duration = 2,
	})
	print('[QR] notify refresh done, player_id=' .. tostring(player_id))
end

--从 vip_info 里取一个可比较的“过期时间”字符串（兼容接口可能用的几种字段名）
function GetVipExpireValue(vip_info)
	if type(vip_info) ~= 'table' then
		return nil
	end
	local keys = { 'vip_expire', 'vip_expired', 'vip_expire_date', 'expire', 'vip_end_time' }
	for _, k in ipairs(keys) do
		local v = vip_info[k]
		if v ~= nil and v ~= '' then
			return tostring(v)
		end
	end
	if type(vip_info.vip) == 'table' and vip_info.vip.vip_expire ~= nil then
		return tostring(vip_info.vip.vip_expire)
	end
	return nil
end

--把新的 vip 信息写回本地缓存；只有真的发生变化时才重写 net table，
--客户端 DACTableChanged("player_info") 会重新 ShowAllPlayerInfo -> 通行证 tooltip 才会刷新
function ApplyPlayerVipInfo(steam_id, user_info)
	if steam_id == nil or user_info == nil then
		return
	end

	local changed = false
	local new_vip_info = user_info.vip_info
	local new_expire = GetVipExpireValue(new_vip_info)

	local entries = {}
	if _G.user_info ~= nil and _G.user_info[steam_id] ~= nil then
		table.insert(entries, _G.user_info[steam_id])
	end
	if _G.stat_info ~= nil and _G.stat_info[steam_id] ~= nil then
		table.insert(entries, _G.stat_info[steam_id])
	end

	for _, entry in pairs(entries) do
		if new_vip_info ~= nil then
			local old_expire = GetVipExpireValue(entry.vip_info)
			if entry.vip_info == nil or old_expire ~= new_expire then
				entry.vip_info = new_vip_info
				changed = true
			end
		end
		--只升不降：不要把“自定义游戏通行证/ticket”带来的 vip 状态抹掉
		if user_info.is_vip == true and entry.is_vip ~= true then
			entry.is_vip = true
			changed = true
		end
	end

	if changed ~= true then
		return
	end

	--优先沿用客户端当前正在显示的那张表：stat_info 里有 vip_info 就写 stat_info，否则写 user_info
	local stat = _G.stat_info and _G.stat_info[steam_id]
	local info_table = nil
	if stat ~= nil and stat.vip_info ~= nil then
		info_table = _G.stat_info
	elseif _G.user_info ~= nil and _G.user_info[steam_id] ~= nil then
		info_table = _G.user_info
	elseif stat ~= nil then
		info_table = _G.stat_info
	end
	if info_table ~= nil then
		CustomNetTables:SetTableValue("dac_table", "player_info",
			{ info = info_table, hehe = RandomInt(1, 1000) })
		print('[VIP] refresh vip_info for ' .. tostring(steam_id) .. ' expire=' .. tostring(new_expire))
	end
end

function DAC:OnCatchCrab(keys)
	local player_id = keys.PlayerID
	--商城二维码弹窗的“刷新我的账户信息”走的是这条路径，顺带刷新账号（通行证有效期）
	if keys.event == 'refresh_shop_v5' then
		--二维码弹窗还开着（_G.qr_hold 有记录）才认为这是弹窗里的刷新按钮，才弹“刷新完成！”
		local hold = _G.qr_hold[player_id]
		RefreshPlayerVipInfo(player_id, hold ~= nil)
		--点了刷新说明弹窗已经关掉：把保护窗口缩到 4 秒，之后补发压住的招募面板
		ShortenQrHold(player_id)
	end
	local urls = {
		ranking_top = 'http://autochess.ppbizon.com/ranking/top',
		-- refresh_shop = 'http://autochess.ppbizon.com/shop/v4/get',
		-- buy_courier = 'http://autochess.ppbizon.com/shop/v4/courier',
		-- buy_effect = 'http://autochess.ppbizon.com/shop/v4/effect',
		-- buy_projectile = 'http://autochess.ppbizon.com/shop/v4/projectile',
		-- buy_pet = 'http://autochess.ppbizon.com/shop/v4/pet',
		-- buy_animation = 'http://autochess.ppbizon.com/shop/v4/animation',
		-- buy_emotion = 'http://autochess.ppbizon.com/shop/v4/emotion',
		-- buy_chessboard = 'http://autochess.ppbizon.com/shop/v4/chessboard',
		choose_hero = 'http://autochess.ppbizon.com/courier/change',
		choose_chessboard = 'http://autochess.ppbizon.com/chessboard/change',
		activate_cdkey = 'http://autochess.ppbizon.com/cdkey/act',
		request_vote_chess = 'http://autochess.ppbizon.com/vip/vote',
		get_season_award = 'http://autochess.ppbizon.com/award/get',
		buy_bet = 'http://autochess.ppbizon.com/bet/ti15',
		get_bet_award = 'http://autochess.ppbizon.com/award/ti15',
		request_casino_award = 'http://autochess.ppbizon.com/award/casino',
		merge_hero = 'http://autochess.ppbizon.com/courier/merge',

		recycle_effect = 'http://autochess.ppbizon.com/effect/del',
		recycle_projectile = 'http://autochess.ppbizon.com/projectile/del',
		recycle_animation = 'http://autochess.ppbizon.com/animation/del',
		recycle_pet = 'http://autochess.ppbizon.com/pet/del',

		refresh_shop_v5 = 'http://autochess.ppbizon.com/shop/v5/get',
		shop_v5_buy = 'http://autochess.ppbizon.com/shop/v5/buy',
		jihuan_hero = 'http://autochess.ppbizon.com/shop/v5/collect',
		lottery_go = 'http://autochess.ppbizon.com/shop/v5/lottery',
		recycle_hero = 'http://autochess.ppbizon.com/shop/v5/recycle/courier',
	}
	if urls[keys.event] ~= nil then
		local send_url = urls[keys.event]
		--user_specific=1：要带上@id
		if keys.user_specific == 1 then
			send_url = send_url .. '/@' .. (_G.playerid2steamid[keys.PlayerID] or '')
		end
		--这些情况有第二个@，最后一个是换棋盘
		if keys.event == 'buy_effect' or keys.event == 'choose_chessboard' or keys.event == 'choose_hero' or keys.event == 'recycle_hero' or keys.event == 'activate_cdkey' or keys.event == 'jihuan_hero' or keys.event == 'merge_hero' or keys.event == 'buy_projectile' or keys.event == 'buy_animation' or keys.event == 'buy_pet' or keys.event == 'buy_emotion' or keys.event == 'buy_chessboard' or keys.event == 'recycle_effect' or keys.event == 'recycle_projectile' or keys.event == 'recycle_pet' or keys.event == 'recycle_animation' or keys.event == 'buy_courier' then
			send_url = send_url .. '@' .. keys.params['hero']
		end
		send_url = send_url .. '?hehe=' .. RandomInt(1, 10000)
		for i, v in pairs(keys.params) do
			send_url = send_url .. '&' .. i .. '=' .. v
		end

		send_url = send_url .. GetSendKey()
		Timers:CreateTimer(RandomFloat(0, 1), function()
			SendHTTP(send_url, function(t)
				if keys.event == 'bet_ti9' then
					_G.user_info[_G.playerid2steamid[keys.PlayerID]]['bet_info'] = t['team']
					CustomNetTables:SetTableValue("dac_table", "player_info",
						{ info = _G.user_info, hehe = RandomInt(1, 1000) })
				end
				CustomGameEventManager:Send_ServerToPlayer(PlayerResource:GetPlayer(player_id), 'send_http_cb', {
					key = GetClientKey(_G.playerid2team[player_id]),
					event = keys.cb,
					data = json.encode(t),
				})
			end)
		end)
	end
end

