function DAC:OnChooseChessboard(keys)
	local player_id = keys.PlayerID
	local chessboard = keys.chessboard
	if player_id == nil then return end
	CustomNetTables:SetTableValue("player_id_table", 'chessboard_' .. player_id, { chessboard = chessboard })
end

function DAC:OnChooseCourier(keys)
	local player_id = keys.PlayerID
	local courier = keys.courier
	local courier_id = keys.courier_id

	local courier_info = CustomNetTables:GetTableValue("player_id_table", "courier_" .. player_id) or {}
	courier_info['courier'] = courier    --只取hxxx部分的id
	courier_info['courier_id'] = courier_id --完整id

	CustomNetTables:SetTableValue("player_id_table", 'courier_' .. player_id, courier_info)

	CustomGameEventManager:Send_ServerToAllClients("update_portrait_courier_name", {})
end

function DAC:OnUpdateMMRLevel(keys)
	local player_id = keys.PlayerID
	local mmr_level = keys.mmr_level
	local queen_rank = keys.queen_rank
	local candy = keys.candy

	CustomNetTables:SetTableValue("player_id_table", 'mmr_level_' .. player_id,
		{ mmr_level = mmr_level, queen_rank = queen_rank, candy = candy })
end

function DAC:OnShowGameNotice(keys)
	local player_id = keys.PlayerID
	if player_id ~= 0 then
		return
	end
	local text = keys.text
end

function DAC:OnPlayerLanguage(keys)
	local player_id = keys.PlayerID
	local language = keys.language
	--按 steamid 额外缓存一份，供后续 HTTP 接口（courier/get 等）带 language 参数用
	_G.player_language = _G.player_language or {}
	local steam_id = _G.playerid2steamid and _G.playerid2steamid[player_id] or nil
	if steam_id ~= nil and language ~= nil and language ~= '' then
		_G.player_language[steam_id] = language
	end
	local hero = PlayerId2Hero(player_id)
	if hero ~= nil then
		hero.language = language
	end
end

--取某个玩家上报过的语言（客户端 player_language 上报），没上报过就用默认值
function GetReportedLanguage(player_id, default_language)
	local language = nil
	if player_id ~= nil then
		local steam_id = _G.playerid2steamid and _G.playerid2steamid[player_id] or nil
		if steam_id ~= nil and _G.player_language ~= nil then
			language = _G.player_language[steam_id]
		end
		if language == nil or language == '' then
			local hero = PlayerId2Hero(player_id)
			if hero ~= nil then
				language = hero.language
			end
		end
	end
	if language == nil or language == '' then
		language = default_language or 'schinese'
	end
	return language
end

--同上，但入参是 steamid（大厅阶段可能还没有 player_id，靠 steamid 反查）
function GetReportedLanguageBySteamID(steam_id, default_language)
	if steam_id ~= nil and _G.player_language ~= nil then
		local cached = _G.player_language[steam_id]
		if cached ~= nil and cached ~= '' then
			return cached
		end
	end
	local player_id = _G.steamid2playerid and _G.steamid2playerid[steam_id] or nil
	if player_id == nil and steam_id ~= nil then
		for pid, sid in pairs(_G.playerid2steamid or {}) do
			if sid == steam_id then
				player_id = pid
				break
			end
		end
	end
	return GetReportedLanguage(player_id, default_language)
end

--获取伤害的来源技能，如果是普攻伤害则返回nil
function GetDamageAbility(a, v, damage, entindex_inflictor_const)
	if not entindex_inflictor_const or damage <= 0 then
		return nil
	end

	local ability = EntIndexToHScript(entindex_inflictor_const)
	if ability ~= nil and ability:GetAbilityName() ~= nil then
		return ability
	end
end

function DAC:DamageFilter(keys)
	if keys.entindex_victim_const == nil then
		return false
	end
	local v = EntIndexToHScript(keys.entindex_victim_const)
	local a = EntIndexToHScript(keys.entindex_attacker_const or keys.entindex_victim_const)
	local t = keys.damagetype_const
	local is_summons = false
	local is_illusion = false
	local a_ori = a
	if IsSummons(a) == true then
		is_summons = true
	end
	if a:HasModifier("modifier_illusion") == true then
		is_illusion = true
	end
	if a.damage_owner ~= nil and a.damage_owner:IsNull() == false then
		a = a.damage_owner
	end
	--仅限同棋盘伤害
	local attacker_at_team_id = a.at_team_id or a.team_id
	local victim_at_teamid = v.at_team_id or v.team_id
	if attacker_at_team_id ~= victim_at_teamid then
		keys.damage = 0
		return false
	end

	--手牌的棋子，不能造成伤害（拿辉耀之类的情况）
	if a.hand_index ~= nil then
		keys.damage = 0
		return false
	end

	--ability是技能伤害，nil是普攻伤害
	local damage_ability = GetDamageAbility(a, v, keys.damage, keys.entindex_inflictor_const)

	--攻击伤害类型转换1：火枪狙击伤害锁定为物理
	if t == DAMAGE_TYPE_MAGICAL and (a:HasModifier('modifier_item_aiweinazhiyu') == false or a:HasModifier('modifier_item_haojie') == true or a:HasModifier('modifier_is_demonhunter_buff_plus') == true or a:HasModifier('modifier_is_demon_buff') == true) and a:HasAbility('sniper_assassinate') and damage_ability and damage_ability:GetAbilityName() == 'sniper_assassinate' then
		--新版狙击手-暗杀：根据等级造成物理伤害，并将原来的魔法伤害无效化
		local d = keys.damage or 400
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = v,
				attacker = a,
				damage_type = DAMAGE_TYPE_PHYSICAL,
				damage = d,
				ability = a:FindAbilityByName('sniper_assassinate'),
			})
		end)
		keys.damage = 0
		return false
	end
	--攻击伤害类型转换2：巨魔战将飞斧技能的伤害锁定为物理伤害
	if damage_ability and a:HasAbility('troll_axe') and damage_ability:GetAbilityName() == 'troll_warlord_whirling_axes_melee' then
		local axe_damage = keys.damage
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = v,
				attacker = a,
				damage_type = DAMAGE_TYPE_PHYSICAL,
				damage = axe_damage,
				ability = a:FindAbilityByName('troll_axe'),
			})
		end)
		a:PerformAttack(v, true, true, true, false, false, false, true)
		play_particle(
		"particles/econ/items/bloodseeker/bloodseeker_eztzhok_weapon/bloodseeker_bloodbath_eztzhok_ribbon.vpcf",
			PATTACH_ABSORIGIN_FOLLOW, v, 2)
		EmitSoundOn("chess_troll.axe.hit", v)
		keys.damage = 0
		return false
	end
	if damage_ability and a:HasAbility('troll_axe') and damage_ability:GetAbilityName() == 'troll_warlord_whirling_axes_ranged' then
		local axe_damage = keys.damage
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = v,
				attacker = a,
				damage_type = DAMAGE_TYPE_PHYSICAL,
				damage = axe_damage,
				ability = a:FindAbilityByName('troll_axe'),
			})
		end)
		a:PerformAttack(v, true, true, true, false, false, false, true)
		play_particle(
		"particles/econ/items/bloodseeker/bloodseeker_eztzhok_weapon/bloodseeker_bloodbath_eztzhok_ribbon.vpcf",
			PATTACH_ABSORIGIN_FOLLOW, v, 2)
		EmitSoundOn("chess_troll.axe.hit", v)
		keys.damage = 0
		return false
	end
	--攻击伤害类型转换3：战鹰、斗熊等锁定伤害类型的攻击
	if a:HasAbility('attack_magical') and t == DAMAGE_TYPE_PHYSICAL then
		--仅在这里将伤害无效化，实际伤害逻辑做在了技能里
		keys.damage = 0
		return false
	end
	if a:HasAbility('attack_pure') and t ~= DAMAGE_TYPE_PURE then
		--仅在这里将伤害无效化，实际伤害逻辑做在了技能里
		keys.damage = 0
		return false
	end
	--攻击伤害类型转换4：单恶魔的攻击伤害转为纯粹
	if a:HasModifier('modifier_is_demon_buff') and is_illusion ~= true and not damage_ability and t ~= DAMAGE_TYPE_PURE then
		--仅在这里将伤害无效化，实际伤害逻辑做在了技能里
		keys.damage = 0
		return false
	end
	--攻击伤害类型转换5：4恶魔猎手、浩劫
	if keys.damage > 0 and (a:HasModifier('modifier_item_haojie') or a:HasModifier('modifier_is_demonhunter_buff_plus')) and t ~= DAMAGE_TYPE_PURE then
		local damage_origin = keys.damage * 1.0
		local m_r = v:Script_GetMagicalArmorValue(nil)
		if t == DAMAGE_TYPE_MAGICAL then
			if m_r >= 1.0 then
				m_r = 0.99
			end
			damage_origin = damage_origin / (1 - m_r)
		end
		local p_r = v:GetPhysicalArmorValue(false)
		if t == DAMAGE_TYPE_PHYSICAL then
			damage_origin = damage_origin / (1 - (0.06 * p_r / (1 + 0.06 * math.abs(p_r))))
		end
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = v,
				attacker = a,
				damage_type = DAMAGE_TYPE_PURE,
				damage = damage_origin,
				ability = damage_ability,
			})
		end)
		keys.damage = 0
		return false
	end
	--攻击伤害类型转换6：艾维娜之羽都转成魔法伤害
	if a:HasModifier('modifier_item_aiweinazhiyu') == true and a:HasModifier('modifier_item_haojie') == false and a:HasModifier('modifier_is_demonhunter_buff_plus') == false and a:HasModifier('modifier_is_demon_buff') == false and t ~= DAMAGE_TYPE_MAGICAL then
		local damage_origin = keys.damage
		local p_r = v:GetPhysicalArmorValue(false)
		if t == DAMAGE_TYPE_PHYSICAL then
			damage_origin = damage_origin / (1 - (0.06 * p_r / (1 + 0.06 * math.abs(p_r))))
		end
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = v,
				attacker = a,
				damage_type = DAMAGE_TYPE_MAGICAL,
				damage = damage_origin,
				ability = damage_ability,
			})
		end)
		keys.damage = 0
		return false
	end
	--图腾受到伤害，锁定伤害量为1或者2
	if (v:HasAbility('is_ward') == true or v:HasAbility("ward_portal") == true) and keys.damage > 0 then
		if IsUnitExist(a) == true and (v:GetAbsOrigin() - a:GetAbsOrigin()):Length2D() > 200 then
			keys.damage = 2
		else
			keys.damage = 1
		end

		-- --恶魔之扉：技能免疫
		-- if v:HasAbility("ward_portal") == true and damage_ability then
		-- 	keys.damage = 0
		-- 	return false
		-- end
	end

	if v:HasModifier('modifier_wisp_tether_buff') then 
		local aa = v:FindModifierByName('modifier_wisp_tether_buff'):GetAbility()
		local reduction_per = GetAbilityKV(aa,'damage_reduction_per') or 0
		keys.damage = keys.damage * (100-reduction_per)/100
	end
	if v:HasModifier('modifier_wisp_altar_power_count') then 
		local power_count = v:FindModifierByName('modifier_wisp_altar_power_count'):GetStackCount()
		keys.damage = keys.damage * math.pow(0.9,power_count)
	end
	if a:HasModifier('modifier_wisp_altar_power_count') then 
		local power_count = a:FindModifierByName('modifier_wisp_altar_power_count'):GetStackCount()
		keys.damage = keys.damage * math.pow(1.1,power_count)
	end
	--被石化的棋子加深伤害
	if a:HasModifier("modifier_is_element_buff_plus_plus") == true and v:HasModifier('modifier_medusa_stone_gaze_stone') then
		local aa = a:FindModifierByName('modifier_is_element_buff_plus_plus'):GetAbility()
		local multi = GetAbilityKV(aa,'multiplier') or 1
		keys.damage = keys.damage * multi
	end
	
	--镜像棋子，只造成50%伤害
	if a:HasModifier("modifier_illusion") == true then
		keys.damage = keys.damage * 0.5
	end
	--幽鬼打荒芜
	if a:HasModifier('modifier_spe_desolate') and IsLonely(v) == true then
		-- play_particle('effect/dead/2.vpcf',PATTACH_ABSORIGIN_FOLLOW,v,3)
		keys.damage = keys.damage * 2.0
		-- local desolate_ability = a:FindAbilityByName('spe_desolate')
		-- if desolate_ability ~= nil then
		-- 	local chaos_per = GetAbilityKV(desolate_ability,'chaos_per')
		-- 	local chaos_duration = GetAbilityKV(desolate_ability,'chaos_duration')
		-- 	if RandomInt(1,100) <= chaos_per then
		-- 		desolate_ability:ApplyDataDrivenModifier(a, v, "modifier_queenofpain_sonic_wave_chaos_debuff", {
		-- 			duration = chaos_duration
		-- 		})
		-- 	end
		-- end
	end

	--幻象法球
	if damage_ability and damage_ability:GetAbilityName() == 'puck_illusory_orb' then
		local duration = GetAbilityKV(damage_ability, 'blind_duration') or 2
		v:AddNewModifier(a, v, "modifier_keeper_of_the_light_blinding_light", { duration = duration })
	end

	--lion死亡一指
	--and (a:HasModifier('modifier_item_haojie') == true or a:HasModifier('modifier_is_demonhunter_buff_plus') == true or a:HasModifier('modifier_is_demon_buff') == true) 
	if t == DAMAGE_TYPE_MAGICAL and damage_ability and damage_ability:GetAbilityName() == 'lion_finger_of_death'  then
		local lion_ability = a:FindAbilityByName('lion_finger_of_death')
		if lion_ability ~= nil then
			local bonus = GetAbilityKV(lion_ability, "damage_bonus") or 200
			local base = GetAbilityKV(lion_ability, "damage") or 300
			local d_count = a.demon_count
			if a.damage_owner and a.damage_owner.demon_count then
				d_count = a.damage_owner.demon_count
			end
			local damage_final = base + ((d_count or 0) * bonus)

			if a:HasModifier('modifier_item_aiweinazhiyu') == true then
				keys.damage = damage_final
			else
				Timers:CreateTimer(0.01, function()
					ApplyDamage({
						victim = v,
						attacker = a,
						damage_type = DAMAGE_TYPE_PURE,
						damage = damage_final,
						ability = damage_ability,
					})
				end)
				keys.damage = 0
				return false
			end
		end
	end
	if t == DAMAGE_TYPE_PHYSICAL then
		if v:HasAbility("mars_bulwark_attack") == true then
			--玛尔斯，计算角度，决定是否抵挡部分伤害
			local ability = v:FindAbilityByName("mars_bulwark_attack")
			local level = ability:GetLevel()
			local v1 = v:GetForwardVector():Normalized()
			local v2 = (a:GetAbsOrigin() - v:GetAbsOrigin()):Normalized()
			-- local cross_product = v1.x * v2.x + v1.y * v2.y
			local angle1 = VectorToAngles(v1)
			local angle2 = VectorToAngles(v2)
			local p = "particles/units/heroes/hero_mars/mars_shield_of_mars_small.vpcf"
			if level >= 3 then
				p = "particles/units/heroes/hero_mars/mars_shield_of_mars.vpcf"
			end

			if math.abs(angle1.y - angle2.y) < 45 or (360 - math.abs(angle1.y - angle2.y)) < 45 then
				--90度范围内
				local damage_reduce_per = ability:GetLevelSpecialValueFor("physical_damage_reduction", level - 1)
				keys.damage = keys.damage / 100.0 * (100 - damage_reduce_per)
				play_particle(p, PATTACH_ABSORIGIN_FOLLOW, v, 2)
			elseif math.abs(angle1.y - angle2.y) < 90 or (360 - math.abs(angle1.y - angle2.y)) < 90 then
				--180度范围内
				local damage_reduce_per = ability:GetLevelSpecialValueFor("physical_damage_reduction_side", level - 1)
				keys.damage = keys.damage / 100.0 * (100 - damage_reduce_per)
				play_particle(p, PATTACH_ABSORIGIN_FOLLOW, v, 2)
			end
		end
		--矮人：所以类型伤害根据距离增加伤害
		if a:HasModifier('modifier_is_dwarf_buff_plus') then
			--2矮人
			local distance = (a:GetAbsOrigin() - v:GetAbsOrigin()):Length2D()

			local damage_bouns_per = distance / 128.0 / 1.414 * 15
			keys.damage = keys.damage * (100 + damage_bouns_per) / 100
		end
		--6野兽：根据层数增加伤害
		if v:FindModifierByName('modifier_is_beast_debuff_plus_plus') ~= nil then
			local count = v:FindModifierByName('modifier_is_beast_debuff_plus_plus'):GetStackCount()
			keys.damage = keys.damage * (1 + count * 10 / 100)
		end
		-- --9猎人：击退敌人
		-- if a:HasModifier('modifier_is_hunter_buff_plus_plus') == true then
		-- 	local blocks = 1
		-- 	local knockback_result = KnockBack({
		-- 		caster = a,
		-- 		target = v,
		-- 		blocks = blocks,
		-- 	})
		-- 	if knockback_result == true then
		-- 		ExtraDamage({
		-- 			caster = a,
		-- 			target = v,
		-- 			damage = 50,
		-- 			damage_type = DAMAGE_TYPE_PHYSICAL
		-- 		})
		-- 	end
		-- end
	end
	if t == DAMAGE_TYPE_MAGICAL then
		--魔法伤害，可被装备加成
		local damage_magical_x_list = {
			modifier_item_konglingguajian = 20,
			-- modifier_item_ahalimumojing = 20,
			modifier_item_hongzhang = 40,
			modifier_item_yangdao = 60,
			modifier_item_ahalimushenzhang = 40,
			modifier_item_huiguang = 30,
			modifier_item_fashulengjing = 20,
			-- modifier_item_aiweinazhiyu = 30,
			modifier_item_yuanlifazhang = 10,
		}

		local damage_magical_bonus = 0
		for m, b in pairs(damage_magical_x_list) do
			if a:FindModifierByName(m) ~= nil then
				damage_magical_bonus = damage_magical_bonus + b
			end
		end
		if a.xuejingshi_count ~= nil and a.xuejingshi_count > 0 then
			local xuejingshi_magic_bonus = tonumber(a.xuejingshi_count or 0) or 0
			damage_magical_bonus = damage_magical_bonus + xuejingshi_magic_bonus * 10.0
		end

		if a:FindModifierByName('modifier_item_zhilidatiaodao_buff_show') ~= nil then
			local datiaodao_stack_count = a:FindModifierByName('modifier_item_zhilidatiaodao_buff_show'):GetStackCount() or
			1
			damage_magical_bonus = damage_magical_bonus + datiaodao_stack_count * 20.0
		end

		keys.damage = math.floor(keys.damage * (100 + damage_magical_bonus) / 100)
		-- 火女，技能造成魔法伤害：叠炽魂
		-- if damage_ability then
		-- 	local ability = EntIndexToHScript(keys.entindex_inflictor_const)
		-- 	if ability ~= nil and ability:GetAbilityName() == 'lina_laguna_blade' and a:FindAbilityByName('lina_laguna_blade') ~= nil then
		-- 		local level = a:FindAbilityByName('lina_laguna_blade'):GetLevel()
		-- 		InvisibleUnitCast({
		-- 			caster = a,
		-- 			ability = 'give_fiery_soul',
		-- 			level = level,
		-- 			unluckydog = a,
		-- 			ignore_nether_ward = true,
		-- 		})
		-- 	end
		-- end
	end
	--格挡：物理伤害减免
	if t == DAMAGE_TYPE_PHYSICAL then
		local gedang_all = 0
		local gedang_list = {
			modifier_item_shenjingdun = 60,
			modifier_item_jurenzhijie_buff = 100,
			modifier_item_xianfengdun = 25,
			-- modifier_item_changdun = 30,
			modifier_item_chihongjia = 25,
			modifier_item_chihongjia_buff = 50,
		}
		for m, gedang in pairs(gedang_list) do
			if v:HasModifier(m) then
				if m == 'modifier_item_xianfengdun' and (RandomInt(1,100) <= 50 and v:Script_GetAttackRange() < 205) then
					gedang = gedang+ 25
				end
				gedang_all = gedang_all + gedang
			end
		end

		if v:HasModifier("modifier_yonghengzhipan_buff") then
			gedang_all = keys.damage
		end

		if gedang_all > 0 then
			keys.damage = math.floor(keys.damage - gedang_all)
			if keys.damage < 0 then
				keys.damage = 0
			end
		end
	end
	--防止友伤杀死自己
	if damage_ability == nil or damage_ability ~= "tester_damage" then
		if a:GetTeam() == v:GetTeam() and keys.damage >= v:GetHealth() then
			keys.damage = v:GetHealth() - 1
		end
	end

	--闪避
	if (not damage_ability) or (damage_ability and (damage_ability:GetAbilityName() == 'attack_magical' or damage_ability:GetAbilityName() == 'attack_pure')) then

		-- if a:HasModifier('modifier_item_jingubang') == false and a:HasModifier('modifier_is_hunter_buff_jingzhun') == false and a:HasModifier('modifier_is_hunter_buff_jingzhun_plus') == false and a:HasModifier('modifier_is_hunter_buff_jingzhun_plus_plus') == false then 
		if a:IsUnableToMiss() == false then
			local miss_per = 0
			local miss_table = {
				modifier_is_elf_buff = 25 * GetLuckyValue(v),

				modifier_is_elf_buff_plus = 40 * GetLuckyValue(v),
				modifier_pangolier_swashbuckle_rolling = 100 * GetLuckyValue(v),
			}
			for m, p in pairs(miss_table) do
				if v:HasModifier(m) then
					miss_per = math.floor(100 - (100 - miss_per) * (100 - p) / 100)
				end
			end

			if a:HasModifier('modifier_brewmaster_cinder_brew') then
				local cinder_brew_miss_table = {
					[1] = 30,
					[2] = 50,
					[3] = 70,
				}
				local cinder_brew_ability = a:FindModifierByName('modifier_brewmaster_cinder_brew'):GetAbility()
				if cinder_brew_ability ~= nil then
					local cinder_brew_ability_level = cinder_brew_ability:GetLevel() or 1
					local cinder_per = cinder_brew_miss_table[cinder_brew_ability_level] or 0
					miss_per = math.floor(100 - (100 - miss_per) * (100 - cinder_per) / 100)
				end
			end

			if RandomInt(1, 100) < miss_per then
				--闪避成功
				keys.damage = 0
				ShowMiss({ caster = a })
				return false
			end
		end

		--移除概率必中的buff
		local per_cannot_miss_buff_table = {
			"modifier_is_hunter_buff_jingzhun",
			"modifier_is_hunter_buff_jingzhun_plus",
			"modifier_is_hunter_buff_jingzhun_plus_plus",
		}
		for _, m in pairs(per_cannot_miss_buff_table) do
			if a:HasModifier(m) then
				a:RemoveModifierByName(m)
			end
		end
	end
	--法术闪避
	if damage_ability and v:HasAbility('phantom_assassin_coup_de_grace') then 
		local per = GetAbilityKV(v:FindAbilityByName('phantom_assassin_coup_de_grace'), "miss_per") or 30
		if RandomInt(1,100) < per then
			keys.damage = 0
			local miss_color = Vector(160,45,39)
			if t == DAMAGE_TYPE_MAGICAL then
				miss_color = Vector(90,145,205)
			elseif t == DAMAGE_TYPE_PURE then 
				miss_color = Vector(216,175,84)
			end
			ShowMiss({
				caster = v,
				color = miss_color
			})
		end
	end
	--虚张声势：免疫所有伤害
	if v:HasModifier('modifier_pangolier_swashbuckle_rolling') == true then
		keys.damage = 0
		ShowMiss({caster = a})
		return false
	end

	--蝮蛇突袭
	if a:GetTeam() ~= v:GetTeam() and v:HasModifier('modifier_ability_viper_viper_strike') == true then
		local viper_m = v:FindModifierByName('modifier_ability_viper_viper_strike')
		if viper_m ~= nil then
			local viper_a = viper_m:GetAbility()
			if viper_a ~= nil then
				local viper_damage_bounus = GetAbilityKV(viper_a, 'damage_bounus') or 10
				keys.damage = keys.damage * ((100+viper_damage_bounus)/100.0)
			end
		end
	end

	--亲王短刀
	if a:GetTeam() ~= v:GetTeam() and a:HasModifier('modifier_item_qinwangduandao') == true and IsSameSpecOrClass(a, v) == true then
		keys.damage = keys.damage * 1.5
	end

	--骑士剑
	if a:GetTeam() ~= v:GetTeam() and (v:HasAbility('is_demon') or v:HasAbility('is_undead')) and (a:HasModifier('modifier_item_qishijian') == true) then
		keys.damage = keys.damage * 1.5
	end

	--勇气之光
	if a:GetTeam() ~= v:GetTeam() and a:HasModifier('modifier_item_yongqizhiguang') == true and GetLevel(a) <= GetLevel(v) then
		keys.damage = keys.damage * 1.25
	end

	--新版骑士盾：百分比的物理/魔法伤害减伤
	if t == DAMAGE_TYPE_PHYSICAL or t == DAMAGE_TYPE_MAGICAL then
		if v:HasModifier("modifier_is_knight_buff_2") then
			keys.damage = keys.damage * 0.65
		end
		if v:HasModifier("modifier_is_knight_buff_2_plus") then
			keys.damage = keys.damage * 0.65
		end
		if v:HasModifier("modifier_is_knight_buff_2_plus_plus") then
			keys.damage = keys.damage * 0.65
		end
	end

	--新守护天使
	if t ~= DAMAGE_TYPE_PURE and (v:HasModifier("modifier_ok_angel_buff") or v:HasModifier("modifier_ok_angel_self_buff")) then
		local modifier_ok_angel = v:FindModifierByName("modifier_ok_angel_buff") or v:FindModifierByName("modifier_ok_angel_self_buff")
		if modifier_ok_angel ~= nil then
			local ability_ok_angel = modifier_ok_angel:GetAbility()
			local magical_resist = GetAbilityKV(ability_ok_angel, 'magical_resist') or 40
			local physical_resist = GetAbilityKV(ability_ok_angel, 'physical_resist') or 40
			if t == DAMAGE_TYPE_MAGICAL then
				keys.damage = keys.damage * (100 - magical_resist) / 100.0
			end
			if t == DAMAGE_TYPE_PHYSICAL then
				keys.damage = keys.damage * (100 - physical_resist) / 100.0
			end
		end
	end

	--最新6娜迦：根据魔抗值反伤
	if t ~= DAMAGE_TYPE_PURE and v:HasModifier("modifier_is_naga_buff_plus_plus_explode") and a:entindex() ~= v:entindex() then
		local coefficient = 1.5
		local m_r = v:Script_GetMagicalArmorValue(nil)
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = a,
				attacker = v,
				damage_type = DAMAGE_TYPE_PURE,
				damage = keys.damage * m_r * coefficient,
			})
		end)
	end
	--9战士：根据护甲值反伤
	if t ~= DAMAGE_TYPE_PURE and v:HasModifier("modifier_is_warrior_buff_plus_plus") and a:entindex() ~= v:entindex() then
		local amount = 1.5
		if v:GetHealth() < v:GetMaxHealth() / 2 then
			amount = 3.0
		end
		Timers:CreateTimer(0.1, function()
			ApplyDamage({
				victim = a,
				attacker = v,
				damage_type = DAMAGE_TYPE_PURE,
				damage = v:GetPhysicalArmorValue(false) * amount,
			})
		end)
	end
	--（9）法师：根据魔法伤害值冻结
	if t == DAMAGE_TYPE_MAGICAL and v:HasModifier("modifier_is_mage_buff_plus_plus") and a:entindex() ~= v:entindex() then
		local dd = keys.damage / 400
		if dd < 0.2 and dd > 0 then
			dd = 0.2
		end
		if dd > 0 then
			local aa = v:FindModifierByName("modifier_is_mage_buff_plus_plus"):GetAbility()
			aa:ApplyDataDrivenModifier(v, v, 'modifier_is_mage_frozen_debuff', { duration = dd })
		end
	end
	--新版如意棒法
	if (damage_ability == nil or damage_ability:GetAbilityName() == 'is_demon_buff' or damage_ability:GetAbilityName() == 'is_demonhunter_buff_plus' or damage_ability:GetAbilityName() == 'monkey_king_boundless_strike') and a:HasModifier("modifier_mk_ruyibangfa") and a:entindex() ~= v:entindex() and keys.damage > 0 and a_ori:HasModifier('modifier_illusion') == false then
		Ruyibangfa({
			caster = a,
			target = v,
		})
	end

	--神镜盾，50%反弹
	if v:HasModifier('modifier_item_shenjingdun') and a:entindex() ~= v:entindex() and RandomInt(1, 100) < 50 then
		local shenjing_damage = keys.damage
		Timers:CreateTimer(0.1, function()
			if shenjing_damage > 99999 then
				shenjing_damage = 99999
			end
			ApplyDamage({
				victim = a,
				attacker = v,
				damage_type = DAMAGE_TYPE_PURE,
				damage = shenjing_damage,
			})
			projectile = ProjectileManager:CreateTrackingProjectile({
				Target = a,
				Source = v,
				Ability = nil,
				EffectName = 'effect/shenjing/tinker_laser.vpcf',
				bDodgeable = false,
				iMoveSpeed = 2000,
				bProvidesVision = false,
				iVisionRadius = 0,
				iVisionTeamNumber = v:GetTeam(),
				iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_HITLOCATION
			})
			EmitSoundOn("shenjingdun.damage", a)
		end)
	end
	--三叉戟
	if a:HasModifier('modifier_item_sanchaji') and (damage_ability == nil or damage_ability:GetAbilityName() ~= 'sd_disseminate') then
		local is_sanchaji_damage = false
		if keys.entindex_inflictor_const ~= nil and keys.entindex_inflictor_const > 0 then
			local ability = EntIndexToHScript(keys.entindex_inflictor_const)
			if ability ~= nil and ability:GetClassname() == 'item_datadriven' and ability:GetAbilityName() ~= nil and ability:GetAbilityName() == 'item_sanchaji' then
				is_sanchaji_damage = true
			end
		end

		if not is_sanchaji_damage then
			local unluckydogs = GetSameNameFriendChess(v, 2)
			if unluckydogs and table.maxn(unluckydogs) > 0 then
				-- keys.damage = keys.damage * 1.25
				local dd = keys.damage
				for _, dog in pairs(unluckydogs) do
					Timers:CreateTimer(0.1, function()
						play_particle("particles/units/heroes/hero_siren/naga_siren_riptide_foam.vpcf",
							PATTACH_ABSORIGIN_FOLLOW, dog, 2)
						ApplyDamage({
							victim = dog,
							attacker = a,
							damage_type = t,
							damage = dd * 0.5,
							ability = FindItemInInventory(a, 'item_sanchaji'),
						})
					end)
				end
			end
		end
		-- keys.damage = keys.damage * 1.2
	end
	if keys.damage > 0 and a:HasModifier('modifier_item_bingyan') and a:entindex() ~= v:entindex() then
		FindItemInInventory(a,'item_bingyan'):ApplyDataDrivenModifier(a, v, 'modifier_item_bingyan_2', { duration = 5 })
	end

	--娜迦海妖：睡眠 普攻打醒
	if keys.damage > 0 and (not damage_ability or damage_ability:GetAbilityName() == 'is_demonhunter_buff_plus') and v:HasModifier('modifier_siren_song_debuff') then
		v:RemoveModifierByName('modifier_siren_song_debuff')
	end
	--4娜迦：减少技能伤害（暂时废弃）
	-- if damage_ability and (v:HasModifier('modifier_is_naga_buff_plus_ability_resist') or v:HasModifier('modifier_is_naga_buff_ability_resist')) then
	-- 	local ability_damage_reduction = 0
	-- 	if v:HasModifier('modifier_is_naga_buff_ability_resist') == true then
	-- 		ability_damage_reduction = ability_damage_reduction + 10
	-- 	end
	-- 	if v:HasModifier('modifier_is_naga_buff_plus_ability_resist') == true then
	-- 		ability_damage_reduction = ability_damage_reduction + 30
	-- 	end
	-- 	if ability_damage_reduction > 100 then
	-- 		ability_damage_reduction = 100
	-- 	end

	-- 	if v.damage_absorbed then
	-- 		v.damage_absorbed = v.damage_absorbed + keys.damage * ability_damage_reduction / 100
	-- 	else
	-- 		v.damage_absorbed = keys.damage * ability_damage_reduction / 100
	-- 	end
	-- 	keys.damage = keys.damage * (100 - ability_damage_reduction) / 100
	-- end

	--离子外壳：减伤
	if v:HasModifier('modifier_dark_seer_ion_shell') == true and t ~= DAMAGE_TYPE_PURE then
		if v:FindModifierByName('modifier_dark_seer_ion_shell') ~= nil and v:FindModifierByName('modifier_dark_seer_ion_shell'):GetAbility() ~= nil then
			local level = v:FindModifierByName('modifier_dark_seer_ion_shell'):GetAbility():GetLevel() or 1
			local reduce = ({ 10, 15, 25 })[level or 1]
			keys.damage = keys.damage * (100 - (reduce or 10)) / 100
		end
	end

	--永恒之盘
	if keys.damage >= v:GetHealth() and v:HasModifier('modifier_yonghengzhipan_buff') == false then
		for slot = 0, 5 do
			if v:GetItemInSlot(slot) ~= nil then
				local ability = v:GetItemInSlot(slot)
				local name = ability:GetAbilityName()
				if name == 'item_yonghengzhipan' and ability:IsCooldownReady() == true then
					ability:ApplyDataDrivenModifier(v, v, 'modifier_yonghengzhipan_buff', { duration = 3.5, })
					EmitSoundOn('DOTA_Item.EssenceRing.Cast', v)
					play_particle("particles/items5_fx/essence_ring.vpcf", PATTACH_ABSORIGIN_FOLLOW, v, 3.5)
					-- v:Purge(false, true, false, false, false) --净化
					ability:StartCooldown(60)
					keys.damage = 0
				end
			end
		end
	end
	if v:HasModifier('modifier_yonghengzhipan_buff') == true then
		keys.damage = 0
	end
	--6野兽
	if t == DAMAGE_TYPE_PHYSICAL and keys.damage > 0 and a:HasAbility('is_beast_buff_plus_plus') == true then
		Add6BeastDebuff({
			ability = a:FindAbilityByName('is_beast_buff_plus_plus'),
			caster = a,
			target = v,
		})
	end

	--薄葬：免受致死伤害
	if v:HasModifier('modifier_dazzle_bozang') and keys.damage > v:GetHealth() then
		keys.damage = 0
		return
	end

	--术士吸血
	if IsUnitExist(a) == true and (damage_ability == nil or (damage_ability:GetAbilityName() ~= 'is_monk_buff' and damage_ability:GetAbilityName() ~= 'is_draenei_buff_plus')) then  --t ~= DAMAGE_TYPE_PURE and 
		local per = 0
		if a:HasModifier("modifier_is_warlock_buff") == true then
			per = per + 0.05
		end
		if a:HasModifier("modifier_is_warlock_buff_plus") == true then
			per = per + 0.20
		end
		if per > 0 then
			local heal = keys.damage * per
			--新6术士 方案2：吸上限
			if a:HasModifier('modifier_is_warlock_buff_plus_plus') == true then
				local is_warlock_6_ability = a:FindModifierByName('modifier_is_warlock_buff_plus_plus'):GetAbility()
				local is_warlock_6_per = GetAbilityKV(is_warlock_6_ability, 'per') or 50
				ModMaxHP({
					caster = v,
					const = -keys.damage * is_warlock_6_per / 100,
					is_heal = false,
				})
				ModMaxHP({
					caster = a,
					const = keys.damage * is_warlock_6_per / 100,
					is_heal = false,
				})
			end
			AttackHeal({
				attacker = a,
				damage = keys.damage,
				per = per,
			})
			play_particle("particles/generic_gameplay/generic_lifesteal.vpcf", PATTACH_OVERHEAD_FOLLOW, a, 2)
		end	
		
		-- --新6术士 方案1：虚弱
		-- if (a:HasModifier('modifier_is_warlock_buff_plus_plus') == true or v:HasModifier('modifier_is_warlock_buff_plus_plus') == true) and v:FindModifierByNameAndCaster('modifier_is_warlock_buff_plus_plus_debuff',a) == nil then
		-- 	local warlock_6_ability = a:FindAbilityByName('is_warlock_buff_plus_plus')
		-- 	if warlock_6_ability ~= nil then
		-- 		warlock_6_ability:ApplyDataDrivenModifier(a, v, 'modifier_is_warlock_buff_plus_plus_debuff',
		-- 		{ duration = 7 })
		-- 	end
		-- end
	end

	--物理普攻吸血
	if t == DAMAGE_TYPE_PHYSICAL and IsUnitExist(a) == true and damage_ability == nil then
		local lifesteal_list = {
			modifier_item_jipin_buff = 25,
			modifier_item_fengkuangmianju_debuff = 25,
			modifier_item_sadan = 50,
			modifier_give_sadan_buff = 100,
			modifier_item_qishijian = 25,
		}
		local per = 0
		for m, b in pairs(lifesteal_list) do
			if a:FindModifierByName(m) ~= nil then
				per = per + b
			end
		end
		if per > 0 then
			AttackHeal({
				attacker = a,
				damage = keys.damage,
				per = per/100.0,
			})
			play_particle("particles/generic_gameplay/generic_lifesteal.vpcf", PATTACH_OVERHEAD_FOLLOW, a, 2)
		end
	end

	--散播
	if keys.damage > 10 and v:HasModifier("modifier_sd_disseminate_debuff") == true then
		local disseminate_ability = v:FindModifierByName("modifier_sd_disseminate_debuff"):GetAbility()
		if disseminate_ability ~= nil then
			local disseminate_radius = GetAbilityKV(disseminate_ability, 'radius') or 300
			local disseminate_per = GetAbilityKV(disseminate_ability, 'damage_reflection_pct') or 15
			local disseminate_owner = disseminate_ability:GetOwner() or a
			ApplyDamageInRadius({
				delay = 0.5,
				caster = disseminate_owner,
				team = disseminate_owner:GetTeam(),
				radius = disseminate_radius,
				role = 2,
				position = v:GetAbsOrigin(),
				damage = keys.damage / 100.0 * disseminate_per,
				damage_type = t,
				ability_entity = disseminate_ability,
				split = false,
				ignore_magic_immune = false,
				exclude_modifier = 'modifier_sd_disseminate_debuff',
				stun_partical = 'effect/sd_sanbo/2.vpcf',
			})
		end
	end
	--changdun_count
	if v:GetHealth() - keys.damage < v:GetMaxHealth() and v:HasModifier('modifier_item_changdun') then
		local vchess = Unit2VChess(v)
		if vchess and (vchess.changdun_round == nil or vchess.changdun_round < _G.battle_round) then
			vchess.changdun_round = _G.battle_round
			if RandomInt(1, 100) < 75 then
				AddPermanentStackCount(v, 'changdun')
			end
		end
	end
	--伤害显示
	if ((_G.show_damage == true and keys.damage > 0) or keys.damage >= 1000) and a:GetTeam() ~= 4 then
		if t == DAMAGE_TYPE_MAGICAL then
			-- AMHC:CreateNumberEffect(v,keys.damage,3,AMHC.MSG_DAMAGE,{90,145,205},9)
			ShowDamageNumberEffect(v, keys.damage, { 90, 145, 205 }, 3)
		elseif t == DAMAGE_TYPE_PHYSICAL then
			-- AMHC:CreateNumberEffect(v,keys.damage,3,AMHC.MSG_DAMAGE,{160,45,39},9)
			ShowDamageNumberEffect(v, keys.damage, { 160, 45, 39 }, 3)
		elseif t == DAMAGE_TYPE_PURE then
			-- AMHC:CreateNumberEffect(v,keys.damage,3,AMHC.MSG_DAMAGE,{216,175,84},9)
			ShowDamageNumberEffect(v, keys.damage, { 216, 175, 84 }, 3)
		end
	end
	--回蓝（法力获取）
	--受到伤害回蓝
	if IsUnitExist(a) == true then
		local mana_get = keys.damage / 5
		if mana_get > 20 then
			mana_get = 20
		end
		if v:HasModifier('modifier_sil_silence_all') == true then
			mana_get = 0
		end
		MPRechargeHit({
			caster = v,
			mana_base = mana_get,
		})
	end

	--造成伤害回蓝
	if IsUnitExist(a) == true then
		mana_get = keys.damage / 10
		if mana_get > 20 then
			mana_get = 20
		end
		if a:HasModifier('modifier_sil_silence_all') == true then
			mana_get = 0
		end
		MPRechargeHit({
			caster = a,
			mana_base = mana_get,
		})
	end

	if v:GetUnitName() == 'dummy' then
		v:StartGestureWithPlaybackRate(ACT_DOTA_FLINCH, 1)
	end
	--伤害统计（不统计过量伤害）
	local damage_stat = keys.damage
	if damage_stat > v:GetHealth() then
		damage_stat = v:GetHealth()
	end
	Add2DamageStat(a, v, damage_stat, t)
	return true
end

function HealDelay(keys)
	local u = keys.u
	local t = keys.t
	local heal = keys.heal
	local delay = keys.delay or 0
	Timers:CreateTimer(delay, function()
		u:Heal(heal, t)
		if keys.effect ~= nil then
			play_particle(keys.effect, PATTACH_ABSORIGIN_FOLLOW, u, 3)
		end
	end)
end

function DAC:HealingFilter(keys)
	local t = EntIndexToHScript(keys.entindex_target_const)

	local heal_bonus = 0

	if t:HasAbility('is_ward') then
		return false
	end

	if t:HasAbility('is_mech') then
		keys.heal = keys.heal * 1.5
	end

	if t:HasModifier('modifier_dazzle_bozang') then
		keys.heal = keys.heal * 2
	end
	if t:HasModifier("modifier_item_bingyan_2") then
		keys.heal = keys.heal * 0.5
	end
	if t:HasModifier("modifier_aa_ice_blast_debuff") then
		keys.heal = keys.heal * 0
	end
	if t:HasModifier("modifier_shiva_debuff") then
		keys.heal = keys.heal * 0.5
	end
	if t:HasModifier("modifier_invoker_ice_wall_debuff") then
		keys.heal = keys.heal * 0.5
	end

	if _G.show_damage == true and keys.heal >= 10 then
		if t ~= nil then
			local h = math.floor(keys.heal)
			AMHC:CreateNumberEffect(t, h, 2, AMHC.MSG_MISS, { 0, 255, 0 }, 0)
		end
	end

	if keys.heal > 10 and t:HasModifier("modifier_sd_disseminate_debuff") == true then
		local disseminate_ability = t:FindModifierByName("modifier_sd_disseminate_debuff"):GetAbility()
		if disseminate_ability ~= nil then
			local disseminate_radius = GetAbilityKV(disseminate_ability, 'radius') or 300
			local disseminate_per = GetAbilityKV(disseminate_ability, 'damage_reflection_pct') or 15
			local disseminate_owner = disseminate_ability:GetOwner() or t
			local unlucky_dogs = FindUnitsInRadiusByTeam({
				team = t:GetTeam(),
				chessboard_id = t.at_team_id or t.team_id or t:GetTeam(),
				role = 2,
				position = t:GetAbsOrigin(),
				radius = disseminate_radius,
				exclude_modifier = 'modifier_sd_disseminate_debuff',
			})
			if unlucky_dogs ~= nil and table.maxn(unlucky_dogs) > 0 then
				for _, u in pairs(unlucky_dogs) do
					if u ~= nil and u:IsNull() == false and u:IsAlive() == true then
						local h = keys.heal / 100.0 * disseminate_per
						HealDelay({
							u = u,
							t = t,
							heal = h,
							delay = 0.5,
							effect = 'effect/sd_sanbo/3.vpcf',
						})
					end
				end
			end
		end
	end

	--德莱尼
	if t:HasModifier("modifier_is_draenei_buff_plus") == true and t.alreadywon ~= true then
		local d = math.floor(keys.heal)
		t.draenei_heal = (t.draenei_heal or 0) + d
		local draenei_ablity = t:FindAbilityByName("is_draenei_buff_plus")
		if draenei_ablity ~= nil and draenei_ablity:IsCooldownReady() == true then
			if t.draenei_heal >= 100 then
				--洗礼！
				local unlucky_dogs = FindUnitsInRadiusByTeam({
					team = t:GetTeam(),
					chessboard_id = t.at_team_id or t.team_id or t:GetTeam(),
					role = 2,
					position = t:GetAbsOrigin(),
					radius = 300,
				})
				t.draenei_heal = t.draenei_heal --*1.5
				if t.draenei_heal > 300 then
					t.draenei_heal = 300
				end
				if table.maxn(unlucky_dogs) > 0 then
					ApplyDamageInRadius({
						delay = 0.5,
						caster = t,
						team = t:GetTeam(),
						radius = 300,
						role = 2,
						position = t:GetAbsOrigin(),
						damage = t.draenei_heal,
						damage_type = DAMAGE_TYPE_PURE,
						ability = 'is_draenei_buff_plus',
						split = false,
						ignore_magic_immune = true,
						-- stun_partical = 'effect/draenei/exp2.vpcf',
					})

					play_particle(
					'effect/draenei_xili/1econ/items/omniknight/hammer_ti6_immortal/omniknight_purification_ti6_immortal.vpcf',
						PATTACH_ABSORIGIN_FOLLOW, t, 3)
					EmitSoundOn('Hero_Omniknight.Purification', t)
					t.draenei_heal = 0
					draenei_ablity:StartCooldown(5)
				end
			end
		end
	end
	return true
end

function DAC:ExecuteOrderFilter(keys)
	if keys.order_type == 19 then
		--移动装备后更改武器将打造状态
		Timers:CreateTimer(0.1,function()
			local h = PlayerId2Hero(keys.issuer_player_id_const)
			local coin_table = GetRecycleItemResult(h)
			CustomGameEventManager:Send_ServerToTeam(h:GetTeam(), "show_item_recycle_result", {
				key = GetClientKey(h:GetTeam()),
				result = coin_table,
				show_confirm = keys.show_confirm,
			})
		end)
		if keys.entindex_target == 6 or keys.entindex_target == 7 or keys.entindex_target == 8 then
			--移动装备到备用栏位
			-- local a = EntIndexToHScript(keys.entindex_ability)
			-- if a ~= nil and a:IsNull() == false and a:GetClassname() == 'item_datadriven' and a:GetAbilityName() ~= nil then
			-- 	if a:GetAbilityName() == 'item_chishu' then
			-- 		--兼容不能吃树的bug，把吃树换成即食的item_chishu_new
			-- 		Timers:CreateTimer(0.1, function()
			-- 			MakeTangoEatable(keys.issuer_player_id_const, keys.entindex_target)
			-- 		end)
			-- 	end
			-- end
		end
	end
	if keys.order_type == 12 then
		--信使丢下装备
		StartUpdateUIRecycleItemResult(PlayerId2Hero(keys.issuer_player_id_const))
	end

	if keys.order_type == 13 then
		--信使给出装备
		StartUpdateUIRecycleItemResult(PlayerId2Hero(keys.issuer_player_id_const))
	end

	if keys.order_type == 14 then
		--信使捡起装备
		StartUpdateUIRecycleItemResult(PlayerId2Hero(keys.issuer_player_id_const))
	end

	return true
end

function StartUpdateUIRecycleItemResult(u)
	if u.update_ui_recycle_timer ~= nil then
		return
	end
	Timers:CreateTimer(0.1, function()
		--启动一个timer，当检测到装备数量发生变化的时候，OnShowRecycleItemResult
		if IsUnitExist(u) == false or u:IsHero() == false then
			u.update_ui_recycle_timer = nil
			return
		end
		local item_count_before = u.item_count or 0
		local try_count = 100
		if u.update_ui_recycle_timer ~= nil then
			return
		end
		DAC:OnShowRecycleItemResult({
			PlayerID = u:GetPlayerID(),
			show_confirm = 0,
		})
		u.update_ui_recycle_timer = Timers:CreateTimer(0.1, function()
			if IsUnitExist(u) == false or try_count <= 0 then
				u.update_ui_recycle_timer = nil
				return
			end
			local item_count = GetUnitItemCount(u)
			if GetUnitItemCount(u) ~= item_count_before then
				DAC:OnShowRecycleItemResult({
					PlayerID = u:GetPlayerID(),
					show_confirm = 0,
				})
				u.update_ui_recycle_timer = nil
				return
			end
			try_count = try_count - 1
			return 0.1
		end)
		return
	end)
end

function GetUnitItemCount(u)
	if IsUnitExist(u) == false then
		return 0
	end
	local count = 0
	for slot = 0, 8 do
		if u:GetItemInSlot(slot) ~= nil then
			count = count + 1
		end
	end
	u.item_count = count
	return count
end

function GetRecycleItemResult(h)
	local coin_table = {}
	local item_level_sum = 0
	local coin_level = 0
	local result_table = {}
	for slot = 0, 8 do
		if h:GetItemInSlot(slot) ~= nil then
			local item = h:GetItemInSlot(slot)
			local item_name = item:GetAbilityName()
			local item_level = _G.ITEM_2_LEVEL[item_name]
			if item_level and item_name ~= 'item_shengjian' then
				item_level_sum = item_level_sum + item_level
				table.insert(result_table, {
					item = item,
					name = item_name,
					slot = slot,
					level = item_level,
				})
			end
		end
	end
	--选出最合适本次铸币的配件
	if item_level_sum > 0 then
		for i = 5, 1, -1 do
			local level_i = 0
			for s = 1, #result_table do
				level_i = level_i + result_table[s]['level']
			end
			local require = 2 * i - 1
			if level_i >= require then
				coin_level = math.ceil(level_i / 2)
				for j = #result_table, 1, -1 do
					if level_i - result_table[j]['level'] >= require then
						level_i = level_i - result_table[j]['level']
						coin_level = math.ceil(level_i / 2)
						table.remove(result_table, j)
					end
				end
				break
			end
		end
	end

	coin_table['item_level_sum'] = item_level_sum
	coin_table['item_level_extra'] = item_level_sum + 1 - (coin_level * 2)
	coin_table['parts'] = result_table

	local upgrade = false
	if h:HasModifier('modifier_item_upgrade_lootbox') == true and coin_level > 0 and h.upgrade_lootbox_chance ~= nil and h.upgrade_lootbox_chance > 0 then
		upgrade = true
		coin_level = coin_level + 1
	end
	if coin_level > 5 then
		coin_level = 5
	end
	if coin_level > 0 then
		coin_table['lootbox_level'] = coin_level
		coin_table['lootbox'] = 'item_lootbox_lv' .. coin_level
	end
	return coin_table
end

function DAC:OnShowRecycleItemResult(keys)
	local h = PlayerId2Hero(keys.PlayerID)
	if IsUnitExist(h) == false then
		return
	end
	local coin_table = GetRecycleItemResult(h)
	CustomGameEventManager:Send_ServerToTeam(h:GetTeam(), "show_item_recycle_result", {
		key = GetClientKey(h:GetTeam()),
		result = coin_table,
		show_confirm = keys.show_confirm,
	})
end

--重铸装备
function DAC:OnRequestRecycleItem(keys)
	local h = PlayerId2Hero(keys.PlayerID)
	if IsUnitExist(h) == false then
		return
	end
	local tt = GetRecycleItemResult(h)
	if tt and tt['lootbox'] then
		for _, item in pairs(tt['parts']) do
			h:RemoveItem(item.item)
			RemoveOneValueInTable(h.item_got, item.name)
			DiscardOneItem(item.name, h)
		end
		EmitSoundOn("item.jixiezhixin.open", h)
		play_particle("effect/combine_item/1.vpcf", PATTACH_ABSORIGIN_FOLLOW, h, 3)
		AddItemPlus(h, tt['lootbox'])
	end
	h.recycle_item_available = false
	StartUpdateUIRecycleItemResult(h)
	CustomGameEventManager:Send_ServerToTeam(h:GetTeam(), "toggle_request_recycle_item", {
		key = GetClientKey(h:GetTeam()),
		available = false,
	})

	if h.upgrade_lootbox_chance ~= nil and GetCurrRelicByTeam(h:GetTeam()) ~= nil and GetCurrRelicByTeam(h:GetTeam()):GetAbilityName() == 'item_upgrade_lootbox' and h.upgrade_lootbox_chance ~= nil and h.upgrade_lootbox_chance > 0 then
		h.upgrade_lootbox_chance = h.upgrade_lootbox_chance - 1
		if GetCurrRelicByTeam(h:GetTeam()) ~= nil then
			GetCurrRelicByTeam(h:GetTeam()):SetCurrentCharges(h.upgrade_lootbox_chance)
		end

		if IsUnitExist(h.blacksmith) == true then
			h.blacksmith:SetHealth(h.upgrade_lootbox_chance)
		end
		if h.upgrade_lootbox_chance <= 0 then
			h.upgrade_lootbox_chance = nil
			if h.blacksmith ~= nil and h.blacksmith:IsNull() == false then
				EmitSoundOn("Hero_Furion.Teleport_Disappear", h.blacksmith)
				h.blacksmith:ForceKill(false)
				h.blacksmith:SetModelScale(0.001)
				play_particle("particles/econ/events/compendium_2023/compendium_2023_teleport_end_streaks.vpcf",
					PATTACH_ABSORIGIN_FOLLOW, h.blacksmith, 3)
			end
		end
	end
end

