function DAC:ModifierGainedFilter(keys)
	local victim = EntIndexToHScript(keys.entindex_parent_const)
	local modifier = keys.name_const
	local duration = keys.duration


	RemindItem(victim, modifier)

	if victim:HasModifier('modifier_is_nraqi_buff') and victim:FindModifierByName(modifier) ~= nil and (victim:FindModifierByName(modifier):IsDebuff() or modifier == "modifier_pangolier_luckyshot_disarm") and IsModifierInNraqiWhiteList(modifier) ~= true then
		--无面者，抵消debuff
		if victim.nraqi_animation ~= true then
			victim.nraqi_animation = true
			play_particle("particles/units/heroes/hero_faceless_void/faceless_void_backtrack.vpcf",
				PATTACH_ABSORIGIN_FOLLOW, victim, 2)
			Timers:CreateTimer(2, function()
				victim.nraqi_animation = nil
			end)
		end
		return false
	end

	-- if victim:HasModifier('modifier_yonghengzhipan_yongheng_buff') and modifier == 'modifier_kill' then
	-- 	play_particle("particles/items5_fx/essence_ring_burst.vpcf",PATTACH_ABSORIGIN_FOLLOW,victim,3)
	-- 	--永恒之盘
	-- 	return false
	-- end

	if victim:HasModifier('modifier_hoodwink_hunters_mark') and victim:FindModifierByName(modifier) ~= nil and victim:FindModifierByName(modifier):IsDebuff() then
		local addition = GetAbilityKV(victim:FindModifierByName('modifier_hoodwink_hunters_mark'):GetAbility(),
			'debuff_amp') or 50
		keys.duration = duration * (1 + addition / 100)
	end

	if modifier == "modifier_medusa_stone_gaze_stone" then
		--石化，净化效果
		local caster = EntIndexToHScript(keys.entindex_caster_const)
		PurgeASummonedChess(caster, victim)
	end

	if modifier == 'modifier_ringmaster_spotlight_debuff' and HasKillModifier(victim) == true then
		--非永久棋子被聚光灯照到
		if victim:HasAbility('dac_guai_base') == true then
			victim:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(victim, victim, 'modifier_base_dissipate',
				{ duration = 2 })
		end
	end

	return true
end

--坟场管理
function ResetAllDeadChessList()
	_G.dead_chess_list = {
		[6] = {},
		[7] = {},
		[8] = {},
		[9] = {},
		[10] = {},
		[11] = {},
		[12] = {},
		[13] = {},
	}
end

function AddChess2DeadChessList(keys)
	local at_team_id = keys.at_team_id        --必填
	local chess_base_name = keys.chess_base_name --必填
	if at_team_id == nil or chess_base_name == nil then
		return
	end

	local level = keys.level or 0
	if string.find(chess_base_name, 'chess_') ~= nil then
		level = _G.chess_2_mana[chess_base_name]
	end
	local items = keys.items or {}
	if _G.dead_chess_list ~= nil and _G.dead_chess_list[at_team_id] ~= nil then
		local index = table.maxn(_G.dead_chess_list[at_team_id]) + 1
		table.insert(_G.dead_chess_list[at_team_id], {
			index = index,
			chess_base_name = chess_base_name,
			items = items,
			level = level,
		})
	end
end

function GetMaxLevelChessFromDeadChessList(keys)
	local at_team_id = keys.at_team_id --必填
	if at_team_id == nil then
		return
	end
	local is_remove = keys.is_remove or false

	local max_level = 0
	local max_level_chess = nil
	local max_level_index = nil
	for i, v in pairs(_G.dead_chess_list[at_team_id]) do
		if v.level ~= nil and v.level > max_level then
			max_level = v.level
			max_level_chess = v
			max_level_index = i
		end
	end
	if is_remove == true and max_level_index ~= nil then
		table.remove(_G.dead_chess_list[at_team_id], max_level_index)
	end
	return max_level_chess
end

--上帝之手：复活
function ChenFuhuo(keys)
	local caster = keys.caster
	local ability = keys.ability
	local level = ability:GetLevel()

	local fuhuo_unit = GetMaxLevelChessFromDeadChessList({
		at_team_id = caster.at_team_id or caster.team_id,
		is_remove = true,
	})

	if fuhuo_unit ~= nil then
		--复活！
		local unit_name = fuhuo_unit.chess_base_name
		if string.find(unit_name, 'chess_') ~= nil then
			if level == 2 then
				unit_name = unit_name .. '1'
			elseif level >= 3 then
				unit_name = unit_name .. '11'
			end
		end
		local p = FindEmptyGridAtUnit(caster, true)

		SummonOneChessAsync({
			teamid = caster.team_id,
			position = p,
			chessname = unit_name,
			at_teamid = caster.at_team_id or caster.team_id,
			items = items,
			cb = function(w)
				if IsUnitExist(w) == true then
					ExtendBeastBuff(w, caster, false, true)
					w.is_fuhuo = true
					w.bh_gold = 1
					if w:HasModifier('modifier_bh_gold') then
						w:RemoveModifierByName('modifier_bh_gold')
					end
					play_particle("particles/units/heroes/hero_chen/chen_holy_persuasion.vpcf", PATTACH_ABSORIGIN_FOLLOW, w, 3)
					SetWard(w)
					SetChessSpecialLook(w)
				end
				EmitSoundOn("chess_chen.fuhuo", caster)
			end
		})
	end
end

function AddSynergy(keys)
	local caster = keys.caster
	local synergy = keys.synergy
	if caster:IsHero() ~= true and synergy ~= nil then
		if synergy == 'is_dwarf' and caster:Script_GetAttackRange() <= 205 then
			return
		end
		-- if synergy == 'is_dragon' then 
		-- 	caster.is_dragon_zhanhou = true
		-- end
		if synergy == 'is_kobold' and keys.jiubei_buff then 
			caster.jiubei_buff = true
			caster:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(caster, caster,'modifier_attackspeed_buff',{})
		end
		if keys.modmaxhp ~= nil then
			ModMaxHP({
				caster = caster,
				const = keys.modmaxhp
			})
		end


		AddAbilityAndSetLevel(caster, synergy, 1)
		-- caster:FindAbilityByName(synergy):SetHidden(true)
		StatClassCount(caster:GetTeam())
	end
end

function RemoveSynergy(keys)
	local caster = keys.caster
	local synergy = keys.synergy
	if synergy ~= nil and FindValueInTable(_G.chess_list_by_synergy[synergy], GetUnitBaseName(caster)) ~= true and FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman[synergy], GetUnitBaseName(caster)) ~= true and FindValueInTable(_G.chess_list_by_synergy_ban_unavailable[synergy], GetUnitBaseName(caster)) ~= true and FindValueInTable(caster.extra_synergy, synergy) == false then
		RemoveAbilityAndModifier(caster, synergy)
		StatClassCount(caster:GetTeam())
		if synergy == 'is_dragon' then 
			caster.is_dragon_zhanhou = nil
		end
		if keys.modmaxhp ~= nil then
			ModMaxHP({
				caster = caster,
				const = keys.modmaxhp
			})
		end
	end
end

