function GetChessCostByName(c)
	for cost, chess_list in pairs(_G.chess_list_by_mana) do
		for _, chess_name in pairs(chess_list) do
			if chess_name == c then
				return cost
			end
		end
	end
	for cost, chess_list in pairs(_G.chess_list_by_mana_black) do
		for _, chess_name in pairs(chess_list) do
			if chess_name == c then
				return cost
			end
		end
	end
	for cost, chess_name in pairs(_G.chess_list_by_mana_gold) do
		if chess_name == c then
			return 5
		end
	end
	for cost, chess_name in pairs(_G.chess_list_ssr) do
		if chess_name == c then
			return 5
		end
	end
	for cost, chess_list in pairs(_G.chess_list_by_mana_special) do
		for _, chess_name in pairs(chess_list) do
			if chess_name == c then
				return cost
			end
		end
	end
	return nil
end

