function MarsAttack(keys)
	local caster = keys.caster
	if caster:HasAbility("mars_bulwark_attack") and caster:FindAbilityByName("mars_bulwark_attack"):GetCooldownTimeRemaining() == 0 and caster:IsSilenced() == false and caster:IsStunned() == false and caster:IsFrozen() == false and caster:HasModifier('modifier_queenofpain_sonic_wave_chaos_debuff') == false and caster:HasModifier('modifier_is_satyr_debuff') == false and caster:IsHexed() == false and caster:IsCommandRestricted() == false and caster:HasModifier("modifier_axe_berserkers_call") == false and caster.is_moving ~= true then
		caster:Stop()
		StartMarsShieldCD(caster)
		caster:StartGesture(ACT_DOTA_CAST_ABILITY_4)

		MarsShieldDamage({
			caster = caster,
			ability = caster:FindAbilityByName("mars_bulwark_attack"),
		})
		local p = "particles/units/heroes/hero_mars/mars_shield_bash.vpcf"
		if caster:FindAbilityByName("mars_bulwark_attack"):GetLevel() >= 3 then
			p = "particles/econ/items/mars/mars_fall20_immortal_shield/mars_fall20_immortal_shield_bash.vpcf"
		end

		Timers:CreateTimer(0.4, function()
			play_particle(p, PATTACH_ABSORIGIN_FOLLOW, caster, 3)
			EmitSoundOn("Hero_Mars.Shield.Cast", caster)
		end)
	else
		--普通攻击
		caster:AddActivityModifier('attack_close_range')
		caster:AddActivityModifier('faster')
		caster:StartGestureWithPlaybackRate(ACT_DOTA_ATTACK, caster:GetAttacksPerSecond(false) * 3)
	end
end

