	local damage = caster:GetAttackDamage()
	local damage_bonus = caster:GetAverageTrueAttackDamage(target) -
	(caster:GetBaseDamageMax() + caster:GetBaseDamageMin()) / 2

	local team_id = target.at_team_id or target.team_id
	ApplyDamage({
