function FindMinHPEnemy(u, last_target)
	local unluckydog = nil
	local min_hp = 999999
	local last_index = -1
	if last_target ~= nil then
		last_index = last_target:entindex()
	end
	local team = u.at_team_id or u.team_id
	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		if unit.team_id ~= u.team_id and IsUnitExist(unit) and unit:entindex() ~= last_index and unit:GetHealth() < min_hp and not unit:HasAbility('is_ward') then
			unluckydog = unit
			min_hp = unit:GetHealth()
		end
	end
	return unluckydog
end

function FindNecScytheTarget(u, xishu, base_damage)
	local max_damage = 0
	local unluckydog = nil
	local team = u.at_team_id or u.team_id
	for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		if unit.team_id ~= u.team_id and IsUnitExist(unit) then
			local hp_max = unit:GetMaxHealth()
			local d = hp_max / 100.0 * xishu + base_damage
			if d > unit:GetHealth() then
				d = d * 100
			end
			if d > max_damage then
				unluckydog = unit
				max_damage = d
			end
		end
	end
	return unluckydog
end

