		end
	end)
	EmitSoundOn("Hero_FacelessVoid.Chronosphere", caster)

	--计时器，每interval秒判断罩子内部的敌人，给interval秒的冻结debuff
	local interval = 0.1
	local count_down = duration or 5
	Timers:CreateTimer(interval, function()
		count_down = count_down - interval
		if count_down <= 0 then
			return
		end
		GiveFvDebuffAndBuff(caster, point, radius, ability, "modifier_faceless_void_chronosphere_freeze", nil, interval)

		return interval
	end)
end

function GiveFvDebuffAndBuff(caster, point, radius, ability, debuff, buff, duration)
	if caster == nil or caster:IsNull() == true then
		return
	end
	if debuff ~= nil then
		--给罩子内全部棋子debuff
		local unlucky_dogs = FindUnitsInRadiusByTeam({
			team = caster:GetTeam(),
			chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam(),
			role = 3,
			position = point,
			radius = radius,
		})
		for i, v in pairs(unlucky_dogs) do
			if IsUnitExist(v) == true and (v:HasAbility('fv_zhao') == false or v:FindAbilityByName('fv_zhao'):IsActivated() == false) and v.is_moving ~= true then
				v:AddNewModifier(v, nil, debuff, { duration = duration })
			end
		end
	end
	if buff ~= nil then
		--未来可能添加的buff
	end
end

function FvZhaoNew(keys)
	local caster = keys.caster
	local ability = keys.ability
	local level = ability:GetLevel()
	local point = caster:GetAbsOrigin()--(keys.target_points or {})[1]
	local duration = ability:GetLevelSpecialValueFor("duration", ability:GetLevel() - 1)
	local radius = ability:GetLevelSpecialValueFor("radius", ability:GetLevel() - 1)
	caster.is_fv_zhao = true

	--播放特效和音效
	local p_addr = 'particles/units/heroes/hero_faceless_void/faceless_void_chronocube.vpcf'
	-- local p_addr = 'effect/fv_zhao/faceless_void_chronosphere.vpcf'
	-- if level >= 3 then
	-- 	p_addr = 'particles/econ/items/faceless_void/faceless_void_arcana/faceless_void_arcana_chronosphere.vpcf'
	-- end

	local particle = ParticleManager:CreateParticle(p_addr, PATTACH_ABSORIGIN, caster)
	ParticleManager:SetParticleControl(particle, 0, point)
	-- ParticleManager:SetParticleControl(particle, 1, Vector(radius-50,radius-50,radius-50))
	ParticleManager:SetParticleControl(particle, 1, Vector(radius, radius, radius))

	Timers:CreateTimer(duration, function()
		caster.is_fv_zhao = nil
		if particle ~= nil then
			ParticleManager:DestroyParticle(particle, true)
			ParticleManager:ReleaseParticleIndex(particle)
		end
	end)
	EmitSoundOn("Hero_FacelessVoid.Chronosphere", caster)

	--计时器，每interval秒判断罩子内部的敌人，给interval秒的冻结debuff
	local interval = 0.1
	local count_down = duration or 5
	Timers:CreateTimer(interval, function()
		count_down = count_down - interval
		if count_down <= 0 then
			return
		end
		GiveFvDebuffAndBuffNew(caster, point, radius, ability, interval)

		return interval
	end)
end

function GiveFvDebuffAndBuffNew(caster, point, radius, ability, duration)
	if caster == nil or caster:IsNull() == true or ability == nil then
		return
	end
	local chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam()
	--遍历当前棋盘
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if IsUnitExist(unit) == true and IsUnitInCube(point, radius - 50, unit) == true then
			if unit:GetTeam() == caster:GetTeam() then
				--队友，buff
				ability:ApplyDataDrivenModifier(caster, unit, 'modifier_fv_zhao_new_buff', { duration = duration })
			else
				--敌人，debuff
				ability:ApplyDataDrivenModifier(caster, unit, 'modifier_fv_zhao_new_debuff', { duration = duration })
			end
		end
	end
end

function IsUnitInCube(center, radius, unit)
	if center == nil or radius == 0 or IsUnitExist(unit) == false then
		return false
	end
	local center_x = center.x
	local center_y = center.y
	local pos = unit:GetAbsOrigin()
	local unit_x = pos.x
	local unit_y = pos.y
	if math.abs(unit_x - center_x) <= radius and math.abs(unit_y - center_y) <= radius then
		return true
	else
		return false
	end
end

function PlaySpawnAnimation(x)
	x:StartGesture(ACT_DOTA_SPAWN)
	if string.find(x:GetUnitName(), 'sniper') ~= nil then
		x:StartGesture(ACT_DOTA_IDLE)
	end
end

