function FindItemAbility(u, item_name)
	for slot = 0, 5 do
		if u:GetItemInSlot(slot) ~= nil then
			local ability = u:GetItemInSlot(slot)
			local name = ability:GetAbilityName()
			if name == item_name then
				return ability
			end
		end
	end
end

--获得某棋子某技能的实际魔法消耗（用自动自带的GetManaCost不会计算modifier减免，很蠢）
function GetManaCostX(u, a)
	local mana_cost = u:FindAbilityByName(a):GetManaCost(u:FindAbilityByName(a):GetLevel()) or 100

	if a == 'leshrac_pulse_nova' then
		mana_cost = 100
	end
	if u:HasModifier('modifier_is_shaman_50mana_count') then
		-- local count = u:FindModifierByName('modifier_is_shaman_50mana_count'):GetStackCount()
		-- if count == 0 then
		-- 	count = 1
		-- end
		-- mana_cost = mana_cost * math.pow(0.75, count)
		mana_cost = math.floor(mana_cost * 0.75)
	end

	return mana_cost
end

