function DropMangoAndUpdateLastBattle(team_id, result)
	local hero = TeamId2Hero(team_id)
	if IsUnitExist(hero) == false then
		return
	end
	if hero.last_battle_victory and hero.last_battle_victory ~= result and hero:HasModifier('modifier_item_mangotree') then
		if IsUnitExist(hero.mango_tree) == true then
			local item_name = 'item_mangguo'
			local curr_health = hero.mango_tree:GetHealth()
			if curr_health == nil then
				curr_health = 1
			end
			curr_health = curr_health - 1
			local newItem = CreateItem(item_name, hero, hero)
			local drop = CreateItemOnPositionForLaunch(hero.mango_tree:GetAbsOrigin(), newItem)
			newItem:SimulateLaunchLoot(hero.mango_tree:GetAbsOrigin() +
			Vector(RandomFloat(-150, -100), RandomFloat(-50, 50), 0))

			if curr_health > 0 then
				hero.mango_tree:SetHealth(curr_health)
				if GetCurrRelicByTeam(hero:GetTeam()) ~= nil then
					GetCurrRelicByTeam(hero:GetTeam()):SetCurrentCharges(curr_health)
				end
			else
				--生成金芒果（移走了）
				EmitSoundOn("item.mangotree.break", hero.mango_tree)
				hero.mango_tree:ForceKill(false)
				hero.mango_tree:SetModelScale(0.001)
				play_particle("effect/animation/tree/2_oak_01_destruction.vpcf", PATTACH_ABSORIGIN_FOLLOW,
					hero.mango_tree, 3)
				if GetCurrRelicByTeam(hero:GetTeam()) ~= nil then
					GetCurrRelicByTeam(hero:GetTeam()):SetCurrentCharges(0)
				end
			end
		end
	end
	hero.last_battle_victory = result
end

function FindRangedChessAtRow34(at_team_id)
	for _, u in pairs(GetValidChessOnBoard(at_team_id)) do
		if IsUnitExist(u) and (u.y == 4) and u:Script_GetAttackRange() > 205 and u:Script_GetAttackRange() < 405 then
			return u
		end
		if IsUnitExist(u) and (u.y == 3 or u.y == 4) and u:Script_GetAttackRange() > 405 then
			return u
		end
	end
	return nil
end

function FindMeleeChessAtRow12(at_team_id)
	for _, u in pairs(GetValidChessOnBoard(at_team_id)) do
		if IsUnitExist(u) and (u.y == 1 or u.y == 2) and u:Script_GetAttackRange() <= 405 then
			return u
		end
	end
	return nil
end

function FindEmptyPosAtRow(at_team_id, min_row, max_row)
	local try_count = 0
	while try_count < 10 do
		local y = RandomInt(min_row, max_row)
		local x = RandomInt(3, 6)
		if IsEmptyGrid(at_team_id, x, y) == true then
			return XY2Vector(x, y, at_team_id)
		end
		try_count = try_count + 1
	end
	try_count = 0
	while try_count < 100 do
		local y = RandomInt(min_row, max_row)
		local x = RandomInt(1, 8)
		if IsEmptyGrid(at_team_id, x, y) == true then
			return XY2Vector(x, y, at_team_id)
		end
		try_count = try_count + 1
	end
end

function PetMakeSynergy(hero)
	local pet = hero.pet_entity
	if pet == nil then
		return
	end
	local pet_kv_synergy = string.split(pet.pet_kv.synergy, ',')

	hero.ai_synergy = {}
	hero.desire_chess = {}

	--决定抽牌策略
	local synergy_table = {}
	local chess_table = {}
	--招募面板
	if hero.curr_chess_table then
		for _, c in pairs(hero.curr_chess_table) do
			local chess_name = c.chess
			local level = _G.chess_2_mana[chess_name] or 1
			local price = c.price

			local classes = GetChessClassAndRaceTable(chess_name)
			for _, s in pairs(classes) do
				if synergy_table[s] == nil then
					synergy_table[s] = 0
				end
				synergy_table[s] = synergy_table[s] + level
			end

			-- if chess_table[chess_name] == nil then
			-- 	chess_table[chess_name] = 0
			-- end
			-- chess_table[chess_name] = chess_table[chess_name] + 1
		end
	end
	--手牌
	if hero.hand_entities then
		for _, ent in pairs(hero.hand_entities) do
			local chess_name = ent:GetUnitName()
			local chess_base_name = GetChessBaseName(chess_name)
			local star = GetChessNameStar(chess_name) or 1
			local level = _G.chess_2_mana[chess_base_name] or 1

			local classes = GetChessClassAndRaceTable(chess_base_name)
			for _, s in pairs(classes) do
				if synergy_table[s] == nil then
					synergy_table[s] = 0
				end
				synergy_table[s] = synergy_table[s] + star * level
			end

			if chess_table[chess_base_name] == nil then
				chess_table[chess_base_name] = 0
			end
			chess_table[chess_base_name] = chess_table[chess_base_name] + ({ 1, 3, 9 })[star]
		end
	end
	--场上棋子
	for _, v in pairs(_G.mychess[hero:GetTeam()]) do
		if v ~= nil and v.chess ~= nil then
			local chess_name = v.chess
			local chess_base_name = GetChessBaseName(chess_name)
			local star = GetChessNameStar(chess_name) or 1
			local level = _G.chess_2_mana[chess_base_name] or 1

			local classes = GetChessClassAndRaceTable(chess_base_name)
			for _, s in pairs(classes) do
				if synergy_table[s] == nil then
					synergy_table[s] = 0
				end
				synergy_table[s] = synergy_table[s] + star * level
			end

			if chess_table[chess_base_name] == nil then
				chess_table[chess_base_name] = 0
			end
			chess_table[chess_base_name] = chess_table[chess_base_name] + ({ 1, 3, 9 })[star]
		end
	end

	--宠物自己的偏好
	for _, v in pairs(pet_kv_synergy) do
		if v then
			if synergy_table[v] == nil then
				synergy_table[v] = 0
			end
			synergy_table[v] = synergy_table[v] + 1
		end
	end

	local synergy_table_sort = {}
	for class, score in pairs(synergy_table) do
		table.insert(synergy_table_sort, {
			class = class,
			score = score or 0,
		})
	end
	table.sort(synergy_table_sort, function(a, b)
		return a.score > b.score
	end)

	local chess_table_sort = {}
	for chess, score in pairs(chess_table) do
		if score >= 9 then
			score = 0
		end
		if score == 8 then
			score = 999
		end
		if score == 2 then
			score = 99
		end
		if score == 1 then
			score = 9
		end
		table.insert(chess_table_sort, {
			chess = chess,
			score = score or 0,
		})
	end
	table.sort(chess_table_sort, function(a, b)
		return a.score > b.score
	end)

	-- if table.maxn(synergy_table_sort) >= 1 then
	-- 	table.insert(hero.ai_synergy,synergy_table_sort[1].class)
	-- end
	-- if table.maxn(synergy_table_sort) >= 2 then
	-- 	table.insert(hero.ai_synergy,synergy_table_sort[2].class)
	-- end
	-- if table.maxn(synergy_table_sort) >= 3 then
	-- 	table.insert(hero.ai_synergy,synergy_table_sort[3].class)
	-- end

	local count = 0
	for _, v in pairs(synergy_table_sort) do
		if v.score > 1 and count < 3 then
			hero.ai_synergy[v.class] = v.score
			count = count + 1
		end
	end

	for _, v in pairs(chess_table_sort) do
		if v.score > 1 then
			hero.desire_chess[v.chess] = v.score
		end
	end

	-- Timers:CreateTimer(0.1,function()
	-- local ai_synergy_str = '策略：<br>'--'text_start_ai'
	-- for k,v in pairs(hero.ai_synergy) do
	-- 	ai_synergy_str = ai_synergy_str..'| |DOTA_Tooltip_ability_'..k..'|('..v..')'
	-- end
	-- ai_synergy_str = ai_synergy_str..'<br>'
	-- for k,v in pairs(hero.desire_chess) do
	-- 	ai_synergy_str = ai_synergy_str..'| |'..k..'|('..v..')'
	-- end

	-- CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
	-- 	unit_index = pet:entindex(),
	-- 	text = ai_synergy_str,
	-- 	player_name = hero.player_name,
	-- })
	-- end)
end

--进化
function EvolveThink(u)
	if IsUnitExist(u) == true and IsUnitAbleToCast(u) == true and u:IsChanneling() == false then
		if u:HasAbility('evolve_immediate') then
			ExecuteOrderFromTable({
				UnitIndex = u:entindex(),
				OrderType = DOTA_UNIT_ORDER_CAST_NO_TARGET,
				AbilityIndex = u:FindAbilityByName('evolve_immediate'):entindex(),
				-- Queue = 1,
			})
			return 0.5
		elseif u:HasAbility('evolve') then
			u.channeling_evolve = true
			ExecuteOrderFromTable({
				UnitIndex = u:entindex(),
				OrderType = DOTA_UNIT_ORDER_CAST_NO_TARGET,
				AbilityIndex = u:FindAbilityByName('evolve'):entindex(),
			})
			return 3
		end
	end
end

function EvolveSuccess(keys)
