function DAC:OnUpdateUserSettings(keys)
	local player_id = keys.PlayerID
	local hero = _G.playerid2hero[player_id]

	if hero == nil then
		return
	end
	local steam_id = hero.steam_id

	if steam_id ~= nil and _G.user_setting[steam_id] ~= nil then
		_G.user_setting[steam_id][keys.key] = keys.value
		CustomNetTables:SetTableValue("setting_table", "show_settings", _G.user_setting)
	end

	if keys.key == 'is_auto_combine' then
		hero.is_auto_combine = keys.value
	end
	if keys.key == 'is_auto_ai' then
		hero.is_auto_ai = keys.value
		if hero.pet_entity then
			if keys.value == 0 then
				--关闭AI
				local result = CourierAI({
					caster = hero,
					on_off = 0,
				})
				CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "set_petgpt_status", {
					key = GetClientKey(hero:GetTeam()),
					on_off = result,
				})
				-- RemoveAbilityAndModifier(hero,'toggle_ai')
				CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "hide_petgpt", {
					key = GetClientKey(hero:GetTeam()),
				})
			else
				-- AddAbilityAndSetLevel(hero,'toggle_ai')
				CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "show_petgpt", {
					key = GetClientKey(hero:GetTeam()),
				})
			end
		end
	end
	if keys.key == 'is_click_select' then
		CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "toggle_is_click_select", {
			key = GetClientKey(hero:GetTeam()),
			is_click_select = keys.value,
			hehe = RandomInt(1, 100000),
		});
	end
end

function DAC:GGSimida(keys)
	local player_id = keys.PlayerID
	local hero = _G.playerid2hero[player_id]
	local check_key = _G.client_key[hero:GetTeam()]
	local key = keys.key
	if IsUnitExist(hero) == true and check_key == key then
		KillSelfTeam(hero:GetTeam())
	end
