function GetChessClassAndRaceTable(chess_name)
	local class_table = {}
	for c, list in pairs(_G.chess_list_by_synergy) do
		for _, ch in pairs(list) do
			if ch == chess_name then
				table.insert(class_table, c)
			end
		end
	end
	return class_table
end

--判断棋子是不是不在棋库中的特殊棋子，包括：
--（1）备用棋子库的棋子（黑核）
--（2）SSR棋子
--（3）非酒仙的熊猫人棋子
--（4）精灵守卫
--（5）本局没有随机到的传说棋子
--（6）骷髅棋子
function IsSpecialChess(chess_name)
	--（1）备用棋子库的棋子（黑核）
	for _, list in pairs(_G.chess_list_by_mana_black) do
		for _, chess in pairs(list) do
			if chess == chess_name then
				return true
			end
		end
	end
	--（2）SSR棋子
	for _, chess in pairs(_G.chess_list_ssr) do
		if chess == chess_name then
			return true
		end
	end
	--（3）非酒仙的熊猫人棋子
	if chess_name == 'chess_brew' then
		return false
	end
	for _, chess in pairs(_G.pandaman_list) do
		if chess == chess_name then
			return true
		end
	end
	--（4）精灵守卫
	if chess_name == 'chess_io' then
		return true
	end
	--（5）本局没有随机到的传说棋子
	if FindValueInTable(_G.chess_list_by_mana_gold, chess_name) == true and FindValueInTable(_G.chess_list_by_mana[5], chess_name) == false then
		return true
	end
	return false
end

--不洗回的3种：io、ssr、亡灵、熊猫
function IsChessCanRefill(chess_name)
	--io和ssr，不洗回
	if string.find(chess_name, 'ssr') or string.find(chess_name, 'chess_io') then
		return false
	end
	local base_name = GetChessBaseName(chess_name)

	--垄断的，不洗回
	local destroy_info = CustomNetTables:GetTableValue("chess_pool_table", "destroy_info") or {}
	if FindValueInTable(destroy_info, base_name) == true then
		return false
	end
	--亡灵不洗回
	if (FindValueInTable(_G.chess_list_by_synergy['is_undead'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_undead'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_undead'],GetChessBaseName(chess_name)) == true) then
		return false
	end
	--熊猫不洗回
	if chess_name ~= 'chess_brew' and ( (FindValueInTable(_G.chess_list_by_synergy['is_pandaman'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_pandaman'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_pandaman'],GetChessBaseName(chess_name)) == true) ) then
		return false
	end

	-- local is_druid = false
	-- if (FindValueInTable(_G.chess_list_by_synergy['is_druid'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_black_and_pandaman['is_druid'],GetChessBaseName(chess_name)) == true or FindValueInTable(_G.chess_list_by_synergy_ban_unavailable['is_druid'],GetChessBaseName(chess_name)) == true) then
	-- 	is_druid = true
	-- end
	-- if GetChessNameStar(chess_name) >= 2 and is_druid then
	-- 	--2星以上德鲁伊，不洗回棋库
	-- 	return false
	-- end
	return true
end

function UpdatePlayerCurrRank()
	local arr = {}
	for steam_id, info in pairs(_G.stat_info) do
		table.insert(arr, info)
	end

	table.sort(arr, function(a, b)
		local aa = 0
		local bb = 0
		aa = aa + (a.hp or 0) * 1000000
		bb = bb + (b.hp or 0) * 1000000

		aa = aa + (10 - a.rank or 0) * 1000
		bb = bb + (10 - b.rank or 0) * 1000

		aa = aa + a.player_id
		bb = bb + b.player_id

		return aa > bb
	end)

	for curr_rank, info in pairs(arr) do
		local steam_id = info.steam_id
		_G.stat_info[steam_id]['curr_rank'] = curr_rank
	end
end

