function GetLevel(u)
	if u == nil or u:IsNull() then return 0 end
	local level = u:GetLevel()
	if u:HasModifier('modifier_illusion') == true then
		return 1
	end
	if u:GetClassname() ~= 'npc_dota_creature' then
		return level
	end

	if u:HasModifier('modifier_more_creep') == true then
		level = level + 1
	end

	if u:HasModifier('modifier_item_shirenmozhimao') == true then
		level = level + 2
	else
		if u:HasModifier('modifier_item_wuzhixiaomao') == true then
			level = level + 1
		end
	end

	if level > 9 then level = 9 end
	return level
end

