function ChessHpRegen(keys)
	local caster = keys.target or keys.caster
	local hp = keys.hp or 0
	if IsUnitExist(caster) == false or caster:IsHero() == true or hp <= 0 then
		return
	end
	caster:Heal(hp, caster)
end

function FindRelaventItems(itemname, checked_item_table)
	if checked_item_table == nil then
		checked_item_table = {}
	end
	local temp_item_table = {}
	--找到直接父子节点
	for i, v in pairs(_G.item_recipe) do
		if string.find(v, itemname) ~= nil and FindValueInTable(checked_item_table, i) == false then
			table.insert(temp_item_table, i)
		end
		if i == itemname then
			local push_table = string.split(v, ';')
			for ii, vv in pairs(push_table) do
				if FindValueInTable(checked_item_table, vv) == false then
					table.insert(temp_item_table, vv)
				end
			end
		end
	end
	--找到所有相关的叶子和中间节点（不含去重和检测是否可掉落）
	local component_item_table = {}
	local try_count = 0
	local undropable_count = 0
	while try_count == 0 or (undropable_count > 0 and try_count < 100) do
		try_count = try_count + 1
		undropable_count = 0
		component_item_table = {}
		for ui, uv in pairs(temp_item_table) do
			if _G.item_recipe[uv] then
				local one_com = string.split(_G.item_recipe[uv], ';')
				for oi, ov in pairs(one_com) do
					table.insert(component_item_table, ov)
				end
				local dpable = false
				for di, dv in pairs(_G.DROP_ITEM_LIST) do
					for ki, kv in pairs(dv) do
						if uv == kv then
							dpable = true
							table.insert(component_item_table, uv)
						end
					end
				end
				if dpable == false then
					undropable_count = undropable_count + 1
				end
			else
				table.insert(component_item_table, uv)
			end
		end
		temp_item_table = CopyTable(component_item_table)
	end
	return component_item_table
end

function TeamRelaventItems(teamid)
	local h = TeamId2Hero(teamid)
	if not IsUnitExist(h) then
		return {}
	end
	local all_items = {}
	if h.item_got then
		for i, v in pairs(h.item_got) do
			table.insert(all_items, v)
		end
	end
	-- for i,v in pairs(_G.mychess[teamid]) do
	-- 	local s_item = v.item or v.lastitem or {}
	-- 	if s_item and table.maxn(s_item) > 0 then
	-- 		for _,lv in pairs(s_item) do
	-- 			table.insert(all_items,lv)
	-- 		end
	-- 	end
	-- end
	-- for slot=0,9 do
	-- 	if h:GetItemInSlot(slot) ~= nil then
	-- 		local item = h:GetItemInSlot(slot)
	-- 		local name = item:GetAbilityName()
	-- 		table.insert(all_items,name)
	-- 	end
	-- end
	-- if h.hand_entities then
	-- 	for _,ent in pairs(h.hand_entities) do
	-- 		for slot=0,9 do
	-- 			if ent:GetItemInSlot(slot) ~= nil then
	-- 				local item = ent:GetItemInSlot(slot)
	-- 				local name = item:GetAbilityName()
	-- 				table.insert(all_items,name)
	-- 			end
	-- 		end
	-- 	end
	-- end

	local checked_item_table = {}
	local sorted_relavent_items = {}
	for pi, pv in pairs(all_items) do
		local single_r_items = FindRelaventItems(pv, checked_item_table)
		--筛选出可掉落的按等级排列并去重
		for si, sv in pairs(single_r_items) do
			for di, dv in pairs(_G.DROP_ITEM_LIST) do
				for ui, uv in pairs(dv) do
					if uv == sv then
						if FindValueInTable(checked_item_table, uv) == false then
							table.insert(checked_item_table, uv)
							if sorted_relavent_items[di] == nil then
								sorted_relavent_items[di] = {}
							end
							table.insert(sorted_relavent_items[di], uv)
						end
					end
				end
			end
		end
	end
	return sorted_relavent_items
end

function AddItemGot(hero, item)
	if IsUnitExist(hero) == false then
		return
	end
	if hero.item_got == nil then
		hero.item_got = {}
	end
	table.insert(hero.item_got, item)
end

-- FindNUnluckyDog({
-- 	caster = 施法者,
-- 	dog_count = 找多少个倒霉蛋（默认1）,
-- 	relation = ally/enemy/all 敌人/友军/全部,
-- 	radius = 寻找范围（默认不限范围）,
-- 	ignore_nomana = 不找没蓝的,
--  ignore_modifier = { ... } 要排除的modifier,
--	ignore_invisible = 不找隐身的,
-- })
function FindNUnluckyDog(keys)
	local dog_count = keys.dog_count or 1
	local caster = keys.caster
	if IsUnitExist(caster) == false then
		return {}
	end
	local chessboard_id = caster.at_team_id or caster.team_id
	local relation = keys.relation or 'enemy'
	local unluckydog_table = {}
	local no_dump_k = {}
	local try_count = 0
	local all_unit = GetValidChessOnBoard(chessboard_id)
	if all_unit ~= nil and table.maxn(all_unit) > 0 then
		while table.maxn(unluckydog_table) < dog_count and try_count < 100 do
			local unit = all_unit[RandomInt(1, table.maxn(all_unit))]
			if IsUnitExist(unit) == true and no_dump_k[unit:entindex()] == nil then
				--用排除法按条件逐一筛选
				local is_unlucky = true
				if unit:entindex() == caster:entindex() then
					is_unlucky = false
				end
				if relation == 'enemy' and unit:GetTeam() == caster:GetTeam() then
					is_unlucky = false
				end
				if relation == 'ally' and unit:GetTeam() ~= caster:GetTeam() then
					is_unlucky = false
				end
				if keys.radius then
					if (unit:GetAbsOrigin() - caster:GetAbsOrigin()):Length2D() > keys.radius then
						is_unlucky = false
					end
				end
				if keys.ignore_nomana and unit:GetMaxMana() <= 0 then
					is_unlucky = false
				end
				if keys.ignore_fullmana and unit:GetMana() >= unit:GetMaxMana() then
					is_unlucky = false
				end
				if keys.ignore_modifier and table.maxn(keys.ignore_modifier) > 0 then
					for _, m in pairs(keys.ignore_modifier) do
						if unit:HasModifier(m) then
							is_unlucky = false
						end
					end
				end
				if keys.ignore_invisible and unit:IsInvisible() == true then
					is_unlucky = false
				end
				if not keys.ignore_magic_immune and unit:IsMagicImmune() == true then
					is_unlucky = false
				end
				if is_unlucky == true then
					--入选！
					table.insert(unluckydog_table, unit)
					no_dump_k[unit:entindex()] = true
				end
			end
			try_count = try_count + 1
		end
	end
	return unluckydog_table
end

function ClearTeamGround(team)
	local all = Entities:FindAllInSphere(CenterVector(team), 1024 + 128)
	for _, i in pairs(all) do
		if i ~= nil then
			if i:GetClassname() == 'dota_item_drop' and i.money == nil then
				i:Destroy()
			end
		end
	end
end

function RainOfDestiny(keys)
	local caster = keys.caster
	local ability = keys.ability
	local level = ability:GetLevel()
	local point = caster.target_position --(keys.target_points or {})[1]
	local radius = GetAbilityKV(ability, "radius") or 300
	local duration = GetAbilityKV(ability, "duration") or 5
	local hps = GetAbilityKV(ability, "hps") or 75
	local tick_rate = GetAbilityKV(ability, "tick_rate") or 0.5

	--播放特效和音效
	local p_addr = 'effect/oracle/rain/units/heroes/hero_oracle/oracle_scepter_rain_of_destiny.vpcf'

	local particle = ParticleManager:CreateParticle(p_addr, PATTACH_ABSORIGIN, caster)
	ParticleManager:SetParticleControl(particle, 0, point)
	ParticleManager:SetParticleControl(particle, 1, Vector(radius, radius, radius))
	Timers:CreateTimer(duration, function()
		if particle ~= nil then
			ParticleManager:DestroyParticle(particle, true)
			ParticleManager:ReleaseParticleIndex(particle)
		end
	end)
	EmitSoundOn("Hero_Oracle.FalsePromise.Cast", caster)

	local count_down = duration or 5
	local heal = hps * tick_rate

	Timers:CreateTimer(tick_rate, function()
		if IsUnitExist(caster) == false then
			return
		end
		--治疗
		local unlucky_dogs = FindUnitsInRadiusByTeam({
			team = caster:GetTeam(),
			chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam(),
			role = 1,
			position = point,
			radius = radius,
		})
		for _, d in pairs(unlucky_dogs) do
			if d:HasModifier("modifier_oracle_rain_of_destiny_debuff") == false then
				d:Heal(heal, d)
				ability:ApplyDataDrivenModifier(caster, d, "modifier_oracle_rain_of_destiny_debuff", { duration = 0.9 })
			end
		end

		count_down = count_down - tick_rate
		if count_down <= 0 then
			return
		end

		return tick_rate
	end)
end

--萨特：恐惧
function AddSatyrAura(keys)
	if GetTime().phase ~= GAME_PHASE_BATTLE then
		return
	end
	local caster = keys.caster
	local ability = keys.ability
	local duration = keys.duration
	local radius = keys.radius
	if ability == nil or ability:IsCooldownReady() == false then
		return
	end
	local units = FindUnitsInRadiusOnTeamGround({
		team = caster:GetTeam(),
		at_team = caster.at_team_id or caster.team_id,
		role = 2,
		position = caster:GetAbsOrigin(),
		radius = radius,
	})
	if table.maxn(units) >= 2 then
		--触发恐惧！
		ability:StartCooldown(RandomInt(4, 8))
		for _, luckydog in pairs(units) do
			if luckydog:IsMagicImmune() == false then
				ability:ApplyDataDrivenModifier(caster, luckydog, 'modifier_is_satyr_debuff', { duration = duration })
			end
		end
		play_particle(
		"particles/econ/items/dark_willow/dark_willow_immortal_2021/dw_2021_willow_wisp_spell_impact_rays_dark.vpcf",
			PATTACH_ABSORIGIN_FOLLOW, caster, 3)
		EmitSoundOn('Hero_DarkWillow.Fear.Target', caster)
	end
end

function AddUntouchableAura(keys)
	local caster = keys.caster
	local ability = keys.ability
	local units = FindUnitsInRadiusOnTeamGround({
		team = caster:GetTeam(),
		at_team = caster.at_team_id or caster.team_id,
		role = 1,
		position = caster:GetAbsOrigin(),
		radius = 200,
	})
	for _, luckydog in pairs(units) do
		ability:ApplyDataDrivenModifier(caster, luckydog, 'modifier_untouchable_aura_buff', { duration = 2 })
	end
end

function ShowTITPEffectAtPosition(p, index)
	local e = 'effect/ti11/' .. index .. '/team15_lvl0.vpcf'
	if e ~= nil then
		p = p + Vector(0, 0, 400)
		local pp = ParticleManager:CreateParticle(e, PATTACH_WORLDORIGIN, nil)
		ParticleManager:SetParticleControl(pp, 0, p)
		ParticleManager:SetParticleControl(pp, 1, p)
		Timers:CreateTimer(5, function()
			if pp ~= nil then
				ParticleManager:DestroyParticle(pp, true)
				ParticleManager:ReleaseParticleIndex(pp)
			end
		end)
	else
		return nil
	end
end

function CTDoubleEdge(keys)
	local caster = keys.caster
	if IsUnitExist(caster) == false then
		return
	end

	if caster.damage_owner ~= nil then
		caster = caster.damage_owner
	end
	local target = keys.target
	local ability = keys.ability
	local level = ability:GetLevel()
	local r = ability:GetSpecialValueFor('radius')
	local damage_base = ability:GetSpecialValueFor('damage_base') or 0
	local damage = ability:GetSpecialValueFor('damage_per') / 100 * caster:GetMaxHealth() + damage_base
	ApplyDamage({
		victim = caster,
		attacker = caster,
		damage = damage,
		damage_type = DAMAGE_TYPE_MAGICAL,
		ability = ability,
	})
	EmitSoundOn("chess_ct.double_edge", caster)

	local partical = 'particles/units/heroes/hero_centaur/centaur_double_edge.vpcf'
	if level >= 3 then
		partical = 'effect/double_edge/body_ti9.vpcf'
	end
	ApplyDamageInRadius({
		caster = caster,
		team = caster.team_id,
		radius = r,
		role = 2,
		position = target:GetAbsOrigin(),
		damage = damage,
		damage_type = DAMAGE_TYPE_MAGICAL,
		ability = ability:GetAbilityName(),
		split = false,
		ignore_magic_immune = false,
		stun_partical = partical,
	})
end

function CentaurBuffStun(keys)
	local caster = keys.caster
	local unlucky_dogs = FindUnitsInRadiusByTeam({
		team = caster:GetTeam(),
		chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam(),
		role = 2,
		position = caster:GetAbsOrigin(),
		radius = 205,
	})
	if unlucky_dogs and table.maxn(unlucky_dogs) then
		for _, u in pairs(unlucky_dogs) do
			if u ~= nil and u:IsNull() == false and u:IsAlive() == true then
				if not u:IsMagicImmune() then
					u:AddNewModifier(u, nil, "modifier_stunned", { duration = 1 })
				end
			end
		end
	end
end

function DRSilence(keys)
	local caster = keys.caster
	local point = caster.target_position--(keys.target_points or {})[1]
	local ability = keys.ability
	local wave_speed = ability:GetSpecialValueFor("wave_speed") or 2000
	local wave_width = ability:GetSpecialValueFor("wave_width") or 250
	local wave_distance = ability:GetSpecialValueFor("distance") or 500

	local vector = point - caster:GetOrigin()

	local projectile_direction = vector
	projectile_direction.z = 0
	projectile_direction = projectile_direction:Normalized()

	local info = {
		Ability = ability,
		EffectName = "particles/units/heroes/hero_drow/drow_silence_wave.vpcf",
		vSpawnOrigin = caster:GetAbsOrigin(),
		fDistance = wave_distance,
		fStartRadius = wave_width,
		fEndRadius = wave_width,
		Source = caster,
		bHasFrontalCone = false,
		bReplaceExisting = false,
		iUnitTargetTeam = DOTA_UNIT_TARGET_TEAM_ENEMY,
		iUnitTargetFlags = DOTA_UNIT_TARGET_NONE,
		iUnitTargetType = DOTA_UNIT_TARGET_HERO + DOTA_UNIT_TARGET_BASIC,
		bDeleteOnHit = false,
		vVelocity = projectile_direction * wave_speed,
		bProvidesVision = false,
		iVisionRadius = 0,
		iVisionTeamNumber = caster:GetTeamNumber(),
	}
	ProjectileManager:CreateLinearProjectile(info)
	EmitSoundOn("Hero_DrowRanger.Silence", caster)
end

--新（9）亡灵  9亡灵
function UndeadDeathRattle(u, attacker)
	if IsUnitExist(attacker) == false then
		return
	end
	local undead_creep_name = 'chess_clinkz'
	if u:Script_GetAttackRange() < 250 then
		undead_creep_name = 'chess_snk'
	end
	-- local items = GetAllItemsAndCDInUnits({[1] = u})
	play_particle("particles/units/heroes/hero_skeletonking/wraith_king_death.vpcf", PATTACH_ABSORIGIN_FOLLOW, u, 3)

	local force_team = 4
	if u:GetTeam() == 4 then
		force_team = u.at_team_id
	end

	Timers:CreateTimer(0.01, function()
		local llevel = GetChessNameStar(u:GetUnitName()) or 1
		-- 阵亡棋子星级
		-- llevel = llevel - 1
		if llevel < 1 then
			llevel = 1
		end
		if llevel == 2 then
			undead_creep_name = undead_creep_name .. '1'
		elseif llevel == 3 then
			undead_creep_name = undead_creep_name .. '11'
		end
		SummonMinion(attacker, undead_creep_name, 1, nil, function(w)
			-- if items ~= nil then
			-- 	GiveItems2Unit(items,w)
			-- end
			w.is_summoned = true
			FillEmptySlot(w)
			AddChessAbility(w, llevel)
			AddAbilityAndSetLevel(w, 'jiaoxie_wudi')
			AddModifierKill(w, 9)

			ExtendBianBuff(w, attacker)
			w.ghost_particle = PlayParticleOnUnitUntilDeath({
				caster = w,
				p = "particles/units/heroes/hero_skeletonking/wraith_king_ghosts_ambient.vpcf",
			})
		end, u:GetAbsOrigin(), false, force_team)
	end)
end

function DAC:OnTesterBoxGiveItem(keys)
	if _G.playing_player_count ~= 1 or _G.is_tester_mode ~= true then
		return
	end
	local hero = PlayerId2Hero(keys.PlayerID)
	if IsUnitExist(hero) then
		local i = keys.item
		local money = RandomInt(1, 10)
		local newItem = CreateItem(i, hero, hero)

		local drop = CreateItemOnPositionForLaunch(hero:GetAbsOrigin(), newItem)

		if i == 'item_money' then
			newItem:GetContainer():SetModelScale(1.4 + (money or 1) / 15)
			newItem.money = money or 1
			drop.money = money or 1
		end
		local dropRadius = RandomFloat(50, 200)
		newItem:SimulateLaunchLoot(hero:GetAbsOrigin() + RandomVector(dropRadius))
		combat('TESTER: +ITEM ' .. keys.item)
		-- newItem:SimulateLaunchLoot(false,200,0.75,hero:GetAbsOrigin() + Vector(RandomFloat( -100, 100 ),RandomFloat( -100, 100 ),0))
	end
end

function KuangfengHit(keys)
	local caster = keys.caster
	local target = keys.target
	local blocks = keys.blocks or 2
	local silence_duration = keys.silence_duration or 3
	local damage = keys.damage or 100
	local ability = keys.ability

	if IsUnitExist(target) == true and target:IsMagicImmune() == false then
		KnockBack({
			caster = caster,
			target = target,
			blocks = blocks,
		})
		ability:ApplyDataDrivenModifier(caster, target, 'modifier_silence_debuff', { duration = silence_duration })
		ApplyDamage({
			victim = target,
			attacker = caster,
			damage = damage,
			damage_type = DAMAGE_TYPE_MAGICAL,
			ability = ability,
		})
	end
end

function StartTouchMode(team_id)
	CustomGameEventManager:Send_ServerToTeam(team_id, "start_touch_mode", {
		key = GetClientKey(team_id),
		hehe = RandomInt(1, 100000),
	})
end

function GetLuckyValue(u)
	if IsUnitExist(u) == false then
		return 1.0
	end
	local lv = 1.0
	
	if u:HasModifier('modifier_item_xingyunguazhui') then
		lv = lv + 0.3
	end
	if u:HasModifier('modifier_oracle_rain_of_destiny_debuff') then
		local m = u:FindModifierByName('modifier_oracle_rain_of_destiny_debuff')
		if m ~= nil then
			local l = m:GetAbility():GetLevel() or 1
			local lucky_bonus = GetAbilityKV(m:GetAbility(), "lucky_bonus") or 0
			lv = lv + (lucky_bonus/100.0)
		end
	end
	return lv
end

function ApplyModifierByChance(keys)
	local ability = keys.ability
	local caster = keys.caster
	local modifier = keys.modifier
	local chance = tonumber(keys.chance) or 0
	local duration = keys.duration

	chance = chance * GetLuckyValue(caster) + GetHoodwinkAcornValue(caster)

	-- prt(modifier..' --> '..chance..'%')
	if RandomInt(1, 100) <= chance then
		if duration then
			ability:ApplyDataDrivenModifier(caster, caster, modifier, { duration = tonumber(duration) })
		else
			ability:ApplyDataDrivenModifier(caster, caster, modifier, {})
		end
	end
end

function GetHoodwinkAcornValue(caster)
	local target = caster:GetAttackTarget()
	if IsUnitExist(target) == false then
		return 0
	elseif target:HasModifier('modifier_hoodwink_acorn_shot_datadriven_debuff') == true then
		return 100
	else
		return 0
	end
end

function GetDistance(u, v)
	if IsUnitExist(u) == false or IsUnitExist(v) == false then
		return -1
	end
	return (u:GetAbsOrigin() - v:GetAbsOrigin()):Length2D()
end

function AbilitySpecialOrAbilityValues2AbilityKV(ability_value, ability_special)
	local result = {}
	if ability_value ~= nil then
		for k, v in pairs(ability_value) do
			if type(v) == 'table' or type(v) == 'settable' and v['value'] ~= nil then
				v = v['value']
			end
			if type(v) == 'string' then
				result[k] = v
			end
			if type(v) == 'number' then
				if GetPreciseDecimal(v, 1) == v then
					result[k] = v
				else
					result[k] = GetPreciseDecimal(v, 1) .. ''
				end
			end
		end
	end
	if ability_special ~= nil then
		for i, kv in pairs(ability_special) do
			for k, v in pairs(kv) do
				if k ~= 'var_type' and k ~= 'LinkedSpecialBonus' then
					if type(v) == 'string' then
						result[k] = v
					end
					if type(v) == 'number' then
						if GetPreciseDecimal(v, 1) == v then
							result[k] = v
						else
							result[k] = GetPreciseDecimal(v, 1) .. ''
						end
					end
				end
			end
		end
	end
	return result
end

function GetChessAbility(u)
	local a = nil
	if string.find(u:GetUnitName(), 'chess_rubick') and u.steal_ability ~= nil then
		--拉比克 偷的技能
		a = u.steal_ability
	elseif string.find(u:GetUnitName(), 'chess_kael') and (u.kael_ability ~= nil or u.kael_ability_last ~= nil) then
		--卡尔 切的技能
		a = u.kael_ability or u.kael_ability_last
	else
		--普通技能
		a = _G.chess_ability_list[u:GetUnitName()] or _G.summon_ability_list[u:GetUnitName()]
	end
	--双头龙切换技能
	if u.ice_or_fire == 'fire' then
		a = 'jakiro_macropyre'
	end
	if u.ice_or_fire == 'ice' then
		a = 'jakiro_ice_path'
	end

	local a_level = 1
	if string.find(u:GetUnitName(), '1') then
		a_level = 2
	end
	if string.find(u:GetUnitName(), '11') then
		a_level = 3
	end

	--a杖，加1级
	if u:HasModifier('modifier_item_ahalimushenzhang') then
		a_level = a_level + 1
	end
	if a_level > 3 then
		a_level = 3
	end

	return a, a_level
end

function ResetChessAbilityLevel(keys)
	local u = keys.caster
	if IsUnitExist(u) == false then
		return
	end

	local a, a_level = GetChessAbility(u)
	if a == nil or u:HasAbility(a) == false then
		return
	end
	u:FindAbilityByName(a):SetLevel(a_level)

	if u:HasModifier('modifier_item_ahalimumojing') == true then
		AddMojingAbility({
			caster = u,
		})
	end
end

function SixGodReduceCooldown(u)
	Timers:CreateTimer(0.5, function()
		local reduced = false

		local ability_name = GetChessAbility(u)
		local ability = u:FindAbilityByName(ability_name)
		if ability and ability:GetCooldownTimeRemaining() > 0 then
			local cd = ability:GetCooldownTimeRemaining()
			local cd_new = cd * 0.4
			reduced = true
			if cd_new < 0 then
				cd_new = 0
			end
			if cd_new <= 0 then
				ability:EndCooldown()
			else
				ability:EndCooldown()
				ability:StartCooldown(cd_new)
			end
		end

		for slot = 0, 5 do
			if u:GetItemInSlot(slot) ~= nil then
				local ability = u:GetItemInSlot(slot)
				local name = ability:GetAbilityName()
				reduced = true

				if ability and ability:GetCooldownTimeRemaining() > 0 then
					local cd = ability:GetCooldownTimeRemaining()
					local cd_new = cd * 0.4
					if cd_new < 0 then
						cd_new = 0
					end
					if cd_new <= 0 then
						ability:EndCooldown()
					else
						ability:EndCooldown()
						ability:StartCooldown(cd_new)
					end
				end
			end
		end

		if reduced == true then
			-- 播放个特效
			play_particle(
			"particles/units/heroes/hero_obsidian_destroyer/obsidian_destroyer_sanity_eclipse_mana_loss.vpcf",
				PATTACH_ABSORIGIN_FOLLOW, u, 3)
		end
	end)
end

function GetCooldownPerByGod(u)
	if IsUnitExist(u) == false then
		return 1.0
	end
	if u:HasAbility('is_god_buff_plus') then
		return 0.6*0.6
	elseif u:HasAbility('is_god_buff') then
		return 0.6
	else
		return 1.0
	end
end

function PetMove(pet, p, speed, cb)
	if pet == nil then
		return
	end
	if pet.idle ~= true then
		Timers:CreateTimer(0.2, function()
			PetMove(pet, p, speed, cb)
		end)
		return
	end
	pet.rest = nil
	-- play_particle("particles/items_fx/courier_speed.vpcf",PATTACH_ABSORIGIN_FOLLOW,pet,3)

	pet:MoveToPosition(p)

	pet.idle = false

	Timers:CreateTimer(0.2, function()
		if (pet:GetAbsOrigin() - p):Length2D() < 50 then
			pet:Stop()
			pet.idle = true

			if cb then
				cb()
			end
			return
		end
		return 0.2
	end)
end

function IsPreferChess(hero, chess)
	-- if hero.level_one_chess ~= nil and string.find(hero.level_one_chess,chess) then
	-- 	return true
	-- end

	if hero.desire_chess and type(hero.desire_chess) == 'table' then
		for k, score in pairs(hero.desire_chess) do
			if k == chess then
				return score
			end
		end
	end
	if hero.ai_synergy and type(hero.ai_synergy) == 'table' then
		for k, score in pairs(hero.ai_synergy) do
			if _G.chess_list_by_synergy[k] then
				for _, c in pairs(_G.chess_list_by_synergy[k]) do
					if c == chess then
						return score
					end
				end
			end
		end
	end

	return -1
end

function CourierAI(keys)
	local hero = keys.caster
	local on_off = keys.on_off or 1
	if IsUnitExist(hero) == false then
		return
	end

	local pet = hero.pet_entity

	if on_off == 0 and pet ~= nil and pet:IsNull() == false then
		--关闭AI
		hero.ai_synergy = {}
		hero.stop_ai = true
		hero.ai_pet = nil
		pet.rest = false
		if hero.ai_on == true then
			EmitSoundOn('high_five.fail', hero)
		end
		pet:RemoveModifierByName('modifier_pet_speed')
		CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
			unit_index = hero:entindex(),
			text = '#ai_say_end_ai',
		})
		hero.ai_on = false
		pet:Stop()
		AddModelScalePlus(pet, pet.ori_scale)

		return hero.ai_on
	end

	if pet == nil or pet:IsNull() == true then
		-- CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(),"mima",{
		-- 	key = GetClientKey(hero:GetTeam()),
		-- 	text = "text_mima_no_pet"
		-- })
		return
	end

	--开启AI
	EmitSoundOn('high_five.cast', hero)
	CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
		unit_index = hero:entindex(),
		text = '#ai_say_start_ai',
	})
	if pet:HasAbility('pet_wudi') then
		pet:FindAbilityByName('pet_wudi'):ApplyDataDrivenModifier(pet, pet, 'modifier_pet_speed', {})
	end

	pet:Stop()
	AddModelScalePlus(pet, pet.ori_scale * 1.5)

	hero.ai_on = true
	local pet_name = hero.pet_name
	hero.ai_synergy = nil
	hero.ai_pet = hero.pet_entity
	hero.stop_ai = false

	local pet = hero.pet_entity
	pet.idle = true
	if pet.aitimer == nil or Timers.timers[pet.aitimer] == nil then
		pet.aitimer = Timers:CreateTimer(1, function()
			--关闭AI、信使死亡或者游戏结束，就终止AI
			if hero == nil or hero:IsNull() == true or hero:IsAlive() == false or _G.is_game_ended == true or hero.stop_ai == true or hero.pet_entity == nil then
				return
			end
			if pet.idle ~= true then
				--信使在忙，不思考
				return 0.5
			end

			if hero.ai_synergy == nil then
				PetMakeSynergy(hero)
				return 0.5
			end
			local is_prepare_round = true
			if GetTime().phase ~= GAME_PHASE_PREPARE then
				is_prepare_round = false
				--非准备回合，只判断能不能购买棋子，如果没有想买的就清空策略、挂机
				-- local shopping_result,buy_index,best_chess,best_price,best_score = GoShopping(hero)
				-- if shopping_result == 2 and buy_index and buy_index > 0 then
				-- 	DAC:OnRequestBuyChess({
				-- 		buy_index = buy_index,
				-- 		PlayerID = hero:GetPlayerID(),
				-- 	})
				-- 	CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
				-- 		unit_index = pet:entindex(),
				-- 		text = 'ai_say_buy_chess|'..best_chess,--..'|('..best_score..')',
				-- 	})
				-- 	hero.ai_synergy = nil
				-- 	return 2
				-- elseif shopping_result == 1 then
				-- 	return 2
				-- else
				-- 	hero.ai_synergy = nil
				-- 	if pet.rest ~= true then
				-- 		local p = Entities:FindByName(nil,'center'..(hero:GetTeam()-6)):GetOrigin()+Vector(0,-340,512)
				-- 		PetMove(pet,p,500,function()
				-- 			Timers:CreateTimer(0.5,function()
				-- 				pet:MoveToPosition(pet:GetOrigin()+Vector(0,10,0))
				-- 			end)
				-- 		end)
				-- 		pet.rest = true
				-- 	end
				-- 	return 2
				-- end
			end

			--0.00：捡起地上的物品
			local entities_table = Entities:FindAllInSphere(CenterVector(hero:GetTeam()), 1100)
			for _, u in pairs(entities_table) do
				if u:GetClassname() == "dota_item_drop" then
					pet:PickupDroppedItem(u)
					return 1
				end
			end

			--把物品给信使
			local hero_has_empty_item_slot = false
			for slot = 0, 8 do
				if hero:GetItemInSlot(slot) == nil then
					hero_has_empty_item_slot = true
				end
			end
			if hero_has_empty_item_slot then
				for slot = 0, 8 do
					if pet:GetItemInSlot(slot) ~= nil then
						--给！
						local i = pet:GetItemInSlot(slot)

						PetGiveItem2Courier(pet, hero, pet:GetItemInSlot(slot))

						return 2
					end
				end
			end

			--0.01：开箱
			-- if OpenCourierBox(pet,hero) then
			-- 	return 2
			-- end

			--0.02：选择战利品
			-- if ChooseCourierLoot(pet,hero) then
			-- 	return 1
			-- end

			local population = _G.population[hero:GetTeam()]
			local population_max = _G.population_max[hero:GetTeam()]
			local empty_hand_slot_count = GetEmptyHandSlotCount(hero:GetTeam())
			--0.1：分析目前场上和手牌的情况
			local my_chess_count_table = {}
			local min_level_onboard = 999
			local druid_count = GetDruidCount(hero:GetTeam())
			local combine_count = 3
			local combine_name = nil
			local onboard_chess_count = 0
			local total_star = 0

			if hero.hand_entities ~= nil then
				for _, ent in pairs(hero.hand_entities) do
					if IsUnitExist(ent) then
						local chess_name = ent:GetUnitName()
						if my_chess_count_table[chess_name] == nil then
							my_chess_count_table[chess_name] = 0
						end
						my_chess_count_table[chess_name] = my_chess_count_table[chess_name] + 1

						local cc = 3
						if ent:HasAbility('is_druid') and GetChessStar(ent) == 1 and druid_count >= 2 then
							cc = 2
						end
						if ent:HasAbility('is_druid') and GetChessStar(ent) == 2 and druid_count >= 4 then
							cc = 2
						end
						if my_chess_count_table[chess_name] >= cc then
							combine_name = chess_name
						end
					end
				end
			end
			for _, v in pairs(GetValidChessOnBoard(hero:GetTeam())) do
				if IsUnitExist(v) == true and v:GetTeam() == hero:GetTeam() then
					local chess_name = v:GetUnitName()
					if my_chess_count_table[chess_name] == nil then
						my_chess_count_table[chess_name] = 0
					end
					my_chess_count_table[chess_name] = my_chess_count_table[chess_name] + 1
					local cc = 3
					if v:HasAbility('is_druid') and GetChessStar(v) == 1 and druid_count >= 2 then
						cc = 2
					end
					if v:HasAbility('is_druid') and GetChessStar(v) == 2 and druid_count >= 4 then
						cc = 2
					end
					if my_chess_count_table[chess_name] >= cc then
						combine_name = chess_name
					end
					local level = v:GetLevel()
					if level < min_level_onboard then
						min_level_onboard = level
					end
					onboard_chess_count = onboard_chess_count + 1
					total_star = total_star + GetChessStar(v)
				end
			end
			local ave_star = 1.0 * total_star / onboard_chess_count

			if is_prepare_round then
				--0.2：有至少3个的可以合成，把它上场！
				if combine_name then
					for _, ent in pairs(hero.hand_entities) do
						if IsUnitExist(ent) and ent:GetUnitName() == combine_name then
							PetMove(
								pet,
								ent:GetAbsOrigin() - (ent:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
								true,
								function()
									RecallChess({
										caster = pet,
										target = ent,
										ai = true,
									})
								end
							)
							local lv = GetChessCostByName(ent:GetUnitName()) or 0
							CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
								unit_index = pet:entindex(),
								text = 'ai_say_combine_chess|<font color="' ..
								(_G.common_kv['rarity_' .. lv]) .. '">|' .. ent:GetUnitName() .. '|</font>★',
							})
							return 1
						end
					end
				end
				--0.3：替补席如果有高等级的，优先上场！
				if hero.hand_entities then
					for _, ent in pairs(hero.hand_entities) do
						local level = ent:GetLevel()
						if ent:GetUnitName() == 'chess_io' then
							level = 1
						end
						if ent:GetUnitName() == 'chess_io1' then
							level = 3
						end
						if IsUnitExist(ent) and level > min_level_onboard then
							PetMove(
								pet,
								ent:GetAbsOrigin() - (ent:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
								true,
								function()
									RecallChess({
										caster = pet,
										target = ent,
										ai = true,
									})
								end
							)
							CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
								unit_index = pet:entindex(),
								text = '#ai_say_up_chess',
							})
							return 1
						end
					end
				end
				--0.4：如果场上人口超了，下一个最弟弟的
				if population > population_max then
					local lowest_level = 999
					local lowest_chess = nil
					for _, v in pairs(GetValidChessOnBoard(hero:GetTeam())) do
						if IsUnitExist(v) == true and v:GetTeam() == hero:GetTeam() then
							local level = v:GetLevel()

							if level < lowest_level then
								lowest_level = level
								lowest_chess = v
							end
						end
					end
					if lowest_chess then
						PetMove(
							pet,
							lowest_chess:GetAbsOrigin() -
							(lowest_chess:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
							true,
							function()
								RecallChess({
									caster = pet,
									target = lowest_chess,
									ai = true,
								})
							end
						)
						CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
							unit_index = pet:entindex(),
							text = '#ai_say_down_chess',
						})
						return 1
					end
				end

				--0.4：如果场上人口不满，尽量补满
				if population < population_max then
					if hero.hand_entities ~= nil and hero:FindAbilityByName('recall_chess') ~= nil and hero:FindAbilityByName('recall_chess'):IsActivated() == true then
						local best_chess = nil
						local best_score = 0

						for _, ent in pairs(hero.hand_entities) do
							local level = ent:GetLevel()
							if ent:GetUnitName() == 'chess_io' then
								level = 1
							end
							if ent:GetUnitName() == 'chess_io1' then
								level = 3
							end
							if IsUnitExist(ent) and level > best_score then
								best_chess = ent
								best_score = ent:GetLevel()
							end
						end
						if best_chess then
							PetMove(
								pet,
								best_chess:GetAbsOrigin() -
								(best_chess:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
								true,
								function()
									RecallChess({
										caster = pet,
										target = best_chess,
										ai = true,
									})
								end
							)
							CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
								unit_index = pet:entindex(),
								text = '#ai_say_up_chess',
							})
							return 1
						end
					end
				end

				--0.3：替补席满了，就删一个最没用的
				-- if empty_hand_slot_count == 0 then
				-- 	local worst_chess = nil
				-- 	local worst_score = 9999
				-- 	for _,ent in pairs(hero.hand_entities) do
				-- 		if IsUnitExist(ent) and ent:GetUnitName() ~= 'egg' then
				-- 			local score = ent:GetLevel() + IsPreferChess(hero,GetChessBaseName(ent:GetUnitName()))
				-- 			if score < worst_score then
				-- 				worst_chess = ent
				-- 				worst_score = score
				-- 			end
				-- 		end
				-- 	end
				-- 	if worst_chess then
				-- 		PetMove(
				-- 			pet,
				-- 			worst_chess:GetAbsOrigin()-(worst_chess:GetAbsOrigin()-pet:GetAbsOrigin()):Normalized()*50,
				-- 			true,
				-- 			function()
				-- 				RemoveChess({
				-- 					caster = hero,
				-- 					target = worst_chess,
				-- 					force_remove = true,
				-- 				})
				-- 			end
				-- 		)
				-- 		CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
				-- 			unit_index = pet:entindex(),
				-- 			text = '#ai_say_recycle_chess',
				-- 		})
				-- 		return 1
				-- 	end
				-- end

				--1：思考选择棋子的策略
				if hero.ai_synergy == nil then
					PetMakeSynergy(hero)
					return 0.5
				end
			end

			--2：考虑购买棋子
			local shopping_result, buy_index, best_chess, best_price, best_score = GoShopping(hero)
			if shopping_result == 2 and buy_index and buy_index > 0 then
				DAC:OnRequestBuyChess({
					buy_index = buy_index,
					PlayerID = hero:GetPlayerID(),
				})
				local lv = GetChessCostByName(best_chess) or 0
				-- CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
				-- 	unit_index = pet:entindex(),
				-- 	text = 'ai_say_buy_chess|<font color="'..(_G.common_kv['rarity_'..lv])..'">|'..best_chess..'|</font>',
				-- })
				hero.ai_synergy = nil
				return 1
			end

			if is_prepare_round then
				--3：考虑上棋子
				if population < population_max then
					if hero.hand_entities ~= nil and hero:FindAbilityByName('recall_chess') ~= nil and hero:FindAbilityByName('recall_chess'):IsActivated() == true then
						for _, ent in pairs(hero.hand_entities) do
							if IsUnitExist(ent) then
								PetMove(
									pet,
									ent:GetAbsOrigin() - (ent:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
									true,
									function()
										RecallChess({
											caster = pet,
											target = ent,
											ai = true,
										})
									end
								)
								CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
									unit_index = pet:entindex(),
									text = '#ai_say_up_chess',
								})
								return 1
							end
						end
					end
				end

				--4：考虑F还是D
				--4.1：根据当前血量决定留多少钱吃利息，最多40
				local lixi_money = 40
				if hero:GetLevel() < 5 then
					lixi_money = 0
				-- else
				-- 	if hero:GetHealth() <= 20 then
				-- 		lixi_money = 0
				-- 	elseif hero:GetHealth() <= 30 then
				-- 		lixi_money = 10
				-- 	elseif hero:GetHealth() <= 40 then
				-- 		lixi_money = 20
				-- 	elseif hero:GetHealth() <= 50 then
				-- 		lixi_money = 30
				-- 	end
				end
				--4.2：根据信使偏好决定是d还是f
				local df = pet.pet_kv.df
				-- if ave_star >= 1.5 then
				-- 	df = df + ((100 - df) / 2.0)
				-- end
				local d = false
				-- if RandomInt(1, 100) < df then
				-- 	d = false
				-- end
				-- if hero:GetLevel() >= 10 then
				-- 	d = true
				-- end
				-- if hero:GetLevel() < 5 then
				-- 	d = false
				-- end

				if hero:GetMana() >= (lixi_money + 4) then
					--有闲钱，来d或者f吧！
					if d then
						-- D
						ExecuteOrderFromTable({
							UnitIndex = hero:entindex(),
							OrderType = DOTA_UNIT_ORDER_CAST_NO_TARGET,
							AbilityIndex = hero:FindAbilityByName('summon_hero'):entindex(),
							Queue = 0,
						})
						CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
							unit_index = pet:entindex(),
							text = '#ai_say_d',
						})
						return 1
					else
						-- F
						ExecuteOrderFromTable({
							UnitIndex = hero:entindex(),
							OrderType = DOTA_UNIT_ORDER_CAST_NO_TARGET,
							AbilityIndex = hero:FindAbilityByName('exp_book'):entindex(),
							Queue = 0,
						})
						CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
							unit_index = pet:entindex(),
							text = '#ai_say_f',
						})
						return 0.5
					end
				end

				--5：调整站位
				if hero:FindAbilityByName("pick_chess") ~= nil and hero:FindAbilityByName("pick_chess"):IsActivated() == true then
					--考虑远程的放后排
					local ranged_chess = FindRangedChessAtRow34(hero:GetTeam())
					if IsUnitExist(ranged_chess) then
						local row = 1
						if GetChessStar(ranged_chess) >= 2 or ranged_chess:Script_GetAttackRange() < 405 then
							row = 2
						end
						local target_pos = FindEmptyPosAtRow(hero:GetTeam(), 1, row)
						if target_pos ~= nil then
							hero.picked_chess = ranged_chess
							PetMove(
								pet,
								ranged_chess:GetAbsOrigin() -
								(ranged_chess:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
								true,
								function()
									DAC:OnPickChessPosition({
										caster = pet,
										x = target_pos.x,
										y = target_pos.y,
										z = target_pos.z,
										player_id = hero:GetOwner():GetPlayerID(),
										PlayerID = hero:GetOwner():GetPlayerID(),
										ai = true,
									})
								end
							)
							CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
								unit_index = pet:entindex(),
								text = '#ai_say_adjust_position',
							})
							return 1
						end
					end

					--考虑近战的放前排
					local melee_chess = FindMeleeChessAtRow12(hero:GetTeam())

					if IsUnitExist(melee_chess) and melee_chess:HasAbility('is_assassin') == false then
						local row = 3
						if GetChessStar(melee_chess) >= 2 and melee_chess:Script_GetAttackRange() < 205 then
							row = 4
						end
						local target_pos = FindEmptyPosAtRow(hero:GetTeam(), 3, row)
						if target_pos ~= nil then
							hero.picked_chess = melee_chess
							PetMove(
								pet,
								melee_chess:GetAbsOrigin() -
								(melee_chess:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
								true,
								function()
									DAC:OnPickChessPosition({
										caster = pet,
										x = target_pos.x,
										y = target_pos.y,
										z = target_pos.z,
										player_id = hero:GetOwner():GetPlayerID(),
										PlayerID = hero:GetOwner():GetPlayerID(),
										ai = true,
									})
								end
							)
							CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
								unit_index = pet:entindex(),
								text = '#ai_say_adjust_position',
							})
							return 1
						end
					end
				end
			end

			--其他高级思想以后慢慢添加

			--6：什么也不做，走到场边休息
			local p = Entities:FindByName(nil, 'center' .. (hero:GetTeam() - 6)):GetOrigin() + Vector(0, -340, 512)
			if pet.idle == true then
				if not pet.rest then
					PetMove(pet, p, 500, function()
						Timers:CreateTimer(0.5, function()
							pet:MoveToPosition(pet:GetOrigin() + Vector(0, 10, 0))
						end)
					end)
					pet.rest = true
					-- CustomGameEventManager:Send_ServerToAllClients("drodo_bubble",{
					-- 	unit_index = pet:entindex(),
					-- 	text = '休息~',
					-- })
					if GetAlivePlayerCount() == 1 and _G.playing_player_count == 1 and is_prepare_round then
						DAC:OnTesterBoxStartBattle({ PlayerID = hero:GetPlayerID() })
						CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
							unit_index = pet:entindex(),
							text = '#ai_say_start_battle',
						})
					end
					CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "close_draw_card", {
						key = GetClientKey(hero:GetTeam()),
						hehe = RandomInt(1, 100000),
					})
					return 3
				end
			end
			-- hero.pet_entity:MoveToPosition(p)

			return 1
		end)
	end

	return hero.ai_on
end

--在招募面板购物的AI逻辑。返回购买意向
--status：0=买不了，1=想买但没钱，2=可以买
function GoShopping(hero)
	local population = _G.population[hero:GetTeam()]
	local population_max = _G.population_max[hero:GetTeam()]
	local empty_hand_slot_count = GetEmptyHandSlotCount(hero:GetTeam())

	if hero.curr_chess_table ~= nil and table.maxn(hero.curr_chess_table) > 0 and FindEmptyHandSlot(hero:GetTeam()) then
		local best_buy_index
		local best_score = -2
		local best_chess
		local best_price
		local buy_index
		for i, c in pairs(hero.curr_chess_table) do
			local score = IsPreferChess(hero, c.chess)
			--看看商店同屏还有几个，可增加score
			for ii, cc in pairs(hero.curr_chess_table) do
				if ii ~= i and cc.chess == c.chess then
					score = score + 9
				end
			end

			if c.price > hero:GetMana() then
				score = score / 2.0
			end
			if score >= best_score then
				--更新best
				best_buy_index = i
				best_score = score
				best_chess = c.chess
				best_price = c.price
			end
		end

		local min_buy_line = 9
		if empty_hand_slot_count >= 4 then
			--有4个以上空位，买相关的
			min_buy_line = 1
		else
			--有4个以下空位，只买相同的
			min_buy_line = 9
		end
		if GetTime().phase ~= GAME_PHASE_PREPARE then
			--非准备回合，只买相同的
			min_buy_line = 9
		end
		if population < population_max then
			--场上人口不满，有啥都买
			min_buy_line = -1
		end

		-- prt('GoShopping:'..best_chess..'('..best_score..'/'..min_buy_line..')')

		if best_score >= min_buy_line then
			buy_index = best_buy_index
		end

		if buy_index then
			if best_price <= hero:GetMana() then
				return 2, buy_index, best_chess, best_price, best_score
			else
				return 1, buy_index, best_chess, best_price, best_score
			end
		else
			return 0
		end
	else
		return 0
	end
end

--宠物开信使身上的宝箱
function OpenCourierBox(pet, hero)
	if hero.loot_table ~= nil then
		return false
	end
	local box_list = {
		'item_relicbox',
		'item_lootbox_lv1',
		'item_lootbox_lv2',
		'item_lootbox_lv3',
		'item_lootbox_lv4',
		'item_lootbox_lv5',
	}
	for slot = 0, 5 do
		if hero:GetItemInSlot(slot) ~= nil then
			local i = hero:GetItemInSlot(slot)
			local name = i:GetAbilityName()

			if FindValueInTable(box_list, name) == true then
				PetMove(
					pet,
					hero:GetAbsOrigin() - (hero:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
					true,
					function()
						local newOrder = {
							UnitIndex = hero:entindex(),
							OrderType = DOTA_UNIT_ORDER_CAST_NO_TARGET,
							TargetIndex = nil, --Optional.  Only used when targeting units
							AbilityIndex = i:entindex(), --Optional.  Only used when casting abilities
							Position = nil, --Optional.  Only used when targeting the ground
							Queue = 0 --Optional.  Used for queueing up abilities
						}
						ExecuteOrderFromTable(newOrder)
						CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
							unit_index = pet:entindex(),
							text = '#ai_say_open_loot',
						})
					end
				)
				return true
			end
		end
	end
end

