---模拟LaunchLoot，不飞，直接瞬移到终点
function CDOTA_Item:SimulateLaunchLoot(vEndPoint, no_effect)
	local hItemPhysical = self:GetContainer()
	if hItemPhysical == nil or hItemPhysical:IsNull() then return end

	vEndPoint = GetGroundPosition(vEndPoint, hItemPhysical)
	hItemPhysical:SetAbsOrigin(vEndPoint)

	if no_effect == true then
		return
	end
	play_particle(
	"particles/econ/items/crystal_maiden/crystal_maiden_maiden_of_icewrack/cm_arcana_pup_lvlup_godray.vpcf",
		PATTACH_ABSORIGIN_FOLLOW, hItemPhysical, 3)
	EmitSoundOn("Hero_OgreMagi.Idle.Headbutt", hItemPhysical)
end

function RemoveAllModifiersByCaster(u)
	if u == nil or u:IsNull() then
		return
	end
	for _, xx in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id)) do
		local allm = xx:FindAllModifiers()
		for _, yy in pairs(allm) do
			if yy ~= nil and yy:GetCaster() ~= nil and xx:entindex() ~= u:entindex() then
				if yy:GetCaster():entindex() == u:entindex() then
					xx:RemoveModifierByNameAndCaster(yy:GetName(), u)
				end
			end
		end
	end
end

function RemoveAllModifiers(u)
	local exclusion_table = {
		'modifier_is_aqir_buff',
		'modifier_is_undead_buff_plus_plus',
		'modifier_skeletonking_reincarnation',
		'modifier_item_xuejingshi',
		'modifier_broodmother_silken_bola',
		'modifier_no_hp_bar',
		'modifier_no_selectable',
		'modifier_root_self',
		'modifier_jiaoxie',
		'modifier_no_minimap_icon',
		'modifier_name',
		'modifier_jiaoxie_wudi',
		'modifier_item_buxiuzhishouhu',
		'modifier_nec_scythe_debuff_no_deathrattle',
		'modifier_more_creep',
		'modifier_illusion',
		'modifier_kill',
		'modifier_ud_dead_bomb',
	}
	--移除modifier
	local all_modifier = u:FindAllModifiers()
	for _, m in pairs(all_modifier) do
		if FindValueInTable(exclusion_table, m:GetName()) == false then
			u:RemoveModifierByName(m:GetName())
		end
	end

	--试图修复剑圣卡音效bug
	StopSoundOn("Hero_Juggernaut.BladeFuryStart", u)
	return
end

