function DestroyChess(keys)
	local target = keys.target

	if IsUnitExist(target) == false then
		return
	end
	--试图修复剑圣卡音效bug
	StopSoundOn("Hero_Juggernaut.BladeFuryStart", target)
	DestroyUnit(target)
end

function KillChess(keys)
	local target = keys.target
	local caster = keys.caster

	if IsUnitExist(target) == false then
		return
	end
	ApplyDamage({
		victim = target,
		attacker = caster,
		damage_type = DAMAGE_TYPE_PURE,
		damage = target:GetHealth(),
		ability = keys.ability
	})
end

function CopySynergy(keys)
	local caster = keys.caster
	local target = keys.target
	local ability = keys.ability
	local p = (keys.target_points or {})[1]

	if GetTime().phase == GAME_PHASE_BATTLE or GetTime().phase == GAME_PHASE_PREPARE and GetTime().left < 2 then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_cannot_delete_battle_chess"
		})
		EmitSoundOn("General.CastFail_NoMana", caster)
		return
	end

	--支持点目标选取
	if not target then
		local x = Vector2X(p, caster:GetTeam())
		local y = Vector2Y(p, caster:GetTeam())
		if y > 0 then
			for _, unit in pairs(GetValidChessOnBoard(caster:GetTeam())) do
				if IsUnitExist(unit) == true and unit.x == x and unit.y == y and unit:GetTeam() == caster:GetTeam() then
					target = unit
				end
			end
		end
		if y == -1 and caster.hand_entities and caster.hand_entities[x] then
			target = caster.hand_entities[x]
		end
	end
	if IsUnitExist(target) == false then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_no_target"
		})
		return
	end
	if target:HasModifier('modifier_shining') == true then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_already_shining"
		})
		return
	end

	local type = keys.type
	local copy_synergy = nil
	local try_count = 0
	local copycat = nil
	local exclusion_table = {}
	--不能坤的羁绊
	local invalid_synergy = {
		'is_human', 'is_pandaman', 'is_druid', 'is_mech', 'is_undead',
	}
	local invalid_synergy_meele = { 'is_dwarf' }
	while copy_synergy == nil and try_count < 200 do
		try_count = try_count + 1
		copycat = FindAllyClosest(target, true, exclusion_table)
		if IsUnitExist(copycat) then
			if type == 'race' then
				local race, race2 = GetChessRace(GetUnitBaseName(copycat))
				local target_race, target_race2 = GetChessRace(GetUnitBaseName(target))
				local synergy_check = nil
				if (target:Script_GetAttackRange() <= 205 or FindValueInTable(invalid_synergy_meele, race) == false) and FindValueInTable(invalid_synergy, race) == false and race ~= target_race and race ~= target_race2 and target:FindAbilityByName(race) == nil then
					synergy_check = race
				end
				if race2 ~= nil then
					if (target:Script_GetAttackRange() <= 205 or FindValueInTable(invalid_synergy_meele, race2) == false) and FindValueInTable(invalid_synergy, race2) == false and race2 ~= target_race and race2 ~= target_race2 and target:FindAbilityByName(race2) == nil then
						if RandomInt(1, 100) < 50 or synergy_check == nil then
							synergy_check = race2
						end
					end
				end
				if synergy_check ~= nil then
					copy_synergy = synergy_check
				end
			end
			if type == 'class' then
				local class, class2, class3 = GetChessClass(GetUnitBaseName(copycat))
				local synergy_check = nil
				if (target:Script_GetAttackRange() <= 205 or FindValueInTable(invalid_synergy_meele, class) == false) and FindValueInTable(invalid_synergy, class) == false and class ~= target_class and class ~= target_class2 and class ~= target_class3 and target:FindAbilityByName(class) == nil then
					synergy_check = class
				end
				if class2 ~= nil and class3 ~= nil then
					if (target:Script_GetAttackRange() <= 205 or FindValueInTable(invalid_synergy_meele, class2) == false) and FindValueInTable(invalid_synergy, class2) == false and class2 ~= target_class and class2 ~= target_class2 and class2 ~= target_class3 and target:FindAbilityByName(class2) == nil then
						if RandomInt(1, 100) < 50 or synergy_check == nil then
							synergy_check = class2
						end
					end
					if (target:Script_GetAttackRange() <= 205 or FindValueInTable(invalid_synergy_meele, class3) == false) and FindValueInTable(invalid_synergy, class3) == false and class3 ~= target_class and class3 ~= target_class2 and class3 ~= target_class3 and target:FindAbilityByName(class3) == nil then
						if RandomInt(1, 100) < 50 or synergy_check == nil then
							synergy_check = class3
						end
					end
				end
				local target_class, target_class2, target_class3 = GetChessClass(GetUnitBaseName(target))
				if synergy_check ~= nil then
					copy_synergy = synergy_check
				end
			end
			if copycat ~= nil and copy_synergy == nil then
				table.insert(exclusion_table, copycat:entindex())
			end
		end
	end
	if copy_synergy ~= nil then
		AddSynergy({
			caster = target,
			synergy = copy_synergy
		})
		SaveExtraSynergy(target, copy_synergy)

		ItemSpendCharge(keys)
		target:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(target, target, 'modifier_shining', {})
		--特效、音效
		local effect_name = "particles/units/heroes/hero_rubick/rubick_spell_steal.vpcf"
		ProjectileManager:CreateTrackingProjectile({
			Target = target,
			Source = copycat,
			Ability = nil,
			EffectName = effect_name,
			bDodgeable = false,
			iMoveSpeed = 1200,
			bProvidesVision = false,
			iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_ATTACK_1
		})
		target:StartGesture(ACT_DOTA_CAST_ABILITY_4)
		EmitSoundOn("Hero_Rubick.SpellSteal.Cast", target)

		play_particle("particles/econ/events/frostivus/frostivus_tree_cast_ability.vpcf", PATTACH_ABSORIGIN_FOLLOW,
			target, 3)

		if type == 'race' then
			CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
				player_id = caster:GetPlayerID(),
				win_streak = caster.win_streak or 0,
				vip = caster.is_vip,
				onduty_hero = caster.onduty_hero,
				text = "notice_add_synergy1",
				chess = target:GetUnitName(),
				time_stamp = math.floor(GameRules:GetGameTime()),
				type = 'copy_synergy_event',
				ability = copy_synergy,
				-- emoji = 175,
			})
		else
			CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
				player_id = caster:GetPlayerID(),
				win_streak = caster.win_streak or 0,
				vip = caster.is_vip,
				onduty_hero = caster.onduty_hero,
				text = "notice_add_synergy2",
				chess = target:GetUnitName(),
				time_stamp = math.floor(GameRules:GetGameTime()),
				type = 'copy_synergy_event',
				ability = copy_synergy,
				-- emoji = 175,
			})
		end
	else
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_no_synergy_to_copy"
		})
		return
	end
end

function SaveExtraSynergy(unit, synergy)
	if unit.extra_synergy == nil then
		unit.extra_synergy = {}
	end
	table.insert(unit.extra_synergy, synergy)
	local v_chess = Unit2VChess(unit)
	if v_chess == nil then
		return
	end
	local es_table = v_chess['extra_synergy']
	if es_table == nil then
		es_table = {}
	end
	table.insert(es_table, synergy)
	v_chess['extra_synergy'] = CopyTable(es_table)
end

function GetPriestTango(hero)
	local gap_count = _G.population_max[hero:GetTeam()] - _G.population[hero:GetTeam()]
	if gap_count >= 1 then
		AddItemPlus(hero, 'item_chishu')
		play_particle("particles/units/heroes/hero_keeper_of_the_light/keeper_of_the_light_illuminate_impact.vpcf",
			PATTACH_ABSORIGIN_FOLLOW, hero, 5)
	end
end

function PetGiveItem2Courier(pet, hero, item)
	local item_name = item:GetAbilityName()
	local charges = 1
	if item:IsPermanent() == false then
		charges = item:GetCurrentCharges()
		if charges < 1 then
			charges = 1
		end
	end

	PetMove(
		pet,
		hero:GetAbsOrigin() - (hero:GetAbsOrigin() - pet:GetAbsOrigin()):Normalized() * 50,
		true,
		function()
			item:RemoveSelf()
			for i = 1, charges do
				hero:AddItemByName(item_name)
			end

			CustomGameEventManager:Send_ServerToAllClients("drodo_bubble", {
				unit_index = pet:entindex(),
				text = 'ai_say_give_item|DOTA_Tooltip_ability_' .. item_name,
			})
			StartUpdateUIRecycleItemResult(hero)
		end
	)
end

function AddMojingAbility(keys)
	--延后0.5秒添加，保证技能顺序
	Timers:CreateTimer(0.5, function()
		local caster = keys.caster
		if IsUnitExist(caster) == true and caster.mojing_ability ~= nil then
			local a_level = caster.mojing_ability_level or 1 --GetChessStar(caster)
			if caster:HasModifier('modifier_item_ahalimushenzhang') then
				a_level = a_level + 1
			end
			if a_level > 3 then
				a_level = 3
			end

			if caster:FindModifierByName('modifier_item_ahalimumojing') == nil then
				AddAbilityAndSetLevel(caster, caster.mojing_ability, 0)
				caster:FindAbilityByName(caster.mojing_ability):SetActivated(false)
			else
				AddAbilityAndSetLevel(caster, caster.mojing_ability, a_level)
				caster:FindAbilityByName(caster.mojing_ability):SetActivated(true)
				local show_ability = caster:FindModifierByName('modifier_item_ahalimumojing'):GetAbility()
				if show_ability then
					show_ability:ApplyDataDrivenModifier(caster, caster, 'modifier_item_ahalimumojing_buff', {})
				end
			end
		end
	end)
end

function RemoveMojingAbility(keys)
	local caster = keys.caster
	if IsUnitExist(caster) == true and caster.mojing_ability ~= nil then
		--RemoveAbilityAndModifier(caster,caster.mojing_ability)
		if caster:FindAbilityByName(caster.mojing_ability) then
			caster:FindAbilityByName(caster.mojing_ability):SetActivated(false)
			caster:FindAbilityByName(caster.mojing_ability):SetLevel(0)
		end
		caster:RemoveModifierByName('modifier_item_ahalimumojing_buff')
	end
end

function SendServerToAllTeam(event, data)
	--发给6-13队伍的玩家
	for team_i = 6, 13 do
		data['key'] = GetClientKey(team_i)
		CustomGameEventManager:Send_ServerToTeam(team_i, event, data)
	end
	--发给观战者
	data['key'] = GetClientKey(1)
	CustomGameEventManager:Send_ServerToTeam(1, event, data)
end

function DAC:OnRequestPetGPT(keys)
	local player_id = keys.PlayerID
	local hero = _G.playerid2hero[player_id]
	local on_off = keys.on_off
	if hero == nil then
		return
	end
	local result = CourierAI({
		caster = hero,
		on_off = on_off,
	})
	
	CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "set_petgpt_status", {
		key = GetClientKey(hero:GetTeam()),
		on_off = result,
	})
end

--water_id: 棋子挂在信使身上的唯一id，不会因为改变y_x或entindex而改变
function AddChess2WaterIDList(u, old_water_id)
	if IsUnitExist(u, true) == false or u:GetTeam() == 4 then
		return false
	end
	local hero = TeamId2Hero(u:GetTeam())
	if IsUnitExist(hero, true) == false then
		return false
	end
	local entindex = u:entindex()
	if hero.water_list == nil then
		hero.water_list = {}
		hero.water_counter = 0
	end
	if old_water_id ~= nil then
		--更新
		hero.water_list[old_water_id] = entindex
		return water_id
	elseif GetChessWaterID(u) == nil then
		--新增
		local n = hero.water_counter + 1
		hero.water_counter = n
		hero.water_list[n] = entindex
		return n
	else
		return GetChessWaterID(u)
	end
end

function RemoveChessFromWaterIDList(u)
	if IsUnitExist(u, true) == false or u:GetTeam() == 4 then
		return false
	end
	local hero = TeamId2Hero(u:GetTeam())
	if IsUnitExist(hero, true) == false or hero.water_list == nil then
		return nil
	end

	local entindex = u:entindex()
	local water_id = GetChessWaterID(u)
	hero.water_list = RemoveOneKeyInTable(hero.water_list, water_id)
end

function GetChessWaterID(unit)
	local hero = TeamId2Hero(unit:GetTeam())
	local entindex = unit:entindex()
	if IsUnitExist(hero, true) == false or hero.water_list == nil then
		return nil
	end
	for water_id, i in pairs(hero.water_list) do
		if i == entindex then
			return water_id
		end
	end
end

function GetChessEntindexByWaterID(hero, water_id)
	if IsUnitExist(hero, true) == false or hero.water_list == nil then
		return nil
	end
	return hero.water_list[water_id]
end

