function MedusaSplitShot(keys)
	local caster = keys.caster
	local ability = keys.ability
	if not IsUnitExist(caster) or ability == nil then
		return
	end

	local arrow_count = GetAbilityKV(ability, "arrow_count") or 3
	local split_shot_bonus_range = GetAbilityKV(ability, "split_shot_bonus_range") or 100

	local team_id = caster.at_team_id or caster.team_id
	local target_table = {}
	for _, v in pairs(GetValidChessOnBoard(team_id)) do
		if IsUnitExist(v) and v:GetTeam() ~= caster:GetTeam() and (caster:GetAttackTarget() and v:entindex() ~= caster:GetAttackTarget():entindex()) and GetDistance(caster, v) < caster:Script_GetAttackRange() + split_shot_bonus_range then
			table.insert(target_table, {
				chess_index = v:entindex(),
				chess_name = v:GetUnitName(),
				distance = GetDistance(caster, v),
			})
		end
	end


	if table.maxn(target_table) > 0 then
		if table.maxn(target_table) > arrow_count then
			table.sort(target_table, function(a, b)
				return a.distance < b.distance
			end)
		end

		Timers:CreateTimer(0.3, function()
			for i = 1, arrow_count do
				if target_table[i] ~= nil and target_table[i].chess_index ~= nil then
					local v = EntIndexToHScript(target_table[i].chess_index)
					if IsUnitExist(v) == true then
						projectile = ProjectileManager:CreateTrackingProjectile({
							Target = v,
							Source = caster,
							Ability = ability,
							EffectName = caster:GetRangedProjectileName(),
							bDodgeable = false,
							iMoveSpeed = 800,
							bProvidesVision = false,
							iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_HITLOC
						})
					end
				end
			end
		end)
	end
end

function MedusaSplitShotHit(keys)
	local ability = keys.ability
	local caster = keys.caster
	local target = keys.target
	if not IsUnitExist(caster, true) or not IsUnitExist(target) or ability == nil then
		return
	end

	-- local damage_modifier_per = GetAbilityKV(ability, "damage_modifier_per") or (-50)
	local damage = caster:GetAverageTrueAttackDamage(target)
	-- damage = damage * (100 + damage_modifier_per) / 100

	-- caster:PerformAttack( target, false, true, true, false, false, false, false )
	ApplyDamage({
		victim = target,
		attacker = caster,
		damage = damage,
		damage_type = DAMAGE_TYPE_PHYSICAL,
		ability = ability,
	})
end

function ExtraAttack(keys)
	local caster = keys.caster
	local target = caster:GetAttackTarget()
	if IsUnitExist(caster) == false or IsUnitExist(target) == false then
		return
	end
	local chance = tonumber(keys.chance) or 100
	chance = chance * GetLuckyValue(caster)
	if RandomInt(1, 100) <= chance then
		Timers:CreateTimer(0.5, function()
			caster:PerformAttack(target, true, true, true, false, true, false, true)
			caster:StartGestureWithPlaybackRate(ACT_DOTA_ATTACK, caster:GetAttacksPerSecond(false) * 2)

			if caster:HasAbility('medusa_split_shot_new') == true then
				MedusaSplitShot({
					caster = caster,
					ability = caster:FindAbilityByName('medusa_split_shot_new'),
				})
			end
		end)
	end
end

--判断a和b是不是同一个种族或职业
function IsSameSpecOrClass(a, b)
	if IsUnitExist(a, true) == false or IsUnitExist(b, true) == false or _G.class_type == nil then
		return false
	end
	for i, s in pairs(_G.class_type) do
		if a:HasAbility(s) == true and b:HasAbility(s) == true then
			return true
		end
	end
	return false
end

function IsSameSpec(a, b)
	if IsUnitExist(a, true) == false or IsUnitExist(b, true) == false or _G.class_type == nil then
		return false
	end
	for i, s in pairs(_G.class_type) do
		if i < 200 and a:HasAbility(s) == true and b:HasAbility(s) == true then
			return true
		end
	end
	return false
end

function IsSameClass(a, b)
	if IsUnitExist(a, true) == false or IsUnitExist(b, true) == false or _G.class_type == nil then
		return false
	end
	for i, s in pairs(_G.class_type) do
		if i > 200 and a:HasAbility(s) == true and b:HasAbility(s) == true then
			return true
		end
	end
	return false
end

function EvolveAChess(u)
	if u.evolve_result == nil and u:HasModifier('modifier_is_shaman_buff_plus') == false and u:HasModifier('modifier_is_shaman_buff_plus_plus') == false and IsUnitExist(u) then
		return
	end

	local old_chess_name = u:GetUnitName()
	local count_modifier = u:FindModifierByName('modifier_is_shaman_50mana_count')
	local stack = 0
	if count_modifier then
		stack = count_modifier:GetStackCount()
	end
	stack = stack + 1
	local item_evolve_level = -1
	if u:HasModifier('modifier_is_shaman_buff_plus_plus') then
		item_evolve_level = 2 --6萨满，+2
		-- elseif u:HasModifier('modifier_is_shaman_buff_plus') then
		-- 	item_evolve_level = -1	--3萨满，无装备	
	end
	TransformAChess(u, u.evolve_result, item_evolve_level, function(x)
		if IsUnitExist(x) then
			SetChessSpecialLook(x)
			EmitSoundOn("shaman.evolve", x)
			play_particle("particles/econ/events/ti10/hero_levelup_ti10.vpcf", PATTACH_ABSORIGIN_FOLLOW, x, 3)
			-- if item_evolve_level == 1 then
			-- x:AddNewModifier(x,nil,"modifier_kill",{duration = RandomInt(20,25)})
			AddModifierKill(x, RandomInt(20, 25))
			-- else
			-- 	x:AddNewModifier(x,nil,"modifier_kill",{duration = 18})
			-- end
			-- AddShaman({caster = x})
			AddAbilityAndSetLevel(x, 'is_shaman', 1)

			local shaman_ability = x:FindAbilityByName('is_shaman')
			if shaman_ability == nil then
				return
			end

			x.old_chess_name = old_chess_name

			-- shaman_ability:ApplyDataDrivenModifier(x, x, 'modifier_is_shaman_50mana_count', {})
			-- x:FindModifierByName('modifier_is_shaman_50mana_count'):SetStackCount(stack)
			-- for i=1,stack do
			-- shaman_ability:ApplyDataDrivenModifier(x, x, 'modifier_is_shaman_50mana', {})
			-- end
		end
	end)
end

function BrWebNew(keys)
	local caster = keys.caster
	local ability = keys.ability
	if not IsUnitExist(caster) or caster.ai_started ~= true or ability == nil then
		return
	end
	if ability:IsCooldownReady() == false then
		return
	end
	if caster.alreadywon == true then
		return
	end
	if caster:HasModifier('modifier_item_test_no_ai') == true then
		return
	end
	local level = ability:GetLevel() or 1
	local cd = ability:GetCooldown(level)

	--丝质重器！
	local unluckydog = FindUnluckyDogClosest(caster, 'modifier_broodmother_silken_bola')
	if unluckydog ~= nil then
		InvisibleUnitCast({
			caster = caster,
			ability = 'broodmother_silken_bola',
			level = level,
			unluckydog = unluckydog,
		})
		unluckydog.web_br = caster
		ability:StartCooldown(cd)
	end
end

function UpdateDemonBuffStackCount(keys)
	local u = keys.caster
	if IsUnitExist(u) == false then
		return
	end
	local demon_count = 0
	if u:HasModifier('modifier_is_demonhunter_buff') == true then
		for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id or u:GetTeam())) do
			if IsUnitExist(unit) == true then
				-- 现在其他的非恶魔棋子不增加恶魔之力层数仅享受效果
				-- if unit.team_id == u.team_id and unit:HasModifier('modifier_is_demon_buff') then
				-- 	demon_count = demon_count + 1
				-- end
				if unit.team_id == u.team_id and unit:HasAbility('is_demon') then
					demon_count = demon_count + 1
				end
				if unit.team_id ~= u.team_id and unit:HasAbility('is_demonhunter') then
					demon_count = demon_count + 1
				end
			end
		end
	else
		--没有恶魔猎手buff，只有友方同名的恶魔才算
		for _, unit in pairs(GetValidChessOnBoard(u.at_team_id or u.team_id or u:GetTeam())) do
			if IsUnitExist(unit) == true then
				if unit.team_id == u.team_id and unit:HasAbility('is_demon') and GetChessBaseName(unit:GetUnitName()) == GetChessBaseName(u:GetUnitName()) then
					demon_count = demon_count + 1
				end
			end
		end
	end
	if demon_count > 7 then
		demon_count = 7
	end
	u.demon_count = demon_count
	if u:HasModifier('modifier_is_demon_buff') then
		if u.demon_count > 0 then
			u:FindModifierByName('modifier_is_demon_buff'):SetStackCount(u.demon_count)
		else
			u:FindModifierByName('modifier_is_demon_buff'):SetStackCount(0)
		end
	end
end

--进化几级需要根据是哪个萨满buff自动算
function GetEvolveLevel(u)
	if IsUnitExist(u) == false then
		return 0
	end
	local u_team = u:GetTeam()
	local chesser_team = u_team
	if u_team == 4 then
		--客场棋子
		chesser_team = _G.counterpart[u.at_team_id or 0]
		if chesser_team == nil then
			return 0
		end
	elseif u_team >= 6 and u_team <= 13 then
		--主场棋子
	else
		return 0
	end
	local level = GetLevel(u) or 1
	local max_level = TeamId2Hero(chesser_team):GetLevel()
	local delta = 0
	if u:HasModifier('modifier_is_shaman_buff_plus_plus') then
		delta = 2
	elseif u:HasModifier('modifier_is_shaman_buff_plus') then
		delta = 2
	end
	level = level + (delta or 0)
	if level > max_level then
		level = max_level
	end
	if level > 9 then
		level = 9
	end
	if level < 1 then
		level = 1
	end
	return level
end

