function SwapExpBookAbility(hero)
	if hero:HasModifier('modifier_talent_2b_promotion') then
		hero:SwapAbilities('exp_book','exp_book_mana_reduced',false,true)
	end
end
function UnlockExpLimit(hero)
	local level_max = 10
	if hero:HasModifier('modifier_talent_4b_morepieces') then
		level_max = 16
	end
	if hero:GetLevel() >= level_max then
		hero:FindAbilityByName('exp_book'):SetActivated(false)
		hero:FindAbilityByName("exp_book_mana_reduced"):SetActivated(false)
	else
		hero:FindAbilityByName('exp_book'):SetActivated(true)
		hero:FindAbilityByName("exp_book_mana_reduced"):SetActivated(true)
	end
end

function DisableAllTalents(hero)
	if IsUnitExist(hero) == false then
		return
	end
	for it, vt in pairs(_G.TALENT_TREE) do
		if hero:FindAbilityByName(vt) ~= nil then
			hero:FindAbilityByName(vt):SetLevel(0)
		end
	end
end

function AddOneTalent(hero, talent_id)
	local valid_level = math.floor((_G.battle_round + 5) / 10)
	local request_level = tonumber(string.sub(talent_id, 1, 1))
	if request_level <= valid_level and _G.stat_info[_G.playerid2steamid[hero:GetPlayerID()]]['talent_tree'][request_level] == nil then
		if hero:FindAbilityByName(_G.TALENT_TREE[talent_id]) ~= nil then
			hero:FindAbilityByName(_G.TALENT_TREE[talent_id]):SetLevel(1)
		end
		_G.stat_info[_G.playerid2steamid[hero:GetPlayerID()]]['talent_tree'][request_level] = _G.TALENT_TREE[talent_id]
	end
	UnlockExpLimit(hero)
	-- SwapExpBookAbility(hero)
	CustomNetTables:SetTableValue("player_info_table", "player_info", { data = _G.stat_info, hehe = RandomInt(1, 100000) })
	Timers:CreateTimer(0.5, function()
		CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "choose_talent_result", {
			key = GetClientKey(hero:GetTeam()),
			result = 1,
		})
	end)
end

function AddAllTalents(hero)
	local hero_talents = _G.stat_info[_G.playerid2steamid[hero:GetPlayerID()]]['talent_tree']
	local valid_level = math.floor((_G.battle_round + 5) / 10)
	if _G.battle_round >= 45 or hero.both_leaves == true then
		for i = 1, valid_level do
			if hero_talents[i] == nil then
				hero_talents[i] = _G.TALENT_TREE[i .. 'a']
				if hero:FindAbilityByName(hero_talents[i]) ~= nil then
					hero:FindAbilityByName(hero_talents[i]):SetLevel(1)
				end
			end
			if hero_talents[i + 4] == nil then
				local unspent_leave = _G.TALENT_TREE[i .. 'b']
				if unspent_leave == hero_talents[i] then
					unspent_leave = _G.TALENT_TREE[i .. 'a']
				end
				hero_talents[i + 4] = unspent_leave
				if hero:FindAbilityByName(unspent_leave) ~= nil then
					hero:FindAbilityByName(unspent_leave):SetLevel(1)
				end
			end
		end
		UnlockExpLimit(hero)
		-- SwapExpBookAbility(hero)

		CustomNetTables:SetTableValue("player_info_table", "player_info",
			{ data = _G.stat_info, hehe = RandomInt(1, 100000) })
		Timers:CreateTimer(0.5, function()
			CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "choose_talent_result", {
				key = GetClientKey(hero:GetTeam()),
				result = 1,
			})
		end)
	end
end

