function FindDianjinEnemy(u)
	local unluckydog = nil
	local try_count = 0
	local hp_u = u:GetHealth()
	local chessboard_id = u.at_team_id or u.team_id
	while unluckydog == nil and try_count < 30 do
		local uu = GetValidChessOnBoard(chessboard_id)[RandomInt(1, table.maxn(GetValidChessOnBoard(chessboard_id)))]
		if IsUnitExist(uu) == true and uu.team_id ~= u.team_id and not uu:HasAbility('is_ward') then
			-- if HasKillModifier(uu) == true then
			if IsSummons(uu) == true or uu:HasModifier('modifier_illusion') == true then
				if uu:HasAbility('tidehunter_kraken_shell') == false and uu:GetHealth() < hp_u then
					unluckydog = uu
				end
			end
		end
		try_count = try_count + 1
	end
	return unluckydog
end

function HwAcornShot(keys)
	local ability = keys.ability
	local caster = keys.caster
	local target = keys.target

	ability.is_split = nil
	projectile = ProjectileManager:CreateTrackingProjectile({
		Target = target,
		Source = caster,
		Ability = ability,
		EffectName = "effect/hw_baolizi/1.vpcf",
		bDodgeable = false,
		iMoveSpeed = 1500,
		bProvidesVision = false,
		iVisionRadius = 0,
		iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_ATTACK_1
	})
	EmitSoundOn('Hero_Hoodwink.AcornShot.Bounce', target)
end

function HwAcornShotHit(keys)
	local ability = keys.ability
	local caster = keys.caster
	local target = keys.target

	local damage = GetAbilityKV(ability, "damage") or 100
	-- local duration = GetAbilityKV(ability, "debuff_duration") or 5
	local bounce_count = GetAbilityKV(ability, "bounce_count") or 3
	local duration = GetAbilityKV(ability, "duration") or 3

	EmitSoundOn('Hero_Hoodwink.AcornShot.Target', target)
	ApplyDamage({
		victim = target,
		attacker = caster,
		damage = damage,
		damage_type = DAMAGE_TYPE_PHYSICAL,
		damage_flags = DOTA_DAMAGE_FLAG_NONE,
		ability = ability,
	})
	if ability.is_split == true then
		-- if target:HasModifier('modifier_hoodwink_acorn_shot_datadriven_debuff') then
		-- 	-- duration = duration + (target:FindModifierByName('modifier_hoodwink_acorn_shot_datadriven_debuff'):GetDuration() or 1)
		-- 	target:RemoveModifierByName('modifier_hoodwink_acorn_shot_datadriven_debuff')
		-- end
		ability:ApplyDataDrivenModifier(target, target, 'modifier_hoodwink_acorn_shot_datadriven_debuff', {
			duration = duration,
		})
		return
	end

	--弹射
	ability.is_split = true
	local dogs = FindNUnluckydog(bounce_count, caster.at_team_id or caster.team_id, function(u)
		if IsUnitExist(u) == false or u:GetTeam() == caster:GetTeam() then
			return -1
		end
		return (u.kill_count or 0) * 10000 + u:GetAttackDamage()
	end)
	for _, dog in pairs(dogs) do
		projectile = ProjectileManager:CreateTrackingProjectile({
			Target = dog,
			Source = target,
			Ability = ability,
			EffectName = "effect/hw_baolizi/1.vpcf",
			bDodgeable = false,
			iMoveSpeed = 1500,
			bProvidesVision = false,
			iVisionRadius = 0,
			iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_ATTACK_1
		})
		EmitSoundOn('Hero_Hoodwink.AcornShot.Bounce', dog)
	end
end

function FindNUnluckydog(n, chessboard_id, fun)
	local chess_table = {}
	for _, unit in pairs(GetValidChessOnBoard(chessboard_id)) do
		if IsUnitExist(unit) == true then
			table.insert(chess_table, {
				entindex = unit:entindex(),
				unit_name = unit:GetUnitName(),
				score = fun(unit),
			})
		end
	end
	table.sort(chess_table, function(a, b)
		return a.score > b.score
	end)
	local result_table = {}
	for i = 1, n do
		local obj = chess_table[i]
		if obj ~= nil and obj.score >= 0 then
			table.insert(result_table, EntIndexToHScript(obj.entindex))
		end
	end
	return result_table
end

--判断一个棋子是不是召唤物
function IsSummons(unit)
	if IsUnitExist(unit) == false then
		return false
	end
	if unit:HasModifier("modifier_kill") == true and string.find(unit:GetUnitName(), 'chess_') == nil then
		return true
	else
		return false
	end
end

--判断一个棋子是不是野怪（中立生物）
function IsNeutrals(unit)
	if IsUnitExist(unit) == false then
		return false
	end
	if string.find(unit:GetUnitName(), 'pve_') ~= nil then
		return true
	else
		return false
	end
end

function MoveChessDelay(hero, chess, target_pos, delay)
	Timers:CreateTimer(delay, function()
		DAC:OnPickChessPosition({
			caster = pet,
			x = target_pos.x,
			y = target_pos.y,
			z = target_pos.z,
			player_id = hero:GetOwner():GetPlayerID(),
			PlayerID = hero:GetOwner():GetPlayerID(),
			force_picked_chess = chess,
		})
	end)
end

--阵型前后反转
function ReverseLineup(hero)
	if IsUnitExist(hero) == false or hero:FindAbilityByName('pick_chess') == nil or hero:FindAbilityByName("pick_chess"):IsActivated() == false then
		CustomGameEventManager:Send_ServerToTeam(hero:GetTeam(), "mima", {
			key = GetClientKey(hero:GetTeam()),
			text = "text_cannot_move_chess",
		})
		return
	end

	local d = 0
	for _, v in pairs(GetValidChessOnBoard(hero:GetTeam())) do
		if IsUnitExist(v) == true and v:GetTeam() ~= 4 then
			local x = v.x
			local y = v.y
			y = 5 - y
			local target_pos = XY2Vector(x, y, hero:GetTeam())
			MoveChessDelay(hero, v, target_pos, d)
			d = d + 0.05
		end
	end
end

