function BmBearTaunt(keys)
	local caster = keys.caster
	local position = caster:GetAbsOrigin()
	local team = caster.team_id
	local unlucky_dogs = FindUnitsInRadiusByTeam({
		team = team,
		chessboard_id = caster.at_team_id or caster.team_id or caster:GetTeam(),
		role = 2,
		position = position,
		radius = 205,
	})

	for _, u in pairs(unlucky_dogs) do
		ExecuteOrderFromTable({
			UnitIndex = u:entindex(),
			OrderType = DOTA_UNIT_ORDER_ATTACK_TARGET,
			TargetIndex = caster:entindex(),
			Queue = 0
		})
	end
end

function IsTaunt(v)
	if IsUnitExist(v) == false then
		return false
	end
	if v:HasModifier('modifier_item_jurenzhijie_buff') == true then
		return true
	end
	if v:HasModifier('modifier_bm_bear_taunt') == true then
		return true
	end
	if v:HasModifier('modifier_axe_berserkers_call_armor') == true then
		return true
	end
	if v:HasModifier('modifier_ward_taunt') == true then
		return true
	end
	if v:HasModifier('modifier_item_xueji_debuff') == true then
		return true
	end
	-- if v:HasModifier('modifier_hoodwink_acorn_shot_datadriven_debuff') == true then
	-- 	return true
	-- end
	return false
end

