	})
end

--为队伍m移除圣物
function RemoveRelic(m,will_repeat)
	local hero = TeamId2Hero(m)

	for slot = 0, 9 do
		local item = hero:GetItemInSlot(slot)
		if item ~= nil then
			local item_name = item:GetAbilityName()
			if item_name == 'item_streak_plus' then
				--自动终结明暗终途
				TerminateStreakPlus(hero,will_repeat)
			end
			if item_name == 'item_exchange_items' then 
				local exchange_items = FindItemInInventory(hero,'item_exchange_items')
				if exchange_items:GetCurrentCharges() > 0 then
					local residual = exchange_items:GetCurrentCharges() + RandomInt(0,14)
					local residual_cantie = math.floor(residual/10)
					if residual_cantie > 0 then
						hero:AddItemByName('item_cantie')
						if residual_cantie > 1 then
							hero:AddItemByName('item_cantie')
						end
					end
				end 
			end
			if item_name == 'item_second_change' then 
				hero.second_draw_activate = nil
			end
			if FindValueInTable(_G.DROP_RELIC_LIST, item_name) == true or item_name == 'item_stolen_vault' then
				hero:RemoveItem(item)
			end
		end
	end

	if TeamId2Hero(m).mango_tree ~= nil and TeamId2Hero(m).mango_tree:IsNull() == false then
		local curr_health = hero.mango_tree:GetHealth()
		if curr_health > 0 then
			local new_pingguo = CreateItem('item_pingguo', TeamId2Hero(m), TeamId2Hero(m))
			local drop_pingguo = CreateItemOnPositionForLaunch(TeamId2Hero(m).mango_tree:GetAbsOrigin(), new_pingguo)
			new_pingguo:SimulateLaunchLoot(TeamId2Hero(m).mango_tree:GetAbsOrigin() +
			Vector(RandomFloat(-150, -100), RandomFloat(-50, 50), 0))
		end
		EmitSoundOn("item.mangotree.break", TeamId2Hero(m).mango_tree)
		TeamId2Hero(m).mango_tree:ForceKill(false)
		TeamId2Hero(m).mango_tree:SetModelScale(0.001)
		play_particle("effect/animation/tree/2_oak_01_destruction.vpcf", PATTACH_ABSORIGIN_FOLLOW,
			TeamId2Hero(m).mango_tree, 3)
	end
	if TeamId2Hero(m).great_vault ~= nil and TeamId2Hero(m).great_vault:IsNull() == false then
		EmitSoundOn("Brewmaster_Storm.DispelMagic", TeamId2Hero(m).great_vault)
		TeamId2Hero(m).great_vault:ForceKill(false)
		TeamId2Hero(m).great_vault:SetModelScale(0.001)
		play_particle("particles/creatures/aghanim/aghanim_shard_channel_swirl.vpcf", PATTACH_ABSORIGIN_FOLLOW,
			TeamId2Hero(m).great_vault, 3)
	end
	if TeamId2Hero(m).blacksmith ~= nil and TeamId2Hero(m).blacksmith:IsNull() == false then
		EmitSoundOn("Hero_Furion.Teleport_Disappear", TeamId2Hero(m).blacksmith)
		TeamId2Hero(m).blacksmith:ForceKill(false)
		TeamId2Hero(m).blacksmith:SetModelScale(0.001)
		play_particle("particles/econ/events/compendium_2023/compendium_2023_teleport_end_streaks.vpcf",
			PATTACH_ABSORIGIN_FOLLOW, TeamId2Hero(m).blacksmith, 3)
	end
	SetStat(TeamId2Hero(m):GetPlayerID(), 'relic', '', true)
end

function OKAngel(keys)
	local target = keys.target
	local caster = keys.caster
	local ability = keys.ability
	local level = ability:GetLevel()

	local duration = GetAbilityKV(ability, "duration") or 3
	local radius = GetAbilityKV(ability, "radius") or 300
	local heal = GetAbilityKV(ability, "heal") or 200

	local units = FindUnitsInRadiusOnTeamGround({
		team = caster:GetTeam(),
		at_team = caster.at_team_id or caster.team_id or caster:GetTeam(),
		role = 1,
		position = caster:GetAbsOrigin(),
		radius = radius,
	})
	if units ~= nil then
		for _, u in pairs(units) do
			if IsUnitExist(u) == true then
				if u:entindex() == caster:entindex() then
					ability:ApplyDataDrivenModifier(caster, u, 'modifier_ok_angel_self_buff', { duration = duration })
					EmitSoundOn('Hero_Omniknight.GuardianAngel.Cast', caster)
					OnKnightBuffCreate({ caster = caster })
				else
					ability:ApplyDataDrivenModifier(caster, u, 'modifier_ok_angel_buff', { duration = duration })
					OnKnightBuffCreate({ caster = u })
				end
				--驱散一下debuff
				u:Purge(false, true, false, false, false)
				-- play_particle('particles/items2_fx/mekanism.vpcf', PATTACH_ABSORIGIN_FOLLOW, unit, 3)
				u:Heal(heal, u)
			end
		end
	end
end

