--每个棋子的入血数量计算
--入血伤害 = 向下取整 （1+（等级/3））
--注1：如果是限时棋子，等级减半
--注2：如果是食人魔棋子，吃的棋子的等级也加到等级里
function GetHitDamage(u)
	local level = GetLevel(u)
	if u.eat_level ~= nil then
		level = level + u.eat_level
	end
	if HasKillModifier(u) == true then
		level = level / 2.0
	end
	local d = math.floor(1 + (1.0 * level / 3))
	return d
end

function CheckItemOwner(keys)
	local modifier1 = keys.modifier1
	local modifier2 = keys.modifier2
	local modifier3 = keys.modifier3
	local ability = keys.ability
	local caster = keys.caster
	Timers:CreateTimer(1,function()
		if IsUnitExist(caster) == false then
			return
		end
		if caster:IsHero() == true or caster.hand_index ~= nil or caster:HasModifier('modifier_illusion') == true or caster:HasModifier('modifier_kill') == true or (caster.is_tb_ally == true and modifier1 == 'modifier_item_buxiuzhishouhu') then
			caster:RemoveModifierByName(modifier1)
			if modifier2 then
				caster:RemoveModifierByName(modifier2)
			end
			if modifier3 then
				caster:RemoveModifierByName(modifier3)
			end
		else
			if caster:HasModifier(modifier1) == false then
				ability:ApplyDataDrivenModifier(caster, caster, modifier1, {})
			end
			if modifier2 and caster:HasModifier(modifier2) == false then
				ability:ApplyDataDrivenModifier(caster, caster, modifier2, {})
			end
			if modifier3 and caster:HasModifier(modifier3) == false then
				ability:ApplyDataDrivenModifier(caster, caster, modifier3, {})
			end
		end
		return 3
	end)
	if keys.modmaxhp ~= nil then
        ModMaxHP({
            caster = caster,
            const = keys.modmaxhp,
        })
    end
end

function OnDraeneiThink(keys)
	local caster = keys.caster
	local ability = keys.ability
	if IsUnitExist(caster) == false or caster.is_in_battle == false or caster.alreadywon == true then
		return
	end
	local dog = FindUnluckyDogClosest(caster)
	if dog ~= nil then
		projectile = ProjectileManager:CreateTrackingProjectile({
			Target = caster,
			Source = dog,
			Ability = ability,
			EffectName = 'particles/units/heroes/hero_bane/bane_projectile.vpcf',
			bDodgeable = false,
			iMoveSpeed = 500,
			bProvidesVision = false,
			iVisionRadius = 0,
			iVisionTeamNumber = caster:GetTeamNumber(),
			iSourceAttachment = DOTA_PROJECTILE_ATTACHMENT_ATTACK_1
		})
		local damage_all = keys.damage + keys.damage_per / 100 * dog:GetMaxHealth()
		ability.damage_all = damage_all
		ApplyDamage({
			victim = dog,
			attacker = caster,
			damage = damage_all or 75,
			damage_type = DAMAGE_TYPE_PURE,
			ability = ability,
		})
	end
end

function OnDraeneiHit(keys)
	local caster = keys.target
	local ability = keys.ability
	if IsUnitExist(caster) == false or caster.is_in_battle == false then
		return
	end
	caster:Heal(ability.damage_all or 75, caster)
	ability.damage_all = nil
end

--卡尔：新冰墙
function IceWallOne(caster, ability, at_team_id, x, y)
	if caster == nil or ability == nil then
		return
	end
	local duration = GetAbilityKV(ability, "duration") or 5

	if x == nil then
		x = 0
	end
	if y == nil then
		y = 0
	end
	if x ~= 0 then
		y = 0
	end
	if y ~= 0 then
		x = 0
	end
	if x == 0 and y == 0 then
		if RandomInt(1, 100) < 50 then
			x = RandomInt(1, 8)
		else
			y = RandomInt(1, 8)
		end
	end

	if at_team_id == nil then
		at_team_id = caster.at_team_id or caster.team_id or caster:GetTeam()
	end

	local start_position = nil
	local end_position = nil
	local point_table = {}
	if y == 0 and x > 0 then
		start_position = XY2Vector(x, 0, at_team_id)
		end_position = XY2Vector(x, 9, at_team_id)
		for z = 1, 8 do
			table.insert(point_table, XY2Vector(x, z, at_team_id))
		end
	end
	if y == 0 and x < 0 then
		start_position = XY2Vector(-x, 9, at_team_id)
		end_position = XY2Vector(-x, 0, at_team_id)
		for z = 1, 8 do
			table.insert(point_table, XY2Vector(-x, z, at_team_id))
		end
	end
	if x == 0 and y > 0 then
		start_position = XY2Vector(0, y, at_team_id)
		end_position = XY2Vector(9, y, at_team_id)
		for z = 1, 8 do
			table.insert(point_table, XY2Vector(z, y, at_team_id))
		end
	end
	if x == 0 and y < 0 then
		start_position = XY2Vector(9, -y, at_team_id)
		end_position = XY2Vector(0, -y, at_team_id)
		for z = 1, 8 do
			table.insert(point_table, XY2Vector(z, -y, at_team_id))
		end
	end

	if start_position ~= nil and end_position ~= nil then
		--Display the Ice Wall particles in a line.
		local ice_wall_particle_effect = ParticleManager:CreateParticle(
		"particles/units/heroes/hero_invoker/invoker_ice_wall.vpcf", PATTACH_ABSORIGIN, caster)
		ParticleManager:SetParticleControl(ice_wall_particle_effect, 0, start_position)
		ParticleManager:SetParticleControl(ice_wall_particle_effect, 1, end_position)

		local ice_wall_particle_effect_b = ParticleManager:CreateParticle(
		"particles/units/heroes/hero_invoker/invoker_ice_wall_b.vpcf", PATTACH_ABSORIGIN, caster)
		ParticleManager:SetParticleControl(ice_wall_particle_effect_b, 0, start_position)
		ParticleManager:SetParticleControl(ice_wall_particle_effect_b, 1, end_position)

		Timers:CreateTimer(0.5, function()
			for _, p in pairs(point_table) do
				-- local caster = keys.caster
				-- local team = caster:GetTeam()
				-- local role = keys.role or 2
				-- local radius = keys.radius or 500
				-- local modifier = keys.modifier
				-- local ability = keys.ability
				AddModifierInRadius({
					caster = caster,
					role = 2,
					radius = 200,
					modifier = 'modifier_invoker_ice_wall_debuff',
					ability = ability,
					duration = 3,
					position = p,
				})
			end
			duration = duration - 0.5
			if duration <= 0 then
				--Remove the Ice Wall particles after the duration ends.
				ParticleManager:DestroyParticle(ice_wall_particle_effect, false)
				ParticleManager:ReleaseParticleIndex(ice_wall_particle_effect)
				ParticleManager:DestroyParticle(ice_wall_particle_effect_b, false)
				ParticleManager:ReleaseParticleIndex(ice_wall_particle_effect_b)
				return
			end
			return 0.5
		end)
	end
end

function invoker_ice_wall_datadriven_on_spell_start(keys)
	keys.caster:EmitSound("Hero_Invoker.IceWall.Cast")
	local ability = keys.ability
	local level = ability:GetLevel() or 1
	local caster = keys.caster
	local wall_count = GetAbilityKV(ability, "wall_count") or 1
	local dup_table = {}

	Timers:CreateTimer(0.1, function()
		if wall_count > 0 then
			local x = 0
			local y = 0
			local try_count = 0
			while try_count < 100 and dup_table[x .. '_' .. y] == nil do
				x = 0
				y = 0
				-- if RandomInt(1,100) < 50 then
				-- x = GetRandomXHasEnemy(caster:GetTeam(), caster.at_team_id or caster.team_id or caster:GetTeam())
				-- else
				y = GetRandomYHasEnemy(caster:GetTeam(), caster.at_team_id or caster.team_id or caster:GetTeam())
				-- end
				try_count = try_count + 1
			end
			-- if RandomInt(1,100) < 50 then
			-- 	x = -x
			-- 	y = -y
			-- end
			IceWallOne(caster, ability, at_team_id, x, y)
			dup_table[x .. '_' .. y] = 1
			wall_count = wall_count - 1
			return 0.1
		else
			return
		end
	end)
end

function AddModifierKill(chess, duration, modifier_name)
	if chess:HasModifier('modifier_yonghengzhipan_yongheng_buff') == true then
		play_particle("particles/items5_fx/essence_ring_burst.vpcf", PATTACH_ABSORIGIN_FOLLOW, chess, 3)
		return
