	chess:AddNewModifier(chess, nil, modifier_name or "modifier_kill", { duration = duration or 10 })
end

--终结明暗终途，获得连胜/连败的奖励
function CalStreakPlusBoxLevel(hero)
	local terminate_level = hero.streak_plus_win or 1
	if terminate_level < (hero.streak_plus_lose or 1) then
		terminate_level = hero.streak_plus_lose
	end
	local box_level = 0
	local relic_history_count = table.maxn(GetRelicHistory(hero) or {}) or 1
	if terminate_level then
		if terminate_level >= 2 and terminate_level < 5 then
			box_level = relic_history_count + 0
		end
		if terminate_level >= 5 and terminate_level < 10 then
			box_level = relic_history_count + 1
		end
		if terminate_level >= 10 then
			box_level = relic_history_count + 2
		end
	end
	if box_level > 5 then
		box_level = 5
	end
	return box_level
end

function TerminateStreakPlus(hero,will_repeat)
	local box_level = CalStreakPlusBoxLevel(hero)
	GiveASingleLootBox(hero, 'item_lootbox_lv' .. box_level)
	play_particle("particles/econ/items/dazzle/dazzle_ti6/dazzle_ti6_shallow_grave_glyph_flare.vpcf",
		PATTACH_ABSORIGIN_FOLLOW, hero, 3)
	EmitSoundOn("relic.item_streak_plus", hero)
	if will_repeat == nil then
		hero.streak_plus_win = nil
		hero.streak_plus_lose = nil
	end
end

