function TriggerSMArcaneBolt(keys)
	local caster = keys.caster
	local target = keys.target
	if IsUnitExist(caster) == false then
		return
	end
	for _, sm in pairs(GetValidChessOnBoard(caster.at_team_id or caster.team_id)) do
		if IsUnitExist(sm) == true and IsChessCanCast(sm) == true and caster:GetTeam() == sm:GetTeam() and sm:HasAbility('skywrath_mage_arcane_bolt_container') then
			local ability = sm:FindAbilityByName('skywrath_mage_arcane_bolt_container')
			if ability ~= nil and ability:IsActivated() == true and ability:IsCooldownReady() == true then
				Timers:CreateTimer(0.1, function()
					SMArcaneBolt({
						caster = sm,
						ability = ability,
						force_target = target,
					})
				end)
				if sm:HasModifier('modifier_is_harpy_buff') == true then
					Timers:CreateTimer(RandomFloat(0.2,0.5), function()
						SMArcaneBolt({
							caster = sm,
							ability = ability,
						})
					end)
				end
				if sm:HasModifier('modifier_is_harpy_buff_plus') == true then
					Timers:CreateTimer(RandomFloat(0.2,0.5), function()
						SMArcaneBolt({
							caster = sm,
							ability = ability,
						})
					end)
				end
				if sm:HasModifier('modifier_item_fashulengjing') then
					Timers:CreateTimer(RandomFloat(0.2,0.5), function()
						SMArcaneBolt({
							caster = sm,
							ability = ability,
						})
					end)
				end
				local cd = ability:GetCooldown(ability:GetLevel()) or 2.0
				cd = 1.0 * cd * GetCooldownPerByGod(sm)
				ability:StartCooldown(cd)
			end
		end
	end
end

function IsChessCanCast(u)
	if IsUnitExist(u) == false then
		return false
	end
	if u:HasModifier('modifier_axe_berserkers_call') == false and u:FindModifierByName('modifier_doom_bringer_doom') == nil and IsHexxed(u) == false and u:FindModifierByName('modifier_medusa_stone_gaze_stone') == nil and u:HasModifier('modifier_queenofpain_sonic_wave_chaos_debuff') == false and u:HasModifier('modifier_is_satyr_debuff') == false and u:IsSilenced() == false and u:FindModifierByName('modifier_illusion') == nil and u:HasModifier('modifier_is_centaur_buff') == false and u:IsStunned() == false and u:IsFrozen() == false then
		return true
	end
	return false
end

function IsUndead(chess_name)
	for _, v in pairs(_G.chess_list_by_mana_black) do
		for _, vv in pairs(v) do
			if vv == chess_name then
				return true
			end
		end
	end
	return false
end

--消散
function BaseDissipate(keys)
	local caster = keys.caster
	if IsUnitExist(caster) == false or HasKillModifier(caster) == false then
		return
	end
	if caster:HasModifier('modifier_ringmaster_spotlight_debuff') == true then
		local m = caster:FindModifierByName('modifier_ringmaster_spotlight_debuff')
		local a = m:GetAbility()
		if m ~= nil and a ~= nil then
			local per = GetAbilityKV(a, "illusion_percent_damage") or 8
			local owner = a:GetOwner()
			local damage = caster:GetMaxHealth() / 100.0 * per / 5.0
			ApplyDamage({
				victim = caster,
				attacker = owner,
				damage = damage,
				damage_type = DAMAGE_TYPE_PURE,
				ability = a,
			})
		end
	end
end

