function ShowDamageNumberEffect(entity, number, color, duration)
	local particle_table = {
		[1] = "effect/damage_show/damage_1.vpcf",
		[2] = "effect/damage_show/damage_2.vpcf",
		[3] = "effect/damage_show/damage_3.vpcf",
		[4] = "effect/damage_show/damage_4.vpcf",
		[5] = "effect/damage_show/damage_5.vpcf",
		[6] = "effect/damage_show/damage_6.vpcf",
		[7] = "effect/damage_show/damage_7.vpcf",
	}
	color = color or { 90, 145, 205 }
	duration = duration or 3
	number = number or 0
	if IsUnitExist(entity, true) == false then
		return
	end
	local color_r = tonumber(color[1]) or 255
	local color_g = tonumber(color[2]) or 255
	local color_b = tonumber(color[3]) or 255
	local color_vec = Vector(color_r, color_g, color_b)

	--处理数字
	number = math.floor(number)
	local number_count = #tostring(number) + 1

	local p = particle_table[1]
	if number > 200 then
		p = particle_table[2]
	end
	if number > 500 then
		p = particle_table[3]
	end
	if number > 1000 then
		p = particle_table[4]
	end
	if number > 2000 then
		p = particle_table[5]
	end
	if number > 4000 then
		p = particle_table[6]
	end
	if number > 10000 then
		p = particle_table[7]
	end

	--创建特效
	local particle = AMHC:CreateParticle(p, PATTACH_CUSTOMORIGIN_FOLLOW, false, entity, duration)
	ParticleManager:SetParticleControlEnt(particle, 0, entity, 5, "attach_hitloc", entity:GetOrigin(), true)
	ParticleManager:SetParticleControl(particle, 1, Vector(10, number, 9))
	ParticleManager:SetParticleControl(particle, 2, Vector(duration, number_count, 0))
	ParticleManager:SetParticleControl(particle, 3, color_vec)
end

function ItemMagicBox(keys)
	local caster = keys.caster
	local target = keys.target
	local ability = keys.ability
	local p = (keys.target_points or {})[1]
	local charge_table = {1,3,9}
	local charges = ability:GetCurrentCharges()
	--支持点目标选取
	if not target then
		local x = Vector2X(p, caster:GetTeam())
		local y = Vector2Y(p, caster:GetTeam())
		if y > 0 then
			for _, unit in pairs(GetValidChessOnBoard(caster:GetTeam())) do
				if IsUnitExist(unit) == true and unit.x == x and unit.y == y and unit:GetTeam() == caster:GetTeam() then
					target = unit
				end
			end
		end
		if y == -1 and caster.hand_entities and caster.hand_entities[x] then
			target = caster.hand_entities[x]
		end
	end
	if IsUnitExist(target) == false then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_no_target"
		})
		return
	end
	local chess_name = target:GetUnitName()
	local star = GetChessStar(target) or 1
	local level = target:GetLevel() or 1
	--兼容德鲁伊的等级问题
	-- local cost = GetChessCostByName(GetChessBaseName(chess_name))
	local cost = level - (2*(star-1))
	if charges < charge_table[star] then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_not_enough_charges"
		})
		return
	end

	if string.find(target:GetUnitName(), 'chess_') == nil or cost < 1 or chess_name == 'egg' then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_invalid_target"
		})
		return
	end

	local hand_index = target.hand_index
	local buy_price = target.buy_price or 0
	if hand_index ~= nil then
		--使用成功了，进盒！
		for i=1,charge_table[star] do
			ItemSpendCharge(keys)
		end
		-- local ptable = CopyChessProperties(nil,target)
		RemoveChess({
			caster = caster,
			target = target,
			is_sell = false,
			force_remove = true,
		})

		if caster.magic_box_exclude_table == nil then
			caster.magic_box_exclude_table = {}
		end
		if FindValueInTable(caster.magic_box_exclude_table,GetChessBaseName(chess_name)) == false then
			table.insert(caster.magic_box_exclude_table,GetChessBaseName(chess_name))
		end

		-- Timers:CreateTimer(0.1, function()
			local holder = CreateChessInHand(caster, "magic_box", true, hand_index)
			if IsUnitExist(holder) then
				AddAbilityAndSetLevel(holder, 'no_hp_add')
				-- BlinkChessX({caster=holder,blink_type="breaksoil"})
				-- holder:SetForwardVector(Vector(0,-1,0))
				holder.buy_price = buy_price
				holder.cost = cost
				holder.level = level
				holder.star = star
				-- holder.chess = GetRandomChessByCostFromAllChess(cost, caster.magic_box_exclude_table)
				-- print(holder.chess)
			end
			EmitSoundOn('magic_box.in', hero)
			AddAbilityAndSetLevel(holder, 'no_hp_add')
			DropItemsFromOneChess({
				caster = caster,
				target = target,
			})
		-- end)
	else
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_no_hand_target"
		})
		return
	end
end

function MagicboxOut(target, v)
	if IsUnitExist(target) == false then
		return
	end
	Timers:CreateTimer(RandomFloat(0, 2), function()
		local box_chess = GetRandomChessByCostFromAllChess((target.cost or 1), v.magic_box_exclude_table)
		EmitSoundOn("magic_box.out", target)
		_G.hand[v:GetTeam()][target.hand_index] = 0
		v.hand_entities[target.hand_index] = nil
		if target.star == 3 then
			box_chess = box_chess..'11'
		elseif target.star == 2 then
			box_chess = box_chess..'1'
		end

		target:ForceKill(false)

		CreateChessInHandAsync(v, box_chess, true, target.hand_index, function(chess)
			chess.buy_price = target.buy_price
		end)
	end)
end

function GetRandomChessByCostFromAllChess(cost, no_dup_table)
	local random_table = {}
	if no_dup_table == nil then
		no_dup_table = {}
	end
	if cost == 5 then
		if _G.chess_list_by_mana_gold then
			for _, c in pairs(_G.chess_list_by_mana_gold) do
				table.insert(random_table, c)
			end
		end
	else
		if _G.chess_list_by_mana[cost] then
			for _, c in pairs(_G.chess_list_by_mana[cost]) do
				table.insert(random_table, c)
			end
		end
		if _G.chess_list_by_mana_black[cost] then
			for _, c in pairs(_G.chess_list_by_mana_black[cost]) do
				table.insert(random_table, c)
			end
		end
	end
	if _G.chess_list_by_mana_special[cost] then
		for _, c in pairs(_G.chess_list_by_mana_special[cost]) do
			if c ~= 'chess_io' then
				table.insert(random_table, c)
			end
		end
	end

	local try_count = 0
	while try_count < 100 do
		local cc = random_table[RandomInt(1, table.maxn(random_table))]
		if FindValueInTable(no_dup_table,cc) == false and FindValueInTable(_G.chess_list_by_synergy['is_druid'],cc) == false then
			return cc
		end
		try_count = try_count + 1
	end
	return no_dup_table[RandomInt(1,table.maxn(no_dup_table))]
end
function CalDoubleCoin(caster)
	local gold = math.floor(caster:GetMana()) or 0
	local hp = math.floor(caster:GetHealth()) or 0
	if gold == hp then
		CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "mima", {
			key = GetClientKey(caster:GetTeam()),
			text = "text_mima_no_double_coin_hp_gold"
		})
		return
	end
	local hp_new = hp
	local gold_new = gold
	local transfer_hp
	local transfer_gold
	if hp > gold then
		transfer_hp = math.floor(hp * 0.2 + 0.5)
		transfer_gold = transfer_hp
		hp_new = hp - transfer_hp
		gold_new = gold + transfer_gold
	else
		transfer_gold = math.floor(gold * 0.2 + 0.5)
		transfer_hp = transfer_gold
		hp_new = hp + transfer_hp
		gold_new = gold - transfer_gold
	end
	return {
		hp = hp,
		gold = gold,
		hp_new = hp_new,
		gold_new = gold_new,
		transfer_hp = transfer_hp,
		transfer_gold = transfer_gold,
	}
end
function ItemDoubleCoinRequest(keys)
	local caster = keys.caster
	local result_table = CalDoubleCoin(caster)
	CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "show_double_coin_confirm", {
		key = GetClientKey(caster:GetTeam()),
		result = result_table,
	})
end
function DAC:ItemDoubleCoin(keys)
	local player_id = keys.PlayerID
	local caster = PlayerId2Hero(player_id)
	if IsUnitExist(caster) == false or caster:HasModifier('modifier_item_double_coin') == false then
		return
	end
	local double_coin_item = FindItemInInventory(caster,'item_double_coin')

	if double_coin_item:GetCurrentCharges() <= 0 then
		return
	end

	ItemSpendCharge({
		caster = caster,
		ability = FindItemInInventory(caster,'item_double_coin'),
	})
	local result_table = CalDoubleCoin(caster)
	caster:SetHealth(result_table.hp_new)
	caster:SetMana(result_table.gold_new)
	AddTotalMoneyStat(caster:GetPlayerID(), result_table.transfer_gold)
	EmitSoundOn('doubloon.cast', caster)
	SyncHP(caster)
	play_particle("particles/units/heroes/hero_ringmaster/ringmaster_escape_act_target_glyph_flare.vpcf",
		PATTACH_OVERHEAD_FOLLOW, caster, 3)
	
	CustomGameEventManager:Send_ServerToTeam(caster:GetTeam(), "show_gold", {
		key = GetClientKey(caster:GetTeam()),
		gold = caster:GetMana(),
		lose_streak = caster.lose_streak or 0,
		win_streak = caster.win_streak or 0,
		box_level = CalStreakPlusBoxLevel(caster),
	})

	--发一条消息通知
	local text = "notice_double_coin1"
	local num = result_table.transfer_gold or 0
	if result_table.hp > result_table.gold then
		text = "notice_double_coin2"
		num = result_table.transfer_hp or 0
	end

	CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
		player_id = player_id,
		win_streak = caster.win_streak or 0,
		vip = caster.is_vip,
		onduty_hero = caster.onduty_hero,
		text = text,
		number = num,
		time_stamp = math.floor(GameRules:GetGameTime()),
		type = 'double_coin_event',
		-- emoji = 175,
	})
end

function KezKatana(keys)
	local caster = keys.caster
	local target = keys.target
	local ability = keys.ability
	local damage = keys.damage or 100
	local damage_per = keys.damage_per or 0
	local stun_duration = keys.stun_duration
	
	local damage_all = target:GetMaxHealth() /100.0*damage_per + damage
	
	local pp = ParticleManager:CreateParticle("particles/units/heroes/hero_kez/kez_katana_impale.vpcf", PATTACH_WORLDORIGIN, nil)
    ParticleManager:SetParticleControl(pp, 0, target:GetOrigin()+((caster:GetOrigin()-target:GetOrigin()):Normalized()*32)+Vector(0,0,80))
	ParticleManager:SetParticleControlOrientation(pp,1,-caster:GetForwardVector(),-caster:GetRightVector(), caster:GetUpVector())
	EmitSoundOn('kez.katana_go', caster)
	ApplyDamage({
		victim = target,
		attacker = caster,
		damage = damage_all / 2.0,
		damage_type = DAMAGE_TYPE_PHYSICAL,
		ability = ability,
	})
	local real_attacker = caster.damage_owner or caster
	if IsUnitExist(real_attacker) == false then return end
	real_attacker:PerformAttack(target, true, true, true, false, false, false, true)
	ability:ApplyDataDrivenModifier(caster, target, 'modifier_kez_kazurai_katana_datadriven_stun_debuff', {duration = stun_duration})
	ability:ApplyDataDrivenModifier(caster, caster, 'modifier_kez_kazurai_katana_datadriven_self_disarm', {duration = 2})

	caster:AddActivityModifier('stab')
	caster:StartGesture(ACT_DOTA_CAST_ABILITY_2_ALLY)
	
	Timers:CreateTimer(1,function()
		caster:ClearActivityModifiers()
		local pp_end = ParticleManager:CreateParticle("particles/units/heroes/hero_kez/kez_katana_impale_end.vpcf", PATTACH_WORLDORIGIN, nil)
    	ParticleManager:SetParticleControl(pp_end, 0, target:GetOrigin()+Vector(0,0,80))
		ParticleManager:SetParticleControlOrientation(pp_end,1,-caster:GetForwardVector(),-caster:GetRightVector(), caster:GetUpVector())
		EmitSoundOn('kez.katana_back', target)
		ApplyDamage({
			victim = target,
			attacker = caster,
			damage = damage_all / 2.0,
			damage_type = DAMAGE_TYPE_PHYSICAL,
			ability = ability,
		})
		Timers:CreateTimer(2,function()
			if pp ~= nil then
				ParticleManager:DestroyParticle(pp, true)
				ParticleManager:ReleaseParticleIndex(pp)
			end
			if pp_end ~= nil then
				ParticleManager:DestroyParticle(pp_end, true)
				ParticleManager:ReleaseParticleIndex(pp_end)
			end
		end)
		local real_attacker = caster.damage_owner or caster
		real_attacker:PerformAttack(target, true, true, true, false, false, false, true)
	end)
end

function GetChessCastRange(u)
	if IsUnitExist(u) == false then
		return 0
	end
	local ability_name = GetChessAbility(u)
	if ability_name == nil then
		return 0
	end
	local ability = u:FindAbilityByName(ability_name)
	if ability == nil then
		return 0
	end

	return ability:GetCastRange(u:GetAbsOrigin(),u) or 0
end

