function WispTetherHealth(keys)
	local caster = keys.caster
	local io_ability = caster:FindAbilityByName('wisp_tether_lua')
	local max_distance = GetAbilityKV(io_ability,'max_distance')
	local allies = caster.io_ally_index_table
	if allies ~= nil then 
		local per_sum = 0
		local count_sum = 0
		local remove_index_table = {}
		for i,v_index in pairs(allies) do 
			local v = EntIndexToHScript(v_index)
			if IsUnitExist(v) then 
				if (v:GetAbsOrigin() - caster:GetAbsOrigin()):Length2D() > max_distance then 
					DestroyIOTether({
						target = v,
					})
					table.insert(remove_index_table,v_index)
				else
					per_sum = per_sum + v:GetHealth()/v:GetMaxHealth()
					count_sum = count_sum + 1
				end
			end	
		end
		local per_sum_average = per_sum/count_sum
		for t,tt in pairs(remove_index_table) do 
			RemoveTableItem(allies,tt)
		end
		for ii,vv_index in pairs(allies) do 
			local vv = EntIndexToHScript(vv_index)
			if IsUnitExist(vv) then 
				local target_health = per_sum_average*vv:GetMaxHealth()
				-- if target_health > vv:GetHealth() then 
				-- 	vv:Heal(target_health-vv:GetHealth(),caster)
				-- else
					vv:SetHealth(target_health)
				-- end
			end
		end
	end
end

function DestroyIOTether(keys)
	local target = keys.target
	if IsUnitExist(target, true) == false then
		--TODO：把这个条件推广到IsUnitExist里面？防止错误类型的野数据导致报错
		return
	end
	target:RemoveModifierByName('modifier_wisp_tether_buff')
	target:RemoveModifierByName('modifier_wisp_altar_power')
	target:RemoveModifierByName('modifier_wisp_altar_power_count')
	
	local ppp = target.io_ally_pid
	if ppp then
		ParticleManager:DestroyParticle(ppp, true)
		ParticleManager:ReleaseParticleIndex(ppp)
	end
end
