function HunterAttackLanded(keys)
	local caster = keys.caster
	local target = keys.target
	if IsUnitExist(caster) == false or IsUnitExist(target) == false then
		return false
	end
	-- KnockBack({
	-- 	caster = caster,
	-- 	target = target,
	-- })
	if caster:HasModifier('modifier_is_hunter_buff') == true then
		local ability = caster:FindAbilityByName("is_hunter_buff")
		if ability ~= nil then
			ability:ApplyDataDrivenModifier(caster, target, 'modifier_is_hunter_buff_debuff', {
				duration = 5
			})
		end
	end
	if caster:HasModifier('modifier_is_hunter_buff_plus') == true then
		local ability = caster:FindAbilityByName("is_hunter_buff_plus")
		if ability ~= nil then
			ability:ApplyDataDrivenModifier(caster, target, 'modifier_is_hunter_buff_plus_debuff', {
				duration = 8
			})
		end
	end
	--9猎人：击退并连击
	if caster:HasModifier("modifier_is_hunter_buff_plus_plus") == true then
		KnockBack({
			caster = caster,
			target = target,
			blocks = 1,
		})
		local ability = caster:FindAbilityByName("is_hunter_buff_plus_plus")
		if ability ~= nil and ability:IsCooldownReady() == true then
			ability:StartCooldown(0.5)
			ExtraAttack({
				caster = caster
			})
		end
	end

end

function UpdateStackModifier(keys)
	local caster = keys.caster
	local target = keys.target
	local ability = keys.ability
	local modifier_name = keys.modifier_name
	local stack_modifier_name = keys.stack_modifier_name

	if IsUnitExist(target) == true then
		local count = 0
		for _, m in pairs(target:FindAllModifiers()) do
			if m:GetName() == modifier_name then
				count = count + 1
			end
		end
		if count == 0 then
			target:RemoveModifierByName(stack_modifier_name)
		else
			if target:HasModifier(stack_modifier_name) == false then
				ability:ApplyDataDrivenModifier(target, target, stack_modifier_name, {})
			end
			target:FindModifierByName(stack_modifier_name):SetStackCount(count)
		end
	end
end

function GetXYDistance(xx,yy,x,y)
	return math.sqrt( math.pow((yy-y),2) + math.pow((xx-x),2) )
end

--恶魔之扉：召唤
function AuCallOfDemon(keys)
	local caster = keys.caster
	local ability = keys.ability
	local level = caster.portal_star or 1
	if IsUnitExist(caster) == false then
		return
	end

	local random_demon = _G.demon_list[RandomInt(1,table.maxn(_G.demon_list))]
	local cost = GetChessCostByName(random_demon)
	if level == 2 then
		random_demon = random_demon..'1'
		cost = cost + 2
	end
	if level == 3 then
		random_demon = random_demon..'11'
		cost = cost + 4
	end

	local p = FindEmptyGridAtUnit(caster, true)
	local p0 = caster:GetAbsOrigin()
	-- SummonOneChess({
	-- 	teamid = caster:GetTeam(),
	-- 	position = p,
	-- 	chessname = random_demon,
	-- 	at_teamid = caster.at_team_id or caser.team_id or caster:GetTeam(),
	-- })
	local hasDemonBuff = false
	if caster:HasModifier('modifier_is_demon_buff') == true then
		hasDemonBuff = true
	end


	local curr_health = caster:GetHealth()
	if curr_health == nil then
		curr_health = 1
	end
	curr_health = curr_health - cost

	if curr_health > 0 then
		caster:SetHealth(curr_health)

		SummonOneChessAsync({
			teamid = caster:GetTeam(),
			at_teamid = caster.at_team_id or caster.team_id or caster:GetTeam(),
			chessname = random_demon,
			position = p,
			cb = function(w)
				if IsUnitExist(w) == true then
					w.is_au_called = true
					w:SetMana(0)
					FillEmptySlot(w)
					AddAbilityAndSetLevel(w, 'jiaoxie_wudi')
					w:SetAbsOrigin(p0)
					BlinkChessX({
						p = p,
						caster = w,
						blink_type = 'run',
						set_forward = true,
					})
					w:AddNewModifier(w,nil,"modifier_kill",{duration = RandomInt(8,12)})
					if hasDemonBuff == true then
						AddAbilityAndSetLevel(w,'is_demon_buff',1)
					end
				end
			end
		})
	else
		EmitSoundOn("Hero_Underlord.Portal.Out", caster)
		
		-- play_particle("particles/units/heroes/heroes_underlord/au_debut_landing.vpcf", PATTACH_OVERHEAD_FOLLOW,
		-- 	caster, 3)

		local ppp = ParticleManager:CreateParticle("particles/units/heroes/heroes_underlord/au_debut_landing.vpcf", PATTACH_WORLDORIGIN, nil)
		ParticleManager:SetParticleControl(ppp, 0, caster:GetAbsOrigin())

		caster:ForceKill(false)
		caster:SetModelScale(0.001)
	end
end

function RequestPrecacheUnitAsync(precache_name,cb)
	--不参加异步加载
	if (string.find(precache_name,'courier_') == nil and string.find(precache_name,'model_') == nil) or (string.find(precache_name,'model_') ~= nil and string.find(precache_name,'11') == nil) or FindValueInTable(_G.precache_list,precache_name) == true then
		if cb then
			cb()
		end
	else
		--需要异步加载
		if _G.precache_busy == true then 
			Timers:CreateTimer(0.5,function()
				RequestPrecacheUnitAsync(precache_name,cb)
				return
			end)
			if _G.precache_count[_G.battle_round] == nil then 
				_G.precache_count[_G.battle_round] = 0
			end
			_G.precache_count[_G.battle_round] = _G.precache_count[_G.battle_round] + 1
		else
			--空闲，开始加载
			_G.precache_busy = true
			if _G.is_tester_mode == true then
	            combat('precache: '..precache_name)
	        end
			PrecacheUnitByNameAsync(precache_name, function()
				_G.precache_busy = false
				table.insert(_G.precache_list, precache_name)
				if cb then
					cb()
				end
			end)
		end
	end
end
--进阶的棋子合成
--units是参与合成的棋子列表table，其中每一个棋子可以是unit，也可以是obj
function CombineChessPlusAsync(units, advance_unit_name, cb)
	local unit_name, y, x, druid_level_count = CombineChessPlusFindChess(units, advance_unit_name)
	if unit_name == nil then
		return
	end
	RequestPrecacheUnitAsync('model_'..unit_name, function()
		local unit = CombineChessPlusCreateChess(units, unit_name, y, x, druid_level_count)
		if cb then
			cb(unit)
		end
	end)
end
--召唤一个棋子
function SummonOneChessAsync(keys)
	RequestPrecacheUnitAsync('model_'..keys.chessname, function()
		local unit = SummonOneChess(keys)
		if keys.cb then
			keys.cb(unit)
		end
	end)
end
