			cb(unit)
		end
	end)
end

function CreateChessOnBoardAsync(unit_name, position, team_id, cb)
	RequestPrecacheUnitAsync('model_'..unit_name, function()
		local unit = CreateUnitByName(unit_name, position, true, nil, nil, team_id)
		if cb then
			cb(unit)
		end
	end)
end
function SetCourierAsync(hero, onduty_hero, onduty_hero_effect, onduty_hero_projectile, onduty_hero_pet, onduty_hero_animation, courier_id)
	
	RequestPrecacheUnitAsync("courier_"..onduty_hero, function()
		local onduty_hero_model = _G.sm_hero_list[onduty_hero]
		local onduty_hero_skin = _G.sm_hero_list_skin[onduty_hero] or 0

		hero.init_model_scale = _G.sm_hero_size[onduty_hero] or 1

		hero.ori_model = onduty_hero_model
		hero.ori_skin = onduty_hero_skin
		local ignore_global_message = false
		if onduty_hero == hero.courier_name then
			ignore_global_message = true
		end
		hero.onduty_hero = onduty_hero or ""
		hero.projectile = onduty_hero_projectile

		hero.pet = onduty_hero_pet
		hero.animation = onduty_hero_animation
		if _G.egg_quest == 'q024' and (string.find(hero.onduty_hero, 'h1') ~= nil or string.find(hero.onduty_hero, 'h0') ~= nil) then
			SetQuest(hero:GetTeam(), true)
		end
		if _G.egg_quest == 'q025' and string.find(hero.onduty_hero, 'h2') ~= nil then
			SetQuest(hero:GetTeam(), true)
		end
		if _G.egg_quest == 'q026' and string.find(hero.onduty_hero, 'h3') ~= nil then
			SetQuest(hero:GetTeam(), true)
		end
		if _G.egg_quest == 'q027' and string.find(hero.onduty_hero, 'h4') ~= nil then
			SetQuest(hero:GetTeam(), true)
		end

		hero.courier_name = onduty_hero

		if hero.effect ~= nil then
			hero:RemoveAbility(hero.effect)
			hero:RemoveModifierByName('modifier_texiao_star')
		end
		if onduty_hero_effect ~= nil and onduty_hero_effect ~= '' and onduty_hero_effect ~= 'e000' then
			if _G.effect_list ~= nil and _G.effect_list[onduty_hero_effect] ~= nil then
				Timers:CreateTimer(2, function()
					AddAbilityAndSetLevel(hero, onduty_hero_effect)
				end)
				hero.effect = onduty_hero_effect
			end
		else
			hero.effect = nil
		end
		ShowCourierEffect(hero, 1)
		hero.onduty_hero = onduty_hero

		-- BlinkChessX({caster=hero,blink_type="fall"})
		if not ignore_global_message then
			CustomGameEventManager:Send_ServerToAllClients("drodo_chat", {
				player_id = hero:GetPlayerID(),
				win_streak = hero.win_streak or 0,
				vip = hero.is_vip,
				onduty_hero = onduty_hero,
				text = "notice_player_select_courier",
				time_stamp = math.floor(GameRules:GetGameTime()),
				type = 'player_courier_event',
			})
		end

		RefreshPets(hero, hero.pet_entity, onduty_hero_pet)

		-- CustomGameEventManager:Send_ServerToAllClients("hp_bar",{
		-- 	player_id = hero:GetPlayerID(),
		-- 	unit_index = hero:entindex(),
		-- 	courier_id = onduty_hero,
		-- 	win_streak = hero.win_streak,
		-- 	level = hero:GetLevel(),
		-- })

		AddAbilityAndSetLevel(hero, 'moving_self')
		local animation_info = GetAnimation(hero.animation or 'n000')
		-- hero:SetOrigin(hero:GetOrigin() + Vector(0,0,1000))
		local p = Entities:FindByName(nil, 'center' .. (hero:GetTeam() - 6)):GetOrigin() + Vector(0, -320, 512)
		hero:SetAbsOrigin(p)

		--获取出场动画
		Timers:CreateTimer(1, function()
			--播放起始动画
			local ppp = ShowTPEffectAtPosition(p, animation_info.tp_effect)
			-- if hero.ti_tp_effect then
			-- 	-- play_particle(,PATTACH_OVERHEAD_FOLLOW,x,5)
			-- 	ShowTITPEffectAtPosition(p,hero.ti_tp_effect)
			-- end

			Timers:CreateTimer(2, function()
				if ppp ~= nil then
					ParticleManager:DestroyParticle(ppp, true)
					ParticleManager:ReleaseParticleIndex(ppp)
				end
				hero:SetOriginalModel(onduty_hero_model)
				hero:SetModel(onduty_hero_model)
				hero:SetModelScale(hero.init_model_scale)
				hero:SetSkin(onduty_hero_skin)
				MakeGreevil(hero, false)
				RemoveAbilityAndModifier(hero, 'moving_self')
				--播放后续动画
				if animation_info.tp_sound ~= nil then
					EmitSoundOn(animation_info.tp_sound, hero)
				end
				if animation_info.animation_modifier ~= nil then
					BlinkChessX({ caster = hero, blink_type = animation_info.animation_modifier })
				end
				if animation_info.end_effect ~= nil then
					play_particle(animation_info.end_effect, PATTACH_ABSORIGIN_FOLLOW, hero, 3)
				end


				DAC:OnChooseCourier({
					PlayerID = hero:GetPlayerID(),
					courier = onduty_hero,
					courier_id = courier_id,
				})

				AddHPBar2HPBarTable({
					unit_index = hero:entindex(),
				})
			end)
		end)

		hero.base_origin = hero:GetAbsOrigin()
		hero.check_afk = true

		--检查开局挂机
		Timers:CreateTimer(1, function()
			if IsUnitExist(hero) and (hero:GetAbsOrigin() - hero.base_origin):Length2D() > 10 and hero.check_afk then
				SetNotAfk(hero)
				return
			end
			if _G.battle_round > 3 then
				return
			end
			return 1
		end)

		DAC:ResetFOW({
			local_player_team = hero:GetTeam(),
			target_player_team = hero:GetTeam()
		})
	end)
end

function MorphStrAgi(keys)
	local ability = keys.ability
	local caster = keys.caster
	
	local hp = caster:GetHealth()
	local hp_max = caster:GetMaxHealth()
	local per = math.floor(hp*10/hp_max + 0.5)
	
	local per0 = caster.str_agi_level or -1
	if per ~= per0 then
		--变化了，开转！
		local all_modifier = caster:FindAllModifiers()
		for _, m in pairs(all_modifier) do
			if m:GetName() == 'modifier_morph_str_buff' or m:GetName() == 'modifier_morph_agi_buff' then
				caster:RemoveModifierByName(m:GetName())
			end
		end
		for i=1,per do
			ability:ApplyDataDrivenModifier(caster, caster, 'modifier_morph_agi_buff', {})
		end
		for i=1,10-per do
			ability:ApplyDataDrivenModifier(caster, caster, 'modifier_morph_str_buff', {})
		end
		caster.str_agi_level = per
	end
end

function MorphAttack(keys)
	local caster = keys.caster
	local wave_ability = caster:FindAbilityByName('morphling_waveform')
	if wave_ability == nil then
		return
	end
	local required_attack_count = GetAbilityKV(wave_ability, "required_attack_count") or 10

	if caster.attack_stack == nil then
		caster.attack_stack = 0
	end
	caster.attack_stack = caster.attack_stack + 1
	if caster.attack_stack > required_attack_count then
		caster.attack_stack = required_attack_count
	end
	caster:FindModifierByName('modifier_morph_attack_count'):SetStackCount(caster.attack_stack)
	
	if caster.attack_stack >= required_attack_count then
		wave_ability:EndCooldown()
	end
end
function CountdownAssassinJump(keys)
	local u = keys.caster
	local a = keys.ability
	local d = keys.Duration
	a:ApplyDataDrivenModifier(u,u,'modifier_is_assassin_buff_plus_plus_countdown',{duration = d})
end
function ExpiredRefreshAssassinJump(keys)
	local u = keys.caster
	u.has_assassin_blink = true
end

function ItemExchangeItems(keys)
	local caster = keys.caster
	local target = keys.target
	local relic_item = FindItemInInventory(caster,'item_exchange_items')
	local charges = relic_item:GetCurrentCharges()
	if charges < 1 then
		return
	end
	local item_count = 0
	local exchange_list = {}
	for slot = 0, 8 do
		if caster:GetItemInSlot(slot) ~= nil then
			local item = caster:GetItemInSlot(slot)
			local item_name = item:GetAbilityName()
			local item_level = _G.ITEM_2_LEVEL[item_name]
			if item_level and charges >= item_level then
				DiscardOneItem(item_name, caster)
				table.insert(exchange_list,item_name)
				item_count = item_count + item_level
				charges = charges - item_level
				caster:RemoveItem(caster:GetItemInSlot(slot))
			end
		end
	end
	for i,v in pairs(exchange_list) do 
		local try_time = 50
		local new_item = nil
		while try_time > 0 do
			try_time = try_time - 1
			local item_level = _G.ITEM_2_LEVEL[v]
			local item_list = _G.ITEM_LIST_BY_LEVEL[item_level]
			new_item = item_list[RandomInt(1,table.maxn(item_list))]
			if FindValueInTable(caster.discard_item_table,new_item) == false then
				break
			end
		end
		caster:AddItemByName(new_item)
	end
	play_particle("particles/econ/items/windrunner/windranger_arcana/windranger_arcana_item_cyclone_v2_magic.vpcf",
		PATTACH_ABSORIGIN_FOLLOW, caster, 3)
	EmitSoundOn('exchange.item',caster)
	ItemSpendCharge({
		caster = caster,
		ability = relic_item,
		charge = item_count,
	})
end
function AddAttackSpeedForSameName(keys)
	local x = keys.caster
	if x.jiubei_buff then
		Timers:CreateTimer(0.5,function()
			if _G.game_status == 2 then
				local samename_chesslist = GetSameNameFriendChess(x, 20)
				for _,unit in pairs(samename_chesslist) do 
					unit:FindAbilityByName('dac_guai_base'):ApplyDataDrivenModifier(unit, unit,'modifier_attackspeed_buff',{})
				end
			end
			return 2
		end)
	end
end
function IsChessDiscount(chess_name)
	if chess_name == nil or chess_name == '' then
		return false
	end
	return IsValueInTable(chess_name,_G.chess_discount_list)
end


function SilencerGlobalSilence(keys)
	local caster = keys.caster
	local ability = keys.ability
	local dur = ability:GetSpecialValueFor('duration') or 4
	caster:StartGesture(ACT_DOTA_CAST_ABILITY_4)
	for _, unit in pairs(GetValidChessOnBoard(caster.at_team_id or caster.team_id)) do
		if IsUnitExist(unit) then
			ability:ApplyDataDrivenModifier(unit, unit, 'modifier_sil_silence_all', {duration = dur})
		end
	end
end
function SilenceDamage(keys)
	local caster = keys.caster
	local target = keys.target
	local ability = keys.ability
	local d = ability:GetSpecialValueFor('damage') or 400
	local owner = ability:GetOwner()
	if IsUnitExist(owner) == false then
		return
	end
	if owner:GetTeam() ~= target:GetTeam() then
		ApplyDamage({
			victim = target,
			attacker = owner,
			damage = d,
			damage_type = DAMAGE_TYPE_MAGICAL,
		})
	end
end

